tachment/([^/]+)/embed/?$\";s:43:\"index.php?attachment=$matches[1]&embed=true\";s:16:\"([^/]+)/embed/?$\";s:37:\"index.php?name=$matches[1]&embed=true\";s:20:\"([^/]+)/trackback/?$\";s:31:\"index.php?name=$matches[1]&tb=1\";s:40:\"([^/]+)/feed/(feed|rdf|rss|rss2|atom)/?$\";s:43:\"index.php?name=$matches[1]&feed=$matches[2]\";s:35:\"([^/]+)/(feed|rdf|rss|rss2|atom)/?$\";s:43:\"index.php?name=$matches[1]&feed=$matches[2]\";s:28:\"([^/]+)/page/?([0-9]{1,})/?$\";s:44:\"index.php?name=$matches[1]&paged=$matches[2]\";s:35:\"([^/]+)/comment-page-([0-9]{1,})/?$\";s:44:\"index.php?name=$matches[1]&cpage=$matches[2]\";s:36:\"([^/]+)/wc/file/transient(/(.*))?/?$\";s:56:\"index.php?name=$matches[1]&wc/file/transient=$matches[3]\";s:25:\"([^/]+)/wc-api(/(.*))?/?$\";s:45:\"index.php?name=$matches[1]&wc-api=$matches[3]\";s:42:\"[^/]+/([^/]+)/wc/file/transient(/(.*))?/?$\";s:62:\"index.php?attachment=$matches[1]&wc/file/transient=$matches[3]\";s:53:\"[^/]+/attachment/([^/]+)/wc/file/transient(/(.*))?/?$\";s:62:\"index.php?attachment=$matches[1]&wc/file/transient=$matches[3]\";s:31:\"[^/]+/([^/]+)/wc-api(/(.*))?/?$\";s:51:\"index.php?attachment=$matches[1]&wc-api=$matches[3]\";s:42:\"[^/]+/attachment/([^/]+)/wc-api(/(.*))?/?$\";s:51:\"index.php?attachment=$matches[1]&wc-api=$matches[3]\";s:24:\"([^/]+)(?:/([0-9]+))?/?$\";s:43:\"index.php?name=$matches[1]&page=$matches[2]\";s:16:\"[^/]+/([^/]+)/?$\";s:32:\"index.php?attachment=$matches[1]\";s:26:\"[^/]+/([^/]+)/trackback/?$\";s:37:\"index.php?attachment=$matches[1]&tb=1\";s:46:\"[^/]+/([^/]+)/feed/(feed|rdf|rss|rss2|atom)/?$\";s:49:\"index.php?attachment=$matches[1]&feed=$matches[2]\";s:41:\"[^/]+/([^/]+)/(feed|rdf|rss|rss2|atom)/?$\";s:49:\"index.php?attachment=$matches[1]&feed=$matches[2]\";s:41:\"[^/]+/([^/]+)/comment-page-([0-9]{1,})/?$\";s:50:\"index.php?attachment=$matches[1]&cpage=$matches[2]\";s:22:\"[^/]+/([^/]+)/embed/?$\";s:43:\"index.php?attachment=$matches[1]&embed=true\";}','auto'),(953,'srfm_options','a:3:{s:20:\"usage_events_pending\";a:2:{i:0;a:4:{s:10:\"event_name\";s:16:\"plugin_activated\";s:11:\"event_value\";s:6:\"2.12.7\";s:10:\"properties\";a:1:{s:6:\"source\";s:11:\"astra-sites\";}s:4:\"date\";s:19:\"2026-09-22 21:36:12\";}i:1;a:4:{s:10:\"event_name\";s:20:\"first_form_published\";s:11:\"event_value\";s:4:\"2152\";s:10:\"properties\";a:3:{s:15:\"is_ai_generated\";s:1:\"0\";s:11:\"block_count\";s:1:\"4\";s:18:\"days_since_install\";s:1:\"0\";}s:4:\"date\";s:19:\"2026-09-22 21:36:48\";}}s:21:\"first_form_created_at\";i:1790105808;s:22:\"plugin_banner_rotation\";a:2:{s:18:\"last_rotation_date\";i:1790105906;s:12:\"plugin_index\";i:0;}}','auto'),(960,'power_coupons_migrated_slideout_visibility','done','auto'),(961,'power_coupons_db_version','1.0.3','auto'),(962,'_transient_timeout_power_coupons_activated','1790105806','off'),(963,'_transient_power_coupons_activated','1','off'),(965,'power_coupons_usage_installed_time','1790105776','auto');
INSERT INTO `wp_options` VALUES (967,'cartflows_docs_data','O:8:\"stdClass\":2:{s:10:\"categories\";O:8:\"stdClass\":6:{s:13:\"uncategorized\";O:8:\"stdClass\":2:{s:4:\"name\";s:13:\"Uncategorized\";s:13:\"subcategories\";a:0:{}}s:9:\"cartflows\";O:8:\"stdClass\":2:{s:4:\"name\";s:9:\"CartFlows\";s:13:\"subcategories\";O:8:\"stdClass\":18:{s:20:\"installation-updates\";O:8:\"stdClass\":2:{s:4:\"name\";s:26:\"Installation &amp; Updates\";s:13:\"subcategories\";a:0:{}}s:15:\"getting-started\";O:8:\"stdClass\":2:{s:4:\"name\";s:15:\"Getting Started\";s:13:\"subcategories\";a:0:{}}s:7:\"general\";O:8:\"stdClass\":2:{s:4:\"name\";s:7:\"General\";s:13:\"subcategories\";a:0:{}}s:8:\"features\";O:8:\"stdClass\":2:{s:4:\"name\";s:8:\"Features\";s:13:\"subcategories\";a:0:{}}s:26:\"frequently-bought-together\";O:8:\"stdClass\":2:{s:4:\"name\";s:26:\"Frequently Bought Together\";s:13:\"subcategories\";a:0:{}}s:15:\"flow-step-clone\";O:8:\"stdClass\":2:{s:4:\"name\";s:19:\"Funnel / Step Clone\";s:13:\"subcategories\";a:0:{}}s:17:\"one-click-upsells\";O:8:\"stdClass\":2:{s:4:\"name\";s:17:\"One Click Upsells\";s:13:\"subcategories\";a:0:{}}s:10:\"order-bump\";O:8:\"stdClass\":2:{s:4:\"name\";s:10:\"Order Bump\";s:13:\"subcategories\";a:0:{}}s:21:\"checkout-field-editor\";O:8:\"stdClass\":2:{s:4:\"name\";s:21:\"Checkout Field Editor\";s:13:\"subcategories\";a:0:{}}s:12:\"integrations\";O:8:\"stdClass\":2:{s:4:\"name\";s:12:\"Integrations\";s:13:\"subcategories\";a:0:{}}s:18:\"permalink-settings\";O:8:\"stdClass\":2:{s:4:\"name\";s:18:\"Permalink Settings\";s:13:\"subcategories\";a:0:{}}s:19:\"translate-cartflows\";O:8:\"stdClass\":2:{s:4:\"name\";s:9:\"Translate\";s:13:\"subcategories\";a:0:{}}s:15:\"flows-analytics\";O:8:\"stdClass\":2:{s:4:\"name\";s:17:\"Funnels Analytics\";s:13:\"subcategories\";a:0:{}}s:15:\"global-checkout\";O:8:\"stdClass\":2:{s:4:\"name\";s:14:\"Store Checkout\";s:13:\"subcategories\";a:0:{}}s:13:\"account-store\";O:8:\"stdClass\":2:{s:4:\"name\";s:19:\"Account &amp; Store\";s:13:\"subcategories\";a:0:{}}s:15:\"troubleshooting\";O:8:\"stdClass\":2:{s:4:\"name\";s:15:\"Troubleshooting\";s:13:\"subcategories\";a:0:{}}s:13:\"code-snippets\";O:8:\"stdClass\":2:{s:4:\"name\";s:13:\"Code Snippets\";s:13:\"subcategories\";a:0:{}}s:14:\"developer-docs\";O:8:\"stdClass\":2:{s:4:\"name\";s:14:\"Developer Docs\";s:13:\"subcategories\";a:0:{}}}}s:27:\"modern-cart-for-woocommerce\";O:8:\"stdClass\":2:{s:4:\"name\";s:11:\"Modern Cart\";s:13:\"subcategories\";a:0:{}}s:25:\"cart-abandonment-recovery\";O:8:\"stdClass\":2:{s:4:\"name\";s:25:\"Cart Abandonment Recovery\";s:13:\"subcategories\";a:0:{}}s:13:\"power-coupons\";O:8:\"stdClass\":2:{s:4:\"name\";s:13:\"Power Coupons\";s:13:\"subcategories\";a:0:{}}s:18:\"variation-swatches\";O:8:\"stdClass\":2:{s:4:\"name\";s:18:\"Variation Swatches\";s:13:\"subcategories\";a:0:{}}}s:4:\"docs\";a:250:{i:0;O:8:\"stdClass\":8:{s:2:\"id\";i:79673;s:5:\"title\";s:41:\"CartFlows Order Bump Positions and Styles\";s:7:\"content\";s:3210:\"CartFlows lets you add an Order Bump to your checkout page, a one-click add-on offer shown right next to the customer\'s order. You can control both where the offer appears on the page and how it looks, without touching any code.\n\n\n\nThis guide walks through the four available positions and the five visual styles, so you can choose the combination that fits your checkout page best.\n\n\n\nHow Order Bump Placement Works\n\n\n\nEvery Order Bump has two layout settings that work independently of each other.\n\n\n\n\nPosition decides where on the checkout page the Order Bump appears, relative to the billing form, the order summary, and the payment section.\n\n\n\nOrder Bump Skin decides how the offer card itself is laid out: where the checkbox sits, whether there\'s a checkbox at all, and how the image, title, and price are arranged.\n\n\n\n\nBecause these two settings are separate, you can pair any style with any position, and each Order Bump on a checkout step can have its own combination.\n\n\n\nHow to Set the Order Bump Position\n\n\n\nStep 1. From your WordPress admin, go to CartFlows → Funnels and open the funnel that contains the checkout step you want to update.\n\n\n\nStep 2. Click the checkout step settings (gear icon), then open Order Bumps from the left sidebar.\n\n\n\nStep 3. Click the gear icon next to the Order Bump you want to update, or add a new one.\n\n\n\nStep 4. Click the Styles tab.\n\n\n\nStep 5. Under Layout, click the Position dropdown.\n\n\n\n\n\n\n\nStep 6. Choose one of the four positions:\n\n\n\n\nBefore Checkout — appears at the very top of the checkout page, above the billing details form.\n\n\n\nAfter Customer Details — appears once the billing and shipping fields end, before the order summary.\n\n\n\nAfter Order Details — appears after the cart and order summary section. This is the default placement.\n\n\n\nAfter Payment Details — appears near the bottom of the page, after the payment method options.\n\n\n\n\nStep 7. Click Save Settings.\n\n\n\nHere\'s what Before Checkout looks like on the live checkout page. The Order Bump sits above the billing form, right below the express payment buttons:\n\n\n\n\n\n\n\nHow to Change the Order Bump Style\n\n\n\nStep 1. With the Order Bump\'s Styles tab still open, find Order Bump Skin under Layout.\n\n\n\nStep 2. Click the dropdown and choose from Style 1 through Style 5. The preview above updates immediately so you can compare them.\n\n\n\n\n\n\n\nStyle 1 places the checkbox in its own row at the top, with the product image, title, and price in a card below it.\n\n\n\n\n\n\n\nStyle 2 puts the offer title at the top, followed by the product image and price, with the checkbox in its own row at the bottom.\n\n\n\n\n\n\n\nStyle 3 condenses everything into a single row. The checkbox, product image, title, and price all sit side by side.\n\n\n\n\n\n\n\nStyle 4 uses the same compact row as Style 3, but replaces the checkbox with an Add link. Customers accept the offer by clicking Add instead of ticking a box.\n\n\n\n\n\n\n\nStyle 5 shows the product image on the left, with the title, price, and checkbox stacked together on the right.\n\n\n\n\n\n\n\nStep 3. Once you\'ve picked a style, use the Width dropdown to set the Order Bump to 50% or 100% of the checkout column.\n\n\n\nStep 4. Click Save Settings.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:55:\"https://cartflows.com/docs/order-bump-positions-styles/\";s:4:\"slug\";s:27:\"order-bump-positions-styles\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-09-17T19:07:02+05:30\";s:8:\"category\";a:1:{i:0;s:10:\"order-bump\";}}i:1;O:8:\"stdClass\":8:{s:2:\"id\";i:79056;s:5:\"title\";s:61:\"How to Add a Quantity Selector to Your One-Click Upsell Offer\";s:7:\"content\";s:3413:\"CartFlows Pro lets you add a quantity selector to your One-Click Upsell and Downsell offers, so shoppers can choose how many of the offer product they want instead of always getting just one. This guide walks through setting the default quantity on your offer step and adding the Offer Product Quantity element to the offer page so shoppers can adjust it themselves.\n\n\n\nHow the Quantity Selector Works\n\n\n\nWhen you set up an Upsell or Downsell offer, CartFlows lets you choose a starting quantity for the offer product right in the step settings. Adding the Offer Product Quantity element to the offer page then puts a quantity field in front of your shopper.\n\n\n\n\nIf you only set the quantity in the step settings, that amount is added automatically when the shopper accepts the offer. They won\'t see a way to change it themselves.\n\n\n\nIf you add the Offer Product Quantity element to the offer page, a quantity stepper appears next to the product, pre-filled with the quantity you set (or 1 if left blank).\n\n\n\nThe shopper can increase or decrease the quantity before accepting, and the amount they choose is what gets added to their order.\n\n\n\n\nThis gives shoppers control over exactly how many they want, right on the offer page, without needing to leave the flow.\n\n\n\nHow to Set Up the Quantity Selector\n\n\n\nStep 1. From the WordPress admin, go to CartFlows → Funnels (or Store Checkout) and open the funnel that contains your Upsell or Downsell step.\n\n\n\nStep 2. Click the settings (gear) icon on that step\'s row to open its settings.\n\n\n\nStep 3. In the Products tab, find the Quantity field next to the offer product you\'ve selected.\n\n\n\n\n\n\n\nStep 4. Set the default quantity you\'d like the offer to start at. Leave this blank and it will default to 1.\n\n\n\nStep 5. Open the same step in your page builder. Gutenberg, Elementor, Bricks, and Beaver Builder are all supported, the element is called Offer Product Quantity, though where you find it in the panel and how you insert it looks a little different from one builder to the next. The steps below use Elementor as the example.\n\n\n\nStep 6. Search for Offer Product Quantity in your builder\'s widget/block/element panel, and add it onto your offer page layout, near the product details.\n\n\n\n\n\n\n\nStep 7. Optional: use the widget\'s style options (alignment, width, colors, border, typography) to match the field to the rest of your offer page. These same style options are available whichever builder you\'re using.\n\n\n\n\n\n\n\nStep 8. Save the page and the step settings.\n\n\n\nThe quantity selector is now active on that Upsell/Downsell offer.\n\n\n\nUsing a different page builder, or no page builder at all? If your offer page is built with something other than Gutenberg, Elementor, Bricks, or Beaver Builder, you can add the [cartflows_offer_product_quantity] shortcode anywhere on the page instead, most builders (and the classic editor) can drop in a shortcode directly. See our Upsell Downsell Shortcodes doc for the full list of available shortcodes and how to place them.\n\n\n\nThe Quantity Selector in Action\n\n\n\nOnce it\'s set up, shoppers land on the offer page and see the quantity field next to the offer product, already filled in with your default quantity.\n\n\n\n\n\n\n\nThey can increase or decrease the number using the stepper, then accept the offer as usual. Whatever quantity is showing when they accept is the amount added to their order.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:62:\"https://cartflows.com/docs/quantity-selector-one-click-upsell/\";s:4:\"slug\";s:34:\"quantity-selector-one-click-upsell\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-09-08T17:09:47+05:30\";s:8:\"category\";a:1:{i:0;s:17:\"one-click-upsells\";}}i:2;O:8:\"stdClass\":8:{s:2:\"id\";i:79008;s:5:\"title\";s:25:\"CartFlows Product Options\";s:7:\"content\";s:4158:\"CartFlows Pro includes a feature called Product Options that lets you offer more than one product, in more than one quantity, right on the checkout page. Shoppers can switch between product variations, adjust quantity, and see the price update instantly, all without leaving checkout.\n\n\n\nHow Product Options Works\n\n\n\nWhen Product Options is turned on for a checkout step, a Your Products section appears on that checkout page listing the product (or products) you\'ve configured for it.\n\n\n\n\nShoppers can pick between the products you\'ve offered, depending on how you\'ve set it up: all of them included automatically, a single choice, or multiple choices.\n\n\n\nIf a product has variations (like size or color), shoppers choose them right there on checkout.\n\n\n\nIf quantity is turned on, shoppers can increase or decrease how many they want with simple plus and minus buttons, and the price updates immediately.\n\n\n\n\nThe shopper never has to leave the checkout page to change what they\'re buying, and every change is reflected in the order total right away.\n\n\n\nHow to Set Up Product Options\n\n\n\nProduct Options is configured per checkout step, so you can turn it on for some funnels and leave it off for others.\n\n\n\nStep 1. From the WordPress admin, go to CartFlows → Funnels and open the funnel that contains the checkout step you want to update.\n\n\n\nStep 2. Click the Settings icon (cog icon) of the Checkout step.\n\n\n\n\n\n\n\nStep 3. In the left sidebar, under Products, click Product Options.\n\n\n\nStep 4. Turn on Enable Product Options.\n\n\n\nStep 5. Choose how shoppers can interact with your products using Enable Conditions:\n\n\n\n\nRestrict user to purchase all products — every product you\'ve added is included automatically, and can\'t be removed.\n\n\n\nLet user select one product from all options — the shopper picks a single product from the list.\n\n\n\nLet user select multiple products from all options — the shopper checks off as many products as they like.\n\n\n\n\nStep 6. Turn on Enable Variations if any of your products have variations (like size or color) you want shoppers to choose at checkout. Then choose Show variations inline to display the choices directly on the product, or Show variations in popup to open them in a separate window.\n\n\n\nStep 7. Turn on Enable Quantity if you want shoppers to be able to adjust how many of a product they\'re buying directly on checkout.\n\n\n\n\n\n\n\nStep 8. Click Save Settings at the top right.\n\n\n\nStep 9. Back on the Products tab (under the Products section in the sidebar), each product you add gets its own row with a few extra controls:\n\n\n\n\nDefault — a toggle that controls whether this product is included/selected for the shopper by default.\n\n\n\nQty — the quantity shown to the shopper when the page first loads.\n\n\n\nDiscount — a dropdown with Original (no discount), Percentage, or Price (a fixed discounted price). Choosing Percentage or Price reveals a field to enter the discount value.\n\n\n\n\n\n\n\n\nStep 10. Click the gear icon on a product row to customize it further:\n\n\n\n\nProduct Name — a custom name shown instead of the product\'s regular title. You can use {{product_name}} and {{quantity}} placeholders to pull in the product\'s own details automatically.\n\n\n\nSubtext — a short line shown under the product name. You can use {{quantity}}, {{discount_value}}, and {{discount_percent}} placeholders here.\n\n\n\nEnable Highlight — turn this on to reveal a Highlight Text field, letting you add a short badge (for example, \"Best Value\") to draw attention to that product.\n\n\n\n\n\n\n\n\nProduct Options is now active on that checkout step.\n\n\n\nThe Products Section in Action\n\n\n\nOnce Product Options is set up, shoppers see the Your Products section on your checkout page as soon as it loads, with each product shown as its own card.\n\n\n\n\n\n\n\nIf quantity is enabled, a number field with - and + buttons lets shoppers adjust how many they want. The price updates immediately, with no page reload.\n\n\n\nIf you\'ve enabled variations on a product, the shopper chooses their options right there before continuing, either inline on the card or in a popup window, depending on how you\'ve configured it.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:53:\"https://cartflows.com/docs/cartflows-product-options/\";s:4:\"slug\";s:25:\"cartflows-product-options\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-09-04T21:50:00+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:3;O:8:\"stdClass\":8:{s:2:\"id\";i:78388;s:5:\"title\";s:23:\"CartFlows Order Bump AI\";s:7:\"content\";s:3947:\"CartFlows Pro includes Order Bump AI, a set of AI-assisted tools that help you choose which product to offer as an order bump and write the copy that goes with it. Instead of guessing which add-on will appeal to a shopper, or staring at a blank text field for the bump\'s title and description, you can let AI make suggestions you can accept, tweak, or ignore.\n\n\n\nThis guide walks you through how Order Bump AI works, how to turn it on for a checkout step, and what your shoppers actually see.\n\n\n\nHow Order Bump AI Works\n\n\n\nOrder Bump AI adds two independent tools to any order bump on your checkout: one for picking the product, and one for writing the text around it.\n\n\n\n\nProduct suggestions — AI looks at the product already in the bump (or a pool of products you choose) and recommends the one most likely to appeal to a shopper, along with a short reason.\n\n\n\nAutomatic matching — Instead of one fixed product, you can let AI choose from a pool per shopper, based on what\'s already in their cart.\n\n\n\nWritten copy — AI can write the bump\'s title, description, highlight text, and checkbox label for you, offering a few options to pick from.\n\n\n\n\nYour shoppers never see anything labeled \"AI.\" They just see a normal order bump on checkout, one that\'s more likely to be relevant to what they\'re already buying.\n\n\n\nHow to Set Up Order Bump AI\n\n\n\nOrder Bump AI is configured per order bump, so you can use it on some bumps and leave others exactly as they are.\n\n\n\nStep 1. From the WordPress admin, go to CartFlows → Funnels and open the funnel that contains your checkout step.\n\n\n\nStep 2. Under that checkout step, you\'ll see an Order Bumps section. If you don\'t have one yet, click Add Order Bump and give it a name.\n\n\n\nStep 3. Click the gear icon on the order bump you want to set up.\n\n\n\n\n\n\n\nStep 4. On the Product tab, choose how you want the product selected:\n\n\n\n\nManual (default) — Pick one fixed product for the bump, as usual.\n\n\n\nAI Auto — Build a pool of eligible products, and each shopper is shown whichever one AI judges most relevant to their cart.\n\n\n\n\n\n\n\n\nStep 5. If you\'re using Manual mode, click Let AI suggest a product. AI returns one recommended product with a relevance badge and a short reason. Click Accept to use it, or Ignore to pick a different product yourself.\n\n\n\n\n\n\n\nStep 6. If you\'re using AI Auto mode, search for and add products to the pool. Each product keeps its own quantity and discount settings. Aim for at least 3 products in the pool. If you\'re under that, you\'ll see a badge reminding you that more products give AI better matches to work with.\n\n\n\n\n\n\n\nStep 7. Go to the Content tab. Next to the Checkbox Label, Highlight Text, and Description fields, click Write with AI. Review the options AI generates and click one to apply it, or click Regenerate for new options.\n\n\n\n\n\n\n\nStep 8. Click Save Settings at the top right.\n\n\n\nOrder Bump AI is now active on that order bump.\n\n\n\nConnecting to CartFlows AI\n\n\n\nThe first time you use any AI tool in CartFlows, you\'ll be asked to Connect to CartFlows AI. This is a one-time, free account connection, separate from your CartFlows Pro license, and only users who can manage your site\'s settings can set it up.\n\n\n\n\n\n\n\nOrder Bump AI in Action\n\n\n\nOn the frontend, an order bump set up with Order Bump AI looks exactly like any other order bump. There\'s no AI label or badge shown to shoppers.\n\n\n\nThe one difference shoppers may notice is with AI Auto mode: since the product shown can vary from one shopper to the next based on their cart, two people checking out at the same time might see different bump offers. Once a shopper has been shown a product (or accepted the bump), that same product stays consistent for them through the rest of checkout.\n\n\n\nIf AI can\'t find a suitable product for a shopper\'s cart, for example if your product pool is too narrow, the bump is simply skipped rather than showing something irrelevant.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:51:\"https://cartflows.com/docs/cartflows-order-bump-ai/\";s:4:\"slug\";s:23:\"cartflows-order-bump-ai\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-25T20:43:13+05:30\";s:8:\"category\";a:1:{i:0;s:10:\"order-bump\";}}i:4;O:8:\"stdClass\":8:{s:2:\"id\";i:78025;s:5:\"title\";s:45:\"Styling the Frequently Bought Together Widget\";s:7:\"content\";s:3291:\"The Frequently Bought Together section is built to inherit your theme, so on most stores it already looks at home. There are no colour or font settings for it, so anything beyond what your theme gives you is done with a few lines of custom CSS.\n\n\n\nHow It Works\n\n\n\nThe section takes its cues from your theme wherever it can, and falls back to a neutral built-in style for its own parts.\n\n\n\n\nText picks up your theme\'s fonts and colours.\n\n\n\nThe add button uses your theme\'s own button style, so it matches the other buttons on the page.\n\n\n\nThe panel itself, the row separators and the total use a plain built-in style you can override.\n\n\n\n\nHere are the parts you can target, so you know what to aim at before you write anything.\n\n\n\n\n\n\n\nWhere to Put Your CSS\n\n\n\nCustom CSS belongs with your theme, never in the plugin\'s own files, so it survives every plugin update.\n\n\n\nStep 1. Go to Appearance and open Editor, then choose Styles.\n\n\n\nStep 2. Click the three dots at the top of the Styles panel and choose Additional CSS.\n\n\n\n\n\n\n\nStep 3. Paste your CSS, then save.\n\n\n\nIf your theme is a classic one rather than a block theme, the same box lives under Appearance, then Customise, then Additional CSS.\n\n\n\nKeep in mind that this CSS is stored against the theme you are using, so if you switch themes later you will need to move it across.\n\n\n\nThe Names to Target\n\n\n\nEach part of the section has its own name you can style.\n\n\n\n\n.wcf-fbt-widget is the panel around everything\n\n\n\n.wcf-fbt-widget-title is the \"Frequently bought together\" heading\n\n\n\n.wcf-fbt-widget-row is one product line\n\n\n\n.wcf-fbt-widget-thumb is the small product image\n\n\n\n.wcf-fbt-widget-name is the product name\n\n\n\n.wcf-fbt-widget-price is the price on the right of a row\n\n\n\n.wcf-fbt-widget-toggle is the \"Show more\" link\n\n\n\n.wcf-fbt-widget-total is the total in the footer\n\n\n\n.wcf-fbt-widget-add is the add button\n\n\n\n\nA Worked Example\n\n\n\nThis is the whole of what produced the change below.\n\n\n\n.wcf-fbt-widget.wcf-fbt-widget {	border: 2px solid #d9b382;	border-radius: 14px;	background: #fdf4e6;	padding: 24px;}.wcf-fbt-widget-title {	font-size: 18px;	color: #7c4a11;}.wcf-fbt-widget-total {	color: #b45309;}\n\n\n\n\n\n\n\nNotice the first line has the panel\'s name written twice. That is deliberate, and it matters.\n\n\n\nIf a Change Does Not Show Up\n\n\n\nThe section brings its own styling for the outer panel, which can win over yours for things like the border, the background and the corners. Writing the name twice, as in the example above, gives your rule enough weight to take over.\n\n\n\nYou only need this for the outer panel. The heading, prices, rows and total all take a single name without any trouble.\n\n\n\nIf something still does not change, clear any caching plugin you are running and reload the page, since a cached copy of the page can hold on to the old styling.\n\n\n\nCommon Changes\n\n\n\nA few short recipes for the things people usually ask about.\n\n\n\nMake the product images bigger\n\n\n\n.wcf-fbt-widget-thumb {	width: 60px;	height: 60px;}\n\n\n\nHide the product images entirely\n\n\n\n.wcf-fbt-widget-thumb {	display: none;}\n\n\n\nRemove the lines between products\n\n\n\n.wcf-fbt-widget-list &gt; * + * {	border-top: none;}\n\n\n\nMake the total stand out\n\n\n\n.wcf-fbt-widget-total {	font-size: 24px;	color: #b45309;}\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:69:\"https://cartflows.com/docs/styling-frequently-bought-together-widget/\";s:4:\"slug\";s:41:\"styling-frequently-bought-together-widget\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-25T13:47:18+05:30\";s:8:\"category\";a:1:{i:0;s:26:\"frequently-bought-together\";}}i:5;O:8:\"stdClass\":8:{s:2:\"id\";i:78013;s:5:\"title\";s:56:\"How the Add Products Separately Setting Affects the Cart\";s:7:\"content\";s:2714:\"The Frequently Bought Together section has one setting that decides what happens after a shopper taps the add button. It controls whether the products arrive in the cart as independent items or as a set that stays together.\n\n\n\nHow It Works\n\n\n\nThe setting is called Add products separately, and it sits with the rest of the section\'s options on the product you are editing.\n\n\n\n\nTicked, every product becomes its own cart line and behaves like anything else in the cart.\n\n\n\nUnticked, the products added from that section are treated as one set, and removing the main product removes the rest with it.\n\n\n\nEither way the prices are unchanged. This setting groups items, it does not discount them.\n\n\n\n\n\n\n\n\nWhere to Find It\n\n\n\nStep 1. Go to Products and open the product whose section you want to change.\n\n\n\nStep 2. Scroll to the Product data box and click the Frequently Bought Together tab.\n\n\n\nStep 3. Tick or untick Add products separately, then update the product.\n\n\n\nThe setting belongs to that one product, so you can group the items on a product where it makes sense and leave everything else independent.\n\n\n\nWith the Setting Ticked\n\n\n\nThis is how a new product starts out, and it is the option most stores want.\n\n\n\nEach product the shopper selected lands in the cart as its own line, exactly as if they had visited each product page and added them one at a time. Nothing links the lines together.\n\n\n\n\n\n\n\nThat means the shopper stays in full control. If they change their mind about the main product and remove it, the companions they liked are still there.\n\n\n\n\n\n\n\nWith the Setting Unticked\n\n\n\nNow the products are treated as a set that belongs together.\n\n\n\nThe lines still look the same in the cart, but they are linked behind the scenes. Removing the main product removes every companion that came with it, so a shopper cannot end up with an accessory for something they are no longer buying.\n\n\n\n\n\n\n\nA few details worth knowing:\n\n\n\n\nRemoving just a companion only removes that one. The rest of the set is untouched.\n\n\n\nAdding the same set again merges into the existing lines rather than creating duplicates.\n\n\n\nItems already sitting in a shopper\'s cart keep the behaviour they were added with, so changing the setting does not rewrite carts that are already in progress.\n\n\n\n\nWhich One to Choose\n\n\n\nThink about whether the companions make sense on their own.\n\n\n\n\nLeave it ticked when each product stands up by itself, such as a lamp offered alongside a desk. A shopper who drops the desk may still want the lamp.\n\n\n\nUntick it when the companions only exist because of the main product, such as a case made for one specific device. Removing the device should take the case with it.\n\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:56:\"https://cartflows.com/docs/add-products-separately-cart/\";s:4:\"slug\";s:28:\"add-products-separately-cart\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-25T13:49:45+05:30\";s:8:\"category\";a:1:{i:0;s:26:\"frequently-bought-together\";}}i:6;O:8:\"stdClass\":8:{s:2:\"id\";i:77988;s:5:\"title\";s:52:\"How Auto Suggest Chooses Which Products to Recommend\";s:7:\"content\";s:5097:\"Auto Suggest fills your Frequently Bought Together section, upsells and cross-sells with products that fit the one you\'re editing. This guide explains where those suggestions come from, why they\'re ordered the way they are, and what to expect on a store that hasn\'t sold much yet.\n\n\n\nHow It Works\n\n\n\nAuto Suggest looks at two things and combines them into a single ranked list.\n\n\n\n\nWhat your shoppers actually buy together, taken from your own past orders.\n\n\n\nWhat each product is, taken from its name and description, so related items can be spotted even without sales behind them.\n\n\n\nWhether the product can actually be offered, so nothing unavailable reaches the list.\n\n\n\n\nThe result is a shortlist, best match first, that you can accept as-is or edit before saving.\n\n\n\n\n\n\n\nWhat Your Order History Contributes\n\n\n\nThe first signal is your own sales. Auto Suggest reviews completed and processing orders from the last twelve months and notes which products turned up in the same order.\n\n\n\nIt doesn\'t simply count pairs. A product that sells constantly would otherwise appear alongside everything, so Auto Suggest measures how much more often two products are bought together than they would be by chance. A quiet product that almost always sells with one particular item can outrank a bestseller that happens to be in a lot of baskets.\n\n\n\nTwo rules keep the results steady:\n\n\n\n\nA pair has to appear in at least two orders before it counts, so a single unusual basket doesn\'t create a suggestion.\n\n\n\nOnly completed and processing orders are counted. Cancelled, failed and refunded orders are left out.\n\n\n\n\nThis analysis runs quietly in the background once a day, in small batches, so it doesn\'t slow your store down.\n\n\n\nWhat the Product Itself Contributes\n\n\n\nOrder history can only describe products that have already sold. CartFlows Pro adds a second signal by reading each product\'s name and description to understand what it actually is, then finding products that make sense next to it.\n\n\n\nThat means a newly added product can be suggested on its first day, before anyone has bought it. When both signals are available they\'re blended, with the product\'s meaning weighted a little more heavily than the sales pattern, and the strongest match leads the list.\n\n\n\nReading the Suggestions\n\n\n\nEach suggestion carries a short label that tells you why it\'s there.\n\n\n\n\nA match percentage shows how strong a suggestion is relative to the best one in that list. The top match is always 100%, so treat it as a ranking, not a probability.\n\n\n\nPopular in your store means the product came from your bestsellers rather than from a specific buying pattern.\n\n\n\nNew means it\'s one of your most recently added products.\n\n\n\n\nA suggestion with no badge and no percentage is simply one where the numbers wouldn\'t tell you anything useful.\n\n\n\nAccept adds the product to your list and Reject drops it from the suggestions. Anything you accept becomes an ordinary entry that you can remove or reorder before saving, exactly as if you\'d searched for it yourself.\n\n\n\n\n\n\n\nSuggestions are kept for up to 24 hours so the panel opens instantly the next time. If you\'ve changed your products since, use Regenerate all to build the list again from scratch.\n\n\n\nWhen There Isn\'t Enough History\n\n\n\nAuto Suggest never leaves you with an empty list. If your orders don\'t produce enough matches, it fills the remaining slots in this order:\n\n\n\n1. Bestsellers in a sensible price range. For a Frequently Bought Together section these usually come from a different category, since add-ons tend to sit alongside a product rather than compete with it. \n\n\n\n2. Your remaining bestsellers, if more slots are still open. \n\n\n\n3. Your newest products, so even a store with no sales at all gets a usable list.\n\n\n\nOn a brand-new store you\'ll mostly see the second and third groups, with badges rather than percentages. As orders come in, real buying patterns take their place automatically.\n\n\n\nPrice Rules\n\n\n\nAuto Suggest keeps the money side sensible, and the rule depends on what you\'re filling in.\n\n\n\n\nFor Frequently Bought Together and cross-sells, catalogue-based suggestions are kept between a quarter and one and a half times the product\'s price. An add-on that costs ten times the product it sits next to rarely converts.\n\n\n\nFor upsells, every suggestion must be priced above the product and no more than three times it. An upsell has to be a genuine step up without being a leap.\n\n\n\n\nSuggestions that come straight from your buying patterns aren\'t price-filtered for Frequently Bought Together and cross-sells, because a real pattern in your own orders is the stronger signal.\n\n\n\n\n\n\n\nWhat Never Gets Suggested\n\n\n\nSome products are held back so shoppers never meet an option they can\'t buy.\n\n\n\n\nProducts that are unpublished, hidden from the catalogue, out of stock or not purchasable.\n\n\n\nProduct types the section can\'t handle, such as grouped or external products.\n\n\n\nVariations that still need a choice the section has no way to collect.\n\n\n\nThe product you\'re editing, and anything already in your list.\n\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:61:\"https://cartflows.com/docs/how-auto-suggest-chooses-products/\";s:4:\"slug\";s:33:\"how-auto-suggest-chooses-products\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-25T13:48:13+05:30\";s:8:\"category\";a:1:{i:0;s:26:\"frequently-bought-together\";}}i:7;O:8:\"stdClass\":8:{s:2:\"id\";i:77980;s:5:\"title\";s:55:\"Widget Placement Options for Frequently Bought Together\";s:7:\"content\";s:3664:\"The Frequently Bought Together section doesn\'t have to sit in one fixed spot. You can choose where it appears on the product page, and you can choose a different spot for each product.\n\n\n\nThis guide covers the four available placements, how to change them, and how to pick the one that suits your store.\n\n\n\nHow It Works\n\n\n\nPlacement is a per-product setting. It lives alongside the rest of the Frequently Bought Together options, so you can position the section wherever it works best for that particular product.\n\n\n\n\nFour placements are available, all on the single product page.\n\n\n\nThe setting applies to one product at a time.\n\n\n\nChanging it moves the section without changing anything about how it behaves.\n\n\n\n\nYour theme controls how a product page is laid out, so the exact spot each option lands in follows your theme\'s own structure.\n\n\n\nChanging the Placement\n\n\n\nStep 1. Go to Products and open the product you want to change.\n\n\n\nStep 2. Scroll to the Product data box and click the Frequently Bought Together tab.\n\n\n\nStep 3. Find Widget placement at the bottom of the panel and pick the spot you want.\n\n\n\n\n\n\n\nStep 4. Click Update, then open the product page to see the result.\n\n\n\nThe Four Placements\n\n\n\nEach option puts the section in a different part of the product page.\n\n\n\n\nAfter Add-to-Cart button - directly beneath the Add to Cart button. This is the default.\n\n\n\nBelow title - high up in the product summary, right after the product name.\n\n\n\nBelow price - in the product summary, after the price.\n\n\n\nBelow summary - underneath the whole summary column, further down the page.\n\n\n\n\nAfter Add-to-Cart button\n\n\n\nThe section sits immediately under the Add to Cart button, so shoppers meet it at the exact moment they\'re deciding to buy. This is the default and the one most stores keep.\n\n\n\n\n\n\n\nBelow title and Below price\n\n\n\nBoth of these put the section up in the summary area, above the product description. Shoppers see the suggestions without scrolling, which suits products where the add-ons matter as much as the main item.\n\n\n\nThe trade-off is that the section pushes the Add to Cart button further down the page.\n\n\n\n\n\n\n\nBelow summary\n\n\n\nThe section moves out of the summary column and sits lower down the page, near the description. Shoppers reach it after they\'ve read through the product details, so it feels less like an interruption.\n\n\n\n\n\n\n\nHow Your Theme Affects the Result\n\n\n\nThemes build product pages in different ways, so the same option can land in slightly different spots from one theme to the next.\n\n\n\nTwo things are worth knowing:\n\n\n\n\nOn some themes, Below title and Below price land in the same place, because the theme shows the title and price together as one block.\n\n\n\nOn themes that arrange the summary their own way, CartFlows adjusts to match, so the section still lands where the option describes rather than at the bottom of everything.\n\n\n\n\nThe reliable approach is to pick an option, save, and view the product page. Switching to a different option takes only a moment if the first one isn\'t right.\n\n\n\nChoosing the Right Spot\n\n\n\nThere\'s no single best answer, so it\'s worth thinking about the product.\n\n\n\n\nPick After Add-to-Cart button when the add-ons are a natural extra at the point of purchase, such as accessories or refills.\n\n\n\nPick Below title or Below price when the companions are part of the decision itself, such as a starter kit or a matching set.\n\n\n\nPick Below summary for higher-priced products where shoppers read the details first and you\'d rather not crowd the Add to Cart button.\n\n\n\n\nYou can mix these across your catalog. Nothing forces the whole store to use the same spot.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:71:\"https://cartflows.com/docs/frequently-bought-together-widget-placement/\";s:4:\"slug\";s:43:\"frequently-bought-together-widget-placement\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-25T13:45:03+05:30\";s:8:\"category\";a:1:{i:0;s:26:\"frequently-bought-together\";}}i:8;O:8:\"stdClass\":8:{s:2:\"id\";i:77950;s:5:\"title\";s:55:\"Using Frequently Bought Together with Variable Products\";s:7:\"content\";s:3569:\"Frequently Bought Together works with variable products on both sides of the offer. The product showing the section can be variable, and the companion products you offer can be variable too.\n\n\n\nThis guide covers what shoppers see when a companion has variations, what gets left out and why, and how to offer one specific variation instead of the whole product.\n\n\n\nHow It Works\n\n\n\nA variable product has options the shopper must choose before it can be added to the cart, such as a size or a colour. Frequently Bought Together handles that by asking for the choice inside the section itself.\n\n\n\n\nCompanion products with variations show a dropdown under the product name.\n\n\n\nUntil a choice is made, the price shows as a From amount, based on the cheapest variation.\n\n\n\nThe button stays unavailable until every ticked product has its options chosen.\n\n\n\n\nNothing is added to the cart until each selected product has enough information to be added properly.\n\n\n\nSetting It Up on a Variable Product\n\n\n\nThe setup is the same as for a simple product. The Frequently Bought Together tab appears on both simple and variable products.\n\n\n\nStep 1. Go to Products and open the variable product you want the section to appear on.\n\n\n\nStep 2. Scroll to the Product data box and click the Frequently Bought Together tab, then turn on Enable Widget.\n\n\n\n\n\n\n\nStep 3. Search for the companion products you want to offer, exactly as you would on a simple product.\n\n\n\nYour shopper still chooses the main product\'s own options using the normal selectors on the product page. The section doesn\'t duplicate those, it only asks about the companions.\n\n\n\nOffering One Specific Variation\n\n\n\nSometimes you don\'t want to offer a whole product with all its choices. If you sell a coffee in three sizes and only want to offer the small one as an add-on, you can add that single variation as the companion.\n\n\n\nThe product search in the panel finds individual variations as well as whole products, so you can pick the exact one you want. Search for the product name and the matching variations appear alongside it in the results.\n\n\n\n\n\n\n\nChoosing a specific variation means the shopper sees no dropdown for it. The product appears at its own fixed price and can be ticked straight away, which makes for a quicker decision.\n\n\n\nWhat Shoppers See\n\n\n\nWhen a companion has variations, its row shows a Choose an option dropdown listing every variation that can actually be bought, each with its own price.\n\n\n\nTwo things change as the shopper makes choices:\n\n\n\n\nThe From price is replaced by the real price of the chosen variation.\n\n\n\nThe total and the button label update to include it.\n\n\n\n\nIf a shopper ticks a variable product without choosing an option, the button tells them to select options before continuing, so nothing can be added half-configured.\n\n\n\n\n\n\n\nProducts That Are Left Out\n\n\n\nSome variations and products are deliberately not offered, so shoppers never meet an option they cannot buy.\n\n\n\n\nVariations that are out of stock are not listed in the dropdown.\n\n\n\nVariations that need extra input from the shopper, such as an attribute set to \"Any\" rather than a specific value, are not listed, because the section has no way to collect that detail.\n\n\n\nA variable product with no purchasable variations left is dropped from the section entirely rather than shown as unavailable.\n\n\n\n\nThat last point is worth knowing when you\'re setting things up. If a companion you added doesn\'t appear on the product page at all, check whether its variations are in stock and purchasable.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:72:\"https://cartflows.com/docs/frequently-bought-together-variable-products/\";s:4:\"slug\";s:44:\"frequently-bought-together-variable-products\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-25T13:44:25+05:30\";s:8:\"category\";a:1:{i:0;s:26:\"frequently-bought-together\";}}i:9;O:8:\"stdClass\":8:{s:2:\"id\";i:77943;s:5:\"title\";s:52:\"Auto Suggest for WooCommerce Upsells and Cross-sells\";s:7:\"content\";s:2767:\"CartFlows adds an Auto Suggest button to WooCommerce\'s own Upsells and Cross-sells fields, so you can fill them from suggestions instead of searching for every product by hand.\n\n\n\nThis guide covers where to find it, how to review the suggestions, and how it differs from filling those fields yourself.\n\n\n\nHow It Works\n\n\n\nWooCommerce already has Upsells and Cross-sells fields on every product, and they work exactly as they always have. Auto Suggest simply offers products to put in them, based on what customers buy alongside the product you are editing.\n\n\n\n\nYou open the suggestions from a button next to each field.\n\n\n\nSuggestions open in a panel, and you accept or reject each one.\n\n\n\nAccepted products drop straight into the WooCommerce field, ready to save.\n\n\n\n\nNothing is added without you accepting it, and nothing you already have in either field is suggested again.\n\n\n\nWhat You Need First\n\n\n\nAuto Suggest comes with CartFlows Pro. Three things need to be in place before the button will return anything:\n\n\n\n\nCartFlows Pro installed and active\n\n\n\nYour CartFlows licence activated\n\n\n\nYour CartFlows account connected\n\n\n\n\nWhere to Find It\n\n\n\nStep 1. Go to Products and open the product you want to set up.\n\n\n\nStep 2. In the Product data box, click the Linked Products tab. You\'ll see an Auto Suggest button beside both the Upsells and the Cross-sells field.\n\n\n\n\n\n\n\nEach button only fills its own field, so use the one next to Upsells for upsells and the one next to Cross-sells for cross-sells.\n\n\n\nAccepting Suggestions\n\n\n\nStep 3. Click Auto Suggest next to the field you want to fill. A panel slides in from the right, headed Auto Suggest Upsells or Auto Suggest Cross-sells so you always know which field you are filling.\n\n\n\n\n\n\n\nStep 4. Each suggestion shows the product image, its name, a badge explaining why it was picked, and the price. A percentage means customers genuinely buy the two together, while Popular in your store means there is not enough buying history yet, so a strong seller was offered instead.\n\n\n\nStep 5. Click Accept to add a product, or Reject to drop it from the list. Rejecting only clears it from this panel, it does not change your product.\n\n\n\nStep 6. Accepted products appear immediately in the WooCommerce field behind the panel.\n\n\n\n\n\n\n\nStep 7. Close the panel and click Update to save the product. Until you do, nothing is saved.\n\n\n\nGetting a Different Set\n\n\n\nIf none of the suggestions suit, Regenerate all fetches a fresh batch. It leaves out both what is already in the field and what is currently on screen, so you get different products rather than the same list again.\n\n\n\nOnce every suggestion has been dealt with, the panel tells you that you are all set, and offers to regenerate or close.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:72:\"https://cartflows.com/docs/auto-suggest-woocommerce-upsells-cross-sells/\";s:4:\"slug\";s:44:\"auto-suggest-woocommerce-upsells-cross-sells\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-24T17:12:27+05:30\";s:8:\"category\";a:1:{i:0;s:26:\"frequently-bought-together\";}}i:10;O:8:\"stdClass\":8:{s:2:\"id\";i:77914;s:5:\"title\";s:55:\"How to Use Auto Suggest with Frequently Bought Together\";s:7:\"content\";s:3298:\"Auto Suggest picks the companion products for you, based on what customers actually buy alongside a product in your store. Instead of searching for each one by hand, you generate a list and keep the ones you want.\n\n\n\nThis guide covers what you need before you start, how to generate and review suggestions, and how to read what each one tells you.\n\n\n\nWhat You Need First\n\n\n\nAuto Suggest is part of CartFlows Pro, and three things have to be in place before the tab will run:\n\n\n\n\nCartFlows Pro installed and active\n\n\n\nYour CartFlows licence activated\n\n\n\nYour CartFlows account connected\n\n\n\n\nUntil all three are done, the Auto Suggest tab shows a prompt instead, asking you either to upgrade to CartFlows Pro or to connect your account. Picking companion products by hand keeps working either way.\n\n\n\nHow Auto Suggest Works\n\n\n\nAuto Suggest looks at what your customers have bought together with the product you are editing, and offers the products that come up most often. When a product is too new or too quiet to have that history, it falls back to popular and related products from your catalogue instead.\n\n\n\n\nNothing is added to your product page automatically. You accept the suggestions you want.\n\n\n\nProducts already in your companion list are never suggested again.\n\n\n\nSuggestions are kept for up to 24 hours, so opening the tab again shows the same list until you ask for a fresh one.\n\n\n\n\nHow to Generate Suggestions\n\n\n\nStep 1. Go to Products, open the product you want companions for, and scroll to the Product data box.\n\n\n\nStep 2. Click the Frequently Bought Together tab and turn on Enable Widget.\n\n\n\nStep 3. Click the Auto Suggest tab, then click Generate suggestions. Analysing your catalogue takes a few seconds.\n\n\n\n\n\n\n\nStep 4. Review the list. Each row shows the product image and name, a badge explaining why it was suggested, and the price.\n\n\n\n\n\n\n\nStep 5. Click Accept on the ones you want. Each accepted product moves straight into the Products tab, and the count on that tab goes up as you go.\n\n\n\nStep 6. Click Reject on anything that does not fit. That only removes it from this list, it does not add it anywhere.\n\n\n\nStep 7. Click Update to save the product. Accepted suggestions are not live on your store until you do.\n\n\n\nReading the Badges\n\n\n\nThe badge next to each product name tells you why Auto Suggest picked it:\n\n\n\n\nA match percentage means the suggestion comes from real buying patterns in your store. The higher the number, the more often the two products are bought together.\n\n\n\nPopular in your store means there was not enough buying history for this product yet, so Auto Suggest offered a strong seller instead.\n\n\n\nNew means the product was added to your catalogue recently.\n\n\n\n\nA new store, or a product nobody has bought yet, will mostly return Popular in your store badges. That is expected, and the suggestions get sharper as orders come in.\n\n\n\nGetting a Fresh Set\n\n\n\nRegenerate all, at the top right of the list, fetches a new batch. It leaves out both the products you have already accepted and the ones currently on screen, so you get genuinely different options rather than the same list again.\n\n\n\nUse it when the first batch does not suit the product, or when you have added new stock and want Auto Suggest to take another look.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:67:\"https://cartflows.com/docs/auto-suggest-frequently-bought-together/\";s:4:\"slug\";s:39:\"auto-suggest-frequently-bought-together\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-25T13:42:44+05:30\";s:8:\"category\";a:1:{i:0;s:26:\"frequently-bought-together\";}}i:11;O:8:\"stdClass\":8:{s:2:\"id\";i:77834;s:5:\"title\";s:52:\"Frequently Bought Together vs Order Bumps vs Upsells\";s:7:\"content\";s:4114:\"CartFlows gives you three ways to put an extra product in front of a shopper: Frequently Bought Together, Order Bumps, and one-click Upsells. They look similar on paper, but each one catches the shopper at a different moment and suits a different kind of offer.\n\n\n\nThis guide explains what each one does, what it needs, and how to pick the right one.\n\n\n\nHow the Three Offers Differ\n\n\n\nThe simplest way to tell them apart is when the shopper sees them.\n\n\n\n\nFrequently Bought Together appears on the product page, before anything reaches the cart.\n\n\n\nOrder Bumps appear on the checkout page, beside the order summary, while the shopper is paying.\n\n\n\nUpsells appear after payment has gone through, on a page of their own.\n\n\n\n\nThat timing decides everything else: how much you can ask for, how much it interrupts the purchase, and what happens if the shopper says no.\n\n\n\nFrequently Bought Together\n\n\n\nThis shows a short list of companion products on a product page, each with a checkbox. The shopper ticks what they want and one button adds the whole selection to the cart. You pick the companions per product, and you choose where the section sits on the page.\n\n\n\nIt is the only one of the three available on the free plugin. Choosing companion products by hand works on free CartFlows, while Auto Suggest, which picks the companions for you, needs CartFlows Pro with your account connected.\n\n\n\n\n\n\n\nReach for it when the extra product only makes sense next to a particular item, like a lamp with a desk or filters with a coffee machine. It works best for small, obvious additions the shopper can decide on without much thought.\n\n\n\nOrder Bumps\n\n\n\nAn Order Bump is a single offer shown on the checkout page, usually as a highlighted box with a tick box. Accepting it adds the product to the order without leaving the page or re-entering anything.\n\n\n\nOrder Bumps need CartFlows Pro, and they appear on a CartFlows Checkout step rather than the default WooCommerce checkout page. You can also run an A/B test on a bump to compare two versions and see which one people accept more often.\n\n\n\n\n\n\n\nReach for it when you have one low-priced, low-effort add-on that suits almost any order, such as gift wrapping, express shipping, or a small accessory. \n\n\n\nOne-Click Upsells\n\n\n\nAn Upsell is a full page of its own that appears after the shopper has paid. Because the payment details from the original order are already on file, accepting the offer takes one click with nothing to fill in again. If the shopper declines, you can show a Downsell, usually the same offer at a lower price or a smaller quantity.\n\n\n\nUpsells need CartFlows Pro and a payment gateway that supports charging the customer a second time. The original order is already complete by this point, so nothing the shopper does on the upsell page puts that first purchase at risk.\n\n\n\n\n\n\n\nReach for it when the offer is bigger, needs explaining, or would clutter the checkout page. This is the right home for an upgrade, a bulk deal, or a related product that deserves its own pitch.\n\n\n\nWhich One to Use\n\n\n\nStart from what you are offering and how much thought it needs:\n\n\n\n\nA companion product tied to one specific item belongs in Frequently Bought Together, where the shopper is already looking at that item.\n\n\n\nA small extra that suits nearly every order belongs in an Order Bump, where accepting it costs one tick.\n\n\n\nAnything that needs a paragraph of persuasion belongs in an Upsell, where it has room and cannot disrupt the sale you already made.\n\n\n\n\nIf an offer would make the shopper hesitate at checkout, move it to an Upsell. If it is so obvious that it barely needs explaining, it probably belongs on the product page instead.\n\n\n\nUsing Them Together\n\n\n\nNothing stops you using all three in the same funnel, and a shopper can meet each one in turn: companions on the product page, a bump at checkout, an upsell after paying.\n\n\n\nIf you do, give each stage a different product. Seeing the same item offered three times reads as pestering, and every extra offer costs a little goodwill. A good rule is one decision per stage.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:77:\"https://cartflows.com/docs/frequently-bought-together-vs-order-bumps-upsells/\";s:4:\"slug\";s:49:\"frequently-bought-together-vs-order-bumps-upsells\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-24T17:11:05+05:30\";s:8:\"category\";a:1:{i:0;s:26:\"frequently-bought-together\";}}i:12;O:8:\"stdClass\":8:{s:2:\"id\";i:77764;s:5:\"title\";s:36:\"CartFlows Frequently Bought Together\";s:7:\"content\";s:4979:\"CartFlows lets you show a Frequently Bought Together section on any product page, where shoppers can add a product and its companion products to the cart in one step. You choose which products appear, where the section sits on the page, and how the extras are added to the cart.\n\n\n\nThis guide covers how the section works, how to set it up on a product, and what your shoppers see.\n\n\n\nHow Frequently Bought Together Works\n\n\n\nYou turn the section on for one product at a time and pick the companion products you want offered alongside it. The section then appears on that product\'s page with the main product listed first.\n\n\n\n\nThe main product is always the first row, marked (this item), and shoppers cannot untick it.\n\n\n\nCompanion products sit below it, each with its own checkbox.\n\n\n\nThe total updates as boxes are ticked, and a single button adds everything to the cart at once.\n\n\n\n\nShoppers pick up two or three related products in one action instead of visiting each product page separately.\n\n\n\nHow to Set Up Frequently Bought Together\n\n\n\nStep 1. From the WordPress admin, go to Products and open the product you want the section to appear on.\n\n\n\nStep 2. Scroll down to the Product data box and click the Frequently Bought Together tab.\n\n\n\n\n\n\n\nStep 3. Turn on Enable Widget at the top right of the panel. The product list and the settings below it appear once the toggle is on.\n\n\n\nStep 4. On the Products tab, search for each companion product you want to offer. Every product you pick is added as a row showing its image, name, price and stock status.\n\n\n\nStep 5. Drag the handle at the left of a row to reorder it. The first row is the first companion shoppers see.\n\n\n\nStep 6. Set the options below the product list:\n\n\n\n\nAdd products separately — When this is on, each product goes into the cart as its own item. When it is off, the extras stay tied to the main product, so removing the main product from the cart removes them too.\n\n\n\nProduct selecting method — Multiple lets shoppers tick as many companions as they want. Single limits them to one companion at a time.\n\n\n\nCustom quantity — Adds a quantity box to each row. You set the starting quantity, and shoppers can change it before adding to the cart.\n\n\n\nWidget placement — Choose where the section appears on the product page: After Add-to-Cart button, Below title, Below price, or Below summary.\n\n\n\n\n\n\n\n\nStep 7. Click Update to save the product.\n\n\n\nThe section is now live on that product\'s page.\n\n\n\nThe Section in Action\n\n\n\nOn the product page, shoppers see a Frequently bought together heading with the main product at the top, ticked and labelled (this item). Companion products follow, and the total next to the button reflects everything currently ticked.\n\n\n\n\n\n\n\nA few details worth knowing:\n\n\n\n\nOnly three companions show at first. If you added more, a Show more link reveals the rest, and Show fewer collapses them again.\n\n\n\nThe total and the button label both count the main product. Ticking two companions gives you Total for 3 items and a button reading Add 3 items to cart, which becomes Add all 4 items to cart once everything is ticked.\n\n\n\nA companion product with variations shows a Choose an option dropdown and a From price. Shoppers pick a variation before that product can be added.\n\n\n\nA companion that is out of stock appears greyed out with an Out of stock badge and cannot be selected.\n\n\n\nAfter adding, a confirmation message with a View cart link appears and the cart total updates without reloading the page.\n\n\n\n\nAuto Suggest with CartFlows Pro\n\n\n\nThe Auto Suggest tab picks companion products for you based on what customers actually buy together in your store. It needs CartFlows Pro active with its licence activated, and your CartFlows account connected. Until all three are in place the tab shows a prompt instead, either to upgrade to CartFlows Pro or to connect your account.\n\n\n\nStep 1. Open the Frequently Bought Together tab on a product and click Auto Suggest.\n\n\n\nStep 2. Click Generate suggestions. Analysing your catalogue takes a few seconds.\n\n\n\nStep 3. The suggestions appear in the tab itself, one product per row. Each row carries a badge saying why it was picked: a match percentage when the product is genuinely bought alongside this one, or Popular in your store when there is not enough buying history yet.\n\n\n\n\n\n\n\nStep 4. Click Accept to add a suggestion to your product list, or Reject to drop it from the batch. Regenerate all fetches a fresh set.\n\n\n\nStep 5. When every suggestion has been reviewed, the tab returns to the Generate suggestions view. Click Update to save the product.\n\n\n\nAccepted products land in the Products tab, where you can reorder them, set quantities and remove them like any product you picked yourself. If a product does not have enough purchase history yet, Auto Suggest tells you so and offers similar and popular products instead. Suggestions are kept for up to 24 hours before a fresh set is generated.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:64:\"https://cartflows.com/docs/cartflows-frequently-bought-together/\";s:4:\"slug\";s:36:\"cartflows-frequently-bought-together\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-25T13:43:35+05:30\";s:8:\"category\";a:1:{i:0;s:26:\"frequently-bought-together\";}}i:13;O:8:\"stdClass\":8:{s:2:\"id\";i:77543;s:5:\"title\";s:58:\"How to Create a Direct Buy-Now Checkout Link for a Product\";s:7:\"content\";s:3476:\"CartFlows lets you create a direct link straight to your checkout page with a specific product already added to the cart. Instead of sending customers through your shop or a landing page first, you can share one link, from an ad, an email, or social media, that takes them straight to checkout, ready to buy.\n\n\n\nThis is especially useful for:\n\n\n\n\nRunning ads that go straight to checkout for a single product, skipping the shop page entirely\n\n\n\nSending existing customers a one-click reorder link in an email\n\n\n\nSharing a pre-filled checkout link with a coupon already applied\n\n\n\nLinking to checkout with a specific product variation (like a size or color) already selected\n\n\n\n\nHow It Works\n\n\n\nCartFlows Checkout pages can read a few special parameters from the URL and use them to automatically add products to the cart, apply a coupon, and even pre-fill the customer\'s checkout fields before they type anything.\n\n\n\nYou don\'t need to build this URL by hand. CartFlows Pro includes a Checkout Link Generator that builds it for you.\n\n\n\nStep 1: Open the Checkout Link Generator\n\n\n\nGo to CartFlows &gt;  Store Checkout (or Funnel checkout) in your WordPress dashboard, open the settings for the checkout step, then open the Checkout Link tab.\n\n\n\n\n\n\n\nStep 2: Configure Your Link\n\n\n\nOn this screen, you can select:\n\n\n\n\nCheckout Step — which published checkout step the link should point to\n\n\n\nProduct — the product to pre-add to the cart, including a specific variation of a variable product (e.g. a particular size or color)\n\n\n\nCoupon — optionally auto-apply a WooCommerce coupon (the generator shows its discount type, amount, and expiry so you can confirm you\'ve picked the right one)\n\n\n\nCustomer Details — optionally pre-fill any billing or shipping field on that checkout step, including custom fields added via the Checkout Field Editor\n\n\n\n\nStep 3: Copy and Use the Generated Link\n\n\n\nCopy the link and use it in ad campaigns, email marketing, or social posts.\n\n\n\n\n\n\n\nWhen a customer opens it, they land on checkout with the product already in the cart, any coupon applied, and any pre-filled details in place, ready to complete their order.\n\n\n\nBuilding a Link Manually\n\n\n\nParameterDescriptionwcf-add-to-cartProduct ID (or variation ID) to add to the cart. Separate multiple IDs with commas.wcf-qtyQuantity for each product listed in wcf-add-to-cart, in the same order, comma-separated. Defaults to 1 if omitted.couponCoupon code to auto-apply.Any checkout field keyPre-fills that field, e.g. billing_first_name, billing_email, billing_address_1, shipping_address_1, or any custom field from the Checkout Field Editor.\n\n\n\nExample:\n\n\n\nhttps:&#47;&#47;yourstore.com/checkout-page/?wcf-add-to-cart=1234\n&amp;wcf-qty=2&amp;coupon=SAVE10&amp;billing_email=jane@example.com\n\n\n\nThis link adds product ID 1234 (quantity 2) to the cart, applies the SAVE10 coupon, and pre-fills the billing email field with jane@example.com.\n\n\n\nNote: If you add a shipping_* field to the link (for example shipping_address_1), CartFlows automatically checks the \"Ship to a different address\" option on checkout so the pre-filled shipping fields are visible right away, instead of staying hidden behind a collapsed section.\n\n\n\nNotes\n\n\n\n\nFor variable products, select the specific variation you want in the Checkout Link Generator (or use that variation\'s own product ID in wcf-add-to-cart if building the link manually), rather than the parent product ID.\n\n\n\nThis feature requires CartFlows Pro.\";s:3:\"url\";s:86:\"https://cartflows.com/docs/how-to-create-a-direct-buy-now-checkout-link-for-a-product/\";s:4:\"slug\";s:58:\"how-to-create-a-direct-buy-now-checkout-link-for-a-product\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-04T16:53:51+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:14;O:8:\"stdClass\":8:{s:2:\"id\";i:76996;s:5:\"title\";s:52:\"How to Show Taxes / Tax-Inclusive Prices in the Cart\";s:7:\"content\";s:2019:\"Modern Cart supports displaying tax information inside the cart tray, including itemized taxes and tax-inclusive pricing. The behavior follows your WooCommerce tax settings. Whether you can toggle the tax row on or off depends on whether you\'re using Modern Cart Free or Pro.&nbsp;\n\n\n\nFree vs Pro Behavior\n\n\n\nIn Modern Cart Pro, there\'s a \"Show Tax\" toggle under WooCommerce &gt; Modern Cart &gt; General tab. You can turn it on or off directly from settings, no code needed.\n\n\n\nIn Modern Cart Free, there\'s no such toggle. The tax row is always shown by Default.\n\n\n\nEnabling Tax Display (Pro)\n\n\n\n\nGo to WooCommerce&gt; Modern Cart &gt; Settings &gt; General\n\n\n\nFind the \"Show Tax\" toggle\n\n\n\nEnable it\n\n\n\nSave your changes\n\n\n\n\n\n\n\n\nConfiguring Tax Display in WooCommerce\n\n\n\nModern Cart inherits tax display settings from WooCommerce.\n\n\n\n\nGo to WooCommerce &gt; Settings &gt; Tax\n\n\n\nUnder \"Tax options,\" set \"Display prices during cart and checkout\" to \"Including tax\" or \"Excluding tax.\" This is the setting that controls Modern Cart\'s cart tray specifically (the separate \"Display prices in the shop\" setting only affects product and shop pages, not the cart).\n\n\n\nIn the same \"Tax options\" section, set \"Display tax totals\" to \"As a single total\" or \"Itemized.\"\n\n\n\nSave changes\n\n\n\n\n\n\n\n\nHere is the Doc on Setting up Taxes in WooCommerce.\n\n\n\nTax-Inclusive Pricing\n\n\n\nWhen WooCommerce is set to display prices including tax, Modern Cart adds a note next to the cart total showing the actual tax amount and label, for example \"(includes $5.00 VAT).\" This is calculated automatically and is not shown as a percentage.&nbsp;\n\n\n\n\n\n\n\nCustomizing Tax Display (Developer)\n\n\n\nUse these filters to customize tax output:\n\n\n\n// Customize the tax HTML output\nadd_filter( \'moderncart_cart_totals_vat_total_html\', function( $html ) {\n    return \'&lt;span class=\"my-tax-row\"&gt;\' . $html . \'&lt;/span&gt;\';\n});\n\n\n\nRefer to this documentation to know how to add custom code to website: How and Where to Add Custom JS, CSS, and PHP Codes\";s:3:\"url\";s:78:\"https://cartflows.com/docs/how-to-show-taxes-tax-inclusive-prices-in-the-cart/\";s:4:\"slug\";s:50:\"how-to-show-taxes-tax-inclusive-prices-in-the-cart\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-22T08:03:57+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:15;O:8:\"stdClass\":8:{s:2:\"id\";i:76943;s:5:\"title\";s:50:\"How to Display Shipping Costs Inside the Cart Tray\";s:7:\"content\";s:1954:\"Modern Cart can display estimated shipping costs inside the cart tray, giving customers visibility into shipping before they reach checkout. This works in both the free and Pro versions, though the two behave a little differently.&nbsp;\n\n\n\nFree vs. Pro Behavior\n\n\n\n\nFree version: Shipping is shown automatically whenever a shipping method applies to the cart. There\'s no toggle for this in the free version\'s settings, it just works out of the box.\n\n\n\nPro version: Adds a \"Show Shipping\" toggle under Cart settings so you can turn the shipping row on or off. This toggle is off by default, so Pro users need to enable it manually.\n\n\n\n\nEnabling Shipping Display(Pro)\n\n\n\n\nGo to Modern Cart &gt; Settings in your WordPress dashboard\n\n\n\nNavigate to the General tab\n\n\n\nFind the \"Show Shipping\" toggle\n\n\n\nEnable it\n\n\n\nSave your changes\n\n\n\n\n\n\n\n\nWooCommerce Shipping Configuration\n\n\n\nFor shipping costs to appear in the cart tray, you must have at least one shipping zone and shipping method configured in WooCommerce.\n\n\n\nSteps to verify:\n\n\n\n\nGo to WooCommerce &gt; Settings &gt; Shipping\n\n\n\nEnsure at least one Shipping Zone is set up with an active shipping method\n\n\n\nIf using flat rate or free shipping, make sure the rates are saved\n\n\n\n\n\n\n\n\nHere is the WooCommerce Documentation on Setting up Shipping Zones\n\n\n\nHow It Works\n\n\n\nModern Cart calls WooCommerce\'s calculate_shipping() and displays the result using get_cart_shipping_total(). If no shipping method applies (e.g., customer\'s address not yet entered), the shipping row will be hidden.\n\n\n\nCustomizing Shipping HTML (Developer)\n\n\n\nUse the moderncart_cart_totals_shipping_html filter to customize the shipping row output:\n\n\n\nadd_filter( \'moderncart_cart_totals_shipping_html\', function( $html ) {\n    return \'&lt;span class=\"custom-shipping\"&gt;\' . $html . \'&lt;/span&gt;\';\n});\n\n\n\nRefer to this documentation to know how to add custom code to website: How and Where to Add Custom JS, CSS, and PHP Codes\";s:3:\"url\";s:78:\"https://cartflows.com/docs/how-to-display-shipping-costs-inside-the-cart-tray/\";s:4:\"slug\";s:50:\"how-to-display-shipping-costs-inside-the-cart-tray\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-22T07:36:31+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:16;O:8:\"stdClass\":8:{s:2:\"id\";i:76911;s:5:\"title\";s:52:\"How to Add a Modern Cart Trigger to a WordPress Menu\";s:7:\"content\";s:2309:\"Modern Cart lets you turn any menu item, header cart icon, or other clickable element into a cart trigger using its built-in Use Custom Trigger setting. This opens the cart tray right from your navigation menu, with no custom JavaScript required.\n\n\n\nNote\nThis feature is available only in the Modern Cart Pro version.\n\n\n\n\nMethod 1 - Custom Menu Item + Use Custom Trigger\n\n\n\nStep 1: Add the menu item\n\n\n\n1. Go to Appearance > Menus.2. Open Screen Options (top right) and tick CSS Classes (this field is hidden by default).\n\n\n\n\n\n\n\n3. Expand the Custom Links section, set the URL to # and the Link Text to Cart (or paste a cart emoji to show an icon).4. Click Add to Menu.5. Enter a class in the menu item’s CSS Classes field, e.g. my-cart-trigger.6. Save the menu.\n\n\n\n\n\n\n\nStep 2: Register the trigger in Modern Cart\n\n\n\n\nGo to WooCommerce &gt; Modern Cart &gt; Floating Cart Icon.\n\n\n\nScroll to Use Custom Trigger and enter your selector: .my-cart-trigger (you can add multiple, comma-separated, e.g. .my-cart-trigger, #my-id).\n\n\n\nSave. Clicking the menu item now opens the cart tray.\n\n\n\n\n\n\n\n\nMethod 2 - Cart Icon in a Header Built with a Page Builder or Theme\n\n\n\nIf your header is built with a page builder (Elementor including Ultimate Addons for Elementor, Bricks, Beaver Builder, Spectra) or your theme’s header builder (Astra, Kadence, etc.), you can use the cart icon there as the trigger:\n\n\n\n\nAdd an Icon, Button, or Cart widget to your header and choose a cart icon.\n\n\n\nIn that element’s settings, add a CSS class or ID, usually under Advanced &gt; CSS Classes or CSS ID, e.g. my-custom-cart.\n\n\n\nGo to WooCommerce &gt; Modern Cart &gt; Floating Cart Icon, scroll to Use Custom Trigger, and enter that selector (.my-custom-cart).\n\n\n\nSave. Clicking the header cart icon now opens the cart tray.\n\n\n\n\nTip: On Astra theme, the theme’s built-in header cart icon opens Modern Cart automatically, with no setup needed.\n\n\n\nNotes\n\n\n\n\nThe floating cart launcher is the primary intended trigger. Menu and header triggers use the Use Custom Trigger setting.\n\n\n\nThe floating button and custom triggers work independently; hiding the floating button does not disable your custom triggers.\n\n\n\nAlways test on both desktop and mobile after adding triggers.\n\n\n\n\nHere is the related Doc on the Custom Trigger feature.\";s:3:\"url\";s:80:\"https://cartflows.com/docs/how-to-add-a-modern-cart-trigger-to-a-wordpress-menu/\";s:4:\"slug\";s:52:\"how-to-add-a-modern-cart-trigger-to-a-wordpress-menu\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-23T10:12:59+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:17;O:8:\"stdClass\":8:{s:2:\"id\";i:76858;s:5:\"title\";s:50:\"How to Show / Hide Product Images in the Cart Tray\";s:7:\"content\";s:1477:\"Modern Cart displays product images inside the cart tray by default. You can control whether images are shown and adjust their size from the plugin settings.\n\n\n\nConfiguring Product Image Size\n\n\n\n\nGo to Modern Cart > Settings in your WordPress dashboard\n\n\n\nNavigate to the Styling tab, and scroll to the Miscellaneous section\n\n\n\nFind the \"Product Image Size\" setting\n\n\n\nChoose from Small, Medium, or Large\n\n\n\nSave your changes\n\n\n\n\n\n\n\n\nHiding Product Images on Mobile (Pro)\n\n\n\nModern Cart Pro includes an option to hide product images on mobile devices to improve performance and save screen space.\n\n\n\n\nGo to Modern Cart > Settings, General tab\n\n\n\nFind the \"Show Product Image In Mobile View\" toggle\n\n\n\nToggle it off to hide images on mobile\n\n\n\nSave your changes\n\n\n\n\n\n\n\n\nHiding Images via Code (Developer)\n\n\n\nTo hide product images programmatically, use the moderncart_woocommerce_cart_item_thumbnail filter:\n\n\n\nadd_filter( \'moderncart_woocommerce_cart_item_thumbnail\', function( $html, $cart_item, $cart_item_key ) {\n    return \'\'; // Return empty string to hide the image\n}, 10, 3 );\n\n\n\nTo replace the image with a custom one:\n\n\n\nadd_filter( \'moderncart_woocommerce_cart_item_thumbnail\', function( $html, $cart_item, $cart_item_key ) {\n    return \'&lt;img src=\"\' . get_template_directory_uri() . \'/custom-image.png\" alt=\"Product\" /&gt;\';\n}, 10, 3 );\n\n\n\nPlease refer to this documentation to know how to add custom code to a website: https://cartflows.com/docs/add-custom-codes/\";s:3:\"url\";s:76:\"https://cartflows.com/docs/how-to-show-hide-product-images-in-the-cart-tray/\";s:4:\"slug\";s:48:\"how-to-show-hide-product-images-in-the-cart-tray\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-17T21:44:49+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:18;O:8:\"stdClass\":8:{s:2:\"id\";i:76795;s:5:\"title\";s:35:\"RTL Language Support in Modern Cart\";s:7:\"content\";s:1430:\"Modern Cart includes built-in RTL (Right-to-Left) language support. When your WordPress site is set to an RTL language such as Arabic, Hebrew, or Persian, Modern Cart automatically loads the appropriate RTL stylesheets and adjusts its layout accordingly.\n\n\n\nHow RTL Support Works\n\n\n\nModern Cart detects RTL direction automatically using WordPress\'s built-in is_rtl() function. No manual configuration is needed. The plugin ships with dedicated RTL CSS files:\n\n\n\n\ncart-rtl.css / cart-rtl.min.css — Cart tray layout\n\n\n\nadmin-notices-rtl.css — Admin notices\n\n\n\nsplide-rtl.css — Product recommendations carousel\n\n\n\nsettings-rtl.css — Admin settings panel\n\n\n\n\nEnabling RTL\n\n\n\nFollow these steps to enable RTL language support:\n\n\n\n\nGo to WordPress Dashboard > Settings > General\n\n\n\nSet your Site Language to an RTL language (e.g., Arabic, Hebrew)\n\n\n\nSave changes. WordPress will automatically switch to RTL mode.\n\n\n\nModern Cart will load RTL stylesheets automatically — no additional setup required.\n\n\n\n\n\n\n\n\nPercentage Display in RTL\n\n\n\nModern Cart also adjusts text formatting for RTL. For example, savings percentages are displayed as \"%10\" in RTL mode instead of \"10%\" to match RTL typography conventions. This is handled automatically.\n\n\n\nNotes\n\n\n\n\nRTL support works with both Modern Cart Starter and Modern Cart Pro.\n\n\n\nIf you notice layout issues in RTL mode, clear your caching plugin\'s cache after switching languages.\";s:3:\"url\";s:63:\"https://cartflows.com/docs/rtl-language-support-in-modern-cart/\";s:4:\"slug\";s:35:\"rtl-language-support-in-modern-cart\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-12T13:00:41+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:19;O:8:\"stdClass\":8:{s:2:\"id\";i:76716;s:5:\"title\";s:51:\"How to Enable/Disable Modern Cart on Specific Pages\";s:7:\"content\";s:1126:\"Modern Cart lets you control where the cart appears on your site. You can enable it everywhere, restrict it to WooCommerce pages, target specific pages, or disable it entirely.\n\n\n\nControlling Where Modern Cart Appears\n\n\n\n\nGo to WooCommerce &gt; Modern Cart in your WordPress dashboard.\n\n\n\nClick the General tab.\n\n\n\nFind the Enable Modern Cart dropdown.\n\n\n\nChoose one of the following options:\n\nAll Pages (Default) — The cart appears on every page of your site.\n\n\n\nWooCommerce Pages Only — The cart appears only on WooCommerce-related pages such as the shop, product, and cart pages.\n\n\n\nSelected Pages (Pro) — The cart appears only on the pages you manually choose.\n\n\n\nDisabled — The cart is hidden everywhere.\n\n\n\n\n\n\n\n\n\n\nEnabling the Cart on Selected Pages Only (Pro)\n\n\n\nIf you choose Selected Pages, a page selector field will appear where you can pick exactly which pages should show the Modern Cart slide-out. All other pages will not display the cart.\n\n\n\n\nSet Enable Modern Cart to Selected Pages.\n\n\n\nIn the Selected Pages field that appears, search for and select the pages where you want Modern Cart to be active.\";s:3:\"url\";s:79:\"https://cartflows.com/docs/how-to-enable-disable-modern-cart-on-specific-pages/\";s:4:\"slug\";s:51:\"how-to-enable-disable-modern-cart-on-specific-pages\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-16T16:46:40+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:20;O:8:\"stdClass\":8:{s:2:\"id\";i:76706;s:5:\"title\";s:51:\"Compatibility with Popular Themes and Page Builders\";s:7:\"content\";s:3049:\"Modern Cart is designed to work with most WordPress themes and page builders. This guide covers known compatibility notes and how to resolve common conflicts\n\n\n\nAstra Theme\n\n\n\nAstra includes its own slide-in cart and mobile cart flyout. When Modern Cart is active, it automatically disables Astra\'s native cart to prevent duplicate cart experiences. No manual action is required.\n\n\n\nIf you prefer to use Astra\'s cart instead of Modern Cart, simply deactivate the Modern Cart plugin, there\'s no partial toggle for this since the override applies as a whole.\n\n\n\n\n\n\n\nElementor\n\n\n\nFree Elementor has no cart feature, so there\'s nothing to conflict with there. If you\'re using Elementor Pro\'s Menu Cart widget in dropdown or off-canvas style, note that Modern Cart does not currently detect or override it, so you may see both carts appear. We\'d recommend using only one.\n\n\n\nElementor\'s Maintenance Mode feature will also disable Modern Cart\'s floating cart for visitors while it\'s active. The same happens under WooCommerce Coming Soon, WooCommerce Private Link, and WordPress\'s own core maintenance mode, Modern Cart treats all four the same way. Logged-in admins bypass this check and will always see the cart, even while maintenance mode is on for visitors.\n\n\n\nWooCommerce Blocks\n\n\n\nModern Cart works alongside standard WooCommerce product and shop blocks, and recognizes orders placed through the WooCommerce Blocks (Store API) checkout. If Add to Cart isn\'t opening the cart drawer as expected on a block-based page, check the general AJAX Add to Cart troubleshooting steps (verify Ajax Add to Cart is enabled in settings, check the browser console for script conflicts).\n\n\n\nCaching Plugins\n\n\n\nModern Cart\'s floating cart button and drawer are rendered dynamically and refreshed via AJAX, so most page caching does not interfere with it directly. The one thing to watch for: a fully cached page can serve a stale security nonce baked into its HTML. If that happens, Add to Cart or other cart actions can fail silently or throw an authorization error.\n\n\n\nIf you run into cart actions not working on a cached page:\n\n\n\n\nClear your cache after changing any Modern Cart settings.\n\n\n\nExclude your cart and checkout pages from full-page caching, since these are the pages most likely to be loaded from an older cached nonce.\n\n\n\nIf the issue persists on other pages too, check your caching plugin\'s settings for a way to keep nonces fresh (most modern caching plugins handle this automatically, but older or aggressive configurations can miss it).\n\n\n\n\nOther Themes and Builders\n\n\n\nModern Cart renders its own cart drawer and floating button independently of your theme, so it works with virtually any WordPress theme.\n\n\n\nIf you still run into a conflict:\n\n\n\n\nSwitch to a default WordPress theme (Storefront or Twenty Twenty-Four) and test.\n\n\n\nIf the cart works with the default theme, the conflict is theme-related. Contact your theme\'s support with the details.\n\n\n\nIf it still doesn\'t work, deactivate other plugins one at a time to identify the conflict.\";s:3:\"url\";s:79:\"https://cartflows.com/docs/compatibility-with-popular-themes-and-page-builders/\";s:4:\"slug\";s:51:\"compatibility-with-popular-themes-and-page-builders\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-10T09:56:07+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:21;O:8:\"stdClass\":8:{s:2:\"id\";i:76606;s:5:\"title\";s:52:\"Troubleshooting Modern Cart: Common Issues and Fixes\";s:7:\"content\";s:3022:\"This guide covers the most common issues users encounter with Modern Cart and the steps to resolve them.\n\n\n\nCart Not Appearing on the Site\n\n\n\nIf the Modern Cart slide-out is not showing at all:\n\n\n\n\nGo to WooCommerce &gt; Modern Cart &gt; General tab.\n\n\n\nCheck the Enable Modern Cart setting. Make sure it is set to All Pages or WooCommerce Pages Only — not Disabled.\n\n\n\nClear your site cache and browser cache, then reload the page.\n\n\n\n\n\n\n\n\nPage Reloads When Adding a Product to Cart\n\n\n\nIf clicking Add to Cart reloads the page instead of opening the slide-out cart:\n\n\n\n\nGo to WooCommerce &gt; Modern Cart &gt; General tab.\n\n\n\nMake sure the Enable AJAX Add To Cart toggle is turned on.\n\n\n\nSave and clear your cache.\n\n\n\n\nCoupon Field Not Showing in Cart\n\n\n\nIf customers cannot see the coupon field inside the cart:\n\n\n\n\nGo to WooCommerce &gt; Modern Cart &gt; General tab.\n\n\n\nFind the Display Coupon Field option and make sure it is set to Minimize or Expand — not Disabled.\n\n\n\nSave your settings.\n\n\n\n\nFree Shipping Bar Not Displaying\n\n\n\nIf the progress bar is not visible even after enabling it:\n\n\n\n\nConfirm the Enable Free Shipping Bar toggle is on in General tab.\n\n\n\nGo to WooCommerce &gt; Settings &gt; Shipping and make sure you have a Free Shipping method with a minimum order amount configured.\n\n\n\nThe bar only appears when a valid free shipping threshold exists in WooCommerce.\n\n\n\n\nCart Not Working in Maintenance Mode\n\n\n\nModern Cart automatically disables itself when your site is in maintenance mode. This includes:\n\n\n\n\nWooCommerce Coming Soon mode\n\n\n\nElementor Maintenance Mode\n\n\n\nWordPress maintenance mode (.maintenance file present)\n\n\n\n\nTo restore Modern Cart, disable maintenance mode from your site settings.\n\n\n\nDuplicate Cart or Conflict with Astra Theme\n\n\n\nIf you are using the Astra theme, it has its own built-in cart flyout. Modern Cart automatically disables Astra\'s cart to prevent duplicates. If you see two cart icons or conflicting behavior, try:\n\n\n\n\nDeactivating Modern Cart temporarily to confirm it is the source of conflict.\n\n\n\nClearing all caches.\n\n\n\nChecking your Astra theme settings to confirm its native cart is not being forced on.\n\n\n\n\nCSS or Styling Looks Broken\n\n\n\nIf the cart styling looks off or is inheriting wrong colors:\n\n\n\n\nIf you use a caching plugin (e.g. WP Rocket, LiteSpeed Cache), exclude Modern Cart\'s CSS from minification and combination. Add /wp-content/plugins/modern-cart/ to the CSS exclusion list.\n\n\n\nClear all caches — plugin cache, server/hosting cache, and browser cache.\n\n\n\nCheck for JavaScript errors in your browser console (F12 &gt; Console tab) and share any errors with support.\n\n\n\n\nGeneral Debugging Tips\n\n\n\n\nAlways test with caching fully disabled first to rule out stale page issues.\n\n\n\nTry switching to a default WordPress theme (Storefront or Twenty Twenty-Four) to check for theme conflicts.\n\n\n\nDeactivate other plugins one by one to identify conflicts.\n\n\n\nCheck your browser console (F12) for JavaScript errors that may point to the root cause.\";s:3:\"url\";s:79:\"https://cartflows.com/docs/troubleshooting-modern-cart-common-issues-and-fixes/\";s:4:\"slug\";s:51:\"troubleshooting-modern-cart-common-issues-and-fixes\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-10T09:53:16+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:22;O:8:\"stdClass\":8:{s:2:\"id\";i:76596;s:5:\"title\";s:35:\"Enable AJAX Add to Cart (Site-wide)\";s:7:\"content\";s:1153:\"By default, Modern Cart enables AJAX Add to Cart on single product pages. This means when a customer clicks \"Add to Cart\", the product is added and the cart updates instantly — without reloading the page. You can enable or disable this behavior from the plugin settings.\n\n\n\nHow to Enable or Disable AJAX Add to Cart\n\n\n\n\nGo to WooCommerce > Modern Cart in your WordPress dashboard.\n\n\n\nClick the General tab.\n\n\n\nFind the Enable AJAX Add To Cart toggle.\n\n\n\nTurn it on to enable AJAX behavior, or turn it off to revert to the default WooCommerce page-reload behavior.\n\n\n\n\n\n\n\n\nWhat Each Setting Does\n\n\n\n\nEnabled (Default) — When a customer clicks Add to Cart on a product page, the item is added silently and the Modern Cart slide-out opens automatically. The page does not reload.\n\n\n\nDisabled — Clicking Add to Cart reloads the page, following the default WooCommerce behavior. The Modern Cart slide-out still works, but it will not open automatically on add-to-cart.\n\n\n\n\nNote\nAJAX Add to Cart applies to single product pages. Shop/Archive pages use WooCommerce\'s own AJAX behavior, which is controlled separately in WooCommerce > Settings > Products.\";s:3:\"url\";s:61:\"https://cartflows.com/docs/enable-ajax-add-to-cart-site-wide/\";s:4:\"slug\";s:33:\"enable-ajax-add-to-cart-site-wide\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-10T09:50:24+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:23;O:8:\"stdClass\":8:{s:2:\"id\";i:76475;s:5:\"title\";s:26:\"Free Shipping Progress Bar\";s:7:\"content\";s:1630:\"The Free Shipping Progress Bar shows customers how much more they need to add to their cart to qualify for free shipping. It encourages higher order values and is displayed at the top of the Modern Cart slide-out.\n\n\n\nPrerequisites\n\n\n\nBefore enabling the progress bar, make sure you have Free Shipping configured in WooCommerce:\n\n\n\n\nGo to WooCommerce > Settings > Shipping.\n\n\n\nAdd or edit a Shipping Zone.\n\n\n\nAdd a Free Shipping method and set a minimum order amount.\n\n\n\nSave the shipping settings.\n\n\n\n\nHere is the Doc on How to Enable Free Shipping in WooCommerce\n\n\n\nNote\nThe progress bar reads the free shipping threshold directly from WooCommerce. If no free shipping method is configured, the bar will not display even when enabled.\n\n\n\n\nEnabling the Progress Bar\n\n\n\n\nGo to WooCommerce > Modern Cart in your WordPress dashboard.\n\n\n\nClick the General tab.\n\n\n\nToggle on Enable Free Shipping Bar.\n\n\n\n\n\n\n\n\nCustomizing the Progress Bar Text\n\n\n\nYou can customize the messages shown to customers:\n\n\n\n1.    Go to WooCommerce > Modern Cart > Text Label tab.2. Update the following fields:\n\n\n\n\nFree Shipping Bar Text — Shown while the customer has not yet reached the threshold. Use {amount} as a dynamic placeholder for the remaining amount. Default: \"You\'re {amount} away from free shipping!\"\n\n\n\nFree Shipping Success Text — Shown once the customer has qualified for free shipping. Default: \"Awesome pick! You\'ve unlocked free shipping.\"\n\n\n\n\n\n\n\n\nHow It Looks in the Cart\n\n\n\nThe progress bar appears at the top of the cart, below the cart header. It updates dynamically as customers add or remove items — no page reload required.\";s:3:\"url\";s:54:\"https://cartflows.com/docs/free-shipping-progress-bar/\";s:4:\"slug\";s:26:\"free-shipping-progress-bar\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-10T09:46:35+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:24;O:8:\"stdClass\":8:{s:2:\"id\";i:76442;s:5:\"title\";s:35:\"How to Use the In-Cart Coupon Field\";s:7:\"content\";s:1315:\"Modern Cart includes a built-in coupon field that lets customers apply discount codes directly inside the slide-out cart — no need to navigate to the checkout page.\n\n\n\nEnabling the Coupon Field\n\n\n\nTo enable the coupon field:\n\n\n\n1.    Go to WooCommerce > Modern Cart in your WordPress dashboard.2.    Click the General tab.3.    Find the Display Coupon Field option.4.    Choose one of the following options:\n\n\n\n\nMinimize (Default) — The coupon field is collapsed and expands when the customer clicks on it.\n\n\n\nExpand — The coupon field is always visible inside the cart.\n\n\n\nDisabled — Hides the coupon field entirely.\n\n\n\n\n\n\n\n\nCustomizing the Coupon Field Labels\n\n\n\nYou can change the text shown in the coupon field to match your store\'s tone:\n\n\n\n1.    Go to WooCommerce > Modern Cart > Text Label tab.2.    Update the following fields:\n\n\n\n\nCoupon Field Title — The heading above the coupon input (Default: \"Got a Discount Code?\").\n\n\n\nCoupon Placeholder — The placeholder text inside the input box (Default: \"Enter discount code\").\n\n\n\n\n\n\n\n\nHow It Works for Customers\n\n\n\nWhen a customer opens the cart, they will see the coupon field (collapsed or expanded depending on your setting). They can type their discount code and click Apply. The cart will update instantly with the discount applied.\";s:3:\"url\";s:63:\"https://cartflows.com/docs/how-to-use-the-in-cart-coupon-field/\";s:4:\"slug\";s:35:\"how-to-use-the-in-cart-coupon-field\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-06T10:18:36+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:25;O:8:\"stdClass\":8:{s:2:\"id\";i:76281;s:5:\"title\";s:76:\"How to Pause or Disable Cart Abandonment for Specific Products or Categories\";s:7:\"content\";s:6674:\"Sometimes you don\'t want every abandoned cart to trigger a recovery email. Common cases:\n\n\n\n\nSubscription — the customer didn\'t abandon, they\'re mid-flow; a recovery email is confusing.\n\n\n\nSensitive products — adult products, health products, or legal-gray items where a follow-up email is inappropriate.\n\n\n\nFree trials or $0 orders — no recovery needed; the cart total doesn\'t warrant outreach.\n\n\n\nWholesale / B2B orders — these customers prefer phone follow-up, not automated emails.\n\n\n\nSpecific SKUs you don\'t want to discount — exclude them so they don\'t receive coupon codes.\n\n\n\n\nCart Abandonment Recovery doesn\'t have a dedicated \"exclude product\" toggle, but with the Pro Rule Engine you can achieve the same result by scoping every recovery template to exclude the products or categories you don\'t want.\n\n\n\nThis guide shows two approaches:\n\n\n\n\nPro approach — Rule Engine with \"does not contain\" conditions\n\n\n\nFree approach — global tracking toggle + careful workarounds\n\n\n\n\nMost flexibility requires Pro. The free version only supports globally enabling or disabling tracking — there\'s no per-product or per-category exclusion. If product-level control is critical, Pro\'s Rule Engine is the tool.\n\n\n\nPrerequisites\n\n\n\n\nCart Abandonment Recovery installed and activated (Pro recommended)\n\n\n\nWooCommerce categories or tags set up on the products you want to include/exclude\n\n\n\nAt least one email template created\n\n\n\n\nMethod 1 — Pro Rule Engine: Exclude Specific Products or Categories\n\n\n\nHow It Works\n\n\n\nOpen each recovery template and add a condition that says: \"only fire if the cart does NOT contain these products / categories.\" The plugin evaluates every cart against these rules, and carts containing the excluded items get no recovery message.\n\n\n\nFor a complete guide on setting up email rules, see the documentation on&nbsp;Dynamic Email Rules.\n\n\n\nStep-by-Step\n\n\n\nStep 1 — Open Your Recovery Template\n\n\n\nGo to WooCommerce > Cart Abandonment > Follow Up Templates and click the &#xfe0f;Edit icon on the template you want to scope.\n\n\n\nStep 2 — Enable Dynamic Conditions\n\n\n\nInside the template editor, toggle Enable Dynamic Conditions to ON.\n\n\n\nStep 3 — Add a \"Does Not Contain\" Condition\n\n\n\nClick Add Condition and configure:\n\n\n\nTo exclude a specific product:\n\n\n\nFieldValueConditionProductOperatorDoes not containValueSelect the product(s) you want to exclude\n\n\n\nTo exclude a product category:\n\n\n\nFieldValueConditionProduct CategoryOperatorDoes not containValueSelect the category(ies) you want to exclude\n\n\n\nStep 4 — Combine Multiple Exclusions (Optional)\n\n\n\nYou can stack multiple \"does not contain\" conditions joined by AND:\n\n\n\nProduct Category → does not contain → SubscriptionsAND\n\n\n\nProduct Category → does not contain → Adult ProductsAND\n\n\n\nProduct → does not contain → Free Trial Access\n\n\n\nThis template now only fires for carts that include none of the excluded items.\n\n\n\nStep 5 — Apply to All Recovery Templates\n\n\n\nIf you have multiple recovery templates (e.g., 1-hour nudge, 24-hour reminder, 3-day final), add the same exclusion rules to every template. Otherwise, the excluded products might still receive later emails in the sequence.\n\n\n\nStep 6 — Test\n\n\n\nAbandon a cart containing only the excluded product — confirm no recovery email arrives. Then abandon a cart with a normal product — confirm recovery works as usual.\n\n\n\nMethod 2 — Exclude by Cart Total (All Versions With Pro)\n\n\n\nIf you want to skip recovery for $0 carts (trials, free downloads, test products):\n\n\n\nCondition: Cart Total → Greater than → 0\n\n\n\nOr to skip small carts not worth chasing:\n\n\n\nCondition: Cart Total → Greater than or equal to → 25\n\n\n\nMethod 3 — Free Version Workarounds\n\n\n\nThe free version has no per-product or per-category control. Your options are limited but not zero:\n\n\n\nOption A — Global Tracking Toggle\n\n\n\nGo to WooCommerce > Cart Abandonment > Settings > General and use the Enable Tracking toggle to completely turn recovery on or off store-wide. This is all-or-nothing.\n\n\n\n\n\n\n\nOption B — Conditional Template Content (Manual)\n\n\n\nWrite email copy that\'s generic enough to work for any product. This doesn\'t stop the email, but it avoids awkward product-specific messaging.\n\n\n\nOption C — Upgrade to Pro\n\n\n\nFor full control, Pro is the cleanest solution.\n\n\n\nCommon Use Cases &amp; Configurations\n\n\n\nUse Case 1 — Skip Recovery for Subscription\n\n\n\nCondition on every template:\n\n\n\n\nProduct Category → does not contain → Subscriptions\n\n\n\n\nUse Case 2 — Skip $0 Carts / Free Trials\n\n\n\nCondition on every template:\n\n\n\n\nCart Total → Greater than → 0\n\n\n\n\nUse Case 3 — Exclude a Single High-Value Product From Discount Emails\n\n\n\nCreate two templates:\n\n\n\n\nTemplate A (Discount Offer):\n\n\n\n\no Product → does not contain → Premium Consulting Package\n\n\n\no Includes a 10% coupon\n\n\n\n\nTemplate B (Personal Note):\n\n\n\n\no Product → contains → Premium Consulting Package\n\n\n\no No coupon, asks customer to reply or book a call\n\n\n\nUse Case 4 — Skip Adult / Sensitive Products\n\n\n\nCondition on every template:\n\n\n\n\nProduct Category → does not contain → Adult AND → does not contain → 18+\n\n\n\n\nTips &amp; Best Practices\n\n\n\n\nApply rules to every template in your sequence — missing one template means the excluded products still get emails later in the flow.\n\n\n\nUse categories, not individual products, when possible — easier to maintain as your catalog grows.\n\n\n\nTest every exclusion — abandon a cart with the excluded item and confirm no email is sent.\n\n\n\nDocument your exclusions — a short note in your internal wiki keeps future admins from wondering why certain carts don\'t trigger emails.\n\n\n\nMind mixed carts — a cart with BOTH an excluded item AND a normal item will be excluded if your condition is \"does not contain\". Decide whether that\'s the behavior you want.\n\n\n\n\nTroubleshooting\n\n\n\nExcluded Products Are Still Getting Emails\n\n\n\n\nConfirm every recovery template has the exclusion rule (not just one).\n\n\n\nCheck that Dynamic Conditions is toggled ON on each template.\n\n\n\nTest with a cart containing only the excluded item.\n\n\n\n\nCarts With Mixed Items Aren\'t Being Handled as Expected\n\n\n\n\n\"Does not contain\" excludes the cart if any matching item is present. If you want \"only exclude carts that are entirely excluded items\", that\'s not directly supported — consider two-template logic with opposite conditions instead.\n\n\n\n\nNo Emails Sending at All After Adding Rules\n\n\n\n\nCheck that your conditions aren\'t too restrictive.\n\n\n\nVerify at least one template\'s conditions match realistic cart scenarios.\n\n\n\nConsider a catch-all template with no conditions as a fallback.\n\n\n\n\nFAQs\";s:3:\"url\";s:104:\"https://cartflows.com/docs/how-to-pause-or-disable-cart-abandonment-for-specific-products-or-categories/\";s:4:\"slug\";s:76:\"how-to-pause-or-disable-cart-abandonment-for-specific-products-or-categories\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-09T21:12:39+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:26;O:8:\"stdClass\":8:{s:2:\"id\";i:76274;s:5:\"title\";s:76:\"GDPR / Privacy Compliance for Cart Tracking (Cookie Consent, Data Retention)\";s:7:\"content\";s:3680:\"If you serve customers in the EU, UK, or other jurisdictions with strict privacy laws, you need to ensure your cart abandonment tracking is compliant with regulations like GDPR, UK-GDPR, CCPA, and similar frameworks.\n\n\n\nThis guide explains:\n\n\n\n\nWhat data Cart Abandonment Recovery captures\n\n\n\nHow to enable the built-in GDPR consent feature\n\n\n\nBest practices for data retention, privacy policies, and unsubscribe handling\n\n\n\n\nWhat Data Does the Plugin Capture?\n\n\n\nWhen a shopper starts a checkout, the plugin stores:\n\n\n\n\nEmail address (primary identifier)\n\n\n\nFirst &amp; last name (if entered)\n\n\n\nBilling/shipping details (if entered)\n\n\n\nCart contents — products, quantities, prices\n\n\n\nDate and time of abandonment\n\n\n\nTracking token (used for unsubscribe links)\n\n\n\n\nThis data is stored in your WordPress database (in custom tables created by the plugin).\n\n\n\nPrerequisites\n\n\n\n\nCart Abandonment Recovery plugin installed and activated\n\n\n\nWooCommerce checkout configured\n\n\n\nA published Privacy Policy page on your site\n\n\n\n\nStep-by-Step: Enabling the Built-In GDPR Consent\n\n\n\nStep 1 — Open GDPR Settings\n\n\n\nGo to WooCommerce → Cart Abandonment → Settings → GDPR.\n\n\n\n\n\n\n\nStep 2 — Enable Email GDPR Integration\n\n\n\nToggle Enable Email GDPR Integration to ON.\n\n\n\nOnce enabled, a consent notice will appear below the email field on your checkout page, asking the customer to agree to data tracking before their cart is captured.\n\n\n\nStep 4 — Customize the Consent Message\n\n\n\nEdit the GDPR message field. Use clear, plain-language wording that:\n\n\n\n\nNames your store\n\n\n\nExplains what data you collect\n\n\n\nLinks to your Privacy Policy\n\n\n\nStates the purpose (abandoned cart recovery emails)\n\n\n\n\nExample:\n\n\n\nBy entering your email, you agree that [Your Store] may send you a recovery email if you don\'t complete your order. See our Privacy Policy for details. You can unsubscribe anytime.\n\n\n\nStep 5 — Save Settings\n\n\n\nClick Save Settings and verify the consent appears on your checkout page.\n\n\n\n\n\n\n\nPro Feature: Phone Number GDPR Consent\n\n\n\nIf you\'re using the Pro version and capturing phone numbers for SMS recovery, you\'ll see an additional Enable Phone GDPR Integration toggle on the same GDPR settings tab. Enable this to add a separate consent notice below the phone field on checkout.\n\n\n\n\n\n\n\nBest Practices for Data Retention\n\n\n\n1. Limit Retention Period\n\n\n\nDon\'t keep abandoned cart data forever. Configure a reasonable Abandoned cart lost time (e.g., 30 days) and delete older records regularly.\n\n\n\nHow:\n\n\n\n\nGo to Reports, filter by Lost status and old date ranges\n\n\n\nUse Bulk Delete\n\n\n\n\n2. Honor Deletion Requests\n\n\n\nWhen a customer requests their data be deleted:\n\n\n\n1. &nbsp; Search for their email in Reports\n\n\n\n2. &nbsp; Delete all matching records\n\n\n\n3. &nbsp; Also delete associated WooCommerce orders if requested\n\n\n\n3. Update Your Privacy Policy\n\n\n\nYour Privacy Policy should disclose:\n\n\n\n\nThat you use Cart Abandonment Recovery (or a similar tool)\n\n\n\nWhat data is captured (email, name, cart contents)\n\n\n\nHow long it\'s kept\n\n\n\nThe purpose (sending recovery emails)\n\n\n\nThe lawful basis (typically \"legitimate interest\" or \"consent\")\n\n\n\nHow users can opt out or request deletion\n\n\n\n\n4. Offer a Clear Unsubscribe\n\n\n\nEvery recovery email must include {{unsubscribe_link}} — this is legally required, not optional.\n\n\n\nSee: Unsubscribe / Opt-Out Handling for Recovery Emails.\n\n\n\nTips &amp; Best Practices\n\n\n\n\nEnable GDPR consent even if you\'re outside the EU — it\'s good practice and works as a trust signal.\n\n\n\nLink to your Privacy Policy in the consent text, not just mention it.\n\n\n\nUse plain language — don\'t hide data practices behind legal jargon.\n\n\n\n\nFAQs\";s:3:\"url\";s:99:\"https://cartflows.com/docs/gdpr-privacy-compliance-for-cart-tracking-cookie-consent-data-retention/\";s:4:\"slug\";s:71:\"gdpr-privacy-compliance-for-cart-tracking-cookie-consent-data-retention\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-09T21:09:07+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:27;O:8:\"stdClass\":8:{s:2:\"id\";i:76221;s:5:\"title\";s:50:\"Unsubscribe / Opt-Out Handling for Recovery Emails\";s:7:\"content\";s:5714:\"Every recovery email you send must include a working unsubscribe option. It\'s a legal requirement under CAN-SPAM, GDPR, and most other email regulations — and it also protects your sender reputation.\n\n\n\nThis guide shows you how to:\n\n\n\n\nAdd the built-in unsubscribe link to every recovery email\n\n\n\nManually unsubscribe customers from the admin dashboard\n\n\n\nHonor unsubscribe requests that come through other channels\n\n\n\n\nHow Unsubscribe Works in Cart Abandonment Recovery\n\n\n\nThe plugin generates a unique unsubscribe URL for each customer using a secure token. When a customer clicks it:\n\n\n\n\nTheir email is added to the plugin\'s internal opt-out list.\n\n\n\nNo further recovery emails will be sent to that address.\n\n\n\nA confirmation message is shown to them.\n\n\n\n\nThe URL format looks like:\n\n\n\nhttps:&#47;&#47;yourstore.com/?unsubscribe=true&amp;wcf_ac_token=&lt;unique-token&gt;\n\n\n\nThis token is unique per customer and can\'t be guessed — so it\'s safe to include in emails.\n\n\n\nPrerequisites\n\n\n\n\nCart Abandonment Recovery plugin installed and activated\n\n\n\nAt least one email template created under Follow Up Templates\n\n\n\n\nStep-by-Step: Adding the Unsubscribe Link to Emails\n\n\n\nStep 1 — Open the Template Editor\n\n\n\nGo to WooCommerce &gt; Cart Abandonment &gt; Follow Up Templates and click the &#xfe0f;Edit icon on the template you want to edit. The editor opens as a right-side drawer.\n\n\n\nStep 2 — Add the Shortcode\n\n\n\nInsert {{cart.unsubscribe}} wherever you want the unsubscribe link to appear — typically in the footer.\n\n\n\nStep 3 — Save the Template\n\n\n\nClick Save Changes.\n\n\n\nStep 4 — Repeat for All Templates\n\n\n\nMake sure every recovery email template has the unsubscribe link — not just the first one.\n\n\n\nStep 5 — Test\n\n\n\nUse the Send Test Email feature to verify the unsubscribe link renders correctly and works when clicked.\n\n\n\nManually Unsubscribing a Customer\n\n\n\nYou can opt out a customer directly from the admin dashboard.\n\n\n\n\nGo to Reports &gt; Follow Up and search for the customer\'s email.\n\n\n\nClick the Unsubscribe action in the row.\n\n\n\n\nUse this when:\n\n\n\n\nA customer emails asking to be removed\n\n\n\nYou\'re cleaning up a stale list\n\n\n\nYou want to opt out specific test accounts\n\n\n\n\nPro Feature: Blacklist (Permanent Block)\n\n\n\nCart Abandonment Recovery Pro adds a Blacklist feature that goes beyond regular unsubscribe. A blacklisted email is:\n\n\n\n\nNever tracked — the cart isn\'t even stored in the database.\n\n\n\nNever sent any recovery message — email, SMS, or WhatsApp.\n\n\n\nProtected from accidental re-subscription — an admin must manually remove them from the blacklist.\n\n\n\n\nWhen to Blacklist vs. Unsubscribe\n\n\n\nSituationActionCustomer clicked unsubscribeAutomatic — normal opt-out listCustomer emailed asking to be removedUnsubscribe (manual)Customer demanded permanent removal under GDPR right-to-erasureBlacklist + delete existing recordsRepeated spam complaints from an addressBlacklistKnown bad/disposable email domains (e.g., mailinator.com)Blacklist the domain patternCompetitor or fraud-flagged accountsBlacklist\n\n\n\nHow to Add an Email to the Blacklist\n\n\n\n\nGo to WooCommerce > Cart Abandonment > Settings > Blacklist (Pro)\n\n\n\nEnter the email address (one per line) or a domain pattern.\n\n\n\nClick Save.\n\n\n\n\nHow to Remove From the Blacklist\n\n\n\nRemove the entry from the Blacklist list and save. The next cart that customer abandons will be tracked again.\n\n\n\nBlacklist ≠ data deletion. Blacklist prevents future tracking but doesn\'t delete past cart records. For GDPR right-to-erasure, also delete existing records from Reports.\n\n\n\nHonoring Out-of-Band Unsubscribe Requests\n\n\n\nSometimes customers will request removal through:\n\n\n\n\nA direct email reply\n\n\n\nA phone call\n\n\n\nA social media message\n\n\n\nA written request (for GDPR compliance)\n\n\n\n\nWhen this happens:\n\n\n\n\nSearch for their email in the Reports tab.\n\n\n\nClick Unsubscribe on all matching rows.\n\n\n\nIf they also want their data deleted (GDPR right-to-erasure), delete the records as well.\n\n\n\nReply to confirm action taken.\n\n\n\n\nTips &amp; Best Practices\n\n\n\n\nAlways include unsubscribe_link — it\'s not optional, even for a single follow-up email.\n\n\n\nMake the unsubscribe link visible — don\'t hide it in tiny grey text at the bottom.\n\n\n\nProcess unsubscribe requests within 10 business days (CAN-SPAM requirement) — ideally faster.\n\n\n\nDon\'t require login to unsubscribe — the token-based link should work without any authentication.\n\n\n\nConfirm the unsubscribe — show a clear \"You\'ve been unsubscribed\" message.\n\n\n\n\nTroubleshooting\n\n\n\nUnsubscribe Link Shows Literal {{unsubscribe_link}} in Email\n\n\n\n\nCheck spelling — the tag is case-sensitive\n\n\n\nEnsure double curly braces {{ }} are used\n\n\n\nRe-save the template and re-test\n\n\n\n\n\"404 Not Found\" When Clicking the Link\n\n\n\n\nCheck that WordPress permalinks are set correctly\n\n\n\nConfirm the plugin is active\n\n\n\nRegenerate permalinks by visiting Settings > Permalinks and clicking Save Changes\n\n\n\n\nCustomer Is Still Receiving Emails After Unsubscribing\n\n\n\n\nVerify they were actually added to the opt-out list (check their cart entry in Reports)\n\n\n\nConfirm the email template is sending to them (may already be queued)\n\n\n\nCheck your email provider logs for delivery status\n\n\n\n\nLegal Compliance Notes\n\n\n\nDifferent jurisdictions have different requirements:\n\n\n\nRegulationKey RequirementCAN-SPAM (US)Clear unsubscribe option, honored within 10 business daysGDPR (EU)Easy withdrawal of consent, process \"without undue delay\"CASL (Canada)Working unsubscribe functional for at least 60 days after email is sentUK-GDPRSame as GDPR, plus PECR restrictions on marketing emails\n\n\n\nNote\nThis is not legal advice. Consult a qualified attorney for your specific obligations.\n\n\n\n\nFAQs\";s:3:\"url\";s:76:\"https://cartflows.com/docs/unsubscribe-opt-out-handling-for-recovery-emails/\";s:4:\"slug\";s:48:\"unsubscribe-opt-out-handling-for-recovery-emails\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-25T16:55:00+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:28;O:8:\"stdClass\":8:{s:2:\"id\";i:76126;s:5:\"title\";s:47:\"How to View and Manage the Abandoned Carts List\";s:7:\"content\";s:3504:\"Every cart tracked by Cart Abandonment Recovery appears in the Reports dashboard — from active recoverable carts to already-recovered orders and carts marked as lost. This centralized view gives you full visibility and control over your recovery operations.\n\n\n\nThis guide walks you through navigating the list, filtering and searching, and taking action on individual or multiple entries.\n\n\n\nPrerequisites\n\n\n\n\nCart Abandonment Recovery plugin installed and activated\n\n\n\nAt least one tracked cart (shoppers must have entered their email on checkout)\n\n\n\n\nAccessing the Abandoned Carts List\n\n\n\nGo to WordPress Dashboard > WooCommerce > Cart Abandonment > Reports > Follow Up.\n\n\n\n\n\n\n\nThe abandoned carts table appears with search, filter, and export controls at the top.\n\n\n\nUnderstanding the Table Columns\n\n\n\nColumnDescriptionCart TotalTotal value of the cartEmail ToShopper\'s email address (primary identifier)User NameFull name if provided on checkoutOrder StatusRecoverable, Recovered, or LostDate &amp; TimeWhen the cart was marked as abandonedActionsView details, unsubscribe, or delete\n\n\n\nFiltering and Searching\n\n\n\nFilter by Status\n\n\n\nUse the status filter to focus on:\n\n\n\n\nAbandoned — carts currently eligible for recovery emails\n\n\n\nRecovered — carts that became completed orders\n\n\n\nLost — carts past the lost-time threshold\n\n\n\nBlacklisted — User emails that are Blacklisted in the plugin\n\n\n\n\n\n\n\n\nFilter by Date Range\n\n\n\nUse the date picker at the top to view carts from:\n\n\n\n\nToday\n\n\n\nYesterday\n\n\n\nLast Week\n\n\n\nLast Month\n\n\n\nCustom Date Range\n\n\n\n\n\n\n\n\nSearch by Email\n\n\n\nUse the search bar to quickly find a specific customer\'s cart by email address or user name.\n\n\n\n\n\n\n\nViewing Cart Details\n\n\n\nClick on any row (or the view icon) to see:\n\n\n\n\nFull cart contents — products, quantities, prices\n\n\n\nCustomer information — email, name, address entered\n\n\n\nTimeline — when the cart was abandoned, when recovery emails were sent\n\n\n\nRecovery status — if the customer clicked through or completed the order\n\n\n\n\n\n\n\n\nActions You Can Take\n\n\n\n1. Delete a Cart\n\n\n\nRemove a single cart from the list — useful for test data or when a customer explicitly requests removal.\n\n\n\nHow: Click the Delete icon in the Actions column.\n\n\n\n2. Unsubscribe a Customer\n\n\n\nStop sending recovery emails to a specific customer record.\n\n\n\nHow: Click the Unsubscribe action on the row — this adds the email to your internal opt-out list.\n\n\n\n3. Blacklist/Whitelist a Customer(Pro)\n\n\n\nPermanently stop sending recovery emails to a specific customer.\n\n\n\nHow: Click the Unsubscribe action on the row — this adds the email to your internal opt-out list.\n\n\n\n4. Bulk Actions\n\n\n\nSelect multiple carts using the checkboxes, then use the Bulk Actions dropdown:\n\n\n\n\nDelete selected carts\n\n\n\n\n5. Export to CSV\n\n\n\nUse the Export button above the table to download a CSV of all entries for external analysis.\n\n\n\n\n\n\n\nTips &amp; Best Practices\n\n\n\n\nClean up test data regularly — especially after staging tests, to keep your reports accurate.\n\n\n\nReview \"Recoverable\" carts weekly — this is your active pipeline; sudden drops may mean tracking is broken.\n\n\n\nExport monthly for record-keeping, especially if you\'re required to retain transaction records.\n\n\n\n\nManaging Privacy and Data Requests\n\n\n\nIf a customer requests deletion of their data (e.g., under GDPR):\n\n\n\n\nSearch for their email in the table.\n\n\n\nClick Delete on all matching entries.\n\n\n\nAlso remove them from any related WooCommerce order records separately.\n\n\n\n\nFAQs\";s:3:\"url\";s:75:\"https://cartflows.com/docs/how-to-view-and-manage-the-abandoned-carts-list/\";s:4:\"slug\";s:47:\"how-to-view-and-manage-the-abandoned-carts-list\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-24T08:42:38+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:29;O:8:\"stdClass\":8:{s:2:\"id\";i:76115;s:5:\"title\";s:82:\"Recovery Email Deliverability Best Practices (SPF, DKIM, Dedicated Sending Domain)\";s:7:\"content\";s:6007:\"Email deliverability is one of the most important factors in whether your recovery campaigns succeed. A well-written recovery email that lands in the spam folder will not recover any carts.\n\n\n\nThis guide covers:\n\n\n\n\nConfiguring sender settings inside Cart Abandonment Recovery\n\n\n\nSetting up SPF, DKIM, and DMARC records on your domain\n\n\n\nWhy you should use a proper SMTP service instead of default WordPress mail\n\n\n\nBest practices for sender domains and deliverability monitoring\n\n\n\n\nWhy Deliverability Matters\n\n\n\nBy default, WordPress uses PHP\'s basic mail() function. This has several issues:\n\n\n\n\nEmails are sent from your web server IP — often on shared hosting with bad reputations.\n\n\n\nNo authentication — SPF/DKIM aren\'t configured out of the box.\n\n\n\nFrequently flagged as spam by Gmail, Outlook, and other major providers.\n\n\n\n\nFor abandoned cart recovery to work, your emails must reliably reach the inbox.\n\n\n\nPrerequisites\n\n\n\n\nCart Abandonment Recovery plugin installed and activated\n\n\n\nAccess to your domain\'s DNS records (through your registrar or host)\n\n\n\nA business email address for your \"From\" sender\n\n\n\n\nStep 1 — Configure Sender Settings in the Plugin\n\n\n\nGo to WooCommerce &gt; Cart Abandonment &gt; Settings &gt; Email.\n\n\n\nConfigure:\n\n\n\nFieldRecommendationFrom NameYour store name (e.g., \"Sarah from ExampleStore\")From EmailA real address on your domain (e.g., hello@yourstore.com) — never use wordpress@yourhost.comReply-To EmailSame as From Email, or a monitored inbox\n\n\n\nNote\nDon\'t use Gmail, Yahoo, or other free providers as your From address — they will fail DMARC checks and be blocked.\n\n\n\n\nStep 2 — Use an SMTP Service (Highly Recommended)\n\n\n\nDon\'t rely on default WordPress mail. Use a dedicated transactional email service:\n\n\n\nRecommended Providers\n\n\n\nServiceFree TierBest ForSendGrid100 emails/daySmall-to-medium storesMailgunPay-as-you-goDeveloper-friendlyAmazon SESVery cheapHigh-volume storesPostmark100 emails/monthExcellent deliverabilityBrevo (Sendinblue)300 emails/dayMarketing + transactional\n\n\n\nHow to Connect\n\n\n\n\nInstall a plugin like SureMails (Knowledge Base) or any other SMTP plugin.\n\n\n\nCreate an account with your chosen SMTP provider.\n\n\n\nFollow the plugin\'s wizard to enter your API key or SMTP credentials.\n\n\n\nSend a test email to confirm it works.\n\n\n\n\nStep 3 — Set Up SPF Record\n\n\n\nSPF (Sender Policy Framework) tells receiving servers which IPs are allowed to send email on behalf of your domain.\n\n\n\nHow to Add\n\n\n\n1.   Log in to your DNS provider (e.g., Cloudflare, GoDaddy, Namecheap).\n\n\n\n2.   Add a TXT record for your domain:\n\n\n\n\nType: TXT\n\n\n\nName: @\n\n\n\nValue: v=spf1 include:YOUR-SMTP-PROVIDER.com ~all\n\n\n\nReplace YOUR-SMTP-PROVIDER.com with your SMTP provider\'s include statement:\n\nSendGrid: include:sendgrid.net\n\n\n\nMailgun: include:mailgun.org\n\n\n\nAmazon SES: include:amazonses.com\n\n\n\nGoogle Workspace: include:_spf.google.com\n\n\n\n\n\n\n3. &nbsp; Save and wait up to 24 hours for DNS propagation.\n\n\n\nAlready using Google Workspace or Microsoft 365? You can combine: v=spf1 include:_spf.google.com include:sendgrid.net ~all\n\n\n\nNote\nAlready using Google Workspace or Microsoft 365? You can combine multiple senders: v=spf1 include:_spf.google.com include:sendgrid.net ~all\n\n\n\n\nStep 4 — Set Up DKIM Record\n\n\n\nDKIM (DomainKeys Identified Mail) cryptographically signs your emails so receiving servers can verify they weren\'t tampered with.\n\n\n\nYour SMTP provider will give you one or more DKIM keys to add as TXT or CNAME records. Follow the exact instructions from your SMTP provider — they differ slightly across services.\n\n\n\nExample (SendGrid — CNAME style):\n\n\n\n\nName: s1._domainkey  |  Value: s1.domainkey.u1234.wl.sendgrid.net\n\n\n\nName: s2._domainkey  |  Value: s2.domainkey.u1234.wl.sendgrid.net\n\n\n\n\nStep 5 — Set Up DMARC Record\n\n\n\nDMARC tells receiving servers what to do when SPF or DKIM checks fail. Start with a monitoring-only policy:\n\n\n\n\nType: TXT\n\n\n\nName: _dmarc\n\n\n\nValue: v=DMARC1; p=none; rua=mailto:dmarc@yourstore.com\n\n\n\n\nThis won\'t block any email but will send you reports about authentication issues. After monitoring for 2–4 weeks and fixing any issues, tighten to p=quarantine or p=reject.\n\n\n\nStep 6 — Verify Your Setup\n\n\n\nUse free tools to confirm everything is working:\n\n\n\n\nMXToolbox SuperTool — check SPF, DKIM, DMARC records\n\n\n\nMail-Tester.com — send a test email and get a spam score (aim for 9+/10)\n\n\n\nGoogle Postmaster Tools — monitor your domain reputation with Gmail\n\n\n\nGlockApps — comprehensive inbox placement testing\n\n\n\n\nExpected Outcome\n\n\n\nAfter completing all six steps, your recovery emails should:\n\n\n\n\nPass SPF, DKIM, and DMARC authentication checks (verifiable via MXToolbox)\n\n\n\nScore 9+/10 on Mail-Tester.com\n\n\n\nLand consistently in the inbox rather than the spam folder for Gmail, Outlook, and other major providers\n\n\n\n\nTips &amp; Best Practices\n\n\n\nContent Best Practices\n\n\n\n\nUse a recognizable From Name — e.g., \"Sarah at ExampleStore\"\n\n\n\nKeep subject lines under 50 characters — better mobile display\n\n\n\nAvoid spam trigger words — \"FREE!!!\", \"100% GUARANTEED\", all caps, excessive exclamation marks\n\n\n\nBalance text and images — image-only emails often get flagged\n\n\n\nAlways include a plain-text version — most SMTP plugins handle this automatically\n\n\n\n\nDomain Best Practices\n\n\n\n\nUse your main domain or a subdomain — e.g., hello@yourstore.com or mail.yourstore.com\n\n\n\nAvoid brand-new domains — they have no sending reputation; warm them up slowly.\n\n\n\nConsider a dedicated sending subdomain (e.g., send.yourstore.com) for high-volume transactional mail — isolates reputation.\n\n\n\n\nMonitoring\n\n\n\n\nWatch bounce rates — over 2% is a warning sign\n\n\n\nCheck spam complaints — keep below 0.1%\n\n\n\nReview unsubscribes regularly — rising rates may indicate targeting issues\n\n\n\n\nTroubleshooting\n\n\n\nEmails Going to Spam\n\n\n\nIf your recovery emails are still landing in spam after completing the steps above, refer to How to Fix Recovery Emails Going to the Spam Folder\n\n\n\nFAQs\";s:3:\"url\";s:72:\"https://cartflows.com/docs/recovery-email-deliverability-best-practices/\";s:4:\"slug\";s:44:\"recovery-email-deliverability-best-practices\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-24T21:08:10+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:30;O:8:\"stdClass\":8:{s:2:\"id\";i:76054;s:5:\"title\";s:45:\"Segmenting Abandonment Recovery by Cart Value\";s:7:\"content\";s:6104:\"Not every abandoned cart is equal. A customer who left a $25 order deserves a different recovery nudge than one who abandoned a $500 cart. With Cart Abandonment Recovery Pro, you can use the Rule Engine (Dynamic Conditions) to send different recovery emails, SMS messages, or coupons based on cart value, products, categories, country, or number of items.\n\n\n\nThis guide walks you through segmenting your recovery flow using cart value and other conditions.\n\n\n\nPro-only feature. The free version of Cart Abandonment Recovery sends the same template flow to every abandoned cart. Segmentation requires Cart Abandonment Recovery Pro.\n\n\n\nWhy Segment by Cart Value?\n\n\n\nDifferent cart values call for different recovery strategies:\n\n\n\nCart ValueRecovery StrategyLow ($10–$50)Small coupon (5%) or free shipping — keep the cost-to-recover reasonableMid ($50–$200)Moderate discount (10%) + urgency — \"your cart expires in 24h\"High ($200+)Concierge touch — no coupon, personal message, or offer a call/consultation\n\n\n\nSending a 20% coupon to a $20 cart burns your margin. Sending no offer at all to a $500 cart misses a huge revenue opportunity. Segmentation gets the right message to the right customer.\n\n\n\nPrerequisites\n\n\n\n\nCart Abandonment Recovery Pro installed and activated\n\n\n\nAt least two email templates created under Follow Up Templates\n\n\n\nWooCommerce checkout configured with abandoned cart tracking working\n\n\n\n\nSupported Conditions (Rule Engine)\n\n\n\nThe Pro Rule Engine supports these conditions for any email, SMS, or WhatsApp template:\n\n\n\nConditionOperatorsExample UseCart Total=, ≠, &gt;, &lt;, ≥, ≤High-value vs. low-value cart offersNumber of Cart Items=, ≠, &gt;, &lt;, ≥, ≤Bulk-order vs. single-item messagingProductcontains, does not containTarget specific SKUsProduct Categorycontains, does not containCategory-specific offers (e.g., apparel vs. electronics)Country=, ≠Country-specific language, currency, shipping offers\n\n\n\nMultiple conditions can be combined with AND / OR logic.\n\n\n\nStep-by-Step: Segmenting by Cart Value\n\n\n\nStep 1 — Create Your Templates\n\n\n\nGo to WooCommerce &gt; Cart Abandonment &gt; Follow Up Templates and create at least two templates you want to use for different segments.\n\n\n\nExample:\n\n\n\n\nTemplate A — Low-Value Cart: 5% off, casual tone\n\n\n\nTemplate B — High-Value Cart: No discount, personal note, urgency\n\n\n\n\n\n\n\n\nStep 2 — Open Template A and Enable Dynamic Conditions\n\n\n\nClick the &#xfe0f;Edit icon on Template A to open the editor drawer. Find the Dynamic Conditions toggle and turn it ON.\n\n\n\nStep 3 — Add the Cart-Value Rule for Low-Value Carts\n\n\n\nClick Add Condition and configure:\n\n\n\nFieldValueConditionCart TotalOperatorLess thanValue100\n\n\n\n\n\n\n\nThis means: send this template only to carts under $100.\n\n\n\nClick Done then Save Changes.\n\n\n\nStep 4 — Configure Template B for High-Value Carts\n\n\n\nOpen Template B and enable Dynamic Conditions. Add the opposite condition:\n\n\n\nFieldValueConditionCart TotalOperatorGreater than or equal toValue100\n\n\n\n\n\n\n\nClick Done then Save Changes.\n\n\n\nStep 5 — Verify Both Templates Are Active\n\n\n\nBack on the Follow Up Templates list, confirm both templates are Active (Status toggle ON). The Pro engine will now evaluate each abandoned cart against the conditions and pick the right template automatically.\n\n\n\nStep 6 — Test With a Real Abandoned Cart\n\n\n\n\nAdd items totaling less than $100 to your cart and abandon at checkout (use a test email).\n\n\n\nWait for the recovery email — confirm Template A arrived.\n\n\n\nRepeat with a cart over $100 — confirm Template B arrived.\n\n\n\n\nSee How to Test Cart Abandonment Recovery Emails for the full testing workflow.\n\n\n\nExample: Multi-Tier Segmentation\n\n\n\nYou can have three or more templates, each covering a different range. Just set matching conditions:\n\n\n\nTemplateConditionSmall Cart OfferCart Total &lt; 50Mid Cart OfferCart Total ≥ 50 AND Cart Total &lt; 200Premium Cart OfferCart Total ≥ 200\n\n\n\nFor the Mid Cart Offer, add two conditions joined by AND in the same template\'s Rule Engine.\n\n\n\nExample: Segmenting by Product Category\n\n\n\nLet\'s say you want apparel buyers to get a style-guide-heavy email while electronics buyers get a technical-specs email.\n\n\n\nTemplate A (Apparel):\n\n\n\n\nCondition: Product Category → contains → Clothing\n\n\n\n\nTemplate B (Electronics):\n\n\n\n\nCondition: Product Category → contains → Electronics\n\n\n\n\nIf a cart has both categories, the first matching template wins — order your templates in the Follow Up Templates list accordingly.\n\n\n\nExample: Country-Based Offers\n\n\n\nOffer free shipping to US customers while giving EU customers a flat discount (since shipping costs differ).\n\n\n\nTemplate A (US):\n\n\n\n\nCondition: Country → equals → United States\n\n\n\nCoupon: Free Shipping\n\n\n\n\nTemplate B (EU):\n\n\n\n\nCondition: Country → not equal to → United States\n\n\n\nCoupon: 10% off\n\n\n\n\nTips &amp; Best Practices\n\n\n\n\nStart simple — two segments (high-value + low-value) before jumping to five or six.\n\n\n\nMonitor each segment in Reports — compare recovery rates per template to see what\'s working.\n\n\n\nBalance your coupons against margin — don\'t hand out 20% on a $30 cart.\n\n\n\nSet conditions that don\'t overlap — if two templates both match a cart, only one fires, and ordering may be non-obvious. Use mutually-exclusive ranges (&lt; 100 and &gt;= 100, not &lt; 100 and &lt; 200).\n\n\n\nDocument your segments — keep a note of which templates apply to which conditions. Future-you will appreciate it.\n\n\n\nTest each segment with a real abandoned cart before relying on it in production.\n\n\n\n\nTroubleshooting\n\n\n\nWrong Template Is Sending\n\n\n\n\nRe-check your conditions — overlapping rules can lead to unexpected matches.\n\n\n\nEnsure both templates have Dynamic Conditions enabled and are Active.\n\n\n\nClear your browser cache and re-check the template after saving.\n\n\n\n\nNo Template Is Sending\n\n\n\n\nVerify at least one template\'s conditions match the abandoned cart.\n\n\n\nIf all templates have conditions and none match, no email is sent.\n\n\n\nConsider keeping one template with no conditions as a catch-all fallback.\n\n\n\n\nFAQs\";s:3:\"url\";s:73:\"https://cartflows.com/docs/segmenting-abandonment-recovery-by-cart-value/\";s:4:\"slug\";s:45:\"segmenting-abandonment-recovery-by-cart-value\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-23T09:27:27+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:31;O:8:\"stdClass\":8:{s:2:\"id\";i:76028;s:5:\"title\";s:39:\"A/B Testing Recovery Emails and Coupons\";s:7:\"content\";s:5266:\"A/B testing (also called split testing) means sending two or more versions of a recovery email to different segments of your audience to measure which performs better. Classic things to test: subject lines, coupon amounts, email layouts, call-to-action wording, and timing.\n\n\n\nCart Abandonment Recovery and its Pro version do not include a built-in A/B testing engine with automatic variant assignment. However, using the Pro Rule Engine along with your Reports data, you can set up manual/sequential A/B tests that still provide reliable results.\n\n\n\nThis guide walks you through both approaches — the sequential time-based method (works for free + Pro users) and the rule-based segmented method (Pro only).\n\n\n\nWhat This Plugin Does &amp; Doesn\'t Support\n\n\n\nCapabilitySupported?Built-in automatic variant splitting (50/50 traffic)&#x274c; Not supportedAutomated statistical significance reporting&#x274c; Not supportedMultiple email templates with different conditions&#x2705; Supported (Pro only, via Rule Engine)Sequential time-based template rotation&#x2705; Supported (manual, free + Pro)Coupon code variation per template&#x2705; Supported\n\n\n\nPrerequisites\n\n\n\n\nCart Abandonment Recovery installed and activated (free version supports Method 1; Pro unlocks Method 2)\n\n\n\nAt least one existing recovery email template\n\n\n\nA 2–4 week testing window (longer = more reliable results)\n\n\n\nA consistent volume of abandoned carts to get meaningful data\n\n\n\n\nMethod 1 — Sequential (Time-Based) A/B Testing\n\n\n\nHow It Works\n\n\n\nRun Variant A for a set period, then switch to Variant B for the same period, then compare results from the Reports tab.\n\n\n\nStep-by-Step\n\n\n\nStep 1 — Create Variant AGo to WooCommerce &gt; Cart Abandonment &gt; Follow Up Templates. Create your first recovery template (e.g., with a 10% coupon and subject \"Come back! Here\'s 10% off\").\n\n\n\nStep 2 — Run Variant A for 2 WeeksLeave the template active for a full 2-week window. Don\'t change anything during this period.\n\n\n\nStep 3 — Note Variant A ResultsOpen Reports &gt; Follow Up and record:\n\n\n\n\nTotal abandoned carts during the window\n\n\n\nTotal recovered carts\n\n\n\nRecovery rate (%)\n\n\n\nTotal recovered revenue\n\n\n\n\nStep 4 — Switch to Variant BDeactivate Variant A and activate Variant B (e.g., 15% coupon, subject \"Your cart misses you — 15% off inside\").\n\n\n\nStep 5 — Run Variant B for 2 WeeksSame duration. Same store, same traffic, same time-of-month dynamics — keep conditions consistent.\n\n\n\nStep 6 — CompareRecord Variant B results using the same metrics. The variant with the higher recovery rate wins.\n\n\n\nBe careful about external factors — seasonal changes, promotions, traffic spikes, and ad campaigns can skew results. Try to keep external variables constant.\n\n\n\nMethod 2 — Rule-Based Segmented Testing (Pro)\n\n\n\nHow It Works\n\n\n\nUsing the Pro Rule Engine, send different templates to different segments based on conditions like cart total, product category, or country. This isn\'t random split testing, but it lets you test targeted messaging against different customer groups in parallel.\n\n\n\nStep-by-Step\n\n\n\nStep 1 — Create Both TemplatesGo to Follow Up Templates and create Template A and Template B with the variations you want to test.\n\n\n\nStep 2 — Enable Dynamic Conditions on Template AClick the Edit icon on Template A to open the drawer. Find the Dynamic Conditions toggle and turn it ON.\n\n\n\nStep 3 — Add a RuleSet a condition — for example:\n\n\n\n\nCondition: Cart Total → Greater than or equal to → 100\n\n\n\n\nThis template will only send to customers whose cart totals $100 or more.\n\n\n\nStep 4 — Create an Opposite Rule for Template BOpen Template B, enable Rule Engine, and set:\n\n\n\n\nCondition: Cart Total → Less than → 100\n\n\n\n\nStep 5 — Let Them Run in ParallelBoth templates send simultaneously, each to its own segment. After 2–4 weeks, compare recovery rates per segment in Reports > Follow Up. Also check the Conversion Rate column in the Follow Up Templates list for a quick per-template comparison.\n\n\n\nRemember: This compares \"high-value carts\" vs. \"low-value carts\" — not a pure A/B of the same audience. Interpret results accordingly.\n\n\n\nThings to Test\n\n\n\n\nSubject lines — urgency vs. friendly vs. question-based\n\n\n\nCoupon amount — fixed $10 vs. 10% vs. free shipping\n\n\n\nSend timing — 1 hour vs. 6 hours vs. 24 hours after abandonment\n\n\n\nEmail length — short + punchy vs. long + detailed\n\n\n\nCTA wording — \"Complete Purchase\" vs. \"Claim Your Cart\" vs. \"Continue Shopping\"\n\n\n\nPersonalization depth — use first name + product name vs. just first name\n\n\n\nImages vs. text-only — does the image help conversion or hurt deliverability?\n\n\n\n\nTips &amp; Best Practices\n\n\n\n\nTest one variable at a time — changing subject AND coupon at once makes it impossible to know which drove the result.\n\n\n\nRun each variant for the same duration — 2 weeks minimum, ideally 4.\n\n\n\nLook for meaningful differences — a 1–2% gap over 50 recoveries is noise. Wait for statistical significance (200+ samples per variant).\n\n\n\nDocument every test — keep a simple spreadsheet of variants, dates, and results. Future you will thank you.\n\n\n\nDeclare a winner — once a test is conclusive, adopt the winner and move on. Don\'t test forever.\n\n\n\n\nFAQs\";s:3:\"url\";s:67:\"https://cartflows.com/docs/a-b-testing-recovery-emails-and-coupons/\";s:4:\"slug\";s:39:\"a-b-testing-recovery-emails-and-coupons\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-23T16:32:56+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:32;O:8:\"stdClass\":8:{s:2:\"id\";i:75902;s:5:\"title\";s:53:\"On-Site Reminder Banner for Cart Abandonment Recovery\";s:7:\"content\";s:5817:\"The On-Site Reminder Banner displays a customizable notification on your store when a visitor returns with items still in their abandoned cart. The banner is authored once in the WordPress block editor and shows automatically to eligible visitors on the pages you choose — no coding required.\n\n\n\nThis feature is available in Cart Abandonment Recovery Pro only.\n\n\n\n1. Where to Find It\n\n\n\nBanner settings: WooCommerce &gt; Cart Abandonment &gt; Settings &gt; On-Site Banner\n\n\n\n\n\n\n\nBanner editor: WooCommerce &gt; Recovery Banners\n\n\n\n\n\n\n\nThe Settings tab controls when and where the banner appears. Recovery Banners is where you create and edit the banner content itself.\n\n\n\n2. How to Enable It\n\n\n\n\nGo to  WooCommerce &gt; Cart Abandonment &gt; Settings &gt; On-Site Banner.\n\n\n\nEnable the Enable On-Site Banner toggle.\n\n\n\nSelect the Position — Top, Bottom, or Custom (shortcode).\n\n\n\nUnder Show On Pages, select the page types where the banner should appear.\n\n\n\nSave the settings.\n\n\n\n\nThe banner will now show to visitors who:\n\n\n\n\nEntered their email on the checkout page in a previous session without completing the order, or\n\n\n\nAre logged in and have an active abandoned cart on their account.\n\n\n\n\n3. Settings\n\n\n\n\n\n\n\n1. Enable On-Site Banner (Toggle)\n\n\n\n\nDefault: Off\n\n\n\nMaster on/off switch for the entire feature.\n\n\n\n\n2. Banner Content\n\n\n\n\nDefault: Default Recovery Banner\n\n\n\nSelects which banner post to display. A default banner is created automatically on first install. You can create multiple banners and switch between them at any time.\n\n\n\n\n3. Position\n\n\n\n\nDefault: Top\n\n\n\nTop — Sticky bar pinned to the top of every targeted page.\n\n\n\nBottom — Sticky bar pinned to the bottom of every targeted page.\n\n\n\nCustom — Banner only appears where you paste the shortcode [wcar_banner]. Use this for inline placement on a specific page or section.\n\n\n\n\n4. Show On Pages\n\n\n\n\nDefault: None selected\n\n\n\nMulti-select: Home, Shop, Product, Cart, Checkout, Archive, Pages &amp; Posts.\n\n\n\nOnly the page types selected here will display the banner.\n\n\n\n\n5. Specific URL Slugs\n\n\n\n\nDefault: Empty\n\n\n\nOne URL slug per line (e.g. about, blog/sale-2026).\n\n\n\nThese are additive — the banner shows on these URLs in addition to any page types selected above.\n\n\n\n\n6. Max Impressions Per Visitor\n\n\n\n\nDefault: 0 (unlimited)\n\n\n\nAfter this many page views with the banner shown, it stops appearing for that visitor. Set to 0 for no limit.\n\n\n\n\n7. Allowed Origins (Cross-Subdomain)\n\n\n\n\nDefault: Empty\n\n\n\nAdvanced setting. One origin per line (e.g. https://www.example.com). Only needed if you want the banner to load on a sibling site sharing the same root domain. See Section 7 for full setup steps.\n\n\n\n\n4. Authoring the Banner\n\n\n\nBanner content is edited in the standard WordPress block editor under WP Admin → Recovery Banners. You can:\n\n\n\n\nChange the headline, body text, and button label.\n\n\n\nAdjust background and text colors.\n\n\n\nUse Group or Columns blocks to control layout (e.g. text on the left, button on the right).\n\n\n\nUse the merge tag {{cart.checkout_url}} anywhere in text or button URLs — it is automatically replaced with the visitor\'s personal checkout recovery link.\n\n\n\n\nMerge Tag Reference\n\n\n\nMerge TagWhat It Inserts{{cart.checkout_url}}Visitor\'s personal checkout recovery URL\n\n\n\nDefault Recovery Banner\n\n\n\nA \"Default Recovery Banner\" post is created automatically on first install. It includes:\n\n\n\n\nBlack background, white text\n\n\n\nHeadline: Your cart is still waiting &#x1f6cd;\n\n\n\nBody: Complete your order in less than a minute.\n\n\n\nWhite pill-shaped CTA button: Complete My Order → (linked to {{cart.checkout_url}})\n\n\n\nSticky bar layout with text on the left and button on the right\n\n\n\n\n\n\n\n\nYou can edit, duplicate, or replace this banner without any restrictions.\n\n\n\nNote\nThe block editor may show a critical error if your server memory limit is too low. If this happens, increase the memory limit of your site.\n\n\n\n\n5. How Visitors See the Banner\n\n\n\nSticky position (Top or Bottom): The banner is fixed to the top or bottom of the page and stays visible as the visitor scrolls. It appears on top of page content.\n\n\n\nShortcode position: The banner renders inline at the exact location of the [wcar_banner] shortcode. It scrolls with the page and is not fixed.\n\n\n\nClose button (×): Visitors can dismiss the banner by clicking the close button. Once dismissed, the banner does not reappear in that browser until local storage is cleared. The close button color automatically inverts to contrast the banner background (e.g. white banner → black button; black banner → white button).\n\n\n\nImpression cap: Once a visitor has seen the banner the configured number of times, it stops showing for that visitor.\n\n\n\n6. Page Targeting Examples\n\n\n\nGoalShow On PagesURL SlugsBanner on home and shop pagesHome, Shop(empty)Banner on cart, checkout, and a specific landing pageCart, Checkoutwinter-saleBanner only on a single sale page(none)flash-sale-2026Banner only where shortcode is placed(none, set Position = Custom)(empty)\n\n\n\n7. Cross-Subdomain Setup\n\n\n\nIf your store is on shop.example.com and you want the banner to also appear on www.example.com:\n\n\n\n\nIn wp-config.php, define COOKIE_DOMAIN to share the visitor cookie across both subdomains: define( \'COOKIE_DOMAIN\', \'.example.com\' );\n\n\n\nIn Allowed Origins, add the marketing site origin (e.g. https://www.example.com) — one per line.\n\n\n\nCopy the embed snippet shown beneath the Allowed Origins field and paste it into any page on the marketing site where you want the banner to appear.\n\n\n\n\nNote\nChrome and Edge require HTTPS on both sides for cross-site cookies to work. Firefox is more permissive. If the banner works in Firefox but not Chrome, your marketing site is likely running on http:// — both sites need HTTPS.\n\n\n\n\n8. Frequently Asked Questions\";s:3:\"url\";s:81:\"https://cartflows.com/docs/on-site-reminder-banner-for-cart-abandonment-recovery/\";s:4:\"slug\";s:53:\"on-site-reminder-banner-for-cart-abandonment-recovery\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-22T10:05:41+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:33;O:8:\"stdClass\":8:{s:2:\"id\";i:75895;s:5:\"title\";s:38:\"Admin Copy of Recovery Emails (CC/BCC)\";s:7:\"content\";s:2879:\"The Admin Copy feature in Cart Abandonment Recovery Pro lets you receive a copy of every recovery email sent to your customers from a specific follow-up email template. The copy contains the live coupon code, real cart contents, and actual send time — exactly what the customer receives. It is intended for monitoring purposes.\n\n\n\nThis feature is configured per template, so you can choose to receive copies only from the emails you want to track.\n\n\n\n1. Where to Find It\n\n\n\nAdmin Path: WooCommerce &gt; Cart Abandonment Recovery &gt; Follow Up Emails &gt; (Edit a template)\n\n\n\n\n\n\n\nThe copy settings appear within the individual email template settings. There is no single global toggle — the option is set separately for each template.\n\n\n\n2. Settings\n\n\n\n1. Send a Copy to Admin (Toggle)\n\n\n\n\nDefault: Off\n\n\n\nEnables or disables the admin copy for this template.\n\n\n\nWhen disabled, no copies are sent, even if addresses are configured.\n\n\n\n\n\n\n\n\n2. Copy Type\n\n\n\n\nDefault: BCC\n\n\n\nBCC — sends a hidden copy; the admin address is not visible to the customer.\n\n\n\nCC — sends a visible copy; the admin address appears in the email header the customer receives.\n\n\n\n\n\n\n\n\n3. Copy To Email Address\n\n\n\n\nDefault: Empty (falls back to site admin email)\n\n\n\nEnter one or more email addresses to receive the copy.\n\n\n\nSeparate multiple addresses with commas.\n\n\n\nIf left blank or all entries are invalid, the copy is sent to the site\'s admin email.\n\n\n\n\n\n\n\n\n3. BCC vs CC\n\n\n\nBCC (Recommended): The admin address is hidden from the customer and will not appear in any \"Reply All\" thread.\n\n\n\nCC: The admin address is visible to the customer in the email header. Use this only if you intentionally want the customer to see that an internal address is copied.\n\n\n\n4. What Gets Copied\n\n\n\nWhen admin copy is enabled, the following is copied for each genuine recovery email sent from that template:\n\n\n\n\nLive coupon code (if applicable)\n\n\n\nReal cart contents\n\n\n\nCustomer\'s checkout recovery link\n\n\n\nCustomer\'s unsubscribe link\n\n\n\n\nImportant: The checkout and unsubscribe links in the copy are tied to the customer\'s cart and account. Do not click them — they are intended for monitoring only.\n\n\n\n5. What Does NOT Get Copied\n\n\n\n\nTest emails sent via \"Send Test Email\" are never copied.\n\n\n\nPreview emails are never copied.\n\n\n\nCopies are only triggered by genuine recovery emails sent to real customers.\n\n\n\n\n6. Things to Keep in Mind\n\n\n\n\nVolume: Every real send from an enabled template generates a copy. On a high-traffic store, this can add up. Consider using a dedicated mailbox as the recipient address.\n\n\n\nInvalid addresses: Invalid entries are skipped. If no valid addresses remain, the copy falls back to the site admin email.\n\n\n\nPer-template scope: Enabling admin copy on one template does not affect other templates. Each template has its own independent setting.\n\n\n\n\n7. Frequently Asked Questions\";s:3:\"url\";s:64:\"https://cartflows.com/docs/admin-copy-of-recovery-emails-cc-bcc/\";s:4:\"slug\";s:36:\"admin-copy-of-recovery-emails-cc-bcc\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-22T10:11:33+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:34;O:8:\"stdClass\":8:{s:2:\"id\";i:75819;s:5:\"title\";s:56:\"How to Configure Abandonment Timeout / Cart Cut-Off Time\";s:7:\"content\";s:2908:\"The Cart Abandonment Cut-Off Time controls how long the plugin waits before deciding that an in-progress checkout is \"abandoned\" — and therefore eligible for recovery emails.\n\n\n\nGetting this timing right is critical:\n\n\n\n\nToo short → you\'ll email customers who are still filling out the form.\n\n\n\nToo long → you\'ll miss the ideal recovery window (most recoveries happen within the first few hours).\n\n\n\n\nThis guide covers the two key timing settings, how to configure them, and recommended values based on store type.\n\n\n\nThe Two Key Timing Settings\n\n\n\nSettingWhat It DoesCart abandoned cut-off timeHow long after a customer stops interacting with checkout before the cart is marked as abandoned. Minimum: 10 minutes.Abandoned cart lost timeHow long an abandoned cart stays in the recovery queue before being marked as lost (no more emails sent). Default: 30 days.\n\n\n\nPrerequisites\n\n\n\n\nCart Abandonment Recovery plugin installed and activated\n\n\n\nCart tracking enabled under Settings > Enable Tracking\n\n\n\n\nStep-by-Step: Configuring Cut-Off Time\n\n\n\nStep 1 — Open Settings\n\n\n\nGo to WooCommerce > Cart Abandonment > Settings > General.\n\n\n\n\n\n\n\nStep 2 — Set the Cart Abandoned Cut-Off Time\n\n\n\nLocate the \"Cart abandoned cut-off time\" field. Enter the number of minutes to wait after the customer stops interacting with the checkout.\n\n\n\n\n\n\n\nStep 3 — Set the Abandoned Cart Lost Time\n\n\n\nLocate the \"Abandoned cart lost time\" field. Enter the number of days after which unrecovered carts are marked as Lost.\n\n\n\n\nDefault: 30 days\n\n\n\nAfter this period, no more recovery emails will be sent for that cart.\n\n\n\n\n\n\n\n\nRecommended Values by Store Type\n\n\n\nStore TypeCut-Off TimeLost TimeLow-consideration purchases (apparel, accessories)15–30 min7–14 daysMedium-consideration (electronics, home goods)30–60 min14–30 daysHigh-consideration B2B / High-ticket60–120 min30–60 daysDigital products / Courses15–30 min7–14 daysSubscriptions30–60 min14–30 days\n\n\n\nHow the Timing Works (Under the Hood)\n\n\n\n\nCustomer starts checkout → enters email, name, address.\n\n\n\nTracking begins → cart details are saved in the database.\n\n\n\nCustomer leaves without purchasing\n\n\n\nCut-off timer starts → (e.g., 15 minutes)\n\n\n\nAfter cut-off → cart status changes to Abandoned, email queue activates.\n\n\n\nRecovery emails sent → based on individual email template timing (e.g., \"Send after 1 hour\").\n\n\n\nIf no recovery by lost time → cart marked Lost, removed from recovery queue.\n\n\n\n\nTips &amp; Best Practices\n\n\n\n\nStart with 15–30 minutes and adjust based on recovery rates.\n\n\n\nWatch your Reports — if recovery rate is low, try a shorter cut-off (faster is often better).\n\n\n\nAlign email timing with cut-off — if your cut-off is 30 min, your first recovery email should ideally send 30 min to 1 hour after.\n\n\n\nA/B test timing by tracking performance before and after changes (over 2–4 week periods).\n\n\n\n\nFAQs\";s:3:\"url\";s:82:\"https://cartflows.com/docs/how-to-configure-abandonment-timeout-cart-cut-off-time/\";s:4:\"slug\";s:54:\"how-to-configure-abandonment-timeout-cart-cut-off-time\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-09T21:08:29+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:35;O:8:\"stdClass\":8:{s:2:\"id\";i:75805;s:5:\"title\";s:33:\"Recovering Unpaid / Failed Orders\";s:7:\"content\";s:3665:\"Not every unfinished sale is an abandoned cart — sometimes a customer reaches the final step, clicks \"Place Order\", but the payment fails, stays pending, or times out. These orders still represent interested buyers who can be recovered with the right follow-up.\n\n\n\nThis guide explains how Cart Abandonment Recovery handles orders with Pending and Failed statuses, and how to configure the plugin to either recover them or exclude them from recovery emails.\n\n\n\nUnderstanding Order Statuses in WooCommerce\n\n\n\nStatusMeaningPending paymentOrder placed, but payment not yet received (e.g., bank transfer, cash on delivery)FailedPayment attempt failed (wrong card, declined, gateway timeout)On holdAwaiting manual confirmation or reviewProcessingPayment received, order being preparedCompletedFulfilled order\n\n\n\nBy default, Cart Abandonment Recovery treats orders as \"completed\" when they move to Processing or Completed — meaning the cart stops receiving recovery emails.\n\n\n\nFor Pending, Failed, or On hold orders, you have control over whether recovery emails continue.\n\n\n\nPrerequisites\n\n\n\n\nWooCommerce checkout configured with at least one payment gateway\n\n\n\nEmail templates set up under the Follow Up Templates tab\n\n\n\n\nHow Pending / Failed Orders Are Handled\n\n\n\n\nCustomer fills out the checkout form — cart is tracked.\n\n\n\nCustomer clicks \"Place Order\" — WooCommerce creates an order with status Pending or Failed (depending on gateway response).\n\n\n\nThe plugin checks the status against the \"Exclude email sending for\" setting.\n\n\n\nIf the status is not excluded, recovery emails are sent based on your templates.\n\n\n\nWhen the order eventually reaches Processing or Completed, the cart is marked as Recovered.\n\n\n\n\nStep-by-Step: Configuring Recovery for Pending / Failed Orders\n\n\n\nStep 1 — Open Settings\n\n\n\nNavigate to WooCommerce &gt; Cart Abandonment &gt; Settings &gt; General.\n\n\n\nStep 2 — Find the \"Exclude Email Sending For\" Option\n\n\n\nScroll down to find the Exclude Email Sending For multi-select dropdown.\n\n\n\nThis multi-select field lets you choose which order statuses should NOT receive recovery emails.\n\n\n\nStep 3 — Choose Your Strategy\n\n\n\nOption A — Recover Pending/Failed Orders (Recommended)Do NOT add \"Pending payment\" or \"Failed\" to the excluded list. The plugin will continue sending recovery emails encouraging the customer to complete payment.\n\n\n\nOption B — Skip Pending OrdersIf you prefer not to chase pending payments (e.g., bank transfer orders you trust will arrive), add \"Pending payment\" to the excluded list.\n\n\n\nOption C — Skip Failed OrdersIf your checkout allows automatic retries or you have a separate flow for failed payments, add \"Failed\" to the excluded list.\n\n\n\n\n\n\n\nWriting Effective Recovery Emails for Pending / Failed Orders\n\n\n\nFor unpaid orders, your messaging should be different from standard cart abandonment. Try these patterns in your email templates:\n\n\n\n\nSubject: \"Your order is just one step away — complete your payment\"\n\n\n\nSubject: \"We couldn\'t process your payment — let\'s fix that\"\n\n\n\nInclude a clear call-to-action linking to the checkout\n\n\n\nOffer alternative payment methods if available\n\n\n\nUse {{cart.abandoned_date}} to reference when they last tried\n\n\n\n\nTips &amp; Best Practices\n\n\n\n\nSplit your templates — create separate templates for \"abandoned at checkout\" vs. \"pending payment\" with different tone.\n\n\n\nShorter follow-up times for failed payments — a 15–30 minute delay is often more effective than hours.\n\n\n\nFor high-value orders, consider a manual phone follow-up alongside the email.\n\n\n\nMonitor your payment gateway — a surge in failed orders may indicate gateway issues.\n\n\n\n\nFAQs\";s:3:\"url\";s:59:\"https://cartflows.com/docs/recovering-unpaid-failed-orders/\";s:4:\"slug\";s:31:\"recovering-unpaid-failed-orders\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-16T19:58:58+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:36;O:8:\"stdClass\":8:{s:2:\"id\";i:75730;s:5:\"title\";s:71:\"How to Test Cart Abandonment Recovery Emails (End-to-End Testing Guide)\";s:7:\"content\";s:4760:\"Before going live with your Cart Abandonment Recovery campaigns, it\'s important to test your emails end-to-end to ensure:\n\n\n\n\nEmails are being delivered (not going to spam)\n\n\n\nEmail shortcodes are rendering correctly\n\n\n\nRecovery links return customers to their cart\n\n\n\nCoupons (if included) are applying properly\n\n\n\n\nThis guide walks you through two testing methods — a quick preview test and a full end-to-end test that simulates a real abandoned cart scenario.\n\n\n\nPrerequisites\n\n\n\n\nCart tracking enabled under Settings > Enable Tracking\n\n\n\nAt least one email template configured under the Follow Up Templates tab\n\n\n\nWorking email on your site (ideally with SMTP configured)\n\n\n\n\nMethod 1 — Quick Preview Test (Send Test Email)\n\n\n\nThis is the fastest way to check how your email looks in an inbox.\n\n\n\nStep 1 — Open the Template Editor\n\n\n\nGo to WooCommerce > Cart Abandonment > Follow Up Templates and click the&#xfe0f; edit icon on the template you want to test. The template editor opens as a right-side drawer.\n\n\n\n\n\n\n\nStep 2 — Use the \"Send Test Email To\" Field\n\n\n\nNear the bottom of the drawer, find the Send Test Email To section. Enter the email address where you want to receive the test.\n\n\n\n\n\n\n\nStep 3 — Click \"Send a Test Email\"\n\n\n\nClick the Send a Test Email button — you should receive the email within a minute.\n\n\n\nNote\nTest emails use sample data for email shortcodes (e.g. \"John Doe\" for the customer\'s name). This is normal and helps you verify the layout.\n\n\n\n\nStep 4 — Check the Email\n\n\n\nVerify in your inbox:\n\n\n\n\nEmail arrived (check spam if not in inbox)\n\n\n\nSubject line renders correctly\n\n\n\nEmail shortcodes show sample values\n\n\n\nLinks are clickable\n\n\n\nImages load properly\n\n\n\nUnsubscribe link appears at the bottom\n\n\n\n\nMethod 2 — Full End-to-End Test (Recommended)\n\n\n\nThis simulates a real abandoned cart and lets you verify the full recovery flow.\n\n\n\nStep 1 — Temporarily Lower the Cut-Off Time\n\n\n\nGo to Settings > General and temporarily change:\n\n\n\n\nCart abandoned cut-off time to 10 minutes (minimum allowed)\n\n\n\n\nRemember: Change it back to your desired value (e.g. 15–30 minutes) after testing.\n\n\n\nStep 2 — Add Your Test Email to Follow Up Templates\n\n\n\nMake sure the template you\'re testing is enabled (toggle ON in the Status column or inside the drawer) and the Send This Email timing (e.g. \"Send after X minutes\") is short enough for your test.\n\n\n\nStep 3 — Simulate an Abandoned Cart\n\n\n\n\nOpen an incognito/private browser window.\n\n\n\nVisit your store and add a product to cart.\n\n\n\nGo to the checkout page.\n\n\n\nFill in the email, first name, and last name — these are required for tracking.\n\n\n\nStart filling other fields, but do not complete the purchase.\n\n\n\nClose the tab.\n\n\n\n\nStep 4 — Wait for the Cut-Off Time\n\n\n\nAfter your cut-off time passes (e.g. 10 minutes), the plugin will:\n\n\n\n1. &nbsp; Mark the cart as Abandoned in the Reports tab\n\n\n\n\n\n\n\n2. &nbsp; Schedule the recovery email based on your template settings\n\n\n\nStep 5 — Check Your Inbox\n\n\n\nYou should receive the recovery email at your test address. Verify:\n\n\n\n\nShortcode shows, your real test data (e.g. your actual first name)\n\n\n\nCheckout recovery link opens your cart with the items pre-filled\n\n\n\nCoupon code (if configured) auto-applies on checkout\n\n\n\nUnsubscribe link works\n\n\n\n\nStep 6 — Complete the Test Purchase\n\n\n\nClick through the checkout link in the email and complete the order. Return to the Reports tab — the cart status should update from Abandoned → Successful.\n\n\n\n\n\n\n\nStep 7 — Restore Your Settings\n\n\n\nDon\'t forget to:\n\n\n\n\nChange the cut-off time back to your preferred value (15–30 min)\n\n\n\nDelete the test abandoned cart and order if needed\n\n\n\n\nTroubleshooting\n\n\n\nEmail Didn\'t Arrive?\n\n\n\n\nCheck spam/junk folder\n\n\n\nVerify your From Email / From Name under Settings > Email Settings\n\n\n\nInstall an SMTP plugin like SureMail to improve deliverability\n\n\n\nCheck WordPress > Tools > Site Health for mail-related warnings\n\n\n\n\nShortcode Show {{customer.firstname}} Instead of the Name?\n\n\n\n\nMake sure you\'re using the correct merge tag syntax (with double curly braces and lowercase).\n\n\n\nIn full end-to-end tests, the customer must have entered their first name on the checkout form.\n\n\n\n\nCart Didn\'t Get Marked as Abandoned?\n\n\n\n\nConfirm Enable Tracking is ON\n\n\n\nConfirm you entered your email on checkout before closing\n\n\n\nWait the full cut-off time before checking the Reports tab\n\n\n\n\nTips &amp; Best Practices\n\n\n\n\nTest every template you create — subject, body, timing, and coupon behavior\n\n\n\nTest on multiple inboxes — Gmail, Outlook, Apple Mail all render HTML differently\n\n\n\nTest on mobile — over 50% of emails are opened on phones\n\n\n\nTest after changing any setting — timing, sender details, coupon codes\n\n\n\n\nFAQs\";s:3:\"url\";s:97:\"https://cartflows.com/docs/how-to-test-cart-abandonment-recovery-emails-end-to-end-testing-guide/\";s:4:\"slug\";s:69:\"how-to-test-cart-abandonment-recovery-emails-end-to-end-testing-guide\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-16T09:52:40+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:37;O:8:\"stdClass\":8:{s:2:\"id\";i:75710;s:5:\"title\";s:52:\"Cart Abandonment Analytics &#038; Reporting Overview\";s:7:\"content\";s:4525:\"Introduction\n\n\n\nThe Cart Abandonment Recovery plugin comes with a built-in analytics dashboard and reporting area that give you a clear picture of how many carts are being abandoned, how many you\'re recovering, and how much revenue your recovery campaigns are generating.\n\n\n\nThis guide walks you through every metric, filter, and table available — so you can make data-driven decisions to improve your recovery rate.\n\n\n\nPrerequisites\n\n\n\n\nCart tracking enabled under Settings &gt; General &gt; Enable Tracking\n\n\n\nAt least a few recorded abandoned and/or recovered carts (reports will appear empty otherwise)\n\n\n\n\nOverview: Two Places to Find Analytics\n\n\n\nLocationWhat You\'ll FindDashboard tabHigh-level summary: 6 stat cards + two-series revenue chartReports &gt; Follow Up tabFull abandoned carts list with email-level detail and exportReports &gt; Product tabProduct-level abandonment stats (Pro)\n\n\n\nThe Dashboard Tab\n\n\n\nGo to WooCommerce &gt; Cart Abandonment — the Dashboard is the default landing tab.\n\n\n\n\n\n\n\nSix Stat Cards\n\n\n\nMetricWhat It MeansRecovered RevenueTotal revenue generated through successful recoveriesRecovered OrdersAbandoned carts that converted into completed orders after recoveryRecoverable RevenueTotal order value of carts that are still eligible for recoveryRecoverable OrdersCarts currently in the recovery queue (emails being sent or scheduled)Lost OrdersCarts that were not recovered within the configured \"lost time\" windowRecovery RatePercentage of abandoned carts that were successfully recovered\n\n\n\nDate Range Picker\n\n\n\nTop-right of the Dashboard. Filter all stats and the chart by:\n\n\n\n\nToday / Yesterday / Last Week / Last Month\n\n\n\nCustom date range\n\n\n\n\nClick Clear Filter to reset to all-time.\n\n\n\nRevenue Chart\n\n\n\nBelow the stat cards: a two-series line chart showing Recoverable Revenue vs. Recovered Revenue over time. Useful for spotting trends and measuring campaign impact.\n\n\n\nReports &gt; Follow Up\n\n\n\nGo to WooCommerce &gt; Cart Abandonment &gt; Reports &gt; Follow Up.\n\n\n\n\n\n\n\nControls\n\n\n\n\nSearch by email\n\n\n\nFilter by status (All / Recoverable / Recovered / Lost)\n\n\n\nDate range picker (mm/dd/yyyy – mm/dd/yyyy)\n\n\n\nExport button — download a CSV of the filtered view\n\n\n\n\nThe Abandoned Carts Table\n\n\n\nEach row represents one tracked cart:\n\n\n\nColumnDescriptionCustomer EmailShopper\'s email address (primary identifier)Order TotalTotal value of the cartCustomer NameFull name if provided at checkoutStatusRecoverable, Recovered, or LostDate AbandonedWhen the cart was marked as abandonedActionsView details, unsubscribe, or delete\n\n\n\nBulk Actions\n\n\n\nCheck multiple rows, then use the Bulk Actions dropdown:\n\n\n\n\nDelete selected carts\n\n\n\nUnsubscribe selected customers\n\n\n\n\nReports &gt; Product (Pro)\n\n\n\nGo to WooCommerce &gt; Cart Abandonment &gt; Reports &gt; Product.\n\n\n\nShows which individual products appear most often in abandoned carts — useful for identifying high-abandonment SKUs and adjusting pricing, descriptions, or recovery offers accordingly.\n\n\n\nPer-Template Metrics in Follow Up Templates (Pro)\n\n\n\nThe Follow Up Templates list (under the Email sub-tab) shows per-template performance columns:\n\n\n\nColumnWhat It MeansSentTotal emails sent from this templateOpen Rate% of sent emails that were openedClick Rate% of opened emails where a link was clickedConversion Rate% that resulted in a recovered orderUnsubscribedNumber of unsubscribes triggered from this template\n\n\n\nUse these to compare which email in your sequence (e.g., 30-min vs. 1-day vs. 3-day) drives the most recoveries.\n\n\n\n\n\n\n\nRecovery Report Emails\n\n\n\nThe plugin can automatically email a weekly recovery summary to one or more admin addresses.\n\n\n\nSetup: Go to Settings &gt; Recovery Report &gt; enable Send Recovery Report Emails &gt; enter admin email addresses (one per line).\n\n\n\nThis is helpful for store managers who want a regular digest without logging into WordPress every week.\n\n\n\nTips &amp; Best Practices\n\n\n\n\nCheck the Dashboard weekly — a sudden spike in Lost Orders may indicate an email deliverability issue.\n\n\n\nCompare date ranges — use custom ranges to measure the impact of changes in your templates or timing.\n\n\n\nAim for a recovery rate of 10%+ — industry average for well-optimized campaigns.\n\n\n\nIf Recovered Revenue is low but Recoverable Orders is high, your emails may not be landing in inboxes — check SPF/DKIM setup.\n\n\n\nUse per-template metrics to identify which email in your sequence earns the most conversions — then optimize timing and copy accordingly.\n\n\n\n\nFAQs\";s:3:\"url\";s:73:\"https://cartflows.com/docs/cart-abandonment-analytics-reporting-overview/\";s:4:\"slug\";s:45:\"cart-abandonment-analytics-reporting-overview\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-15T19:48:16+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:38;O:8:\"stdClass\":8:{s:2:\"id\";i:75669;s:5:\"title\";s:64:\"Setting Up Abandoned Cart Recovery for Guest vs Registered Users\";s:7:\"content\";s:3590:\"Introduction\n\n\n\nWhenever a shopper — whether logged in or checking out as a guest — leaves your WooCommerce store before completing their purchase, Cart Abandonment Recovery can automatically capture their details and send follow-up emails to bring them back.\n\n\n\nThis guide explains how the plugin tracks guest and registered users, what\'s captured, and how you can configure your store to recover both types of abandoned carts effectively.\n\n\n\nHow Cart Abandonment Recovery Tracks Users\n\n\n\nThe plugin tracks all visitors who reach your checkout page and start entering their information — regardless of whether they are logged in or purchasing as a guest.\n\n\n\nUser TypeWhen Tracking StartsGuest UsersAs soon as they enter their email address on the checkout formRegistered UsersWhen they land on the checkout page (their email is already known and filled by WooCommerce)\n\n\n\nNote\nThe email address is the key identifier used for recovery. Without an email, the cart cannot be tracked or recovered.\n\n\n\n\nPrerequisites\n\n\n\nBefore configuring recovery for both user types, make sure:\n\n\n\n\nCart Abandonment Recovery (free) is installed and activated.\n\n\n\nWooCommerce is active and checkout is working normally.\n\n\n\nYour site can send emails (a basic SMTP setup is recommended — see Recovery Email Deliverability Best Practices).\n\n\n\n\n\n\n\n\nStep-by-Step: Enabling Tracking for Both Guest and Registered Users\n\n\n\nStep 1 — Open the Plugin Settings\n\n\n\nGo to WordPress Dashboard > WooCommerce > Cart Abandonment > Settings.\n\n\n\n\n\n\n\nStep 2 — Enable Tracking\n\n\n\nUnder the General Settings section, make sure \"Enable Tracking\" is turned ON.\n\n\n\nOnce enabled, the plugin will start capturing email addresses and cart details from every visitor — both guests and logged-in users.\n\n\n\n\n\n\n\nStep 2b — Exclude Specific User Roles From Tracking (Optional)\n\n\n\nUnder General Settings, the \"Disable Tracking For\" multi-select dropdown lets you exclude specific registered-user roles (e.g., Shop Manager, Administrator, Wholesale Customer) from abandonment tracking entirely. Useful for preventing internal test accounts from cluttering your reports.\n\n\n\nStep 3 — Configure the Abandonment Cut-Off Time\n\n\n\nSet the Cart abandoned cut-off time (in minutes). This is how long the plugin waits before marking a cart as abandoned.\n\n\n\n\nRecommended: 15–30 minutes for most stores\n\n\n\nMinimum allowed: 10 minutes\n\n\n\n\nStep 4 — Set Up Your Recovery Emails\n\n\n\nNavigate to the Follow Up Templates tab and customize the recovery emails. Use merge tags like {{customer.firstname}} so the email feels personalized — this works identically for guests and registered users.\n\n\n\n\n\n\n\nStep 5 — Test with Both User Types\n\n\n\nRun a test checkout:\n\n\n\n\nAs a guest — Open an incognito window, add a product to cart, fill in email + details on checkout, and leave the page.\n\n\n\nAs a registered user — Log in with a test account, start a checkout, and abandon it.\n\n\n\n\nCheck the Reports > Follow Up tab after the cut-off time — both sessions should appear in the abandoned carts list.\n\n\n\nTips &amp; Best Practices\n\n\n\n\nAlways include an unsubscribe link using the {{unsubscribe_link}} merge tag — required for legal compliance.\n\n\n\nPersonalize your emails using {{customer.firstname}} — works for both guests and registered users if they entered their name on checkout.\n\n\n\nEnable GDPR consent if you serve EU customers (see GDPR / Privacy Compliance for Cart Tracking).\n\n\n\nGuest carts are only captured after the user types their email on the checkout form. If they leave before that, there\'s no way to contact them.\n\n\n\n\nFAQs\";s:3:\"url\";s:92:\"https://cartflows.com/docs/setting-up-abandoned-cart-recovery-for-guest-vs-registered-users/\";s:4:\"slug\";s:64:\"setting-up-abandoned-cart-recovery-for-guest-vs-registered-users\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-13T17:19:41+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:39;O:8:\"stdClass\":8:{s:2:\"id\";i:75648;s:5:\"title\";s:47:\"How to Add Coupon Incentives to Recovery Emails\";s:7:\"content\";s:4833:\"The Cart Abandonment Recovery plugin can automatically generate a unique coupon code for each abandoned cart email it sends. The coupon is configured entirely inside the email template — there is no need to create coupons manually in WooCommerce. Each customer receives their own one-time code, which can be applied automatically when they click the recovery link.\n\n\n\nHow It Works\n\n\n\nWhen Create Coupon Code is enabled on an email template, the plugin generates a unique coupon at send time for each customer. The coupon is created in WooCommerce automatically in the background, linked to that specific abandoned cart session.\n\n\n\n\nEach customer gets a unique coupon code — codes are not shared or reusable across customers.\n\n\n\nIf Auto Apply Coupon is enabled, the coupon is applied at checkout the moment the customer clicks {{cart.checkout_url}} — no manual entry required.\n\n\n\nExpired and used coupons can be cleaned up automatically via the plugin\'s coupon cleanup settings.\n\n\n\n\nEnabling and Configuring the Coupon on a Template\n\n\n\nOpen any email template from WooCommerce &gt; Cart Abandonment &gt; Follow Up Templates, edit the, email template then scroll down to the coupon settings section.\n\n\n\nCoupon settings inside an email template\n\n\n\n\n\n\n\nCoupon Settings Reference\n\n\n\nThe following settings are available once Create Coupon Code is toggled ON:\n\n\n\nSettingDescriptionCreate Coupon CodeMaster toggle. When ON, the plugin auto-generates a unique coupon for each customer at the time the email is sent. When OFF, no coupon is created or included.Discount TypeSets the type of discount. Options include Percentage Discount, Fixed Cart Discount, and Fixed Product Discount.Coupon AmountThe value of the discount. For percentage discounts, enter a number between 1 and 100. For fixed discounts, enter the monetary amount.Coupon Expires AfterHow long after the email is sent the coupon remains valid. Enter a number and select Minutes, Hours, or Days. Setting an expiry creates urgency.Free ShippingWhen enabled, the coupon also grants free shipping on the order, regardless of the store\'s shipping rules.Individual Use OnlyWhen enabled, the coupon cannot be combined with other coupon codes at checkout.Auto Apply CouponWhen enabled, the coupon is applied automatically when the customer clicks the recovery link. The customer does not need to enter the code manually.\n\n\n\nDisplaying the Coupon in the Email Body\n\n\n\nEven with Auto Apply enabled, it is good practice to display the coupon code visibly in the email body. This reinforces the offer and builds trust. Use these shortcodes:\n\n\n\nShortcodeWhat It Outputs{{cart.coupon_code}}Displays the unique coupon code generated for this customer.{{cart.checkout_url}}The recovery link that restores the cart and auto-applies the coupon at checkout (when Auto Apply is ON).\n\n\n\nExample email body snippet:\n\n\n\nHi {{customer.firstname}},You left something behind! Here\'s an exclusive discount to complete your order:&nbsp;&nbsp;Your code: {{cart.coupon_code}}It\'s applied automatically when you click below:&nbsp;&nbsp;{{cart.checkout_url}}\n\n\n\nUsing Coupon Expiry to Create Urgency\n\n\n\nThe Coupon Expires After field sets a countdown from the moment the email is sent. A short expiry window encourages customers to act quickly rather than saving the email for later.\n\n\n\n\n 24 Hours — strong urgency, works well for a final email in a sequence.\n\n\n\n48–72 Hours — balanced urgency, gives the customer time without feeling pressured.\n\n\n\n7 Days — low urgency, suitable for stores that want a relaxed recovery approach.\n\n\n\n\nTip: Mention the expiry in the email subject line and body to reinforce urgency — for example: \"Your 10% discount expires in 24 hours.\"\n\n\n\nWhen to Include a Coupon in a Sequence\n\n\n\nIf you are running a multi-step email sequence, avoid including a coupon in every email. Sending a discount too early reduces its impact and can train customers to abandon intentionally.\n\n\n\n\nEmail 1 (e.g. 1 hour):&nbsp; No coupon — simple cart reminder.\n\n\n\nEmail 2 (e.g. 24 hours): No coupon — reinforce product value.\n\n\n\nEmail 3 (e.g. 3 days):&nbsp; Coupon enabled — final incentive to close the sale.\n\n\n\n\nSee How to Set Up Abandoned Cart Email Sequences (Multi-Step) for full sequence setup guidance.\n\n\n\nCoupon Cleanup\n\n\n\nSince a unique coupon is generated for every email sent, your WooCommerce coupon list can grow quickly. The plugin provides cleanup options under WooCommerce &gt; Cart Abandonment &gt; Settings &gt; Coupon Settings:\n\n\n\n\nDelete Coupons Automatically — runs a weekly cleanup of all expired and used recovery coupons.\n\n\n\nDelete Coupons Manually — immediately removes all expired and used recovery coupons on demand.\n\n\n\n\n\n\n\n\nNote\nManual deletion is immediate and cannot be undone. Only run this if you are sure those coupons are no longer needed.\";s:3:\"url\";s:75:\"https://cartflows.com/docs/how-to-add-coupon-incentives-to-recovery-emails/\";s:4:\"slug\";s:47:\"how-to-add-coupon-incentives-to-recovery-emails\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-13T16:54:50+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:40;O:8:\"stdClass\":8:{s:2:\"id\";i:75592;s:5:\"title\";s:53:\"Using Unique Recovery Links / One-Click Cart Recovery\";s:7:\"content\";s:5140:\"The Cart Abandonment Recovery plugin automatically generates a unique recovery link for every abandoned cart. When a customer clicks this link in a recovery email, their cart is instantly restored and they are taken directly to the checkout page — no need to search for items or re-add products.\n\n\n\nThis guide explains how the recovery link works, how to add it to your email templates, and how to customize the checkout experience customers see when they click through.\n\n\n\nHow It Works\n\n\n\nWhen a cart is abandoned, the plugin captures the cart session and assigns it a unique token. This token is embedded into a personalized checkout URL. When the customer clicks the link:\n\n\n\n\nTheir original cart items are automatically restored.\n\n\n\nAny coupon code configured in the email template is applied automatically.\n\n\n\nThe customer lands directly on the checkout page, ready to complete the purchase.\n\n\n\n\nThis is commonly referred to as One-Click Cart Recovery — the customer does not need to take any manual steps to rebuild their cart.\n\n\n\nAdding the Recovery Link to Your Email Template\n\n\n\nTo include the recovery link in a recovery email, use the {{cart.checkout_url}} shortcode in your email template.\n\n\n\nTo add the link:\n\n\n\n1. Go to WooCommerce > Cart Abandonment > Follow Up Templates.\n\n\n\n\n\n\n\n2. Open an existing template or create a new one.\n\n\n\n\n\n\n\n3. In the email body, insert the shortcode {{cart.checkout_url}} wherever you want the recovery link to appear.\n\n\n\n\n\n\n\n4. Save your template.\n\n\n\nNote\nThe {{cart.checkout_url}} shortcode generates a complete, unique URL for each customer. You can use it as a plain text link or wrap it in a button using your email editor\'s link/button tools.\n\n\n\n\nUsing the Shortcode as a Button\n\n\n\nFor higher click-through rates, it is recommended to display the recovery link as a button. The email editor allows you to apply button styling to a link using HTML editor. Simply use {{cart.checkout_url}} as the URL target of a button element.\n\n\n\n&lt;a href=\"{{cart.checkout_url}}\" style=\"display:inline-block;background-color:#2271b1;color:#ffffff;padding:12px 24px;text-decoration:none;border-radius:4px;font-weight:bold;\">Complete Your Purchase&lt;/a>\n\n\n\nExample display text for the button:\n\n\n\n\nComplete Your Purchase\n\n\n\nReturn to Your Cart\n\n\n\nClaim Your Discount\n\n\n\n\nCombining the Recovery Link with a Coupon\n\n\n\nYou can pair the {{cart.checkout_url}} shortcode with the {{cart.coupon_code}} shortcode to display a discount offer alongside the recovery link. When the customer clicks the checkout URL, the coupon is applied automatically — they do not need to enter the code manually.\n\n\n\nExample email copy:\n\n\n\nHi {{customer.firstname}},You left something behind! Use code {{cart.coupon_code}} to get a discount — it\'s applied automatically when you click the link below.{{cart.checkout_url}}\n\n\n\nNote\nTo generate a coupon automatically in recovery emails, you must configure a coupon in the email template settings. See the Configuring Cart Abandonment Recovery Settings documentation for more details.\n\n\n\n\nAvailable Shortcodes for Recovery Emails\n\n\n\nThe following shortcodes can be used in any recovery email template to personalize the message and include the recovery link.\n\n\n\nShortcodeDescription{{cart.checkout_url}}The unique recovery link that restores the customer\'s cart and redirects them to checkout.{{cart.coupon_code}}The coupon code automatically applied when the customer clicks the recovery link.{{customer.firstname}}The customer\'s first name.{{customer.lastname}}The customer\'s last name.{{customer.fullname}}The customer\'s full name.{{cart.product.table}}A table showing abandoned products with name, image, quantity, price, and line subtotal.{{cart.product.names}}A plain-text list of the abandoned product names.{{cart.abandoned_date}}The date on which the cart was abandoned.{{cart.unsubscribe}}An unsubscribe link allowing customers to opt out of future recovery emails.{{admin.firstname}}The shop owner\'s or administrator\'s name.{{admin.company}}The shop or company name.{{site.url}}The main URL of the store.\n\n\n\nWhat Customers See When They Click the Link\n\n\n\nWhen a customer clicks the {{cart.checkout_url}} link in a recovery email:\n\n\n\n\nThey are taken directly to the WooCommerce checkout page.\n\n\n\nTheir previously abandoned cart items are pre-loaded.\n\n\n\nIf a coupon was configured, it is automatically applied to the order.\n\n\n\nAll checkout fields are pre-filled if the customer had previously entered their details.\n\n\n\n\nThe customer can then complete the purchase in a single step — no cart rebuilding required.\n\n\n\nLink Expiry and Security\n\n\n\nEach recovery link contains a unique session token tied to the specific abandoned cart. This means:\n\n\n\n\nEach link is unique to one customer and one cart session.\n\n\n\nA link cannot be reused across different customers.\n\n\n\nOnce the cart is recovered (i.e., the order is completed), no further recovery emails are sent for that session.\n\n\n\n\nNote\nIf a customer clicks the recovery link but does not complete checkout, the cart remains in the abandoned state and future scheduled emails (if configured) will continue to be sent.\";s:3:\"url\";s:79:\"https://cartflows.com/docs/using-unique-recovery-links-one-click-cart-recovery/\";s:4:\"slug\";s:51:\"using-unique-recovery-links-one-click-cart-recovery\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-12T16:51:22+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:41;O:8:\"stdClass\":8:{s:2:\"id\";i:75493;s:5:\"title\";s:61:\"How to Create and Customize Email Templates for Cart Recovery\";s:7:\"content\";s:9815:\"The Cart Abandonment Recovery plugin lets you build a sequence of automated recovery emails that are sent to customers who leave your store without completing checkout. Each email is fully customizable — you control the subject line, timing, body content, coupon incentives, and the conditions under which the email is delivered.\n\n\n\nThis guide walks through how to create a new email template, configure all available settings, personalize the content using shortcodes, and use Dynamic Conditions to send targeted emails to the right customers.\n\n\n\nAccessing Email Templates\n\n\n\nTo manage your recovery email templates, go to:\n\n\n\nWooCommerce &gt; Cart Abandonment &gt; Follow-up Emails\n\n\n\n\n\n\n\nThis screen lists all existing templates in your recovery sequence. You can create new ones, edit existing templates, toggle them on or off, or delete them.\n\n\n\nCreating a New Email Template\n\n\n\nTo create a new recovery email:\n\n\n\n\nGo to WooCommerce > Cart Abandonment > Follow-up Emails.\n\n\n\nClick Add New Template.\n\n\n\nFill in the template fields described in the next section.\n\n\n\nClick Save Template when finished.\n\n\n\n\nNote\nYou can create multiple templates to build a full recovery sequence — for example, a first reminder after 1 hour, a follow-up after 24 hours, and a final email with a coupon after 3 days.\n\n\n\n\nTemplate Fields\n\n\n\nEach email template includes the following settings:\n\n\n\nFieldDescriptionEmail SubjectThe subject line of the recovery email. Shortcodes can be used here to personalize it (e.g., include the customer\'s first name or the store name).Send This EmailSets how long after cart abandonment this email is sent. Enter a number and select the unit: Minutes, Hours, or Days.Email BodyThe main content of the email. Use the visual editor to format the message and insert shortcodes to dynamically populate customer and cart details.CouponOptionally attach a WooCommerce coupon to the email. When enabled, the coupon code is auto-applied when the customer clicks the recovery link.Active / InactiveToggles whether this template is enabled in the sending sequence. Inactive templates are saved but will not be sent.\n\n\n\n\n\n\n\nWriting the Email Body\n\n\n\nThe email body editor supports standard HTML formatting — headings, bold text, links, images, and buttons. Use the toolbar to style your content without writing code.\n\n\n\nTo create a high-converting recovery email, it is recommended to include:\n\n\n\n\nA personalized greeting using {{customer.firstname}}\n\n\n\nThe abandoned product list using {{cart.product.table}}\n\n\n\nA prominent recovery button or link using {{cart.checkout_url}}\n\n\n\nA coupon code (optional) using {{cart.coupon_code}}\n\n\n\nAn unsubscribe link using {{cart.unsubscribe}}\n\n\n\n\nPersonalizing with Shortcodes\n\n\n\nShortcodes let you insert dynamic content into your email subject and body. The plugin replaces each shortcode with the appropriate value at the time the email is sent.\n\n\n\nShortcodeWhere to UseWhat It Inserts{{customer.firstname}}Subject / BodyCustomer\'s first name{{customer.lastname}}Subject / BodyCustomer\'s last name{{customer.fullname}}Subject / BodyCustomer\'s full name{{cart.checkout_url}}BodyUnique recovery link (restores cart, applies coupon){{cart.coupon_code}}BodyThe coupon code assigned to this template{{cart.product.table}}BodyProduct table with name, image, quantity, and price{{cart.product.names}}BodyPlain-text list of abandoned product names{{cart.abandoned_date}}BodyDate the cart was abandoned{{cart.unsubscribe}}BodyUnsubscribe link for the customer{{admin.firstname}}Subject / BodyShop owner / administrator name{{admin.company}}Subject / BodyShop or company name{{site.url}}BodyMain URL of the store\n\n\n\nHere is the Doc with the complete list of shortcodes: https://cartflows.com/docs/shortcode-reference-for-email-fields/\n\n\n\nAdding a Coupon to a Template\n\n\n\nYou can automatically generate a unique discount coupon for each abandoned cart recovery email.\n\n\n\nWhen a coupon is configured:\n\n\n\n\nThe {{cart.coupon_code}} shortcode in the email body will display the auto-generated coupon code.\n\n\n\nIf Auto-apply coupon is enabled, the coupon is automatically applied when the customer clicks the {{cart.checkout_url}} recovery link — no manual entry required.\n\n\n\n\nTo set up a coupon on a template:\n\n\n\n\nOpen or create an email template.\n\n\n\nIn the Coupon section, toggle on Create Coupon Code.\n\n\n\nChoose a Discount Type (Percentage, Fixed Cart, or Free Shipping).\n\n\n\nEnter the Coupon Amount.\n\n\n\nOptionally set an Expiry period and enable Free Shipping or Individual Use Only.\n\n\n\nEnable Auto-apply coupon if you want the coupon applied automatically when the customer clicks the recovery link.\n\n\n\nSave the template.\n\n\n\n\n\n\n\n\nThe plugin will generate a unique coupon code for each customer automatically — no need to create one manually in WooCommerce.\n\n\n\nNote\nYou can also exclude specific products from the coupon in the Exclude Products (Pro) Settings.\n\n\n\n\nSetting the Send Timing\n\n\n\nEach template has a Send This Email field that controls when the email is sent after the cart is abandoned. You can specify a number and select:\n\n\n\n\nMinutes — for immediate or near-immediate follow-up (minimum 10 minutes after the cut-off time)\n\n\n\nHours — for same-day follow-ups\n\n\n\nDays — for multi-day recovery sequences\n\n\n\n\n\n\n\n\nRecommended timing sequence:\n\n\n\nEmail 1 — Send after: 1 Hour (First reminder, no coupon)Email 2 — Send after: 24 Hours  (Follow-up, cart contents reminder) Email 3 — Send after: 3 Days (Final email with coupon incentive)\n\n\n\nNote\nEmails are only sent if the cart is still in an abandoned state at the scheduled send time. If the customer completes their order before the email is due, the email is automatically skipped.\n\n\n\n\nConfiguring Email Sender Settings\n\n\n\nThe \"From\" name and address used in recovery emails are set globally in the plugin settings, not per template. To update these:\n\n\n\n\nGo to WooCommerce > Cart Abandonment > Settings.\n\n\n\nUnder Email Settings, configure:\n\n\n\n\nFieldDescription\"From\" NameThe name displayed as the sender in the customer\'s inbox (e.g., your store name).\"From\" AddressThe email address the recovery emails are sent from.\"Reply-To\" AddressThe address where customer replies are directed. Can differ from the \"From\" address.\n\n\n\n\n\n\n\nUsing Dynamic Conditions (Pro)\n\n\n\nDynamic Conditions allow you to restrict a template so it only sends when specific cart, product, or customer criteria are met. This is a Pro feature available in the Cart Abandonment Recovery Pro plugin.\n\n\n\nWith Dynamic Conditions, you can target emails by:\n\n\n\n\nCart total — e.g., only send for orders above $100\n\n\n\nProduct or product category — e.g., send only when a customer abandons electronics\n\n\n\nBilling country — e.g., target US-based customers with a specific offer\n\n\n\nNumber of cart items — e.g., target carts with 3 or more products\n\n\n\n\nTo know more about how to set up Dynamic Email Conditions, refer to this doc.\n\n\n\nAvailable Conditions and Operators\n\n\n\nFieldDescriptionCart TotalNumeric operators: is equal to, greater than, less than, greater/less than or equal to.ProductExistence operators: Exists / Does not exist. Search for a specific product by name.Product CategoryEquality operators: Equal to / Not equal to. Select from existing categories.Billing CountryEquality operators: Equal to / Not equal to. Select from country dropdown.Number of Cart ItemsNumeric operators: is equal to, greater than, less than, greater/less than or equal to.\n\n\n\nNote\nIf none of the conditions in any rule group are met at send time, the email is not sent and the attempt is recorded as rule-blocked in the email history.\n\n\n\n\nExample Email Templates\n\n\n\nEmail 1 — Simple Reminder (No Coupon)\n\n\n\nSubject:&nbsp; Hey {{customer.firstname}}, you left something behind!&nbsp;Hi {{customer.firstname}},&nbsp;It looks like you left some items in your cart at {{admin.company}}.Your cart is saved — just click the button below to pick upwhere you left off.&nbsp;{{cart.product.table}}&nbsp;Complete your purchase: {{cart.checkout_url}}&nbsp;If you have any questions, just reply to this email.&nbsp;Thanks,{{admin.firstname}}{{admin.company}}&nbsp;Unsubscribe: {{cart.unsubscribe}}\n\n\n\nEmail 3 — Final Offer with Coupon\n\n\n\nSubject:&nbsp; Last chance — here\'s a discount just for you, {{customer.firstname}}&nbsp;Hi {{customer.firstname}},&nbsp;We noticed you haven\'t completed your order yet. As a thank youfor shopping with us, here\'s an exclusive discount:&nbsp;&nbsp;&nbsp;Use code: {{cart.coupon_code}}&nbsp;It\'s applied automatically when you click the link below.This offer won\'t last long!&nbsp;{{cart.product.table}}&nbsp;Claim your discount: {{cart.checkout_url}}&nbsp;Unsubscribe: {{cart.unsubscribe}}\n\n\n\nActivating and Deactivating Templates\n\n\n\nEach template has an Active / Inactive toggle on the Follow-up Emails list screen. Only active templates are included in the sending sequence.\n\n\n\nYou can use this toggle to:\n\n\n\n\nPause a template temporarily without deleting it.\n\n\n\nTest a single template by deactivating all others.\n\n\n\nRun seasonal campaigns by activating specific templates during promotional periods.\n\n\n\n\n\n\n\n\nTips for Effective Recovery Emails\n\n\n\n\nKeep subject lines short and personal. Including the customer\'s name or a reference to their cart improves open rates.\n\n\n\nUse a single clear call to action. One prominent recovery button is more effective than multiple links.\n\n\n\nDelay your first coupon. Send the first email without a coupon to avoid training customers to abandon intentionally. Offer a discount only in a later email.\n\n\n\nAlways include an unsubscribe link. Using {{cart.unsubscribe}} is required for compliance and good email hygiene.\n\n\n\nTest before activating. Use a test email address and a staging cart to verify that shortcodes, coupon codes, and recovery links all work correctly.\";s:3:\"url\";s:89:\"https://cartflows.com/docs/how-to-create-and-customize-email-templates-for-cart-recovery/\";s:4:\"slug\";s:61:\"how-to-create-and-customize-email-templates-for-cart-recovery\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-09T21:08:20+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:42;O:8:\"stdClass\":8:{s:2:\"id\";i:31284;s:5:\"title\";s:54:\"How to Modify the Checkout Page Using Backend Settings\";s:7:\"content\";s:6097:\"CartFlows allows you to customize the Checkout step directly from the backend settings without editing the page design. These settings help you manage products, offers, layout, checkout form behavior, and other configurations from a single place.\n\n\n\nYou can access these options from the Checkout step settings panel within your funnel.\n\n\n\nHow to Access Checkout Step Settings\n\n\n\nFollow the steps below to open the checkout settings.\n\n\n\nStep 1: Navigate to CartFlows &gt; Funnels from your WordPress dashboard.Step 2: Open the funnel where you want to modify the checkout page.\n\n\n\n\n\n\n\nStep 3:&nbsp;Click the settings icon of the&nbsp;Checkout&nbsp;step.\n\n\n\n\n\n\n\nA settings panel will open where you can configure various options for the checkout page.\n\n\n\nAssign Product\n\n\n\nIn this section, you can assign WooCommerce product that will be purchased through the checkout page.\n\n\n\n\n\n\n\nYou can also configure additional options such as:\n\n\n\n\nApplying coupons for promotions (make sure coupons are enabled in WooCommerce settings)\n\n\n\nManaging product variations\n\n\n\nAdding product restrictions\n\n\n\nEnabling quantity selection\n\n\n\n\nOrder Bump\n\n\n\nThe Order Bump option allows you to present an additional offer on the Checkout page to increase the order value.\n\n\n\nYou can create and configure an order bump directly from this section. Once enabled, customers will see the bump offer on the checkout page and can add it to their order with a single click.\n\n\n\n\n\n\n\nRefer to this documentation for more details about Order Bump: https://cartflows.com/docs/how-to-add-order-bumps-to-woocommerce-sales-funnel/\n\n\n\nCheckout Form\n\n\n\nThe Checkout Form tab allows you to manage and customize the checkout fields displayed on the form.\n\n\n\nFrom this section, you can:\n\n\n\n\nEnable Coupon Field – Allows customers to apply coupon codes during checkout.\n\n\n\nEnable Ship to Different Address – Adds a separate shipping address section.\n\n\n\nEnable Google Address Autocomplete – Allows address auto-completion for faster checkout.\n\n\n\nEnable the Custom Field Editor\n\n\n\nShow or hide specific checkout fields\n\n\n\nReorder fields using drag-and-drop\n\n\n\nModify field labels, placeholders, and requirements\n\n\n\n\n\n\n\n\nThese settings help you collect only the necessary information from customers during checkout.\n\n\n\nRefer to this documentation for more details about the Field Editor: https://cartflows.com/docs/custom-checkout-fields-and-its-settings/\n\n\n\nDynamic Offer\n\n\n\nThe Dynamic Offer allows you to control the redirection to Upsell or Downsell steps based on specific conditions set on the checkout page.\n\n\n\nRefer to this documentation for more details about the Dynamic Offer feature: https://cartflows.com/docs/cartflows-dynamic-offers-rule-engine/\n\n\n\nCheckout Design (Including Shortcode)\n\n\n\nThe Design tab allows you to control the layout and appearance of the checkout page and also access the checkout shortcode when needed.\n\n\n\nYou can configure layout options such as:\n\n\n\n\nModern Checkout\n\n\n\nModern One Column\n\n\n\nMultistep Checkout\n\n\n\nOne Column\n\n\n\nTwo Column\n\n\n\nTwo-Step\n\n\n\n\nYou can also customize the checkout appearance by adjusting:\n\n\n\n\nTypography\n\n\n\nPrimary colors\n\n\n\nForm styling options\n\n\n\n\nIf Advanced Options are enabled, you can further customize elements such as:\n\n\n\n\nHeadings\n\n\n\nInput fields\n\n\n\nButtons\n\n\n\nBackground styles\n\n\n\n\nWithin this tab, you can also find the Checkout Shortcode, which includes:\n\n\n\n\nBilling fields\n\n\n\nShipping fields\n\n\n\nOrder details\n\n\n\nPlace Order button\n\n\n\n\nThis shortcode can be used when building a custom checkout layout manually.\n\n\n\n\n\n\n\nThe Design tab may only be visible when the page builder is set to Other in the CartFlows settings.\n\n\n\nTo enable access to this tab:\n\n\n\nStep 1: Navigate to CartFlows &gt; Settings &gt; General.Step 2: Locate the Page Builder option.Step 3: Select Other from the dropdown.Step 4: Click Save Settings.\n\n\n\nOnce saved, the Checkout Design tab will become available in the checkout step settings, allowing you to configure the checkout layout and access the shortcode if required.\n\n\n\n\n\n\n\nCustom CSS and Script\n\n\n\nThe fields to add custom CSS and script are available under the tab Checkout Settings &gt; Settings &gt; General.\n\n\n\nThis section allows you to add scripts to the checkout page, which can be useful for integrations such as:\n\n\n\n\nCustom JavaScript functionality\n\n\n\nCustom CSS\n\n\n\nAnalytics tracking scripts\n\n\n\n\n\n\n\n\nFrequently Asked Questions (FAQ)\n\n\n\n\nWhat can I configure from the CartFlows checkout step backend settings?From the checkout step settings panel, you can assign products, configure order bumps, manage checkout form fields, set up dynamic offers for upsell or downsell redirection, customize the checkout design and layout, and add custom CSS or JavaScript scripts — all without editing the page design directly.\n\n\n\nHow do I add an order bump to my CartFlows checkout page?Open your funnel in CartFlows → Funnels, click the settings icon on the Checkout step, and go to the Order Bump section. From there you can create and configure an order bump offer that customers can add to their order with a single click directly on the checkout page.\n\n\n\nHow do I enable Google Address Autocomplete on the CartFlows checkout form?Go to CartFlows → Funnels, open your funnel, and click the settings icon on the Checkout step. Open the Checkout Form tab and enable the Google Address Autocomplete option. This allows customers to auto-complete their address during checkout for a faster experience.\n\n\n\nWhy can\'t I see the Design tab in my CartFlows checkout step settings?The Design tab is only visible when your page builder is set to \"Other\" in CartFlows settings. Go to CartFlows → Settings → General, set the Page Builder dropdown to \"Other\", and save. The Design tab will then appear in the checkout step settings.\n\n\n\nHow do I add custom CSS or JavaScript to the CartFlows checkout page?Go to Checkout Settings → Settings → General. You will find fields to add custom CSS and scripts. These can be used for custom JavaScript functionality, styling overrides, or analytics tracking integrations on the checkout page.\";s:3:\"url\";s:48:\"https://cartflows.com/docs/modify-checkout-page/\";s:4:\"slug\";s:20:\"modify-checkout-page\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:49:04+05:30\";s:8:\"category\";a:1:{i:0;s:21:\"checkout-field-editor\";}}i:43;O:8:\"stdClass\":8:{s:2:\"id\";i:31092;s:5:\"title\";s:37:\"Placing Shortcode in the Right Places\";s:7:\"content\";s:3606:\"When you create a funnel using one of the ready templates, CartFlows automatically adds the Next Step Link or shortcode to your call-to-action buttons or links.\n\n\n\nIf you’re building your own funnel or editing a step manually, you can copy the link or shortcode from the step settings and place it anywhere on the page.\n\n\n\nNote\nShortcodes are only shown in the step settings if you are using a page builder other than the Block Editor, Elementor, Beaver Builder, or Bricks Builder, and have selected “Other” under the Page Builder option in CartFlows settings.\n\n\n\n\nIf you’re using the Block Editor, Elementor, Beaver Builder, or Bricks Builder, CartFlows includes native elements that can be added directly while editing the page.\n\n\n\nEach step has its own unique shortcode, and it only works inside that specific step. If used on a different page, the shortcode will not work.From the WordPress dashboard, go to CartFlows &gt; Funnels and edit your funnel. To edit a specific step, click the gear icon on that step.\n\n\n\n\n\n\n\nLanding Page\n\n\n\nOpen the Landing Page step and scroll down to the Landing Page Settings section. Under the Shortcodes option, you’ll see the Next Step Link.\n\n\n\nUse this link in your call-to-action button to send users to the Checkout page or the next step in the funnel.\n\n\n\n\n\n\n\nCopy the link, edit your page, and paste it into your call-to-action button.\n\n\n\n\n\n\n\nCheckout Page\n\n\n\nOpen the Checkout Page step and go to the Design tab. In the Shortcodes section, you’ll find the Checkout Page shortcode.\n\n\n\n\n\n\n\nCopy the shortcode, then edit your Checkout page and paste it where you want the form to appear. This will display the customer information form, order details, and the purchase button.\n\n\n\n\n\n\n\nThank You Page\n\n\n\nOpen the Thank You Page step and click the Design tab. Under the Shortcode section, you’ll find the Order Details shortcode.\n\n\n\nUse this shortcode to display a summary of the customer’s order. You can also add other content like a video, image, or social sharing buttons.\n\n\n\n\n\n\n\nNote\nEach step has its own unique shortcode, and it only works inside that specific step. If used on a different page, the shortcode will not work.\n\n\n\n\n\n\n\n\n\n\n\n\nFrequently Asked Questions (FAQ)\n\n\n\n\nWhen do I need to manually add shortcodes in CartFlows?Shortcodes are needed when you build a funnel from scratch or edit a step manually without using a ready-made template. When using templates, CartFlows automatically adds the Next Step Link to call-to-action buttons. Shortcodes are only available if your page builder is set to \"Other\" in CartFlows settings — for Elementor, Block Editor, Beaver Builder, and Bricks Builder, CartFlows provides native elements instead.\n\n\n\nHow do I add a Next Step Link to a landing page button in CartFlows?Go to CartFlows → Funnels, edit your funnel, and click the gear icon on the Landing Page step. Scroll down to the Landing Page Settings section and find the Next Step Link under the Shortcodes option. Copy it, then edit your page and paste it into your call-to-action button.\n\n\n\nCan I use a CartFlows shortcode on any page?No. Each step has its own unique shortcode that only works inside that specific step. If a shortcode is placed on a different page, it will not work.\n\n\n\nHow do I display order details on the Thank You page in CartFlows?Open the Thank You Page step and click the Design tab. Under the Shortcode section, you\'ll find the Order Details shortcode. Use this shortcode to display a summary of the customer\'s order. You can also add other content like a video, image, or social sharing buttons alongside it.\";s:3:\"url\";s:65:\"https://cartflows.com/docs/placing-shortcode-in-the-right-places/\";s:4:\"slug\";s:37:\"placing-shortcode-in-the-right-places\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:46:49+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:44;O:8:\"stdClass\":8:{s:2:\"id\";i:45024;s:5:\"title\";s:62:\"Configuring Cart Abandonment Recovery for WooCommerce Settings\";s:7:\"content\";s:5270:\"This guide explains how to configure the settings available in the Cart Abandonment Recovery for WooCommerce plugin. You can access these settings by navigating to WooCommerce &gt; Cart Abandonment &gt; Settings. The options available here help you track abandoned carts, automate recovery emails, webhook, manage coupons, and ensure privacy compliance.\n\n\n\n\n\n\n\nGeneral Settings\n\n\n\nControl the main behavior for tracking and handling abandoned carts.Enable Tracking\n\n\n\nActivates abandoned cart tracking. When enabled, the plugin monitors carts and triggers recovery actions if checkout is not completed within the set cut-off time.\n\n\n\nCart Abandoned Cut-Off Time\n\n\n\nSet how many minutes after an item is added to the cart (without completing checkout) the cart will be considered abandoned. Minimum: 10 minutes.\n\n\n\nDisable Tracking For\n\n\n\nExclude specific user roles (e.g., Administrator, Editor, Shop Manager) from abandonment tracking. These users will not trigger abandonment or receive recovery emails.\n\n\n\nExclude Email Sending For\n\n\n\nSelect which WooCommerce order statuses (e.g., Processing, Completed) are considered recovered. Once marked as recovered, no further recovery emails are sent.\n\n\n\nNotify Recovery to Admin\n\n\n\nSends a notification email to the site admin when an abandoned cart is recovered.\n\n\n\nWebhook Settings\n\n\n\nControl how webhook events are triggered in your store.\n\n\n\nEnable Webhook\n\n\n\nAllows you to trigger a webhook automatically when a cart is abandoned or recovered. This is useful if you want to connect your store with third-party services for further automation.\n\n\n\nRefer to this documentation to learn more about how to use webhooks.\n\n\n\nCoupon Settings\n\n\n\nManage how recovery coupons are cleaned up.\n\n\n\nDelete Coupons Automatically\n\n\n\nSchedules a weekly cleanup of all expired and used recovery coupons created by the plugin.\n\n\n\nDelete Coupons Manually\n\n\n\nImmediately removes all expired and used coupons created by the plugin.\n\n\n\nEmail Settings\n\n\n\nConfigure sender details for recovery emails.\n\n\n\n“From” Name\n\n\n\nThe name that appears as the sender in recovery emails.\n\n\n\n“From” Address\n\n\n\nThe email address from which recovery emails are sent.\n\n\n\n“Reply-To” Address\n\n\n\nThe email address where customer replies will be sent.\n\n\n\nRecovery Report Settings\n\n\n\nGet regular summary reports about your cart recovery performance.\n\n\n\nSend Recovery Report Emails\n\n\n\nEnable to receive periodic recovery report emails.\n\n\n\nEmail Address\n\n\n\nEnter one or more email addresses (one per line) to receive the reports.\n\n\n\nGDPR Settings\n\n\n\nEnsure your store’s abandoned cart process complies with privacy regulations.\n\n\n\nEnable GDPR Integration\n\n\n\nAdds a consent message below the email field at checkout, informing customers their email and cart details will be saved for recovery purposes.\n\n\n\nGDPR Message\n\n\n\nCustomize the privacy message shown to customers during checkout.\n\n\n\nFor more information about this setting, refer to this documentation.\n\n\n\nAdvanced Settings\n\n\n\nFine-tune plugin behavior and data handling.\n\n\n\nUTM Parameters\n\n\n\nAdd UTM parameters to checkout page links in recovery emails for tracking in analytics. Enter each parameter on a new line.\n\n\n\nDelete Plugin Data\n\n\n\nDelete all plugin data and database tables when uninstalling the plugin. The plugin creates and uses its own database tables to store abandoned cart data. These tables will also be deleted when this option is enabled:\n\n\n\ncartflows_ca_cart_abandonment\ncartflows_ca_email_history\ncartflows_ca_email_templates\nCartflows_ca_email_templates_meta\n\n\n\nNote: All changes are saved automatically, there is no save button in the settings panel.\n\n\n\nFrequently Asked Questions (FAQ)\n\n\n\n\nHow long after cart abandonment does Cart Abandonment Recovery start tracking?You can set the cut-off time yourself — the minimum is 10 minutes after an item is added to the cart without checkout being completed. Once that time passes, the cart is marked as abandoned and recovery emails are triggered.\n\n\n\nCan I exclude certain user roles from abandoned cart tracking?Yes. In the General Settings, use the Disable Tracking For option to exclude specific user roles such as Administrator, Editor, or Shop Manager. Excluded roles will not trigger abandonment tracking or receive recovery emails.\n\n\n\nHow do I stop recovery emails from being sent after an order is completed?Use the Exclude Email Sending For setting to select WooCommerce order statuses such as Processing or Completed. Once an order reaches those statuses, it is marked as recovered and no further recovery emails are sent.\n\n\n\nDoes Cart Abandonment Recovery support GDPR compliance?Yes. Enable the GDPR Integration setting to add a consent message below the email field at checkout, informing customers that their email and cart details will be saved for recovery purposes. You can also customize the consent message text.\n\n\n\nHow do I track recovery email performance in Google Analytics?Go to Advanced Settings and add UTM parameters to the checkout page links included in recovery emails. Enter each parameter on a new line and they will be automatically appended to links in recovery emails for analytics tracking. Note that all changes in this settings panel are saved automatically — there is no save button.\";s:3:\"url\";s:74:\"https://cartflows.com/docs/configuring-cart-abandonment-recovery-settings/\";s:4:\"slug\";s:46:\"configuring-cart-abandonment-recovery-settings\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:46:17+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:45;O:8:\"stdClass\":8:{s:2:\"id\";i:46245;s:5:\"title\";s:23:\"What is Store Checkout?\";s:7:\"content\";s:2477:\"The Store Checkout feature lets you replace the default WooCommerce Checkout page with a CartFlows-powered checkout. It applies across your entire store, including products not assigned to a funnel.\n\n\n\nPreviously, identifying which funnel was assigned as the Global Checkout could be confusing, especially if you had numerous funnels. The new Store Checkout concept simplifies this by providing a dedicated interface and better control, replacing the old Global Checkout approach.\n\n\n\nOnce enabled, the Store Checkout will replace the default WooCommerce checkout page with your CartFlows-designed checkout experience, making it easier to manage and optimize conversions without confusion.\n\n\n\nWhat’s New in Store Checkout?\n\n\n\nHere are the key changes introduced with the Store Checkout feature:\n\n\n\n\nEnable/Disable Store Checkout: You can now toggle whether CartFlows should take over the WooCommerce checkout page.\n\n\n\nFixed Checkout Step Position: The Checkout step in the store flow cannot be reordered. It will always appear right after the Cart page, ensuring the correct flow of WooCommerce transactions.\n\n\n\nRemoved Product Tab: Since this Checkout is designed to replace the default WooCommerce flow, the Product tab has been removed from the settings. If needed, you can still enable it using a filter as outlined in our documentation.\n\n\n\n\nHow to Set Up Store Checkout\n\n\n\nThere are two ways to set up the Store Checkout in CartFlows:\n\n\n\nOption 1: Through the Onboarding Process\n\n\n\n\nIdeal for new users installing CartFlows for the first time.\n\n\n\n\nOption 2: Manual Setup\n\n\n\nFollow these steps to manually configure the Store Checkout:\n\n\n\nStep 1: Navigate to the Store Checkout Menu\n\n\n\nGo to the CartFlows &gt; Store Checkout section from your WordPress dashboard.\n\n\n\n\n\n\n\nStep 2: Create a Store Checkout \n\n\n\nClick the Create Store Checkout button to begin the setup process.\n\n\n\n\n\n\n\nStep 3: Choose a Template\n\n\n\nSelect from our ready-made templates and click Import Template to bring it into your site.\n\n\n\n\n\n\n\nStep 4: Customize and Enable\n\n\n\nEdit the imported template as needed. Once ready, click the Enable Store Checkout button to activate it. This replaces the WooCommerce default checkout with your new CartFlows checkout.\n\n\n\n\n\n\n\nStep 5: Add Additional Steps (Optional)\n\n\n\nYou may add Upsell or Downsell steps after the Checkout page if desired. Other step types like Optin and Landing pages are not applicable in this Store Checkout.\n\n\n\n\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:42:\"https://cartflows.com/docs/store-checkout/\";s:4:\"slug\";s:14:\"store-checkout\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:45:43+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"global-checkout\";}}i:46;O:8:\"stdClass\":8:{s:2:\"id\";i:32705;s:5:\"title\";s:42:\"How to Activate Your CartFlows Pro License\";s:7:\"content\";s:1524:\"To access all CartFlows Pro features and receive automatic updates, you need to activate your license. This documentation will guide you through the process.\n\n\n\nBefore You Start\n\n\n\nBefore activating your license, make sure:\n\n\n\n\nThe CartFlows Pro plugin is installed and activated on your website. If you haven\'t installed it yet, follow this document: How to Install CartFlows Pro\n\n\n\nYou have access to your CartFlows account to retrieve the License Key.\n\n\n\n\nHow to Activate Your CartFlows Pro License\n\n\n\nStep 1: Get Your License Key\n\n\n\n\nLog in to your CartFlows account.\n\n\n\nClick on API Keys from the sidebar.\n\n\n\nCopy your License Key.\n\n\n\n\n\n\n\n\nStep 2: Activate Your License in WordPress\n\n\n\n1. Log in to your WordPress dashboard.2. Go to CartFlows &gt; Settings &gt; License tab.3. Paste your License Key into the field.4. Click the Activate License button.\n\n\n\n\n\n\n\nTroubleshooting License Activation Issues\n\n\n\nIf you’re facing problems while activating your license, refer to this document for detailed troubleshooting steps: Troubleshooting License Activation Issues\n\n\n\nFrequently Asked Questions (FAQ)\n\n\n\n\nWhere do I find my CartFlows Pro license key?Log in to your CartFlows account at my.cartflows.com, click on API Keys from the sidebar, and copy your license key from there.\n\n\n\nHow do I activate my CartFlows Pro license in WordPress?Log in to your WordPress dashboard, go to CartFlows → Settings → License tab, paste your license key into the field, and click the Activate License button to complete activation.\";s:3:\"url\";s:58:\"https://cartflows.com/docs/activate-cartflows-pro-license/\";s:4:\"slug\";s:30:\"activate-cartflows-pro-license\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:45:18+05:30\";s:8:\"category\";a:1:{i:0;s:20:\"installation-updates\";}}i:47;O:8:\"stdClass\":8:{s:2:\"id\";i:32382;s:5:\"title\";s:39:\"Supported Payment Gateways in CartFlows\";s:7:\"content\";s:4484:\"This documentation lists all payment gateways that work with CartFlows and explains their compatibility with the Checkout page and Upsell or Downsell pages.\n\n\n\nCheckout Page\n\n\n\nThe Checkout page in CartFlows supports all payment gateways that are already supported by WooCommerce.\n\n\n\nTo use a gateway, ensure that its integration is enabled or that the required plugin is installed and activated.\n\n\n\nMost payment gateways used on the Checkout page also work with Pre Checkout Offer and Order Bump.\n\n\n\nUpsell / Downsell\n\n\n\nCartFlows supports the following payment gateways for Upsell and Downsell pages:\n\n\n\n\nCOD\n\n\n\nBACS\n\n\n\nPayPal Standard\n\n\n\nPayPal Payments\n\n\n\nWooCommerce Stripe Payment Gateway\n\n\n\nAuthorize.net\n\n\n\nMollie Credit Card and iDEAL\n\n\n\nWooCommerce Square\n\n\n\nWooCommerce Payments\n\n\n\n\nSome gateways support one click upsells while others do not. More compatibility improvements will be added in future updates.\n\n\n\n Cash on Delivery - COD\n\n\n\n\nPayment Gateway: Cash on Delivery\n\n\n\nPlugin Supported: Not required, comes by default with WooCommerce.\n\n\n\n\n Direct Bank Transfers - BACS\n\n\n\n\nPayment Gateway: Direct Bank Transfer\n\n\n\nPlugin Supported: Not required, comes by default with WooCommerce.\n\n\n\n\n PayPal Standard\n\n\n\n\nPayment Gateway: WooCommerce PayPal Payment Gateway\n\n\n\nPlugin Required: None. This gateway is included with WooCommerce.\n\n\n\nTo view the built in WooCommerce gateways go to WordPress Dashboard &gt; WooCommerce &gt; Settings &gt; Payments.\n\n\n\n\n\n\n\n\nWooCommerce PayPal Payments\n\n\n\n\nPayment Gateway: PayPal Payments\n\n\n\nPlugin Required: WooCommerce PayPal Payments plugin from WordPress.org\n\n\n\n\n\n\n\n\nStripe\n\n\n\n\nPayment Gateway: Stripe Payment Gateway\n\n\n\nPlugin Required: WooCommerce Stripe Payment Gateway plugin from WordPress.org\n\n\n\nInfo: CartFlows supports Stripe credit card payments. Other Stripe payment methods are not supported at this time.\n\n\n\n\n\n\n\n\nAuthorize.net\n\n\n\n\nPayment Gateway: Authorize Net Credit Card\n\n\n\nPlugin Required: The official Authorize.net plugin from the WooCommerce store.\n\n\n\nInfo: CartFlows supports only the credit card option provided by Authorize Net.\n\n\n\n\n\n\n\n\nMollie\n\n\n\n\n\n\n\n\nPayment Gateway: Mollie Payments for WooCommerce\n\n\n\nPlugin Required: The official \"Mollie Payments for WooCommerce\" plugin which is available on WordPress.org.\n\n\n\nInfo: CartFlows currently supports only Credit Card and iDEAL Option of Mollie Payment Gateway.\n\n\n\n\nWooCommerce Square\n\n\n\n\n\n\n\n\n\n\n\n\nPayment Gateway: WooCommerce Square\n\n\n\nPlugin Required: The official \"WooCommerce Square\" plugin which is available on WordPress.org.\n\n\n\nInfo: CartFlows currently supports only the Credit Card option of Square Payment Gateway.\n\n\n\n\nWooCommerce Payments\n\n\n\n\n\n\n\n\nPayment Gateway: WooCommerce Payments\n\n\n\nPlugin Required: The official \"WooCommerce Payments\" plugin which is available on WordPress.org.\n\n\n\n\nWe are striving to add more Payment Gateways and they are lined up. Stay Tuned!\n\n\n\nNote\nNot all payment gateways support the one-click upsells feature, but yet we will add more gateway support in the future updates of CartFlows for upsell/downsells.\n\n\n\n\n\n\n\n\nFrequently Asked Questions (FAQ)\n\n\n\n\nWhich payment gateways does CartFlows support on the checkout page?CartFlows supports all payment gateways that work with WooCommerce on the checkout page. To use a gateway, ensure its plugin is installed and activated. Most gateways that work on the checkout page also work with Pre Checkout Offers and Order Bumps.\n\n\n\nWhich payment gateways support one-click upsells and downsells in CartFlows?CartFlows supports the following gateways for upsell and downsell pages: Cash on Delivery, Direct Bank Transfer (BACS), PayPal Standard, WooCommerce PayPal Payments, Stripe, Authorize.net, Mollie (Credit Card and iDEAL), WooCommerce Square (Credit Card only), and WooCommerce Payments. Note that not all of these gateways support the one-click upsells feature.\n\n\n\nDoes CartFlows support all Stripe payment methods for upsells?No. CartFlows currently supports only Stripe credit card payments for upsell and downsell pages. Other Stripe payment methods are not supported at this time.\n\n\n\nDo I need an additional plugin to use PayPal Standard with CartFlows?No. PayPal Standard (WooCommerce PayPal Payment Gateway) is included with WooCommerce by default and does not require an additional plugin. You can find it under WordPress Dashboard → WooCommerce → Settings → Payments. Note that WooCommerce PayPal Payments is a separate plugin that does require installation.\";s:3:\"url\";s:67:\"https://cartflows.com/docs/supported-payment-gateways-by-cartflows/\";s:4:\"slug\";s:39:\"supported-payment-gateways-by-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:44:49+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:48;O:8:\"stdClass\":8:{s:2:\"id\";i:31339;s:5:\"title\";s:45:\"How to Customize Checkout Fields in CartFlows\";s:7:\"content\";s:2865:\"CartFlows allows you to customize the checkout fields on your checkout step so you can collect only the information you need from your customers. This helps create a simpler and more optimized checkout experience.\n\n\n\nYou can easily add, remove, reorder, or modify checkout fields directly from the checkout step settings.\n\n\n\nHow to Customize Checkout Fields\n\n\n\nFollow the steps below to customize the checkout fields in your CartFlows checkout step.\n\n\n\nStep 1: Navigate to CartFlows &gt; Funnels.Step 2: Open the funnel where you want to customize the checkout fields.\n\n\n\n\n\n\n\nStep 3: Click the settings icon of the&nbsp;Checkout&nbsp;step.\n\n\n\n\n\n\n\nStep 4: Navigate to the Checkout Form &gt; Field Editor and enable Custom Field Editor.\n\n\n\n\n\n\n\nHere you will see the list of fields available for the checkout form.\n\n\n\nManaging Checkout Fields\n\n\n\nWithin the Checkout Fields section, you can customize the fields in the following ways:\n\n\n\nEnable or Disable FieldsYou can enable or disable specific fields depending on the information you want to collect from customers.\n\n\n\nMake Fields Required or OptionalYou can set fields as required if customers must fill them before completing the order.\n\n\n\nReorder FieldsFields can be rearranged using drag-and-drop to change the order in which they appear on the checkout page.\n\n\n\nEdit Field Labels and PlaceholdersYou can modify the field labels and placeholder text to better match your store’s requirements.\n\n\n\n\n\n\n\nSaving Your Changes\n\n\n\nOnce you finish customizing the checkout fields, click Save Settings to apply the settings.\n\n\n\nYour checkout page will now display the updated fields according to your configuration.\n\n\n\nCustomizing checkout fields helps you create a cleaner checkout experience and collect only the necessary information from your customers, improving overall conversion rates.\n\n\n\nFrequently Asked Questions (FAQ)\n\n\n\n\nHow do I access the checkout field editor in CartFlows?Go to CartFlows → Funnels, open the funnel containing your checkout step, click the settings icon on the Checkout step, then navigate to Checkout Form → Field Editor and enable the Custom Field Editor.\n\n\n\nCan I make checkout fields required or optional in CartFlows?Yes. In the Field Editor, you can set fields as required — customers must fill these before completing their order. You can also enable or disable specific fields depending on what information you want to collect.\n\n\n\nCan I reorder checkout fields in CartFlows?Yes. CartFlows supports drag-and-drop reordering of checkout fields. Simply drag a field to the position you want it to appear on the checkout page.\n\n\n\nCan I edit the labels and placeholder text of checkout fields?Yes. You can modify the field labels and placeholder text for any checkout field to match your store\'s language or requirements. After making changes, click Save Settings to apply them.\";s:3:\"url\";s:67:\"https://cartflows.com/docs/custom-checkout-fields-and-its-settings/\";s:4:\"slug\";s:39:\"custom-checkout-fields-and-its-settings\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:43:50+05:30\";s:8:\"category\";a:1:{i:0;s:21:\"checkout-field-editor\";}}i:49;O:8:\"stdClass\":8:{s:2:\"id\";i:30155;s:5:\"title\";s:59:\"How to Embed a Checkout Form on the CartFlows Checkout Page\";s:7:\"content\";s:3039:\"CartFlows allows you to customize the layout and content within the Checkout step of your funnel. If you\'d like to create a landing or sales page-style layout while still using the CartFlows checkout form, you can place the checkout form shortcode directly inside the Checkout step.\n\n\n\nThis documentation explains how to embed the checkout form on the CartFlows Checkout page.\n\n\n\nSteps to Embed a Checkout Form\n\n\n\nStep 1: Enable the Design Tab for Shortcode Access\n\n\n\n\nTo access the Design tab where the shortcode is available, ensure that your page builder is set to \"Other\" in the CartFlows settings.\n\n\n\nFrom your WordPress dashboard, go to CartFlows &gt; Settings &gt; General and select Other from the page builder list.\n\n\n\nClick Save Settings.\n\n\n\n\n\n\n\n\n\nAfter saving the settings, go to the funnel and open the settings of Checkout step settings by clicking the gear icon.\n\n\n\n\n\n\n\n\n\nYou will now see the Design tab. Open it to find the CartFlows Checkout Shortcode ([cartflows_checkout]).\n\n\n\nCopy the shortcode.\n\n\n\n\n\n\n\n\nStep 2: Add the Shortcode to the Checkout Page\n\n\n\n\nEdit the Checkout page using your page builder.\n\n\n\nPaste the shortcode wherever you want the checkout form to appear on the page.\n\n\n\nThis will display the CartFlows checkout fields, allowing users to complete their purchase directly on that section of the page.\n\n\n\n\nNote: If you\'re using the Block Editor, Elementor, Beaver Builder, or Bricks Builder, you don’t need to use the shortcode. CartFlows provides a dedicated Checkout Form element that you can add directly when editing the page using your page builder.\n\n\n\nImportant Notes\n\n\n\n\nThe shortcode must be used only on the CartFlows Checkout page. It will not work if added to any other page.\n\n\n\n\n\n\n\n\n\nIf the shortcode is placed incorrectly or on a different page, you may see an error saying: “Checkout ID not found”\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nIf you need more information about placing shortcodes correctly, refer to this documentation: https://cartflows.com/docs/placing-shortcode-in-the-right-places\n\n\n\nFrequently Asked Questions (FAQ)\n\n\n\n\nHow do I embed a checkout form on the CartFlows checkout page?Set your page builder to \"Other\" in CartFlows → Dashboard → Settings → General and save. Then open the Checkout step settings by clicking the gear icon, go to the Design tab, and copy the [cartflows_checkout] shortcode. Paste this shortcode wherever you want the checkout form to appear on your checkout page.\n\n\n\nDo I need a shortcode to add a checkout form in Elementor or the Block Editor?No. If you are using the Block Editor, Elementor, Beaver Builder, or Bricks Builder, you do not need the shortcode. CartFlows provides a dedicated Checkout Form element that you can add directly from within your page builder.\n\n\n\nWhat happens if the CartFlows checkout shortcode is placed on the wrong page?The shortcode only works on the CartFlows Checkout page. If it is placed on any other page, you may see a \"Checkout ID not found\" error. Make sure the shortcode is used only within the CartFlows Checkout step.\";s:3:\"url\";s:56:\"https://cartflows.com/docs/how-to-embed-a-checkout-form/\";s:4:\"slug\";s:28:\"how-to-embed-a-checkout-form\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:43:23+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:50;O:8:\"stdClass\":8:{s:2:\"id\";i:32904;s:5:\"title\";s:53:\"How to Fix Checkout Page Redirecting to the Home Page\";s:7:\"content\";s:1663:\"If your CartFlows checkout page redirects to the homepage of your website instead of loading the correct checkout page, it’s likely due to a missing setting in your WooCommerce configuration.\n\n\n\nThis issue commonly occurs when using Store Checkout.\n\n\n\nWhy the Redirect Happens\n\n\n\nWhen Store Checkout is enabled, WooCommerce needs to know which page to treat as the Checkout page. If the Checkout page is not set under WooCommerce → Settings, WooCommerce doesn’t know where to send the customer, and it defaults to the homepage.\n\n\n\nFix the Redirect Issue\n\n\n\nFollow these steps to stop the redirection and make sure the correct checkout page is used:\n\n\n\n\nGo to WooCommerce → Settings → Advanced.\n\n\n\nIn the Page setup section, find the Checkout page option.\n\n\n\nSelect the correct page that’s used for your Checkout page.\n\n\n\nClick Save changes.\n\n\n\n\n\n\n\n\nNote: Only standard WordPress pages will appear in the Checkout page dropdown. Your CartFlows checkout step should be built on one of these pages.\n\n\n\nFrequently Asked Questions (FAQ)\n\n\n\n\nWhy does the checkout page redirect to the homepage?This happens when WooCommerce doesn\'t have a Checkout page assigned under its settings. When Store Checkout is enabled and no Checkout page is set, WooCommerce defaults to redirecting customers to the homepage.\n\n\n\nHow do I stop the checkout page from redirecting to the homepage?Go to WooCommerce → Settings → Advanced, find the Checkout page option under Page setup, select the correct page used for your checkout, and save changes. Make sure only standard WordPress pages appear in this dropdown — your checkout step should be built on one of those pages.\";s:3:\"url\";s:70:\"https://cartflows.com/docs/resolve-checkout-page-homepage-redirection/\";s:4:\"slug\";s:42:\"resolve-checkout-page-homepage-redirection\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:42:55+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:51;O:8:\"stdClass\":8:{s:2:\"id\";i:32713;s:5:\"title\";s:74:\"How to Fix the &#8220;Sorry, This Product Cannot Be Purchased&#8221; Error\";s:7:\"content\";s:2039:\"If you see the message “Sorry, this product cannot be purchased” on your CartFlows Checkout page, it means one or more of the selected products are not purchasable.\n\n\n\nThis documentation explains why the error appears and how to resolve it.\n\n\n\nWhy This Happens\n\n\n\nThe error typically occurs when WooCommerce restricts the product from being purchased due to one of the following reasons:\n\n\n\n\nThe product has no price set\n\n\n\nThe product is in draft or private status\n\n\n\nRequired details (such as for subscription products) are missing\n\n\n\nStock or catalog settings are preventing purchase\n\n\n\n\nTo confirm that the issue is product-related, try purchasing the same product using the default WooCommerce Checkout page. If you see the same error there, the product is not configured properly.\n\n\n\nHow to Fix the Error\n\n\n\n\nGo to Products &gt; All Products and edit the product causing the issue.\n\n\n\nMake sure all required details are set, including:\n\nProduct name\n\n\n\nRegular or sale price\n\n\n\nStock status and quantity\n\n\n\nSubscription details (if applicable)\n\n\n\n\n\nSave or update the product.\n\n\n\nTest the product again on the default WooCommerce Checkout page.\n\n\n\n\nOnce it works correctly there, it will also work without issue on your CartFlows Checkout page.\n\n\n\nFrequently Asked Questions (FAQ)\n\n\n\n\nWhat causes the \"Sorry, this product cannot be purchased\" error on the checkout page?This error appears when WooCommerce restricts a product from being purchased. Common causes include the product having no price set, the product being in draft or private status, missing subscription details, or stock and catalog settings preventing purchase.\n\n\n\nHow do I fix the \"Sorry, this product cannot be purchased\" error?Go to Products > All Products and edit the product causing the issue. Make sure the product name, regular or sale price, stock status, and any subscription details are all properly configured. Save the product and test it on the default WooCommerce checkout page first — if it works there, it will work on your checkout page too.\";s:3:\"url\";s:83:\"https://cartflows.com/docs/resolve-sorry-product-cannot-be-purchased-error-message/\";s:4:\"slug\";s:55:\"resolve-sorry-product-cannot-be-purchased-error-message\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:41:58+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:52;O:8:\"stdClass\":8:{s:2:\"id\";i:32671;s:5:\"title\";s:58:\"How to Fix the &#8220;Session Expired&#8221; Error Message\";s:7:\"content\";s:4660:\"If you’re seeing a “Your session has expired” message on your Upsell or Downsell pages in CartFlows, it means the session data from the original checkout step is no longer available.\n\n\n\nThis documentation explains why this happens and how to resolve it.\n\n\n\nWhy This Happens\n\n\n\nCartFlows relies on session cookies to pass data from the checkout page to the upsell and downsell steps. When that session data is missing or blocked, CartFlows cannot process the offer step, resulting in the “Session Expired” error.\n\n\n\nBelow are common causes of this issue.\n\n\n\nCase 1: Page Opened Directly Without Test Mode\n\n\n\nIf the upsell or downsell page is opened directly by URL (outside the actual Funnel) and Test Mode is not enabled, the session key will not be set. This will trigger the error, especially for users who are not logged in.\n\n\n\nSolution: If you want to preview the page layout or design, enable Test Mode and make sure you’re logged in while viewing the step.\n\n\n\nFor help, see this guide: Funnel in Test Mode\n\n\n\nCase 2: Upsell or Downsell Placed After an Opt-in Step\n\n\n\nOpt-in steps do not collect payment or generate an order. If you place an upsell or downsell after an opt-in step, CartFlows will not have the required session to proceed.\n\n\n\nSolution: Do not place upsell or downsell steps immediately after an opt-in step. Make sure the customer completes a purchase on the checkout page first.\n\n\n\nCase 3: Cookie Naming Restrictions by Hosting Provider\n\n\n\nSome hosting environments (like Pantheon) block cookies that don’t follow a specific naming format (e.g. wp_, woocommerce_). Since CartFlows uses its own cookie (cartflows_session_), this may be blocked.\n\n\n\nSolution: Contact your hosting provider and ask if they allow third-party cookies. If needed, request that they exclude CartFlows cookies from any restrictions. For reference, here’s the full list of CartFlows cookies.\n\n\n\nCase 4: Missing SSL or Improper HTTPS Configuration\n\n\n\nCartFlows cookies require a secure HTTPS connection. If your site does not have SSL properly installed or configured, session cookies may not register.\n\n\n\nSolution: Make sure your website is fully configured to use HTTPS with a valid SSL certificate.\n\n\n\nCase 5: Caching Conflicts\n\n\n\nIf CartFlows pages are cached at the browser, plugin, or server level, the session cookie may be blocked or not set correctly.\n\n\n\nSolution:\n\n\n\n\nClear all site and browser cache\n\n\n\nTemporarily disable any active caching plugins\n\n\n\nExclude CartFlows checkout, upsell, and downsell pages from caching\n\n\n\n\nRefer to this doc for help: How to Disable Caching\n\n\n\nFrequently Asked Questions (FAQ)\n\n\n\n\nWhat causes the \"Session Expired\" error on upsell or downsell pages?The session expired error occurs when session data from the original checkout step is missing or blocked. Common causes include opening the upsell page directly by URL without Test Mode enabled, placing a upsell after an opt-in step, hosting providers blocking CartFlows cookies, missing SSL configuration, or caching conflicts on checkout pages.\n\n\n\nHow do I fix the session expired error when previewing an upsell or downsell page?Enable Test Mode in your funnel settings and make sure you are logged in while viewing the step. Opening upsell or downsell pages directly by URL without Test Mode active will always trigger this error.\n\n\n\nCan caching plugins cause the session expired error in a sales funnel?Yes. If checkout, upsell, or downsell pages are cached at the browser, plugin, or server level, session cookies may not register correctly. To fix this, clear all site and browser cache, temporarily disable caching plugins, and exclude CartFlows checkout and offer pages from your caching system.\n\n\n\nWhy does my hosting provider block CartFlows session cookies?Some hosting environments like Pantheon block cookies that do not follow specific naming formats like wp_ or woocommerce_. Since CartFlows uses its own cartflows_session_ cookie, it may be blocked. Contact your hosting provider and ask them to allow CartFlows cookies or exclude them from any cookie restrictions.\n\n\n\nWhy do I see the session expired error on the checkout page instead of the upsell page?This usually means the CartFlows or WooCommerce session cookie is not being registered, most often due to caching. Clear your cache and exclude the CartFlows checkout page from any caching system.\n\n\n\nWhat if I see the error on the checkout page instead of an upsell or downsell page?This usually means the CartFlows or WooCommerce session cookie is not being registered. It’s often due to caching. Clear the cache and exclude the CartFlows checkout page from any caching system.\";s:3:\"url\";s:57:\"https://cartflows.com/docs/session-expired-error-message/\";s:4:\"slug\";s:29:\"session-expired-error-message\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:41:29+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:53;O:8:\"stdClass\":8:{s:2:\"id\";i:34939;s:5:\"title\";s:98:\"How to Fix the &#8220;Sorry, the content area was not found in your page&#8221; Error in Elementor\";s:7:\"content\";s:2955:\"If you\'re using Elementor to edit CartFlows Steps and see the following message:\n\n\n\n\n“Sorry, the content area was not found in your page. You must call the_content function in the current template, in order for Elementor to work on this page.”\n\n\n\n\n\n\n\n\nThis documentation explains why the error appears and how to fix it.\n\n\n\nWhy This Error Happens\n\n\n\nThis message typically appears when Elementor can’t detect the proper content area (usually the_content function) in the template you’re trying to edit. In most cases, this occurs when editing dynamic pages or if there are configuration conflicts.\n\n\n\nHere are the most common causes and solutions:\n\n\n\n1. Issue with Permalinks\n\n\n\nSometimes the permalink structure may be out of sync. To fix it:\n\n\n\n\nGo to Settings &gt; Permalinks in your WordPress admin\n\n\n\nClick Save Changes without changing anything\n\n\n\nRepeat this 2–3 times if necessary\n\n\n\n\nThis flushes the rewrite rules and often resolves the issue. Learn how to refresh WordPress permalinks\n\n\n\n2. Editing a Dynamic Page\n\n\n\nIf you’re trying to edit a Blog or Posts page, Elementor won’t allow you to edit it directly unless you’re using Elementor Pro.\n\n\n\nSolution: Only static pages (like those used in CartFlows Steps) can be edited with Elementor Free. If you\'re trying to edit archive pages or blog templates, refer to Elementor’s Theme Builder documentation.\n\n\n\n3. Plugin Conflict\n\n\n\nAnother possible cause is a plugin conflict. To test:\n\n\n\n\nTemporarily deactivate all plugins except Elementor and CartFlows\n\n\n\nTry editing the page again\n\n\n\nIf the error disappears, reactivate the plugins one by one to find the conflicting one\n\n\n\n\nOnce found, consider replacing or removing that plugin — or reaching out to its support team.\n\n\n\nStill Not Working?\n\n\n\nIf none of the above solutions fix the issue, try the following:\n\n\n\n\nRefer to Elementor’s troubleshooting guide\n\n\n\nContact our support team — we’re happy to help\n\n\n\n\nFrequently Asked Questions (FAQ)\n\n\n\n\nWhat causes the \"Sorry, the content area was not found in your page\" error in Elementor?This error is usually caused by one of three things: a permalink structure issue that needs refreshing, trying to edit a dynamic page like the blog page directly in Elementor, or a conflict with another plugin installed on the site.\n\n\n\nHow do I fix the content area not found error in Elementor?Start by refreshing your WordPress permalinks two to three times — this resolves the issue in most cases. If that does not work, temporarily deactivate all plugins except Elementor and CartFlows to check for a plugin conflict, then reactivate them one by one to identify the problem plugin.\n\n\n\nCan I edit the WordPress blog page directly with Elementor?No. Dynamic pages like the WordPress blog page cannot be edited directly with Elementor Free. Only static pages like CartFlows steps can be edited. For archive or blog templates, you will need Elementor Pro and its Theme Builder.\";s:3:\"url\";s:56:\"https://cartflows.com/docs/content-area-not-found-error/\";s:4:\"slug\";s:28:\"content-area-not-found-error\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:40:57+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:54;O:8:\"stdClass\":8:{s:2:\"id\";i:32796;s:5:\"title\";s:53:\"How to Fix the “Your Cart is Empty” Error Message\";s:7:\"content\";s:2238:\"If you\'re seeing the “Your Cart is Empty” message on your Checkout page, it usually means no product has been added to the cart before accessing the page.\n\n\n\nThis documentation explains why this happens and how to resolve it.\n\n\n\nWhy This Happens\n\n\n\nThe error appears when you are using the Store Checkout feature in CartFlows and a customer lands directly on the checkout page without having added any product to the cart.\n\n\n\nIn Store Checkout, the expected flow is: Shop page &gt; Add to Cart &gt; Cart page &gt; Checkout page\n\n\n\nIf the checkout page is accessed directly (for example, through a bookmarked URL or direct link) without adding a product first, the system has nothing to show and displays the “Your Cart is Empty” message.\n\n\n\n\n\n\n\nTo learn more about how Store Checkout works, refer to the Store Checkout documentation.\n\n\n\nHow to Avoid This\n\n\n\nTo prevent this error:\n\n\n\n\nMake sure customers follow the complete flow starting from the shop or product page\n\n\n\nAvoid linking directly to the Checkout page unless a product is already in the cart\n\n\n\n\nNote: Make sure the default WooCommerce Cart and Checkout pages are created and published under Pages in your WordPress dashboard. These are required for proper handling of cart and checkout logic in Store Checkout.\n\n\n\nFrequently Asked Questions (FAQ)\n\n\n\n\nWhat causes the \"Your Cart is Empty\" error on the CartFlows checkout page?This error appears when using the Store Checkout feature in CartFlows and a customer lands directly on the checkout page without adding a product to the cart first. The expected flow is: Shop page > Add to Cart > Cart page > Checkout page.\n\n\n\nHow do I fix the \"Your Cart is Empty\" error in CartFlows?To fix this error, make sure customers follow the complete purchase flow starting from the shop or product page instead of accessing the checkout page directly. Avoid linking directly to the checkout page unless a product is already in the cart.\n\n\n\nDo I need WooCommerce Cart and Checkout pages for CartFlows Store Checkout to work?Yes. The default WooCommerce Cart and Checkout pages must be created and published under Pages in your WordPress dashboard. These are required for proper cart and checkout logic to function in Store Checkout.\";s:3:\"url\";s:60:\"https://cartflows.com/docs/resolve-your-cart-is-empty-error/\";s:4:\"slug\";s:32:\"resolve-your-cart-is-empty-error\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-10T00:38:50+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:55;O:8:\"stdClass\":8:{s:2:\"id\";i:75337;s:5:\"title\";s:35:\"How Cart Abandonment Tracking Works\";s:7:\"content\";s:9294:\"The Cart Abandonment Recovery plugin tracks shoppers as they move through your WooCommerce checkout process. It captures cart data as soon as a customer provides their email address, monitors whether they complete the order, and — if they do not — marks the cart as abandoned and queues any scheduled recovery emails.\n\n\n\nThis document explains precisely how and when a cart is captured, what defines the abandonment cut-off, how the cart lifecycle progresses through its various states, and what conditions will prevent a cart from being tracked.\n\n\n\nHow Tracking Is Triggered\n\n\n\nTracking begins the moment a customer enters their email address on the WooCommerce Checkout page. The plugin captures the email and saves the current cart contents to the database at that point — it does not wait for any other field to be filled in.\n\n\n\nThis means:\n\n\n\n\nA cart is captured even if the customer only types their email and immediately leaves the page.\n\n\n\nNo payment details are ever stored by the plugin. Only the cart contents, customer contact details, and checkout metadata are saved.\n\n\n\nGuest customers and logged-in customers are both tracked, as long as an email address has been entered.\n\n\n\n\nNote\nTracking requires the Enable Tracking toggle to be switched ON in WooCommerce &gt; Cart Abandonment &gt; Settings &gt; General Settings. If tracking is disabled, no carts will be captured regardless of other settings.\n\n\n\n\n\n\n\n\nThe Cart Abandoned Cut-Off Time\n\n\n\nOnce a cart is captured, the plugin does not immediately consider it abandoned. It waits for a configurable period — the Cart Abandoned Cut-Off Time — before marking the cart as abandoned and starting the recovery email sequence.\n\n\n\nWhat the Cut-Off Time Controls\n\n\n\nThe cut-off time defines the minimum number of minutes that must pass after a cart is captured without the order being completed before the cart is treated as abandoned. The default and minimum value is 10 minutes.\n\n\n\nFor example, if the cut-off time is set to 60 minutes:\n\n\n\n\nA customer enters their email at 2:00 PM and leaves.\n\n\n\nThe plugin captures the cart at 2:00 PM.\n\n\n\nAt 3:00 PM (60 minutes later), a background check runs.\n\n\n\nIf the order has not been completed, the cart is marked as abandoned and the recovery email sequence begins.\n\n\n\n\nHow to Configure the Cut-Off Time\n\n\n\n\nGo to WooCommerce &gt; Cart Abandonment &gt; Settings.\n\n\n\nUnder General Settings, find the Cart Abandoned Cut-Off Time field.\n\n\n\nEnter the number of minutes after which an incomplete cart should be considered abandoned. The minimum is 10 minutes.\n\n\n\nChanges are saved automatically — there is no save button.\n\n\n\n\n\n\n\n\nTip: A cut-off time of 15–30 minutes is typically a good balance for most stores. Setting it too short can result in capturing customers who are still actively filling in their details; setting it too long delays the first recovery email.\n\n\n\nHow the Background Check Works\n\n\n\nThe plugin uses a WP-Cron scheduled job to periodically scan the database and check whether any captured carts have passed the cut-off time without completing checkout. This job is named:\n\n\n\ncartflows_ca_update_order_status_action\n\n\n\nThis cron job runs every 15 minutes. It checks all carts in a capturing state and promotes those that have exceeded the cut-off time to abandoned status, which triggers the recovery email queue.\n\n\n\nWhy WP-Cron Must Be Active\n\n\n\nIf WP-Cron is disabled on your WordPress installation, the status-check job will not run. This means:\n\n\n\n\nCaptured carts will never be promoted to abandoned status.\n\n\n\nNo recovery emails will be sent.\n\n\n\nThe abandoned orders list in the plugin dashboard will remain empty.\n\n\n\n\nImportant: If abandoned carts are not appearing in your dashboard, the most common cause is a disabled WP-Cron. Check your wp-config.php file and ensure the following line is not present or is set to false:\n\n\n\ndefine(\'DISABLE_WP_CRON\', true); &nbsp; // Disable WP-Cron and will break tracking\n\n\n\nTo re-enable WP-Cron, either remove that line or change it to:\n\n\n\ndefine(\'DISABLE_WP_CRON\', false);\n\n\n\nAlternatively, if you prefer to run cron tasks via a server-level scheduler (e.g., cPanel), you can set up an external cron job to call the WordPress cron URL at regular intervals. This is often the more reliable approach for high-traffic sites.\n\n\n\nCart Lifecycle: The Possible States\n\n\n\nEvery tracked cart moves through a defined set of states from the moment it is captured to the time it is resolved. Understanding these states helps you interpret the data shown in WooCommerce &gt; Cart Abandonment &gt; Reports &gt; Follow Up.\n\n\n\nStageOrder StatusWhat It MeansCapturingNormalThe customer\'s email has been recorded and the cart is saved. The cut-off time has not yet elapsed. No emails have been sent.AbandonedAbandonedThe cut-off time has elapsed without the order being completed. The cart is now eligible for recovery emails. The recovery sequence begins.RecoveredSuccessfulThe customer completed their order — either by clicking a recovery link or by returning to the store independently. No further emails are sent.UnsubscribedUnsubscribedThe customer clicked the unsubscribe link in a recovery email. They will not receive any further recovery emails for this abandoned carts.LostFailedThe cart was abandoned and the full recovery sequence has been exhausted without conversion. No further action is taken.\n\n\n\n\n\n\n\nRecovering a Cart\n\n\n\nA cart transitions from abandoned to recovered when the associated WooCommerce order reaches one of the statuses configured in the Exclude Email Sending For setting (typically Processing or Completed). This transition happens automatically — you do not need to manually mark anything.\n\n\n\nOnce a cart is recovered, all pending scheduled recovery emails for that cart are cancelled.\n\n\n\nWhat Carts Are Not Tracked\n\n\n\nNot all checkout sessions are eligible for tracking. The following conditions will prevent a cart from being captured:\n\n\n\nTracking Is Disabled\n\n\n\nIf the Enable Tracking toggle is turned OFF in the plugin settings, no carts will be tracked, regardless of any other configuration.\n\n\n\nNo Email Address Entered\n\n\n\nTracking only begins when a customer types their email address into the checkout email field. If a customer adds items to the cart but never reaches the checkout page, or reaches the checkout page but does not enter an email, no cart data is captured.\n\n\n\nUser Role Is Excluded\n\n\n\nThe Disable Tracking For setting allows specific WordPress user roles to be excluded from tracking entirely. By default, it is recommended to exclude administrator and shop manager roles to avoid logging internal test orders.\n\n\n\nTo check or update which roles are excluded:\n\n\n\n\nGo to WooCommerce &gt; Cart Abandonment &gt; Settings.\n\n\n\nUnder General section, review the Disable Tracking For field.\n\n\n\nAdd or remove roles as needed.\n\n\n\n\n\n\n\n\nEmail Address Is Blacklisted\n\n\n\nIf a customer\'s email address or domain is on the Email/Domain Blacklist, the cart will be captured but no recovery emails will be sent to that address. This is useful for excluding known test accounts, internal addresses, or competitor domains.\n\n\n\nOrder Is Already Completed\n\n\n\nIf the customer completes their order normally (without abandoning), the cart is never promoted to abandoned status. The plugin continuously checks whether the associated WooCommerce order has been paid, and if so, the cart session is immediately resolved.\n\n\n\nTracking and GDPR Compliance\n\n\n\nSending abandoned cart recovery emails falls under legitimate interest for data processing under GDPR guidelines. This means no separate opt-in consent is required to capture cart data and send recovery emails, though transparency in your store\'s privacy policy is strongly recommended.\n\n\n\nIf you prefer to give customers an explicit opt-in mechanism at the checkout page, the plugin includes an optional GDPR Integration setting.\n\n\n\nEnabling the GDPR Consent Message\n\n\n\n\nGo to WooCommerce &gt; Cart Abandonment &gt; Settings.\n\n\n\nClick the GDPR tab.\n\n\n\nToggle Enable GDPR Integration ON.\n\n\n\nOptionally customize the GDPR Message text shown below the email field at checkout.\n\n\n\n\n\n\n\n\nWhen enabled, a consent notice appears below the email field. If the customer clicks \"No thanks\", their cart will not be tracked. This ensures full opt-in compliance for stores that require it.\n\n\n\nNote\nEnabling the GDPR confirmation message may reduce the number of carts captured, since some customers will decline. Only enable it if your store\'s compliance requirements specifically demand an explicit opt-in for abandoned cart tracking.\n\n\n\n\nQuick Reference Summary\n\n\n\nSetting / ConceptDetailsTracking triggerCustomer enters email address on the checkout page.Cut-off timeConfigurable (minimum 10 minutes). Defines when a cart becomes \"abandoned\".Background check frequencyEvery 15 minutes via the cartflows_ca_update_order_status_action WP-Cron job.Cart statescapturing → abandoned → recovered or lost. Customers can also unsubscribe.Excluded from trackingSpecific user roles, blacklisted emails/domains, customers who opt out via GDPR message.Recovery triggerOrder reaches a status listed in \"Exclude Email Sending For\" (e.g., Processing, Completed).GDPRAbandoned cart emails fall under legitimate interest. Optional opt-in consent message available.\";s:3:\"url\";s:63:\"https://cartflows.com/docs/how-cart-abandonment-tracking-works/\";s:4:\"slug\";s:35:\"how-cart-abandonment-tracking-works\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-15T18:37:02+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:56;O:8:\"stdClass\":8:{s:2:\"id\";i:75330;s:5:\"title\";s:57:\"How to Set Up Abandoned Cart Email Sequences (Multi-Step)\";s:7:\"content\";s:5681:\"A multi-step email sequence lets you send a series of timed, automated recovery emails to customers who abandon their cart. Instead of relying on a single email, a sequence gives you multiple touchpoints — each with a different message, tone, and incentive — to bring customers back at the right moment.\n\n\n\nThis guide covers how to plan, build, and activate a full sequence in the Cart Abandonment Recovery plugin using the Follow-up Emails tab.\n\n\n\nHow Sequences Work\n\n\n\nEvery active email template in the Follow-up Emails tab is part of the sequence. The plugin sends each template independently based on its own Send This Email delay, measured from the moment the cart was first abandoned.\n\n\n\nAll timers run from the same starting point — the abandonment timestamp — not from the previous email. For example:\n\n\n\n\nEmail 1 set to 1 hour sends 1 hour after abandonment.\n\n\n\nEmail 2 set to 24 hours sends 24 hours after abandonment.\n\n\n\nEmail 3 set to 3 days sends 3 days after abandonment.\n\n\n\n\nNote\nIf a cart is recovered at any point in the sequence, all remaining scheduled emails for that cart are automatically cancelled. The customer will not receive further emails once their order is complete.\n\n\n\n\nStep 1: Navigate to Follow-up Emails\n\n\n\nGo to WooCommerce &gt; Cart Abandonment from your WordPress admin menu.\n\n\n\nThen click the Follow-up Emails tab.\n\n\n\nThis screen shows all existing email templates in your sequence. Each row displays the template name, send delay, and active/inactive status.\n\n\n\n\n\n\n\nStep 2: Plan Your Sequence\n\n\n\nBefore creating templates, decide how many emails your sequence will include and what each one should accomplish. A typical 3-email sequence looks like this:\n\n\n\nEmailTimingGoalCoupon?Email 11 HourGentle reminder - cart is savedNo coupon. Keep it friendly and simple.Email 224 HoursFollow-up - highlight product valueNo coupon. Reinforce the purchase decision.Email 33 DaysFinal offer - urgency + incentiveYes. Apply a discount to close the sale.\n\n\n\nTip: Hold back the coupon until the final email. Sending a discount too early can train customers to abandon carts intentionally to receive offers.\n\n\n\nStep 3: Create Each Email Template\n\n\n\nCreate one template per email in your sequence. Click Add New Template from the Follow-up Emails screen.\n\n\n\n\n\n\n\nFor each template, fill in the following fields:\n\n\n\nEmail Subject\n\n\n\nWrite a subject line that matches the purpose of that email in the sequence. Use the {{customer.firstname}} shortcode to personalize it.\n\n\n\nSend This Email\n\n\n\nSet the delay from the abandonment time. Enter a number and select Minutes, Hours, or Days.\n\n\n\nEmail Body\n\n\n\nWrite the body content for this email. At minimum, each email in the sequence should include:\n\n\n\n\nA personalized greeting using {{customer.firstname}}\n\n\n\nThe recovery link using {{cart.checkout_url}}\n\n\n\nAn unsubscribe link using {{cart.unsubscribe}}\n\n\n\n\nFor the product reminder email (Email 2), also include {{cart.product.table}} to show the abandoned items. For the coupon email (Email 3), add {{cart.coupon_code}}.\n\n\n\nSee How to Create and Customize Email Templates for Cart Recovery for full shortcode reference and body formatting guidance.\n\n\n\nCoupon (Optional)\n\n\n\nAttach a WooCommerce coupon to the template if this email should include a discount. The coupon will be auto-applied when the customer clicks the recovery link.\n\n\n\nActive / Inactive Toggle\n\n\n\nLeave the template set to Active so it fires as part of the sequence. You can deactivate individual emails at any time without deleting them.\n\n\n\nStep 4: Save and Repeat\n\n\n\nClick Save Template after completing each template. Then click Add New Template again and repeat for the next email in your sequence.\n\n\n\nOnce all templates are saved and active, the Follow-up Emails screen will show your full sequence in a list ordered by send delay.\n\n\n\nStep 5: Verify the Sequence\n\n\n\nReview the Follow-up Emails list to confirm:\n\n\n\n\nAll templates are set to Active.\n\n\n\nSend delays are in the correct order with no overlapping times.\n\n\n\nThe coupon template is the last email, not the first.\n\n\n\nEach template has a distinct subject line and purpose.\n\n\n\n\nNote\nThe plugin does not enforce ordering by delay — it sends each template independently based on its own timer. Make sure your delays don\'t overlap (e.g., don\'t set two emails to the same delay).\n\n\n\n\nUsing Dynamic Conditions to Vary the Sequence (Pro)\n\n\n\nWith Cart Abandonment Recovery Pro, you can apply Dynamic Conditions to any template in the sequence so that specific emails only send to customers who meet certain criteria — for example, sending a higher-value coupon only to customers whose cart total exceeds $100.\n\n\n\nThis allows you to run a single sequence that behaves differently for different customer segments without building separate sequences manually.\n\n\n\nSee Dynamic Email Rules for full setup instructions.\n\n\n\nManaging an Existing Sequence\n\n\n\nPausing a Single Email\n\n\n\nToggle any template to Inactive on the Follow-up Emails screen. The email will be skipped in the sequence without affecting any other templates. Reactivate it at any time.\n\n\n\nEditing a Template\n\n\n\nClick the template name or edit icon on the Follow-up Emails screen to open it. Any changes to the subject, body, timing, or coupon take effect immediately for all future sends.\n\n\n\nDeleting a Template\n\n\n\nClick the delete icon on the Follow-up Emails list. Deleting a template is permanent — consider deactivating it instead if you may want to use it again.\n\n\n\nReordering the Sequence\n\n\n\nThe sequence order is determined by each template\'s send delay. To change the order, edit the Send This Email field on the relevant templates to adjust their timing.\";s:3:\"url\";s:83:\"https://cartflows.com/docs/how-to-set-up-abandoned-cart-email-sequences-multi-step/\";s:4:\"slug\";s:55:\"how-to-set-up-abandoned-cart-email-sequences-multi-step\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-07-09T12:22:17+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:57;O:8:\"stdClass\":8:{s:2:\"id\";i:74056;s:5:\"title\";s:41:\"How to Activate Power Coupons License Key\";s:7:\"content\";s:1101:\"To start using Power Coupons Pro and receive automatic updates, you need to activate your license. This documentation will guide you through the process.\n\n\n\nBefore You Start\n\n\n\nBefore activating your license, make sure:\n\n\n\n\nThe Power Coupons Free plugin is installed and activated on your website.If you haven’t installed it yet, follow this document: How to Install Power Coupons\n\n\n\nYou have access to your account to retrieve the license key.\n\n\n\n\nHow to Activate Your Power Coupons Pro License\n\n\n\nStep 1: Get Your License Key\n\n\n\n\nLog in to Membership Area.\n\n\n\nClick on API Keys from the sidebar.\n\n\n\nCopy your License Key.\n\n\n\n\n\n\n\n\nStep 2: Activate Your License in WordPress\n\n\n\n\nLog in to your WordPress dashboard.\n\n\n\nGo to Power Coupons &gt; Settings &gt; License.\n\n\n\nClick on the My Account tab.\n\n\n\nPaste your License Key into the provided field.\n\n\n\nClick the Activate License button.\n\n\n\n\n\n\n\n\nTroubleshooting License Activation Issues\n\n\n\nIf you’re facing problems while activating your license, refer to this document for detailed troubleshooting steps: Troubleshooting License Activation Issues\";s:3:\"url\";s:69:\"https://cartflows.com/docs/how-to-activate-power-coupons-license-key/\";s:4:\"slug\";s:41:\"how-to-activate-power-coupons-license-key\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-15T14:04:12+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"power-coupons\";}}i:58;O:8:\"stdClass\":8:{s:2:\"id\";i:74046;s:5:\"title\";s:32:\"How to Install Power Coupons Pro\";s:7:\"content\";s:1450:\"This documentation explains how to install the Power Coupons Pro plugin on your website. You can install the plugin by downloading it from your account and uploading it to your WordPress site.\n\n\n\nNote\nTo use Power Coupons Pro, the Power Coupons Free plugin must also be installed and activated. Refer to&nbsp;this doc&nbsp;to learn how to install Power Coupons Free.\n\n\n\n\nSteps to Install Power Coupons Pro\n\n\n\nStep 1: Go to Your Account and Click on Your Products\n\n\n\nIn your account page, go to Your Products to view all your purchased products.\n\n\n\n\n\n\n\nStep 2: Download Power Coupons Pro\n\n\n\nClick Download to start the .zip file download.\n\n\n\n\n\n\n\nStep 3: Log in to Your WordPress Website\n\n\n\nWhen you log in, you will be in your Dashboard.\n\n\n\nStep 4: In the Plugins Menu, Click on Add New Plugin\n\n\n\nGo to Plugins &gt; Add New Plugin from the WordPress menu.\n\n\n\n\n\n\n\nStep 5: Click Upload Plugin at the Top of the Screen\n\n\n\nThe screen will expand with the option to upload a plugin.\n\n\n\n\n\n\n\nStep 6: Upload the Plugin and Click Install Now\n\n\n\nClick Choose File, select the downloaded .zip file, and then click Install Now to begin the installation.\n\n\n\n\n\n\n\nStep 7: Click Activate Plugin\n\n\n\nOnce the plugin is installed, click Activate Plugin to complete the installation.\n\n\n\n\n\n\n\nWhat’s Next?\n\n\n\nMake sure to activate your license key to start using the plugin and receive plugin updates. Click here to learn how to activate your Power Coupons Pro license.\";s:3:\"url\";s:60:\"https://cartflows.com/docs/how-to-install-power-coupons-pro/\";s:4:\"slug\";s:32:\"how-to-install-power-coupons-pro\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-15T14:07:08+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"power-coupons\";}}i:59;O:8:\"stdClass\":8:{s:2:\"id\";i:73357;s:5:\"title\";s:51:\"How to Set Preferred Countries on the Checkout Page\";s:7:\"content\";s:2646:\"By default, the country dropdown on your checkout page lists every country in alphabetical order. If most of your customers come from the same few countries, that long list can feel like a chore. Preferred Countries lets you pin your top countries to the top of the dropdown so customers can pick their country in one click.\n\n\n\nThis setting is configured per Checkout step, so different funnels can have different preferred countries.\n\n\n\nHow to Enable Preferred Countries\n\n\n\nPreferred Countries lives inside the Advanced tab of your Checkout step settings.\n\n\n\n\nOpen the funnel that contains your Checkout step.\nClick Settings on the Checkout step.\nSwitch to the Advanced tab.\nTurn on Enable Preferred Countries.\nIn the Select Preferred Countries field, search and pick the countries you want to pin. You can add as many as you like.\nSave your changes.\n\n\n\n\n\n\n\n\n\n\n\n\nThe countries appear at the top of the dropdown in the same order you add them, so add your most important country first.\n\n\n\nWhat Customers See on the Checkout Page\n\n\n\nWhen a customer opens the country dropdown on your checkout page, the countries you pinned show up first. Below them, the rest of the countries continue in their usual alphabetical order.\n\n\n\nThis applies to both the billing and shipping country dropdowns.\n\n\n\n\n\n\n\nThings to Keep in Mind\n\n\n\n\nThe order of pinned countries matches the order you select them. Add the most important one first.\nIf you have restricted WooCommerce to ship only to specific countries, Preferred Countries will respect that restriction. Any country you pinned that is not allowed for shipping will simply not appear.\nTurning the toggle on without selecting any countries has no effect — the dropdown will look like a default WooCommerce checkout.\nPreferred Countries works on every Checkout step layout CartFlows offers.\n\n\n\n\nFrequently Asked Questions\n\n\n\nQ: Does this remove other countries from the dropdown?A: No. The countries you pin are added to the top of the list. All other countries still appear below them in alphabetical order.\n\n\n\nQ: Can I set different preferred countries for different funnels?A: Yes. The setting is configured on each Checkout step individually, so every funnel can have its own list.\n\n\n\nQ: Does it apply to the shipping country field as well?A: Yes. The pinned countries appear at the top of both the billing and shipping country dropdowns.\n\n\n\nQ: Will it work if I sell to all countries?A: Yes. Whether your store is set to sell to specific countries or all countries, your pinned list will show at the top of the dropdown.\n\n\n\nStill have questions? Reach out to our support team and we\'ll be happy to help.\";s:3:\"url\";s:56:\"https://cartflows.com/docs/preferred-countries-checkout/\";s:4:\"slug\";s:28:\"preferred-countries-checkout\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-04T15:38:55+05:30\";s:8:\"category\";a:2:{i:0;s:8:\"features\";i:1;s:15:\"global-checkout\";}}i:60;O:8:\"stdClass\":8:{s:2:\"id\";i:72764;s:5:\"title\";s:21:\"CartFlows Smart Login\";s:7:\"content\";s:5178:\"CartFlows Pro includes a feature called Smart Login that helps returning customers sign in to their account during checkout without leaving the page. When a registered customer enters their email, a friendly prompt appears, and a single click opens a clean login window right on top of the checkout.\n\n\n\nThis guide walks you through how Smart Login works, how to enable it on a checkout step, and what the experience looks like for your shoppers.\n\n\n\nHow Smart Login Works\n\n\n\nWhen a guest reaches your checkout page and enters their email address, CartFlows quietly checks whether the email belongs to an existing customer.\n\n\n\n\nIf the email is not registered, nothing changes. The guest continues with checkout as usual.\n\n\nIf the email is registered, a small message appears below the email field inviting the customer to sign in.\n\n\nWhen the customer clicks the prompt, a centered login window opens on top of the checkout. They sign in, the page refreshes, and their saved details are populated automatically.\n\n\n\n\nThe customer never leaves the checkout page, and the cart they were building is preserved.\n\n\n\nHow to Set Up Smart Login\n\n\n\nSmart Login is configured per checkout step, so you can turn it on for some funnels and leave it off for others.\n\n\n\nStep 1. From the WordPress admin, go to CartFlows &rarr; Funnels and open the funnel that contains the checkout step you want to update.\n\n\n\nStep 2. Click the checkout step to open its settings.\n\n\n\nStep 3. In the left sidebar of the step settings, click Settings &rarr; Advanced.\n\n\n\nStep 4. Scroll to the Smart Login options.\n\n\n\n\n\n\n\nStep 5. Configure the four options:\n\n\n\n\nEnable Smart Login &mdash; Turn this on to activate the feature for this checkout step.\n\n\nLogin Form Style &mdash; Choose Overlay to open a centered window above the checkout (recommended), or Inline to show the login form inside the checkout page between fields.\n\n\nNudge Returning Users &mdash; When enabled, a short message appears below the email field if the customer&rsquo;s email is recognised.\n\n\nMessage &mdash; The text shown in the prompt. You can use the placeholder {{site_title}} and it will be replaced with your store&rsquo;s name automatically.\n\n\n\n\nStep 6. Click Save Settings at the top right.\n\n\n\nSmart Login is now active on that checkout step.\n\n\n\nThe Login Window in Action\n\n\n\nOnce Smart Login is enabled, customers see the standard checkout page until they enter a registered email. After they click the prompt (or the &ldquo;Log in&rdquo; link in the checkout header), the login window appears.\n\n\n\n\n\n\n\nThe window is centered on the screen with a darkened background. Customers enter their password and click Login. The page reloads, and they are signed in and ready to continue.\n\n\n\nThe window can be closed at any time by clicking outside of it, pressing the Esc key, or clicking the close button in the top right.\n\n\n\nOn Mobile Devices\n\n\n\nOn smaller screens, the window automatically adjusts to fit the viewport with comfortable spacing and large touch targets.\n\n\n\n\n\n\n\nForgot Password Flow\n\n\n\nIf a returning customer can&rsquo;t remember their password, they can click Lost your password? in the login window.\n\n\n\n\n\n\n\nThe customer enters their email and clicks Reset Password. They receive a password reset email, and after completing the reset they are returned to the same checkout step they started on, ready to finish their purchase.\n\n\n\nFor security, the same confirmation message is shown whether or not the email matches an existing account. This prevents anyone from probing your store to discover which emails are registered.\n\n\n\nFrequently Asked Questions\n\n\n\nDoes Smart Login work without CartFlows Pro?\n\n\n\nNo. Smart Login is a CartFlows Pro feature and requires both CartFlows and CartFlows Pro to be active.\n\n\n\nWill it interfere with my existing checkout?\n\n\n\nNo. When Smart Login is turned off, the checkout behaves exactly as before. When it is on, it only adds the prompt and login window &mdash; your checkout fields, payment options, and order summary remain unchanged.\n\n\n\nWhat happens if a logged-in customer visits the checkout page?\n\n\n\nNothing extra happens. Smart Login only runs for guests. Logged-in customers see the regular checkout.\n\n\n\nDoes the customer&rsquo;s cart get preserved during the password reset?\n\n\n\nYes. When the customer follows the reset link from their email, completes the password reset, and signs in, they are redirected back to the same checkout step with their cart intact.\n\n\n\nCan I customise the prompt message?\n\n\n\nYes. The Message field lets you write any text that fits your store&rsquo;s voice. Use the {{site_title}} placeholder if you want your store&rsquo;s name to appear in the message.\n\n\n\nIs it available on every checkout layout?\n\n\n\nYes. Smart Login works with the Default and Instant Checkout layouts and is compatible with the supported page builders.\n\n\n\nCan I use Inline mode instead of the popup?\n\n\n\nYes. Set Login Form Style to Inline and the existing slide-down login form is used instead of the centered window. The recognition prompt still appears.\n\n\n\n\n\n\n\nIf you have any questions or run into trouble, please reach out to our support team and we&rsquo;ll be happy to help.\";s:3:\"url\";s:39:\"https://cartflows.com/docs/smart-login/\";s:4:\"slug\";s:11:\"smart-login\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-04T15:40:59+05:30\";s:8:\"category\";a:2:{i:0;s:8:\"features\";i:1;s:15:\"global-checkout\";}}i:61;O:8:\"stdClass\":8:{s:2:\"id\";i:68918;s:5:\"title\";s:21:\"How to Use Gift Cards\";s:7:\"content\";s:14549:\"The Gift Cards feature in Power Coupons Pro lets you sell digital gift cards that customers can purchase and send to anyone via email. Recipients receive a unique coupon code they can redeem at checkout, with support for partial redemption across multiple orders.\n\n\n\nKey highlights:\n\n\n\n\nSell gift cards as WooCommerce products with preset or custom amounts\n\n\n\nCustomers fill in recipient name, email, and a personal message at purchase\n\n\n\nUnique coupon codes are auto-generated and emailed to recipients on order completion\n\n\n\nPartial redemption support — recipients can use gift cards across multiple orders\n\n\n\nConfigurable expiry, product/category restrictions, and text customization\n\n\n\nMy Account \"Gift Cards\" tab for customers to view received and sent gift cards\n\n\n\nGift cards are protected from discounts — no coupons or loyalty credits can be applied to gift card purchases\n\n\n\n\nRequirements: WordPress 6.0+, WooCommerce 3.0+, Power Coupons (free) plugin installed and active, Power Coupons Pro plugin installed, active, and license activated.\n\n\n\nGetting Started\n\n\n\nEnabling Gift Cards\n\n\n\n\nGo to Power Coupons → Settings in your WordPress admin.\n\n\n\nClick on the Gift Cards tab (in the settings navigation).\n\n\n\nUnder the General sub-tab, toggle Enable Gift Cards to ON.\n\n\n\nThe setting saves automatically. Once enabled, the gift card system becomes active.\n\n\n\n\n\n\n\n\nWhen Gift Cards is disabled, customers cannot purchase gift cards and the My Account tab is hidden. Any existing gift card coupons remain in the system and will work again when re-enabled.\n\n\n\nSettings Overview\n\n\n\nGift Cards settings are organized into two sub-tabs under Power Coupons → Settings → Gift Cards: General and Restrictions.\n\n\n\nGeneral Settings\n\n\n\n\nEnable Gift Cards – Master toggle for the entire feature. When OFF, no gift cards can be purchased or redeemed. Default: OFF.\n\n\n\nPreset Gift Card Values – Comma-separated list of amounts shown in the amount dropdown on the product page (e.g., 10,25,50,100). Only positive numeric values are accepted. Non-numeric values are automatically stripped on save. Default: 10,25,50,100.\n\n\n\nAllow Custom Amount – Let customers enter a custom gift card value instead of choosing from presets. Default: ON.\n\n\n\nMinimum Custom Amount – Minimum value for custom amounts. Only visible when Allow Custom Amount is enabled. Default: 5.\n\n\n\nMaximum Custom Amount – Maximum value for custom amounts. Only visible when Allow Custom Amount is enabled. If set lower than minimum, it is auto-corrected to match. Default: 500.\n\n\n\nGift Card Expiry – How long gift cards remain valid after purchase. Options: 1 Month, 3 Months, 6 Months, 9 Months, 1 Year, No Expiry. Default: 1 Year.\n\n\n\nAllow Partial Redemption – Allow recipients to use gift cards across multiple orders until the balance is exhausted. When OFF, the gift card can only be used once. Default: ON.\n\n\n\nSend Sender Confirmation – Send a confirmation email to the buyer when the gift card is delivered to the recipient. Default: ON.\n\n\n\n\n\n\n\n\nRestrictions Settings\n\n\n\nControl where gift cards can be redeemed. These restrictions are applied to the generated coupon codes.\n\n\n\n\nRestrict to Products – Gift cards can only be redeemed on these specific products. Leave empty for no restriction.\n\n\n\nRestrict to Categories – Gift cards can only be redeemed on products in these categories. Leave empty for no restriction.\n\n\n\nExclude Products – Gift cards cannot be redeemed on these specific products.\n\n\n\nExclude Categories – Gift cards cannot be redeemed on products in these categories.\n\n\n\n\n\n\n\n\nCreating a Gift Card Product\n\n\n\nGift cards are sold as regular WooCommerce Simple products with the Gift Card option enabled.\n\n\n\nSetting Up a Gift Card Product\n\n\n\n\nGo to Products → Add New in your WordPress admin.\n\n\n\nEnter a product name (e.g., \"Gift Card\") and add a description and product image.\n\n\n\nIn the Product data section, ensure the product type is set to Simple product.\n\n\n\nCheck the Gift Card checkbox (next to Virtual and Downloadable). The Virtual checkbox will be automatically checked and locked — gift cards are always virtual.\n\n\n\nA new Gift Card tab appears in the product data panel. Click on it.\n\n\n\n\n\n\n\n\nGift Card Product Settings\n\n\n\nThe Gift Card tab allows you to override global settings at the product level:\n\n\n\n\nGift Card Amounts – Enter preset denominations separated by commas (e.g., 25,50,100). Leave empty to use the global preset values from the Gift Cards settings page.\n\n\n\nAllow custom amount – Let customers enter their own gift card value for this product.\n\n\n\nMinimum amount – Minimum value for custom amounts. Leave empty to use the global setting. Only visible when Allow custom amount is checked.\n\n\n\nMaximum amount – Maximum value for custom amounts. Leave empty to use the global setting. Only visible when Allow custom amount is checked.\n\n\n\n\n\n\n\n\n\nYou do not need to set a product price — the price is determined by the customer\'s selected amount. A $0 price is set automatically to ensure the add-to-cart form renders.\n\n\n\nClick Publish (or Update) to save the product.\n\n\n\n\nCustomer Experience\n\n\n\nProduct Page\n\n\n\nWhen a customer visits a gift card product page, they see:\n\n\n\n\nPrice range – Instead of a fixed price, the product shows a range based on preset amounts (e.g., \"$10.00 – $100.00\").\n\n\n\nAmount dropdown – A select dropdown with all preset amounts. If custom amounts are enabled, a \"Custom Amount\" option appears at the end.\n\n\n\nCustom amount input – When \"Custom Amount\" is selected from the dropdown, a number input appears with the currency symbol and min/max placeholder (e.g., \"5.00 – 500.00\").\n\n\n\nRecipient fields – A section with fields for the recipient\'s name (required), email address (required), and a personal message (optional, up to 500 characters).\n\n\n\n\n\n\n\n\nWhen the quantity is set to more than 1, additional recipient groups are added automatically — one for each gift card. Each recipient requires a name and email.\n\n\n\nValidation\n\n\n\nThe following validations are enforced before a gift card can be added to the cart:\n\n\n\n\nAn amount must be selected (preset or custom).\n\n\n\nCustom amount must be within the configured min/max range.\n\n\n\nRecipient name is required for each gift card.\n\n\n\nA valid email address is required for each recipient.\n\n\n\nThe number of recipients must match the quantity.\n\n\n\n\nValidation runs both in the browser (JavaScript) and on the server (PHP) to prevent bypassing.\n\n\n\nShop Archive\n\n\n\nOn shop and category pages, gift card products display a \"Select options\" button instead of \"Add to cart\". This redirects customers to the single product page where they can fill in recipient details. AJAX add-to-cart is disabled for gift cards.\n\n\n\nCart and Checkout\n\n\n\nAfter adding a gift card to the cart:\n\n\n\n\nThe cart displays the Gift Card Amount, Recipient name and email, and Message for each gift card item.\n\n\n\nEach gift card is treated as a unique cart item, even if the same product and amount are selected.\n\n\n\nQuantity cannot be changed in the cart or mini-cart — it is locked to the value set on the product page because recipients are tied to the quantity.\n\n\n\nDiscounts are blocked — no coupons or loyalty credits can reduce the price of gift card items. This prevents a financial loophole where someone could buy a discounted gift card and redeem it at full value.\n\n\n\n\n\n\n\n\nWhat Happens After Purchase\n\n\n\nCoupon Generation\n\n\n\nWhen the order status changes to Completed, the following happens automatically for each gift card item in the order:\n\n\n\n\nA unique WooCommerce coupon is generated for each recipient with a code in the format gc-xxxxxxxx (8 random characters).\n\n\n\nThe coupon is configured as a fixed cart discount with the face value of the gift card.\n\n\n\nProduct and category restrictions from the Gift Cards settings are applied to the coupon.\n\n\n\nThe expiry date is set based on the configured Gift Card Expiry setting.\n\n\n\nAn email is sent to the recipient with the gift card code, amount, sender\'s name, personal message, and a link to the shop.\n\n\n\nIf enabled, a confirmation email is sent to the buyer confirming the gift card has been delivered.\n\n\n\n\nThe order is flagged to prevent double-processing if the status changes multiple times.\n\n\n\nEmail Notifications\n\n\n\nTwo types of emails are sent (both use the WooCommerce email template with your store\'s header and footer):\n\n\n\n\nRecipient Email – Sent to the recipient\'s email address. Contains the gift card code, amount, sender\'s name, personal message, expiry date, and a link to the shop. Subject line is customizable (default: \"You\'ve received a {amount} gift card!\").\n\n\n\nSender Confirmation Email – Sent to the buyer\'s billing email (only if \"Send Sender Confirmation\" is enabled). Contains the recipient\'s name, amount, and coupon code. Subject line is customizable (default: \"Your {amount} gift card has been sent!\").\n\n\n\n\nGift Card Redemption\n\n\n\nRecipients redeem gift cards by entering the coupon code at checkout, just like any WooCommerce coupon.\n\n\n\nPartial Redemption\n\n\n\nWhen Allow Partial Redemption is enabled (default), gift cards work as a stored balance:\n\n\n\n\nIf the order total is less than the gift card balance, only the order amount is deducted and the remaining balance is preserved.\n\n\n\nThe recipient can use the same code on future orders until the balance is exhausted.\n\n\n\nA success notice shows the remaining balance when the gift card is applied (e.g., \"Gift card applied! Remaining balance: $70.00\").\n\n\n\nWhen the balance reaches $0, the gift card is marked as fully redeemed and cannot be used again.\n\n\n\n\nWhen partial redemption is disabled, the gift card can only be used once regardless of the remaining balance.\n\n\n\nBalance Tracking\n\n\n\nGift card balances are updated atomically when orders are completed. This means even if two orders using the same gift card are processed simultaneously, the balance will be calculated correctly without race conditions.\n\n\n\nThe discount is also capped to the remaining balance — a gift card can never give more discount than its current balance, even when applied to a cart with multiple items.\n\n\n\nMy Account — Gift Cards Tab\n\n\n\nA Gift Cards tab is added to the WooCommerce My Account page (placed after \"Orders\"). The tab label is customizable via Text Customization settings.\n\n\n\nMy Gift Cards (Received)\n\n\n\nShows all gift cards the customer has received, with the following columns:\n\n\n\n\nCode – Partially masked code (e.g., gc-****dcas) to prevent shoulder-surfing.\n\n\n\nOriginal Amount – The face value of the gift card.\n\n\n\nBalance – Current remaining balance.\n\n\n\nStatus – Active, Partially Used, Fully Redeemed, or Expired.\n\n\n\nExpiry – Expiry date or \"No expiry\".\n\n\n\nCopy Code – A button (shown only for Active gift cards) that copies the full code to the clipboard.\n\n\n\n\n\n\n\n\nSent Gift Cards\n\n\n\nShows all gift cards the customer has purchased and sent, with columns for:\n\n\n\n\nRecipient – Name and email of the recipient.\n\n\n\nAmount – The gift card value.\n\n\n\nCode – Masked code, or \"Pending\" if the order hasn\'t been completed yet.\n\n\n\nStatus – Delivered, Active, Partially Used, Fully Redeemed, or Expired.\n\n\n\nDate – When the gift card was sent.\n\n\n\n\n\n\n\n\nText Customization\n\n\n\nAll customer-facing text strings can be customized under Power Coupons → Settings → Text Customization → Gift Cards sub-tab.\n\n\n\nAvailable Customizations\n\n\n\n\nAmount Selector Label – Label above the amount dropdown. Default: \"Select Amount\".\n\n\n\nCustom Amount Option Label – Text for the custom amount option. Default: \"Custom Amount\".\n\n\n\nRecipient Section Label – Label above recipient fields. Default: \"Send this gift card to...\".\n\n\n\nName Placeholder – Placeholder for recipient name. Default: \"Recipient\'s name\".\n\n\n\nEmail Placeholder – Placeholder for recipient email. Default: \"Recipient\'s email address\".\n\n\n\nMessage Placeholder – Placeholder for personal message. Default: \"Add a personal message (optional)\".\n\n\n\nBalance Applied Message – Notice when gift card is applied. Default: \"Gift card applied! Remaining balance: {balance}\".\n\n\n\nFully Redeemed Message – Error when a used-up gift card is applied. Default: \"This gift card has been fully redeemed.\".\n\n\n\nRecipient Email Subject – Subject for recipient email. Default: \"You\'ve received a {amount} gift card!\".\n\n\n\nSender Confirmation Email Subject – Subject for buyer email. Default: \"Your {amount} gift card has been sent!\".\n\n\n\nMy Account Tab Label – Label for the Gift Cards tab. Default: \"Gift Cards\".\n\n\n\n\n\n\n\n\nPlaceholder Reference\n\n\n\nThe following placeholders can be used in text customization fields:\n\n\n\n\n{amount} – The gift card amount with currency symbol (used in email subjects).\n\n\n\n{balance} – The remaining gift card balance with currency symbol (used in the balance applied message).\n\n\n\n\nGift Cards in the Admin\n\n\n\nOrder Details\n\n\n\nWhen viewing an order that contains gift card items in WooCommerce → Orders, the order item meta shows:\n\n\n\n\nGift Card Amount – The face value selected by the customer.\n\n\n\nRecipients – Each recipient\'s name, email, and personal message.\n\n\n\n\nGenerated Coupons\n\n\n\nGift card coupons appear in WooCommerce → Coupons (or Marketing → Coupons) with the code format gc-xxxxxxxx. Each coupon stores:\n\n\n\n\nThe current balance (as the coupon amount).\n\n\n\nThe initial face value.\n\n\n\nThe source order ID and item ID.\n\n\n\nThe recipient email.\n\n\n\n\nGift card coupons are automatically hidden from the frontend \"View All Coupons\" drawer and coupon display lists. They are personal, recipient-specific codes and should not be browsed alongside promotional coupons.\n\n\n\nFully redeemed gift card coupons are kept in the system (not trashed) to preserve the audit trail for customer support and order history.\n\n\n\nExample Setup\n\n\n\nHere is a quick example of setting up gift cards for your store:\n\n\n\n\nGo to Power Coupons → Settings → Gift Cards and enable Gift Cards.\n\n\n\nSet preset amounts to 25,50,100,200.\n\n\n\nEnable Allow Custom Amount with a minimum of 10 and maximum of 500.\n\n\n\nSet expiry to 1 Year and enable Partial Redemption.\n\n\n\nGo to Products → Add New, create a product called \"Gift Card\".\n\n\n\nCheck the Gift Card checkbox and publish.\n\n\n\n\nResult: Customers can now visit your gift card product page, choose an amount ($25, $50, $100, $200, or a custom value between $10–$500), enter the recipient\'s details, and purchase. On order completion, the recipient receives an email with a unique coupon code they can use at checkout. The balance tracks across multiple orders for up to one year.\";s:3:\"url\";s:49:\"https://cartflows.com/docs/how-to-use-gift-cards/\";s:4:\"slug\";s:21:\"how-to-use-gift-cards\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-04-16T22:33:37+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"power-coupons\";}}i:62;O:8:\"stdClass\":8:{s:2:\"id\";i:68797;s:5:\"title\";s:47:\"How to Use Loyalty Rewards &#038; Store Credits\";s:7:\"content\";s:12830:\"The Loyalty Rewards feature in Power Coupons Pro lets you reward customers with store credits for purchases, signups, and product reviews. Customers earn credits automatically and can redeem them for discounts on future orders, driving repeat purchases and customer loyalty.\n\n\n\nKey highlights:\n\n\n\n\nEarn credits on orders, signups, and product reviews\n\n\n\nFlexible earning campaigns with conditions and priority-based matching\n\n\n\nTwo redemption modes: Full Credits and Max Limit\n\n\n\nCredit expiry with configurable notice period\n\n\n\nFrontend widgets on product, cart, checkout, and My Account pages\n\n\n\nAdmin dashboard for campaign management, credit history, and manual adjustments\n\n\n\n\nRequirements: WordPress 6.0+, WooCommerce 3.0+, Power Coupons (free) plugin installed and active, Power Coupons Pro plugin installed, active, and license activated.\n\n\n\nGetting Started\n\n\n\nEnabling Loyalty Rewards\n\n\n\n\nGo to Power Coupons → Settings in your WordPress admin.\n\n\n\nClick on the Loyalty Rewards tab (in the settings navigation).\n\n\n\nUnder the General sub-tab, toggle Enable Loyalty Rewards to ON.\n\n\n\nThe setting saves automatically. Once enabled, the entire credits system becomes active.\n\n\n\n\n\n\n\n\nWhen Loyalty Rewards is disabled, all earning, redemption, and frontend displays are turned off. Customer balances are preserved and will be available when re-enabled.\n\n\n\nSettings Overview\n\n\n\nLoyalty Rewards settings are organized into three sub-tabs under Power Coupons → Settings → Loyalty Rewards: General, Earning, and Redemption.\n\n\n\nGeneral Settings\n\n\n\n\nEnable Loyalty Rewards – Master toggle for the entire feature. When OFF, no credits are earned or redeemed. Default: OFF.\n\n\n\nEnable Credits Expiry – When ON, earned credits expire after the configured period. Default: OFF.\n\n\n\nExpiry Period (Days) – Number of days after which earned credits expire. Minimum: 1. Default: 365.\n\n\n\nExpiry Notice (Days Before) – How many days before expiry to send a warning email to the customer. Must be less than the expiry period. Default: 30.\n\n\n\nShow on Product Page – Display \"Earn X Credits\" message on single product pages. Default: ON.\n\n\n\nShow on Cart Page – Display earning message and redemption widget on the cart page. Default: ON.\n\n\n\nShow on Checkout Page – Display earning message and redemption widget on checkout. Default: ON.\n\n\n\n\nEarning Settings\n\n\n\n\nDefault Earn Rate – Fallback credits per currency unit when no campaign matches. For example, 1.0 means the customer earns 1 credit per $1 spent. Default: 1.0.\n\n\n\nRound Credits – How to round fractional credits: Round to Nearest, Round Down (floor), or Round Up (ceil). Default: Round to Nearest.\n\n\n\nEarning Applies To – Calculate credits based on Subtotal (before tax and shipping) or Total (after tax and shipping). Default: Subtotal.\n\n\n\nExclude Sale Items – When ON, products on sale do not earn credits. Default: OFF.\n\n\n\nExclude Couponed Orders – When ON, orders that use a coupon do not earn credits (unless the coupon has a custom earning override). Default: OFF.\n\n\n\n\nRedemption Settings\n\n\n\n\nRedemption Mode – Choose how customers redeem credits:\nFull Credits – Customers must redeem their entire credit balance at once.\nMax Limit – Customers can choose how many credits to redeem, up to a maximum cap.\n\n\n\nMax Credits per Order – Cap per order when using Max Limit mode. Set to 0 for no limit. Default: 0.\n\n\n\nRedemption Ratio – How many credits equal $1 of discount. Example: 100 means 100 credits = $1 discount. Default: 100.\n\n\n\nMaximum Discount Type – Cap the discount from credits: No Limit, Fixed Amount, or Percentage of Cart Total. Default: No Limit.\n\n\n\nMaximum Discount Value – The limit amount (when type is Fixed or Percentage). Set to 0 for no limit. Default: 0.\n\n\n\nCombine with Coupons – Allow credits to be used alongside regular WooCommerce coupons. When OFF, customers must choose one or the other. Default: ON.\n\n\n\n\nEarning Campaigns\n\n\n\nCampaigns define how and when customers earn credits. You can create multiple campaigns with different rules, and the system automatically picks the best-matching one based on priority.\n\n\n\nAccessing Campaigns\n\n\n\nGo to Power Coupons → Loyalty Rewards in the WordPress admin sidebar. This opens the campaigns management page.\n\n\n\n\n\n\n\nCampaign Types (Action Types)\n\n\n\n\nOrder Earning – Credits based on order amount. Most common type. Supports fixed, per-currency, and percentage earn types.\n\n\n\nSignup Bonus – One-time fixed credit bonus when a new customer creates an account.\n\n\n\nProduct Review – Credits awarded when a customer\'s product review is approved by admin. Each product can only earn review credits once per customer.\n\n\n\n\nEarn Types (for Order Earning Campaigns)\n\n\n\nWhen the action type is Order Earning, you choose how credits are calculated:\n\n\n\n\nFixed – A flat number of credits per order, regardless of order total. Example: Earn Value = 50 → Customer gets 50 credits on every qualifying order.\n\n\n\nPer Currency Unit – Credits multiplied by the order amount. Example: Earn Value = 2 → A $75 order earns 150 credits (75 x 2).\n\n\n\nPercentage – Credits as a percentage of the order amount. Example: Earn Value = 10 → A $75 order earns 7.5 credits (10% of 75).\n\n\n\n\nCampaign Conditions\n\n\n\nCampaigns can have optional conditions to control when they apply:\n\n\n\n\nMinimum Order Amount – The order must meet a minimum subtotal/total.\n\n\n\nMaximum Order Amount – The order must not exceed this amount.\n\n\n\nSpecific Products – Only orders containing specific products qualify.\n\n\n\nSpecific Categories – Only orders containing products from specific categories qualify.\n\n\n\nUser Roles – Only specific user roles (e.g., Wholesale, VIP) qualify.\n\n\n\n\n\n\n\n\n\n\n\n\nCampaign Fields Reference\n\n\n\n\nCampaign Name – A descriptive name for the campaign (e.g., \"Double Credits on Electronics\").\n\n\n\nAction Type – Order Earning, Signup Bonus, or Product Review.\n\n\n\nEarn Type – Fixed, Per Currency Unit, or Percentage (for Order Earning only).\n\n\n\nEarn Value – The numeric value used for credit calculation.\n\n\n\nPriority – When multiple campaigns match, the one with the highest priority (lowest number) wins. Default: 10.\n\n\n\nStatus – Active or Inactive. Inactive campaigns are ignored during matching.\n\n\n\n\nHow Campaign Matching Works\n\n\n\nWhen an order is completed, the system evaluates all active campaigns in priority order (lowest number first). The first campaign whose conditions match the order is used. If no campaign matches, the Default Earn Rate from Earning Settings is used as a fallback.\n\n\n\nHow Credits Are Earned\n\n\n\nOrder Earning Flow\n\n\n\n\nCustomer places an order.\n\n\n\nWhen the order status changes to Completed, the system evaluates active campaigns.\n\n\n\nThe best-matching campaign (by priority) determines the credit amount.\n\n\n\nCredits are added to the customer\'s balance.\n\n\n\nA log entry is created in the credit history.\n\n\n\n\nWhat happens if an order is refunded? If an order is fully or partially refunded, the credits earned from that order are automatically deducted from the customer\'s balance. A \"Pending Refund\" entry appears in the credit history until the refund is processed.\n\n\n\nSignup Bonus\n\n\n\nWhen a Signup Bonus campaign is active, new customers who create an account receive a one-time fixed credit bonus. The bonus is awarded immediately upon registration.\n\n\n\nProduct Review Credits\n\n\n\nWhen a Product Review campaign is active, customers earn credits when their product review is approved by an admin. Each product can only earn review credits once per customer to prevent abuse.\n\n\n\nCoupon Overrides on Earning\n\n\n\nIndividual WooCommerce coupons can override the default earning behavior. When editing a coupon, you can set a custom earning rate that applies when that coupon is used, even if \"Exclude Couponed Orders\" is enabled in settings.\n\n\n\nCredit Redemption\n\n\n\nCustomers can redeem their earned credits for discounts on future orders. The redemption widget appears on the cart and checkout pages (when enabled in General Settings).\n\n\n\nFull Credits Mode\n\n\n\nIn this mode, customers redeem their entire credit balance at once. A single \"Apply Credits\" button is shown. The discount is calculated as: Credits ÷ Redemption Ratio = Discount Amount.\n\n\n\n\n\n\n\nMax Limit Mode\n\n\n\nIn this mode, customers can choose how many credits to redeem via an input field, up to the configured maximum. This gives customers flexibility to save credits for larger purchases.\n\n\n\nFrontend Display\n\n\n\nLoyalty Rewards adds several customer-facing elements throughout your store:\n\n\n\nProduct Page\n\n\n\nShows an \"Earn X Credits\" message on single product pages, letting customers know how many credits they\'ll earn by purchasing the product.\n\n\n\n\n\n\n\nCart Page\n\n\n\nDisplays the earning message (how many credits will be earned for the current cart) and the credit redemption widget where customers can apply their credits.\n\n\n\nCheckout Page\n\n\n\nSame as the cart page – shows earning information and the redemption widget for applying credits at checkout.\n\n\n\nThank You / Order Confirmation\n\n\n\nAfter a successful purchase, the order confirmation page shows how many credits were earned from the order.\n\n\n\nMy Account → My Credits\n\n\n\nA dedicated \"My Credits\" tab is added to the WooCommerce My Account page, featuring:\n\n\n\n\nSummary Cards – Show the customer\'s total credit balance, total earned, total redeemed, and credits expiring soon.\n\n\n\nCredit History Table – A detailed log of all credit transactions (earned, redeemed, expired, adjusted) with dates, amounts, and notes.\n\n\n\n\n\n\n\n\nEmail Notifications\n\n\n\nThe system sends email notifications for credit-related events, including credits earned on order completion and credit expiry warnings (sent the configured number of days before expiry).\n\n\n\nAdmin Management\n\n\n\nCampaigns List\n\n\n\nThe Power Coupons → Loyalty Rewards page shows all campaigns in a table with columns for Campaign Name, Action Type, Earn Type, Earn Value, Priority, Status, and Actions (Edit, Clone, Delete). You can toggle campaigns active/inactive with the status switch.\n\n\n\nCredits History / Logs\n\n\n\nThe Logs page provides a complete audit trail of all credit transactions across all customers. Each entry shows the customer, transaction type (earned, redeemed, expired, adjusted), amount, date, and related order or campaign.\n\n\n\n\n\n\n\nFiltering the Logs: You can filter the log by date range, customer, transaction type, and campaign to quickly find specific entries.\n\n\n\nManual Credit Adjustments\n\n\n\nAdmins can manually add or deduct credits from any customer\'s balance. This is useful for:\n\n\n\n\nCompensating a customer for a service issue\n\n\n\nRunning a special promotion with bonus credits\n\n\n\nCorrecting an error in earned credits\n\n\n\n\nManual adjustments are logged in the credit history with an \"Adjustment\" type and an optional admin note.\n\n\n\nText Customization\n\n\n\nAll customer-facing text strings can be customized under Power Coupons → Settings → Text Customization → Loyalty Rewards sub-tab.\n\n\n\nAvailable Customizations\n\n\n\n\nProduct page earning message\n\n\n\nCart/Checkout earning message\n\n\n\nRedemption widget labels and button text\n\n\n\nMy Account credits page headings\n\n\n\nOrder confirmation earning message\n\n\n\n\n\n\n\n\nPlaceholder Reference\n\n\n\nThe following placeholders can be used in text customization fields:\n\n\n\n\n{credits} – The number of credits (earned or available)\n\n\n\n{credits_value} – The monetary value of the credits\n\n\n\n{balance} – The customer\'s current credit balance\n\n\n\n{expiry_date} – The date when credits will expire\n\n\n\n\nExample Setups\n\n\n\nExample 1: Simple Loyalty Program\n\n\n\nA straightforward setup where every customer earns credits on every order:\n\n\n\n\nEnable Loyalty Rewards in General Settings.\n\n\n\nSet the Default Earn Rate to 1.0 (1 credit per $1 spent).\n\n\n\nSet the Redemption Ratio to 100 (100 credits = $1 discount).\n\n\n\nUse Full Credits redemption mode for simplicity.\n\n\n\nEnable display on Product, Cart, and Checkout pages.\n\n\n\n\nResult: A customer who spends $100 earns 100 credits, which they can redeem for a $1 discount on their next order.\n\n\n\nExample 2: Tiered Earning with Signup Bonus\n\n\n\nA more advanced setup with multiple campaigns:\n\n\n\n\nCreate a Signup Bonus campaign: 500 credits for new registrations.\n\n\n\nCreate an Order Earning campaign for orders over $100: Per Currency Unit, Earn Value = 3 (triple credits), Priority = 1.\n\n\n\nCreate a default Order Earning campaign with no conditions: Per Currency Unit, Earn Value = 1, Priority = 10.\n\n\n\nCreate a Product Review campaign: 50 credits per approved review.\n\n\n\nSet Redemption Mode to Max Limit with Max Credits per Order = 500.\n\n\n\n\nResult: New customers get 500 bonus credits. Orders over $100 earn triple credits. All other orders earn standard credits. Customers can also earn 50 credits per product review. They can redeem up to 500 credits per order.\";s:3:\"url\";s:68:\"https://cartflows.com/docs/how-to-use-loyalty-rewards-store-credits/\";s:4:\"slug\";s:40:\"how-to-use-loyalty-rewards-store-credits\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-03-27T12:01:41+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"power-coupons\";}}i:63;O:8:\"stdClass\":8:{s:2:\"id\";i:68793;s:5:\"title\";s:22:\"How to Use BOGO Offers\";s:7:\"content\";s:10046:\"BOGO (Buy One Get One) Offers is a PRO feature in Power Coupons for WooCommerce that lets you create intelligent promotional offers to drive sales. With BOGO, you can reward customers with free or discounted products based on what they buy or how much they spend.\n\n\n\nKey highlights:\n\n\n\n\n6 pre-built offer types covering quantity-based and spend-based promotions\n\n\n\nChoose reward type: free product, percentage discount, or fixed amount discount\n\n\n\nAuto-apply offers or require a coupon code\n\n\n\nTarget any product or specific products only\n\n\n\nCart progress bar for spend-based offers to encourage customers to spend more\n\n\n\nVariable product support – customers can select size, color, etc. when claiming gifts\n\n\n\n\nRequirements: Both the free Power Coupons plugin and the Power Coupons PRO plugin must be installed and active for BOGO offers to work.\n\n\n\nAccessing BOGO Offers\n\n\n\nNavigate to your WordPress admin dashboard and go to:\n\n\n\nPower Coupons → BOGO Offers\n\n\n\nYou can also access it from the top navigation tabs on the Power Coupons settings page by clicking the BOGO Offers tab.\n\n\n\n\n\n\n\nBOGO Offer Types\n\n\n\nWhen you click \"+ Create New Offer\", you will see 6 pre-built offer type templates to choose from. These are divided into two categories:\n\n\n\n\n\n\n\nQuantity-Based Offers\n\n\n\nThese offers are triggered when the customer adds a specific number of qualifying products to their cart.\n\n\n\n\nBuy X Get X Free – Give the same product free when customers buy X quantity. For example, \"Buy 2 T-shirts, get 1 T-shirt free.\"\n\n\n\nBuy X Get Y – Offer a different product free with a qualifying purchase. For example, \"Buy 3 Eggs, get 1 Honey free.\"\n\n\n\nBuy X Get Y at X% Off – Give a discounted product when X is purchased. For example, \"Buy 2 Shirts, get 1 Pair of Pants at 50% off.\"\n\n\n\n\nSpend-Based Offers\n\n\n\nThese offers are triggered when the customer\'s cart total reaches a minimum spend amount.\n\n\n\n\nSpend $X Get Y for Free – Offer a free product when the cart reaches a minimum value. For example, \"Spend $100, get a free Gift Box.\"\n\n\n\nSpend $X Get Y at X% Off – Unlock a discounted product after spending a minimum amount. For example, \"Spend $75, get a Premium Case at 30% off.\"\n\n\n\nSpend $X Get Free Shipping – Enable free shipping when the cart total reaches a threshold. For example, \"Spend $50 and get free shipping on your order.\"\n\n\n\n\nCreating a BOGO Offer\n\n\n\nThe offer creation process uses a multi-step wizard with 3 tabs (or 4 tabs for spend-based offers). Here is a walkthrough of each step:\n\n\n\nStep 1: Basic Settings\n\n\n\nAfter selecting an offer type, you will be taken to the Basic Settings tab.\n\n\n\n\n\n\n\n\nOffer Name (Required) – A descriptive name for your offer. This name is displayed to customers in the cart summary when the offer is applied.\n\n\n\nDescription (Optional) – An internal description to help you identify the offer\'s purpose.\n\n\n\nActivate Offer (Required) – Choose how the offer is triggered:Automatically – The offer applies automatically when the customer\'s cart meets the conditions. This is the default option.Using Coupon Code – The customer must enter a specific coupon code to activate the offer.\n\n\n\n\nClick \"Save &amp; Continue\" to proceed to the next step.\n\n\n\nStep 2: Offer Conditions\n\n\n\nThis tab defines the specific conditions and discount details for your offer.\n\n\n\n\n\n\n\nDiscount Type – Choose one of three discount types:\n\n\n\n\nFree – The reward product is completely free (100% discount)\n\n\n\nPercentage – A percentage discount is applied to the reward product (e.g., 50% off)\n\n\n\nFixed Amount – A fixed dollar amount is deducted from the reward product price (e.g., $5 off)\n\n\n\n\nFor Quantity-Based Offers:\n\n\n\n\nBuy Quantity – The number of qualifying products the customer must add to their cart (minimum: 1)\n\n\n\nGet Quantity – The number of reward products the customer will receive (minimum: 1)\n\n\n\n\nFor Spend-Based Offers:\n\n\n\n\nMinimum Spend Amount – The minimum cart subtotal required to trigger the offer\n\n\n\nGet Quantity – The number of reward products (not shown for \"Spend $X Get Free Shipping\")\n\n\n\n\nAdditional fields:\n\n\n\n\nDiscount Percentage – Shown when Discount Type is \"Percentage\". Enter a value between 1–100%.\n\n\n\nFixed Discount Amount – Shown when Discount Type is \"Fixed Amount\".\n\n\n\nInclude Free Shipping – An optional checkbox to add free shipping on top of the product discount.\n\n\n\n\nStep 3: Product Selection\n\n\n\nThis tab lets you define which products trigger the offer and which products customers receive as rewards.\n\n\n\n\n\n\n\nTrigger Type (Quantity-Based Offers Only):\n\n\n\n\nAny Product – The offer triggers when the cart contains any product meeting the quantity requirement.\n\n\n\nSpecific Products – The offer only triggers when the customer buys one of the selected products.\n\n\n\n\nProducts to Buy – Use the searchable product selector to choose which products qualify for the offer. Type at least 3 characters to search. You can select multiple products.\n\n\n\nProducts to Get (Reward Products) – Select which products the customer will receive as their reward. This field is hidden for \"Buy X Get X Free\" (same product is given) and \"Spend $X Get Free Shipping\" (no product reward).\n\n\n\nUsage Limit – Optionally set a maximum number of times this offer can be redeemed across all customers. Leave empty for unlimited usage.\n\n\n\nStep 4: Cart Progress Bar (Spend-Based Offers Only)\n\n\n\nThis tab is only available for spend-based offer types. It allows you to show a progress bar on the cart/checkout page that motivates customers to spend more to unlock the offer.\n\n\n\n\n\n\n\n\nEnable Progress Bar – Toggle to enable or disable the progress bar.\n\n\n\nIcon – Choose an icon: Tag, Truck, Gift, or Percent. Default: Gift.\n\n\n\nPriority – Display order if multiple offers have progress bars. Lower numbers display first.\n\n\n\nProgress Message – Message shown before reaching the threshold. Default: \"Spend {remaining} more to unlock {coupon_name}!\" Placeholders: {remaining}, {threshold}, {coupon_name}.\n\n\n\nSuccess Message – Message shown after reaching the threshold. Default: \"You unlocked {coupon_name}!\" Placeholders: {remaining}, {coupon_name}.\n\n\n\n\nClick \"Create Offer\" (or \"Update Offer\") to save.\n\n\n\nManaging BOGO Offers\n\n\n\nThe main BOGO Offers page shows a table listing all your offers.\n\n\n\nOffers Table\n\n\n\n\n\n\n\n\nOffer Name – Clickable to edit the offer\n\n\n\nDescription – A truncated preview of the offer description\n\n\n\nOffer Type – Shows the preset type (e.g., \"Buy X Get Y\") or \"Custom\"\n\n\n\nStatus – Toggle switch to quickly enable or disable an offer\n\n\n\nActions:Preview (eye icon) – View a read-only summary of the offerEdit (pencil icon) – Open the multi-step editorClone (copy icon) – Duplicate the offer with all settingsDelete (trash icon) – Permanently remove the offer\n\n\n\n\nSearch, Bulk Actions, and Status Toggle\n\n\n\n\nUse the search bar to filter offers by name or description in real time.\n\n\n\nSelect multiple offers using checkboxes for bulk delete operations.\n\n\n\nUse the status toggle to quickly enable or disable any offer. Inactive offers remain in your list but won\'t apply to customer carts.\n\n\n\n\nOffer Preview\n\n\n\nClick the Preview (eye) icon on any offer to see a read-only summary modal displaying:\n\n\n\n\n\n\n\n\nOffer Settings – Activation method, Discount Type, Discount Value\n\n\n\nConditions – Buy Quantity or Minimum Spend, Get Quantity, Trigger type\n\n\n\nProducts – Products to Buy and Products to Get\n\n\n\nStatus Badge – \"Active\" (green) or \"Inactive\" (gray)\n\n\n\nOffer Type Badge – Displays the preset type name\n\n\n\n\nHow BOGO Offers Work on the Frontend\n\n\n\nOnce an offer is active, here is what your customers will experience:\n\n\n\nCart and Checkout Notifications\n\n\n\nWhen a customer\'s cart meets the BOGO offer conditions, a notification appears on the cart and checkout pages:\n\n\n\n\n\n\n\n\nProduct image thumbnail of the reward product\n\n\n\nOffer name and description\n\n\n\nA status badge showing \"Available Offer\" (blue) or \"Offer Applied\" (green)\n\n\n\nAn \"Apply Offer\" button for auto-apply offers, or instructions to enter the coupon code\n\n\n\nOnce applied, the text changes to \"This offer has been applied to your cart\"\n\n\n\n\nCart Progress Bar (Spend-Based Offers)\n\n\n\nIf the Cart Progress Bar is enabled for a spend-based offer, customers see a visual progress indicator showing:\n\n\n\n\nHow much more they need to spend to unlock the offer\n\n\n\nA progress bar that fills as the cart total increases\n\n\n\nThe configured icon (Tag, Truck, Gift, or Percent)\n\n\n\nOnce the threshold is reached, the Success Message is displayed\n\n\n\n\nImportant Notes\n\n\n\n\nBOGO offers are separate from regular coupons. They do not appear in the standard WooCommerce coupon list or the Power Coupons coupon drawer.\n\n\n\nBoth plugins required. The free Power Coupons plugin and the Power Coupons PRO plugin must both be installed and activated.\n\n\n\nOffer stacking. Multiple BOGO offers can be active simultaneously. Each offer is evaluated independently.\n\n\n\nCoupon code mode. When \"Using Coupon Code\" is selected, a WooCommerce coupon is automatically created and linked to the BOGO offer.\n\n\n\nUsage limits. If a usage limit is set, the offer stops being available once the total redemption count reaches the limit.\n\n\n\nCloning offers. Use the Clone action to quickly duplicate an existing offer and modify it for similar promotions.\n\n\n\n\nExample Use Cases\n\n\n\nClearance Sale\n\n\n\nCreate a \"Buy X Get X Free\" offer targeting clearance products. Set Buy Quantity to 1 and Get Quantity to 1 so customers get a second item free when they buy one.\n\n\n\nCross-Sell Promotion\n\n\n\nUse \"Buy X Get Y\" to offer a complementary product free. For example, buy a Phone Case and get a Screen Protector free.\n\n\n\nTiered Spend Incentive\n\n\n\nCreate multiple spend-based offers with different thresholds and enable the Cart Progress Bar on each. For example: Spend $50 for 10% off an accessory, Spend $100 for a free gift, Spend $150 for free shipping.\n\n\n\nLimited-Time Free Gift\n\n\n\nUse \"Spend $X Get Y for Free\" with a usage limit to offer the first 100 customers a free gift when they spend over $75.\";s:3:\"url\";s:50:\"https://cartflows.com/docs/how-to-use-bogo-offers/\";s:4:\"slug\";s:22:\"how-to-use-bogo-offers\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-03-27T11:20:23+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"power-coupons\";}}i:64;O:8:\"stdClass\":8:{s:2:\"id\";i:67725;s:5:\"title\";s:52:\"Email/Domain Blacklist for Cart Abandonment Recovery\";s:7:\"content\";s:3086:\"The Email/Domain Blacklist feature in Cart Abandonment Recovery Pro allows store owners to prevent recovery messages (email, SMS, WhatsApp) from being sent to specific email addresses or entire domains. Blacklisted carts are excluded from messaging while the cart record remains in the database.\n\n\n\nThis feature ensures that recovery messages are suppressed for unwanted or disposable addresses without affecting cart visibility or checkout functionality.\n\n\n\n1. Where to Find It\n\n\n\nAdmin Path: WooCommerce &gt; Cart Abandonment Recovery &gt; Settings &gt; Blacklist\n\n\n\n\n\n\n\nThis section is available only in the Pro version with an active license.\n\n\n\n2. Settings\n\n\n\n1. Enable Blacklist (Toggle)\n\n\n\n\nDefault: Off\n\n\n\nTurns the blacklist feature on or off.\n\n\n\nWhen disabled, no blacklist checks are performed, even if entries exist.\n\n\n\n\n2. Blacklisted Emails &amp; Domains (Textarea with Dropdown)\n\n\n\n\nDefault: Empty\n\n\n\nMultiline input; each line represents one blacklist rule.\n\n\n\nIncludes a searchable dropdown of 5,100+ known disposable email domains (e.g., tempmail.com, 10minutemail.com) that can be added with a click.\n\n\n\n\n3. How to Add Entries\n\n\n\nFormats Supported:\n\n\n\n\nExact Email Address\n\nExample: john@example.com\n\n\n\nBlocks only this specific email.\n\n\n\n\n\nDomain Wildcard\n\nExample: *tempmail.com\n\n\n\nBlocks all emails from @tempmail.com.\n\n\n\n\n\n\nRules:\n\n\n\n\nOne entry per line.\n\n\n\nCase-insensitive matching.\n\n\n\nDomain wildcard must start with an asterisk (*).\n\n\n\n\n4. How It Works\n\n\n\n1. Automatic Blacklist Check (On Cart Abandonment)\n\n\n\n\nCustomer abandons cart and enters email.\n\n\n\nPlugin saves the abandonment record.\n\n\n\nBlacklist check runs automatically.\n\n\n\nCustomer email/domain is compared against blacklist entries.\n\n\n\nIf a match is found, cart status is set to \"Blacklisted.\"\n\n\n\nRecovery message scheduler skips blacklisted carts — no emails, SMS, or WhatsApp messages are sent.\n\n\n\n\n2. Manual Blacklisting from Admin Dashboard\n\n\n\n\nGo to abandoned cart details page.\n\n\n\nClick Blacklist button.\n\n\n\nCart status updates to \"Blacklisted.\"\n\n\n\nCustomer email is added to Blacklisted Emails &amp; Domains list.\n\n\n\n\n\n\n\n\n3. Removing from Blacklist (Whitelisting)\n\n\n\n\nGo to blacklisted cart details page.\n\n\n\nClick Whitelist button.\n\n\n\nCart status restores to \"Abandoned.\"\n\n\n\nCustomer email is removed from blacklist.\n\n\n\n\n\n\n\n\n5. What Gets Blocked\n\n\n\nWhen a cart is blacklisted, the following are suppressed:\n\n\n\n\nRecovery Emails\n\n\n\nRecovery SMS messages\n\n\n\nRecovery WhatsApp messages\n\n\n\n\nAll three channels respect the blacklist status.\n\n\n\n6. What Does NOT Happen\n\n\n\n\nCart data is not deleted; blacklisted carts remain visible.\n\n\n\nCustomers can still complete purchases.\n\n\n\nAlready-sent messages are unaffected; blacklist only applies to future messages.\n\n\n\nWooCommerce checkout and order creation are unaffected.\n\n\n\n\n7. Disposable/Temporary Email Domain Suggestions\n\n\n\nThe textarea includes a searchable dropdown with 5,100+ pre-configured temporary email domains. These suggestions are not blacklisted by default; the store owner must explicitly add them.\n\n\n\n8. Frequently Asked Questions\";s:3:\"url\";s:80:\"https://cartflows.com/docs/email-domain-blacklist-for-cart-abandonment-recovery/\";s:4:\"slug\";s:52:\"email-domain-blacklist-for-cart-abandonment-recovery\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-03-05T22:44:16+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:65;O:8:\"stdClass\":8:{s:2:\"id\";i:67713;s:5:\"title\";s:50:\"WhatsApp Integration for Cart Abandonment Recovery\";s:7:\"content\";s:11645:\"The WhatsApp Followup feature in Cart Abandonment Recovery Pro enables store owners to automatically send WhatsApp messages to customers who abandon their carts at checkout. Messages are delivered using the Meta (Facebook) WhatsApp Cloud API and pre-approved templates created in Meta Business Manager.\n\n\n\nThis feature allows multiple follow-up templates with customizable delays, discount coupons, and targeting conditions. A global integration settings section and per-template configuration system provide full control over message automation.\n\n\n\nHow It Works - The Big Picture\n\n\n\nBefore diving into setup, here\'s what you\'re building and why each piece matters:\n\n\n\nComponentWhat It DoesMeta (WhatsApp Cloud API)The platform that actually delivers WhatsApp messages to your customers. You need a Meta Business account to use it.Message TemplatesPre-written message formats that Meta approves before you can send them. You create these in Meta, then use them in Cart Abandonment Recovery.Cart Abandonment Recovery​Cart Abandonment Pro PluginDetects when someone leaves without buying, and triggers your approved WhatsApp templates automatically.Customer Phone ConsentWhatsApp legally requires customers to opt in before you message them. This is captured at checkout.\n\n\n\nTime EstimateThe setup has two sides: (1) Setting up your Meta/WhatsApp account and creating message templates, and (2) Connecting those templates to Cart Abandonment RecoCart Abandonment Recovery​. Plan for 30–60 minutes for your first-time setup.\n\n\n\n1. Prerequisites\n\n\n\nMake sure you have all of the following ready. Missing any one of these will block the setup.\n\n\n\n\nCart Abandonment Recovery Pro - an active Pro license is required. The WhatsApp feature is not available in the free version.\n\n\n\nMeta (Facebook) Business Account - if you don\'t have one, create it at business.facebook.com.\n\n\n\nWhatsApp Business Account - must be linked to your Meta Business account.\n\n\n\nA verified phone number - added to your WhatsApp Business account. This is the sender number your customers will see.\n\n\n\nAt least one approved message template - you\'ll create this in Meta Business Manager. Templates must be approved before Cart Abandonment Recovery can use them.\n\n\n\nPhone Number and Phone Consent fields - must be enabled on your WooCommerce checkout page (covered in Step 3).\n\n\n\n\n2. Setting Up Your Meta WhatsApp Account\n\n\n\nThis is the most technical part of the setup. Follow each sub-step carefully - you\'ll be collecting three pieces of information you\'ll need later: a Phone Number ID, a WhatsApp Business Account ID, and an Access Token.\n\n\n\n2A. Create a Meta Developer App\n\n\n\n\nLog in at Meta for Developers.\n\n\n\nNavigate to My Apps &gt; Create App.\n\n\n\nSelect Business as the app type.\n\n\n\nGive your app a name (e.g., \"My Store WhatsApp\"), then click Create App.\n\n\n\nAfter creation, click Add Product &gt; WhatsApp &gt; Set Up.\n\n\n\n\n2B. Retrieve Phone Number ID and WhatsApp Business Account ID\n\n\n\n\nGo to WhatsApp &gt; Getting Started in your app.\n\n\n\nCopy and save somewhere safe the Phone Number ID and WhatsApp Business Account ID.\n\n\n\n\n2C. Create a Permanent Access Token\n\n\n\nImportant\nWhy \"permanent\"? Temporary tokens expire and will break your WhatsApp messages silently. Always generate a token set to \"Never\" expire.\n\n\n\n\n\nVisit Meta Business Suite &gt; Settings &gt; Business Settings &gt; Users &gt; System Users.\n\n\n\nCreate a new system user (e.g., “WhatsApp Bot”) with Admin role.\n\n\n\nAdd your app as an asset with Full Control.\n\n\n\nGenerate a new token with permissions: whatsapp_business_messaging and whatsapp_business_management.\n\n\n\nSet expiration to Never and copy the token immediately - Meta only shows it once. Store it securely.\n\n\n\n\n2D. Create a WhatsApp Message Template\n\n\n\nMessage templates are the pre-approved messages Meta allows you to send. You must create and get at least one approved before Cart Abandonment Recovery can send any messages.\n\n\n\n\nGo to Meta Business Suite &gt; Account Tools &gt; Message Templates (or search for \"Message Templates\" in the search bar).\n\n\n\nClick Create Template, choose Marketing (for promotional messages with discounts) or Utility (for transactional/recovery messages).\n\n\n\nAdd a name (e.g., cart_recovery_reminder) and select the language.\n\n\n\nBuild your template:\n\nHeader (optional): A short title or image shown at the top of the message.\n\n\n\nBody (required): The main message. Use {{1}}, {{2}} etc. as placeholders for dynamic content like customer name, cart total, or recovery link.\n\n\n\nButtons (optional): You can add a \"Complete Purchase\" button that links to the cart recovery URL.\n\n\n\n\n\nSubmit for approval. Approval usually takes a few minutes to a few hours.\n\n\n\n\nImportant\nOnly Approved templates will appear in Cart Abandonment Recovery. If your template shows as Pending or Rejected, it won\'t show up in the plugin dropdown. Check your template status in Meta Business Manager before continuing.\n\n\n\n\n3. Enable Phone &amp; Consent Fields on Your Checkout\n\n\n\nWhatsApp messages can only be sent to customers who provided their phone number AND explicitly agreed to receive WhatsApp messages at checkout. This is a legal requirement.\n\n\n\n1. In your WordPress admin, go to WooCommerce &gt; Cart Abandonment Recovery &gt; Settings.2. Find the GDPR options and make sure both Phone Number and Phone Consent (GDPR opt-in checkbox) are enabled.\n\n\n\n\n\n\n\n3. These fields will now appear on your Checkout page - customers must fill them in and check the box for WhatsApp messages to be sent to them.\n\n\n\n\n\n\n\nNote:\nCustomers who don\'t check the consent box will never receive WhatsApp messages - even if they provide a phone number. This is by design to stay compliant with messaging regulations.\n\n\n\n\n4. Configure Global WhatsApp Settings\n\n\n\nNow you\'ll connect the Meta credentials you collected earlier to the Cart Abandonment Recovery plugin.\n\n\n\nNavigate to: WooCommerce &gt; Cart Abandonment Recovery &gt; Settings &gt; Integrations &gt; WhatsApp\n\n\n\n\n\n\n\n1. Enable WhatsApp - Toggle to activate the feature (default: off).2. Phone Number ID - Enter the Phone Number ID from Meta Developer App you saved in the earlier step.3. WhatsApp Business Account ID - Enter your WABA ID from Meta Developer App you saved in the earlier step.4. Access Token - Enter the permanent token created earlier.5. WhatsApp Template - Select an approved template from Meta. Use the refresh button to fetch updates.6. Map Variables - for Header and Body placeholders (e.g., {{1}}, {{2}}), select which Cart Abandonment Recovery data should fill each one:\n\n\n\nAvailable VariableWhat It InsertsCustomer First NameThe first name from the checkout billing fieldsCustomer Last NameThe last name from the checkout billing fieldsCart TotalThe total value of the abandoned cartCoupon CodeA discount coupon if configured on the templateCart Recovery URLThe unique link that restores the customer\'s cart\n\n\n\n7. Test WhatsApp Message - use this to send a test message to your own phone number and verify the integration works before going live.\n\n\n\n5. WhatsApp Follow-up Templates\n\n\n\nThis is where you define when and how many WhatsApp messages to send after a cart is abandoned. You can create multiple templates with different time delays - for example, a gentle reminder at 1 hour and a discount offer at 24 hours.\n\n\n\nNavigate to: WooCommerce &gt; Cart Abandonment Recovery &gt; Follow Up Templates &gt; WhatsApp\n\n\n\n\n\n\n\n\nClick Create New Template to create your first followup.\n\n\n\nTemplate Name - this is just an internal label for your reference (e.g., \"1-hour reminder\").\n\n\n\nWhatsApp Template - choose an approved Meta template from the dropdown.\n\n\n\nMap Variables - same as in Step 4: assign Cart Abandonment Recovery data to each placeholder in the template.\n\n\n\nSend This Message  - choose how long after abandonment the message should be sent (e.g., 60 minutes, 24 hours).\n\n\n\nCreate Coupon Code (optional) - attach a discount coupon to this template if you want to incentivize purchase.\n\n\n\nActivate Template - turn this on when you\'re ready for it to go live. Inactive templates are saved but don\'t send.\n\n\n\nRepeat to add more followup messages at different delays.\n\n\n\n\n\n\n\n\n6. Test Before Going Live\n\n\n\nBefore real customers see your messages, test the full flow:\n\n\n\n\nOpen your store in an incognito/private browser window.\n\n\n\nAdd a product to cart and go to Checkout page.\n\n\n\nFill in your own name, email, and real phone number (in international format, e.g., +919876543210).\n\n\n\nCheck the WhatsApp consent checkbox.\n\n\n\nClose the browser tab without completing the purchase.\n\n\n\nWait for the time delay you set on your first template to pass.\n\n\n\nCheck your WhatsApp - you should receive the message.\n\n\n\n\nPhone Format:\nPhone number format matters! The number must include the country code (e.g., +91 for India, +1 for US). Cart Abandonment Recovery tries to auto-add this based on billing country, but asking customers to enter their full number including country code is safest.\n\n\n\n\n7. Unsubscribe / Opt-Out\n\n\n\nCustomers who unsubscribe from one channel (WhatsApp, SMS, or email) are unsubscribed from all recovery messages for that abandoned cart session. You don\'t need to manage this separately per channel.\n\n\n\n8. Troubleshooting - Common Problems &amp; Fixes\n\n\n\n8A: Template dropdown is empty\n\n\n\n\nCheck credentials - Make sure Phone Number ID, Business Account ID, and Access Token are all saved in Settings.\n\n\n\nClick Refresh - Use the refresh button next to the template dropdown to fetch from Meta.\n\n\n\nCheck template status - Only templates with Approved status in Meta Business Manager appear here. Pending or Rejected templates are excluded.\n\n\n\n\n8B:Test message works, but live messages aren\'t sending\n\n\n\n\nToggle check - Confirm the WhatsApp Enable toggle is turned ON in global settings.\n\n\n\nTemplate activation - Make sure at least one followup template has \"Activate Template\" turned on.\n\n\n\nCustomer consent - The customer must have checked the phone consent checkbox at checkout. Without it, no message is sent - even if a phone number was entered.\n\n\n\n\n8C: Customer didn\'t receive the message\n\n\n\n\nPhone number format - Must include country code (e.g., +91XXXXXXXXXX, +1XXXXXXXXXX). Missing the country code will cause silent delivery failure.\n\n\n\nNo consent given - Customer didn\'t check the consent checkbox at checkout.\n\n\n\nWhatsApp not installed - The customer\'s phone number must be registered and active on WhatsApp. If they don\'t have the app, delivery fails.\n\n\n\nTemplate status changed - If the Meta template was edited or rejected after being selected in the plugin, messages will stop working. Re-check the template\'s status in Meta.\n\n\n\n\n8D: Access token expired or became invalid\n\n\n\n\nGo back to Meta Business Suite &gt; Settings &gt; Business Settings &gt; Users &gt; System Users and regenerate a new token with the same permissions.\n\n\n\nUpdate the token in Cart Abandonment Recovery &gt; Integrations &gt; WhatsApp and save.\n\n\n\nSend a test message to confirm it works again.\n\n\n\n\n9. Frequently Asked Questions\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nWhat You Need to DoWhere to GoEnable WhatsApp &amp; enter credentialsWooCommerce &gt; Cart Abandonment Recovery &gt; Settings &gt; Integrations &gt; WhatsAppCreate / manage followup templatesWooCommerce &gt; Cart Abandonment Recovery &gt; WhatsAppEnable phone &amp; consent fieldsWooCommerce &gt; Cart Abandonment Recovery &gt; SettingsCreate / manage message templatesMeta Business Suite &gt; Account Tools &gt; Message TemplatesGenerate / renew access tokenMeta Business Suite &gt; Settings &gt; System UsersFind Phone Number ID &amp; WABA IDMeta Developer App &gt; WhatsApp &gt; Getting Started\";s:3:\"url\";s:78:\"https://cartflows.com/docs/whatsapp-integration-for-cart-abandonment-recovery/\";s:4:\"slug\";s:50:\"whatsapp-integration-for-cart-abandonment-recovery\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-10T11:40:17+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:66;O:8:\"stdClass\":8:{s:2:\"id\";i:67322;s:5:\"title\";s:38:\"How to Edit and Customise Funnel Steps\";s:7:\"content\";s:4917:\"This documentation provides an overview of the general step controls and the available settings inside each funnel step type in CartFlows.\n\n\n\nEach step includes action controls and dedicated configuration tabs depending on its function within the funnel.\n\n\n\n1. General Step Actions (Available on Every Step)\n\n\n\nOn the right side of every funnel step, you will see four action options:\n\n\n\nView StepOpens the step on the frontend to preview how it appears to users.\n\n\n\nEdit StepOpens the step inside the page builder or editor to modify its design and content.\n\n\n\nSettingsOpens the step configuration panel where you can manage products, behavior, scripts, and advanced options.\n\n\n\nMore OptionsProvides additional actions such as:\n\n\n\n\nDuplicate Step\n\n\n\nA/B Test (Pro)\n\n\n\nDelete Step\n\n\n\n\n\n\n\n\nThese options help you manage and organize your funnel efficiently.\n\n\n\nThe Settings option is where most functional customization takes place. The available tabs inside the Settings panel depend on the type of step.\n\n\n\n2. Landing Step\n\n\n\nThe Landing step is typically used to present your offer before sending users to checkout. It does not process payments. When you click Settings on a Landing step, a settings panel appears with configuration options specific to that step.\n\n\n\nSettings Tab\n\n\n\nStep SlugDefines the URL path of the landing page.\n\n\n\nCustom CSS/ScriptsAllows adding custom CSS, custom JavaScript or tracking scripts specific to this step.\n\n\n\n\n\n\n\n3. Checkout Step\n\n\n\nThe Checkout step processes payments and finalizes purchases. It includes multiple configuration tabs. Clicking Settings on the Checkout step opens several tabs that control products, checkout layout, conditional logic, and advanced behavior.\n\n\n\nProducts\n\n\n\nProductsAssign WooCommerce products to this checkout step. Here is Doc for the step by step guide.\n\n\n\nAuto Apply CouponAutomatically applies a selected coupon when customers land on the checkout page.\n\n\n\nProduct OptionsControls how products are displayed and selected at checkout. You can refer to this related Doc\n\n\n\n\n\n\n\nOrder Bumps\n\n\n\nTurn your checkout into a powerful upsell moment. Add an order bump offer directly on the checkout page and let customers add it with a single click. No friction, no redirects.\n\n\n\nIn this section, you can:\n\n\n\n\nEnable or disable the bump anytime\n\n\n\nSelect the product you want to offer\n\n\n\nCustomize the headline, description, layout, and overall design\n\n\n\n\nRefer to the Order Bump documentation for detailed setup instructions.\n\n\n\n\n\n\n\nCheckout Form\n\n\n\nDesign your checkout form to work best for your store. Improve clarity, reduce friction, and create a smoother buying experience.\n\n\n\nWith this section, you can:\n\n\n\n\nModify checkout fields (add, remove, or edit)\n\n\n\nCustomize the field layout and positioning\n\n\n\nAdjust and organize form sections\n\n\n\n\nNeed step by step guidance? Check this documentation.\n\n\n\n\n\n\n\nDynamic Offers\n\n\n\nSend customers to the right offer at the right time with rule-based conditional redirection. Show different upsell or downsell steps based on what they buy and how they behave.\n\n\n\nWith dynamic offers, you can:\n\n\n\n\nCreate multiple rule groups\n\n\n\nDefine specific conditions\n\n\n\nDynamically redirect customers to relevant upsell/downsell steps\n\n\n\n\nNeed help? Check this documentation.\n\n\n\n\n\n\n\nSettings\n\n\n\nAdvanced Section\n\n\n\nDisplay Product ImagesShows or hides product images in the order summary.\n\n\n\nEnable Cart Editing on CheckoutAllows customers to remove cart items directly on the checkout page.\n\n\n\nEnable Browser Tab AnimationAdds attention-grabbing animation to the browser tab.\n\n\n\n\n\n\n\nGeneral Section\n\n\n\nStep SlugDefines the URL path of the checkout step.\n\n\n\nCustom CSS/ScriptAdds custom CSS, tracking or custom JavaScript specific to this step.\n\n\n\n\n\n\n\n4. Thank You Step\n\n\n\nDisplayed after successful order completion. Clicking Settings opens configuration options for controlling what information is displayed and what happens after purchase.\n\n\n\nSettings\n\n\n\nOptions Section\n\n\n\nEnable Order OverviewDisplays a summary of purchased items.\n\n\n\nEnable Order DetailsShows full order breakdown.\n\n\n\nEnable Billing DetailsDisplays billing information.\n\n\n\nEnable Shipping DetailsDisplays shipping information (if applicable).\n\n\n\n\n\n\n\nAdvanced Section\n\n\n\nThank You Page TextCustomize the confirmation message shown to customers.\n\n\n\nRedirect After PurchaseRedirect customers to a different URL after the Thank You page loads.\n\n\n\n\n\n\n\nGeneral Section\n\n\n\nStep SlugDefines the URL path of the step.\n\n\n\nCustom CSS/ScriptAdd step-specific scripts or tracking code.\n\n\n\n\n\n\n\n5. Upsell/Downsell Steps\n\n\n\nThe Upsell/Downsell step allows you to offer an additional product immediately after checkout using one-click purchase functionality. When you click Settings, you can configure the offer product and its behavior.\n\n\n\nRefer to this documentation for more detail about Upsell: How to Create One-Click Upsell and Downsell Offers in CartFlows\";s:3:\"url\";s:64:\"https://cartflows.com/docs/editing-and-customising-funnel-steps/\";s:4:\"slug\";s:36:\"editing-and-customising-funnel-steps\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-08T16:03:42+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"getting-started\";}}i:67;O:8:\"stdClass\":8:{s:2:\"id\";i:67314;s:5:\"title\";s:63:\"How to Create One-Click Upsell and Downsell Offers in CartFlows\";s:7:\"content\";s:1535:\"Creating one-click upsell and downsell offers in CartFlows (Pro) allows you to present additional products to customers immediately after checkout without requiring them to re-enter payment information. This method helps increase your average order value (AOV) by giving users an easy way to accept extra offers.\n\n\n\nStep 1: Create or Edit a Funnel\n\n\n\nNavigate to CartFlows &gt; Funnels in your WordPress dashboard. Select an existing funnel or click Add New to start a fresh funnel.\n\n\n\n\n\n\n\nStep 2: Add Upsell/Downsell Step\n\n\n\nWithin your selected funnel, click Add New Step and choose Upsell or Downsell from the available step types.\n\n\n\n\n\n\n\nStep 3: Position the Step\n\n\n\nEnsure the new Upsell or Downsell step is placed after the Checkout step and before the Thank You page.\n\n\n\nStep 4: Assign Products\n\n\n\nClick on the settings icon on the upsell step. Under the Products tab, assign the specific product you want to offer for upsell or downsell.\n\n\n\n\n\n\n\n\n\n\n\nStep 5: Configure the Conditional Redirection\n\n\n\nUnder Settings Tab ,Configure the conditional redirection to direct customers who decline the upsell to either a downsell page (if applicable) or the final Thank You page.\n\n\n\n\n\n\n\nStep 6: Use a Supported Payment Gateway\n\n\n\nEnsure your WooCommerce store uses a payment gateway that supports Upsell/Downsell, to allow seamless purchases.\n\n\n\nStep 7: Save and Publish\n\n\n\nSave your changes and publish the flow. Test the upsell and downsell steps to confirm that accepting or declining the offers works correctly and updates the order.\";s:3:\"url\";s:66:\"https://cartflows.com/docs/create-oneclick-upsell-downsell-offers/\";s:4:\"slug\";s:38:\"create-oneclick-upsell-downsell-offers\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-12T20:15:51+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"getting-started\";}}i:68;O:8:\"stdClass\":8:{s:2:\"id\";i:67274;s:5:\"title\";s:34:\"How to Add Products in WooCommerce\";s:7:\"content\";s:3090:\"This documentation explains how to add products in WooCommerce using the WordPress dashboard. WooCommerce supports different product types, allowing you to sell physical products, digital items, services, and grouped products based on your store requirements.\n\n\n\nBefore You Start\n\n\n\nMake sure WooCommerce is installed and activated on your WordPress site. You also need sufficient permissions to create and manage products.\n\n\n\nAccess the Add Product Screen\n\n\n\nTo create a new product: \n\n\n\n1. o to WordPress Dashboard > Products > Add New\n\n\n\n\n\n\n\n2. Enter the product name\n\n\n\n3. Add the product description\n\n\n\n\n\n\n\nYou can now configure the product using the Product data panel.\n\n\n\nWooCommerce Product Types\n\n\n\nWooCommerce supports several product types. This documentation covers the most commonly used ones.\n\n\n\n\nSimple product\n\n\n\nGrouped product\n\n\n\nVariable product\n\n\n\nVirtual product\n\n\n\n\nAdd a Simple Product in WooCommerce\n\n\n\nA Simple product is a single product without variations. This is the most commonly used product type.\n\n\n\n\nFrom the Product data dropdown, select Simple product\n\n\n\nSet the regular price and optional sale price\n\n\n\nConfigure inventory, shipping, and tax settings if required\n\n\n\nAdd a product image and optional gallery\n\n\n\nClick Publish\n\n\n\n\n\n\n\n\nAdd a Grouped Product in WooCommerce\n\n\n\nA Grouped product lets you display multiple related products together on a single product page.\n\n\n\n\nSelect Grouped product from the Product data dropdown\n\n\n\nLeave pricing fields empty\n\n\n\nOpen the Linked Products tab\n\n\n\nSelect the products you want to include\n\n\n\nPublish the product\n\n\n\n\n\n\n\n\nAdd a Variable Product in WooCommerce\n\n\n\nA Variable product allows you to offer different variations of the same product, such as size or color.\n\n\n\nBecause variable products require additional configuration, please refer to the dedicated documentation below:\n\n\n\nHow to Add a Variable Product in WooCommercehttps://cartflows.com/docs/creating-variable-products/\n\n\n\nAdd a Virtual Product in WooCommerce\n\n\n\nA Virtual product is used for items that do not require shipping, such as services or digital offerings.\n\n\n\n\nSelect Simple product from the Product data dropdown\n\n\n\nEnable the Virtual option\n\n\n\nConfigure pricing and relevant settings\n\n\n\nAdd a product image and optional gallery\n\n\n\nPublish the product\n\n\n\n\n\n\n\n\nWhen the Virtual option is enabled, shipping related settings are automatically disabled.\n\n\n\nAdditional Product Settings\n\n\n\nDepending on the product type, you may also configure the following settings:\n\n\n\n\nInventory and stock status\n\n\n\nLinked products such as upsells and cross sells\n\n\n\nProduct categories and tags\n\n\n\nShort description shown on the product page\n\n\n\n\nPublish the Product\n\n\n\nOnce all required details are set, click Publish to make the product live. You can update or edit the product at any time from Products &gt; All Products.\n\n\n\nLearn More About WooCommerce Products\n\n\n\nFor a complete explanation of all product options and advanced configurations, refer to the official WooCommerce documentation: https://woocommerce.com/document/managing-products/add-product/\";s:3:\"url\";s:62:\"https://cartflows.com/docs/how-to-add-products-in-woocommerce/\";s:4:\"slug\";s:34:\"how-to-add-products-in-woocommerce\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-02-05T14:00:20+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:69;O:8:\"stdClass\":8:{s:2:\"id\";i:67249;s:5:\"title\";s:59:\"How to Add /Assign Products to a Checkout Step in CartFlows\";s:7:\"content\";s:2738:\"Adding or assigning products to a checkout step in CartFlows allows you to define exactly what customers will purchase during the funnel flow. You can add single or multiple products, set default selections, enable variations, and even control quantity options — all directly from the checkout step settings.\n\n\n\nStep-by-Step: Add Products to a CartFlows Checkout Step\n\n\n\nStep 1: Open the Funnel Checkout Step\n\n\n\nNavigate to CartFlows &gt; Funnels from your WordPress dashboard.\n\n\n\n\n\n\n\nOpen the funnel you want to edit and click the Edit (gear icon) on the Checkout step.\n\n\n\n\n\n\n\nStep 2: Access the Products Tab\n\n\n\nIn the checkout step editor, go to the Products tab.\n\n\n\nClick on + Add New Product to begin.\n\n\n\nStep 3: Add Products to the Checkout\n\n\n\nUse the search field to find your WooCommerce product.\n\n\n\nSelect the product and click Add.\n\n\n\n\n\n\n\nYou can repeat this process to add multiple products to the same checkout step.\n\n\n\nNot sure how to create products in WooCommerce? Check this guide.\n\n\n\nConfigure Product Options (Optional)\n\n\n\nOnce a product is added, you can further customize how it appears and behaves on the checkout page:\n\n\n\n\nVariable Products: If you’ve added a variable product, enable the Variation option to display variation choices (such as size or color) directly on the checkout page.\n\n\n\nSet Default Product: When multiple products are added, you can choose one as the default selection by enabling the radio button next to it in the Product Options section.\n\n\n\nQuantity Selector: Enable the quantity option to allow customers to adjust product quantity directly on the checkout page.\n\n\n\n\n\n\n\n\nStep 4: Save Your Changes\n\n\n\nAfter configuring your products and options, click Save Settings to apply the changes to the checkout step.\n\n\n\nAlternative Ways to Add Products to a Checkout\n\n\n\nCartFlows also provides additional methods to assign products to a checkout step:\n\n\n\nAdd Products via URL Parameter\n\n\n\nYou can dynamically add products to the checkout using a URL parameter such as:\n\n\n\nhttps:&#47;&#47;yourdomain.com/checkout-page/?wcf-add-to-cart=3&amp;wcf-qty=4\n\n\n\nThis is useful for targeted campaigns or custom links. Here is the Doc for further details\n\n\n\nAssign Product from WooCommerce Product Page\n\n\n\nFrom the WooCommerce product edit screen, use the CartFlows tab to force the product to start a specific funnel. This automatically adds the product to the checkout step when the funnel starts.\n\n\n\nImportant Notes\n\n\n\n\nIf you see the error “No product is selected”, make sure at least one product is assigned in the Backend Settings of the checkout step.\n\n\n\nFor subscription products, ensure the WooCommerce Subscriptions plugin is installed and active before assigning the product to the checkout.\";s:3:\"url\";s:86:\"https://cartflows.com/docs/how-to-add-assign-products-to-a-checkout-step-in-cartflows/\";s:4:\"slug\";s:58:\"how-to-add-assign-products-to-a-checkout-step-in-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-12T19:41:58+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"getting-started\";}}i:70;O:8:\"stdClass\":8:{s:2:\"id\";i:67240;s:5:\"title\";s:41:\"How to Create Your First CartFlows Funnel\";s:7:\"content\";s:2800:\"Creating your first funnel with CartFlows is straightforward and helps you guide customers through a smooth buying journey. By using pre-made templates and connecting your WooCommerce products, you can quickly set up an optimized sales funnel.\n\n\n\nStep 1: Install and Activate CartFlows\n\n\n\nInstall the CartFlows plugin from your WordPress dashboard. After activation, choose your preferred page builder in the settings, such as Block Editor, Elementor or Beaver Builder, for designing your funnel steps.\n\n\n\nStep 2: Create a New Funnel\n\n\n\nNavigate to CartFlows > Dashboard and click Create New Funnel to start creating a new funnel.\n\n\n\n\n\n\n\nStep 3: Select a Template\n\n\n\nPick a pre-made template that matches your goal, such as Sales or Lead Generation. These templates typically include:\n\n\n\n\nSales Landing Page\n\n\n\nCheckout Page\n\n\n\nThank You Page\n\n\n\n\nIf you prefer full control over the structure and design, you can also create a blank funnel by choosing Start from Scratch and build each step according to your specific requirements.\n\n\n\n\n\n\n\nStep 4: Configure the Funnel Steps\n\n\n\nCustomize Each Step\n\n\n\nClick the pencil icon to edit each page using your page builder. Adjust the design to match your brand and style. \n\n\n\nCartFlows also provides Instant Layouts for a faster setup with pre-designed, conversion-focused designs. To learn how to use Instant Layouts, refer to the documentation below: https://cartflows.com/docs/cartflows-instant-layout/\n\n\n\n\n\n\n\nAdd a Product\n\n\n\nIn the Checkout step, select the WooCommerce product you want to sell and save settings\n\n\n\n\n\n\n\nConfigure Checkout Fields\n\n\n\nModify the checkout fields to suit your product. For example, remove unnecessary shipping fields for digital products.\n\n\n\n\n\n\n\nStep 5: Save and Publish\n\n\n\nOnce all steps are configured, click Publish to make your funnel live.\n\n\n\n\n\n\n\nKey Tips for Success\n\n\n\n\nKeep it Simple: Maintain a clean, concise checkout page to reduce friction.\n\n\n\nTest Everything: Test the full checkout process to ensure it works smoothly before launch.\n\n\n\n\nIncrease Conversions with Additional Offers\n\n\n\nYou can further optimize your funnel by adding post-purchase and in-checkout offers.\n\n\n\nAdd an Order Bump\n\n\n\nAn Order Bump is a small complementary offer displayed on the checkout page. It helps increase your average order value by allowing customers to add an extra product with a single click.\n\n\n\nTo learn more about creating an Order Bump, refer to this document. \n\n\n\nAdd Upsell / Downsell Offers\n\n\n\nAn Upsell is a higher-value offer shown after the initial purchase, while a Downsell is an alternative offer presented if the customer declines the upsell. These help maximize revenue without interrupting the checkout experience.\n\n\n\nTo learn more about creating one-click Upsell and Downsell offers, refer to this document.\";s:3:\"url\";s:69:\"https://cartflows.com/docs/how-to-create-your-first-cartflows-funnel/\";s:4:\"slug\";s:41:\"how-to-create-your-first-cartflows-funnel\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-12T21:02:36+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"getting-started\";}}i:71;O:8:\"stdClass\":8:{s:2:\"id\";i:67140;s:5:\"title\";s:28:\"CartFlows Advanced Analytics\";s:7:\"content\";s:5217:\"CartFlows Advanced Analytics provides detailed insights into how your funnels perform by tracking visitors, conversions, revenue, and opt-ins. It presents this data through key performance indicators (KPIs), visual charts, and structured tables, making it easier to understand funnel performance and identify areas for improvement.\n\n\n\nThe Analytics Dashboard is organised into dedicated sections that focus on different aspects of funnel performance, including Funnels, Conversions, and Opt-ins.\n\n\n\nNote\nAdvanced Analytics requires version 2.2.0 or higher of both CartFlows Free and Pro.\n\n\n\n\nHow CartFlows Advanced Analytics Works\n\n\n\nCartFlows Advanced Analytics automatically collects and organises performance data across your funnels. This data is displayed in dashboards that combine KPIs, trend charts, and detailed tables so you can review performance at both a high level and a detailed level.\n\n\n\nYou can use these insights to evaluate funnel effectiveness, understand user behaviour, and make informed decisions based on real data.\n\n\n\nAnalytics Overview\n\n\n\nThe Analytics section includes three reporting pages, each focused on a specific area of funnel performance.\n\n\n\n\nFunnel Analytics\n\n\n\nConversions Analytics\n\n\n\nOpt-in Analytics\n\n\n\n\nTogether, these pages provide a complete view of how visitors interact with your funnels and where conversions and revenue are generated.\n\n\n\nAvailable KPIs\n\n\n\nTotal VisitorsTotal number of visitors across all steps in the funnel\n\n\n\nTotal OrdersTotal number of successful orders generated by the funnel\n\n\n\nTotal RevenueCombined revenue generated across all funnel steps\n\n\n\nAverage Order ValueAverage revenue generated per order\n\n\n\nOrder Bump RevenueTotal revenue generated from order bump offers\n\n\n\nOffer RevenueCombined revenue generated from upsell and downsell offers\n\n\n\nRevenue Per VisitAverage revenue generated per visit\n\n\n\nRevenue Per Unique VisitorAverage revenue generated per unique visitor\n\n\n\nEach KPI includes a visual chart that helps you track performance trends over time.\n\n\n\n\n\n\n\nAdditional Funnel Data\n\n\n\nThe Funnel Analytics page also includes a table that displays funnel level metrics such as visits, conversions, conversion rate, and revenue across all funnels.\n\n\n\n\n\n\n\nConversions Analytics\n\n\n\nThe Conversions Analytics page focuses on how users convert across funnel steps, offers, and devices.\n\n\n\nAvailable KPIs\n\n\n\nTotal VisitorsTotal number of visitors across all steps in the selected funnel or funnels\n\n\n\nTotal ConversionsTotal number of successful conversions across all steps\n\n\n\nOrder Bump ConversionsNumber of successful order bump purchases\n\n\n\nOffer ConversionsTotal number of successful upsell and downsell conversions\n\n\n\nLaptop ConversionsConversions completed on laptop and desktop devices\n\n\n\nMobile ConversionsConversions completed on mobile devices\n\n\n\nEach KPI includes a chart that allows you to analyse conversion trends over time.\n\n\n\n\n\n\n\nAdditional Conversion Data\n\n\n\nThis page includes two tables for deeper analysis.\n\n\n\nStep-level analytics table for the selected funnel\n\n\n\n\n\n\n\nProduct-level analytics table for products associated with funnel steps\n\n\n\n\n\n\n\nOpt-in Analytics\n\n\n\nThe Opt-in Analytics page provides insights into opt-in form performance across your funnels.\n\n\n\nAvailable KPIs\n\n\n\nTotal SubmissionsTotal number of successful opt-in form submissions\n\n\n\nConversion RatePercentage of visitors who successfully submitted the opt-in form\n\n\n\nEach KPI is supported by visual charts to help identify trends.\n\n\n\n\n\n\n\nAdditional Opt-in Data\n\n\n\nThe Opt-in Analytics table displays funnel name, opt-in step, total submissions, and conversion rate.\n\n\n\n\n\n\n\nFilters and Comparison Options\n\n\n\nEach Analytics page includes filtering and comparison options to help refine your analysis.\n\n\n\nTimeframe filterView data for predefined ranges such as Today, Yesterday, Last 7 Days, This Month, or a custom date range\n\n\n\nFunnel selectorView analytics for all funnels or a specific funnel\n\n\n\nTrend comparisonCompare the selected timeframe with the previous period or the same period in the previous year\n\n\n\n\n\n\n\nTrend Indicators\n\n\n\nEach KPI includes a trend indicator that shows how performance has changed over time.\n\n\n\nTrend indicators compare the current data with:\n\n\n\n\nthe previous period\n\n\n\nthe same period from the previous year\n\n\n\n\n\n\n\n\nThis makes it easier to identify growth, declines, and performance shifts at a glance.\n\n\n\nTop Performing Funnels (Dashboard Overview)\n\n\n\nThe Analytics Dashboard includes a Top Performing Funnels table that highlights the top five funnels based on revenue. This provides a quick overview of which funnels contribute most to overall performance.\n\n\n\n\n\n\n\nFunnel Editor KPIs\n\n\n\nKey performance indicators are also available directly in the Funnel Editor. This allows you to review funnel performance while building or editing funnels, without switching to the Analytics pages.\n\n\n\nAvailable KPIs in the Funnel Editor\n\n\n\n\nTotal Visitors\n\n\n\nTotal Orders\n\n\n\nTotal Revenue\n\n\n\nAverage Order Value (AOV)\n\n\n\nOrder Bump Revenue\n\n\n\nOffer Revenue\n\n\n\nRevenue Per Visit (RPV)\n\n\n\nRevenue Per Unique Visitor (RPUV)\n\n\n\n\nThese KPIs help you quickly assess funnel performance and make optimisation decisions during funnel creation.\";s:3:\"url\";s:56:\"https://cartflows.com/docs/cartflows-advanced-analytics/\";s:4:\"slug\";s:28:\"cartflows-advanced-analytics\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-04-24T16:44:58+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"flows-analytics\";}}i:72;O:8:\"stdClass\":8:{s:2:\"id\";i:67094;s:5:\"title\";s:31:\"Power Coupons Settings Overview\";s:7:\"content\";s:2506:\"Power Coupons is a WooCommerce enhancement plugin that helps increase coupon visibility and usage directly on your Cart and Checkout pages. By displaying available coupons in a clear and engaging way, it encourages customers to apply discounts, improving both their shopping experience and your store conversions.\n\n\n\nHow to Access Power Coupons Settings\n\n\n\n\nLog in to your WordPress admin dashboard.\n\n\n\nNavigate to Dashboard > Power Coupons > Settings\n\n\n\n\nThe settings are divided into three main sections for easier management:\n\n\n\n\nGeneral\n\n\n\nCoupon Styling\n\n\n\nText Customization\n\n\n\n\nGeneral Settings\n\n\n\nThese options control the overall behavior of Power Coupons across your site.\n\n\n\n1. Enable Plugin\n\n\n\nToggle this option to enable or disable Power Coupons functionality site-wide.\n\n\n\n2. Show on Cart\n\n\n\nDisplays available coupons on the Cart page so customers can easily view discounts before proceeding to checkout.\n\n\n\n3. Show on Checkout\n\n\n\nDisplays available coupons on the Checkout page to encourage last-minute coupon usage.\n\n\n\n4. Enable for Guests\n\n\n\nAllows visitors who are not logged in to view and apply coupons, helping to increase conversions.\n\n\n\n5. Show Applied Coupons\n\n\n\nDisplays a list of coupons that have already been applied, so customers can track discounts in real-time.\n\n\n\n6. Show Expiry Info\n\n\n\nShows coupon expiry dates, creating urgency and driving faster conversions.\n\n\n\nCoupon Styling Settings\n\n\n\nThis section lets you control the visual presentation of your coupons.\n\n\n\nChoose Coupon Styling\n\n\n\nSelect from available coupon design templates to match your store’s branding.\n\n\n\nText Customization Settings\n\n\n\nCustomize all customer-facing text for coupons to match your store’s tone and messaging.\n\n\n\n1. Drawer Heading\n\n\n\nText displayed at the top of the coupon drawer. Example: Available Coupons\n\n\n\n\n\n\n\n2. Drawer Trigger Button Label\n\n\n\nText shown on the button that opens the coupon drawer. Example: View Available Coupons\n\n\n\n\n\n\n\n3. Coupon Applying Text\n\n\n\nText shown while a coupon is in the process of being applied. Example: Applying...\n\n\n\n\n\n\n\n4. Coupon Applied Text\n\n\n\nText displayed after a coupon is successfully applied. Example: Applied\n\n\n\n\n\n\n\n5. No Coupons Text\n\n\n\nMessage displayed when no valid coupons are available. Example: No coupons available at this time.\n\n\n\n\n\n\n\n6. Coupons Loading Text\n\n\n\nText displayed while coupons are being fetched inside the drawer. Example: Loading coupons...\n\n\n\n\n\n\n\nThis helpful for setting user expectations during AJAX loading.\";s:3:\"url\";s:59:\"https://cartflows.com/docs/power-coupons-settings-overview/\";s:4:\"slug\";s:31:\"power-coupons-settings-overview\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-02-12T10:46:55+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"power-coupons\";}}i:73;O:8:\"stdClass\":8:{s:2:\"id\";i:67089;s:5:\"title\";s:28:\"How to Install Power Coupons\";s:7:\"content\";s:816:\"This documentation explains how to install the Power Coupons plugin on your WordPress site.\n\n\n\nHow to install Power Coupons\n\n\n\nTo install the Power Coupons plugin on your WordPress site, follow the steps below.\n\n\n\nStep 1: Log in to your WordPress website\n\n\n\nWhen you log in, you will be in your Dashboard.\n\n\n\nStep 2: In the Plugins menu, click on Add New Plugin\n\n\n\nFrom your WordPress dashboard, go to Plugins &gt; Add New Plugin to open the plugin installation screen.\n\n\n\n\n\n\n\nStep 3: Search for Power Coupons\n\n\n\nIn the search bar, search for Power Coupons.\n\n\n\n\n\n\n\nStep 4: Click Install Now\n\n\n\nIn the Power Coupons card, click Install Now.\n\n\n\n\n\n\n\nStep 5: Click Activate\n\n\n\nOnce the installation has finished, click Activate.\n\n\n\n\n\n\n\nYou’ve successfully installed the Power Coupons plugin on your website. Well Done!\";s:3:\"url\";s:56:\"https://cartflows.com/docs/how-to-install-power-coupons/\";s:4:\"slug\";s:28:\"how-to-install-power-coupons\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-15T13:26:43+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"power-coupons\";}}i:74;O:8:\"stdClass\":8:{s:2:\"id\";i:66898;s:5:\"title\";s:45:\"SMS Integration for Cart Abandonment Recovery\";s:7:\"content\";s:4692:\"The SMS Integration is part of the Cart Abandonment Recovery Pro feature and allows you to automatically send SMS follow-ups to users who leave the checkout without completing their purchase. By using Twilio as the SMS provider, this feature helps re‑engage customers with timely reminders, personalized content, recovery links, and optional discount coupons.\n\n\n\nThe SMS recovery flow works alongside existing cart abandonment logic and ensures messages are sent only when a cart is genuinely abandoned and all required conditions, such as consent and product availability, are met.\n\n\n\nOverview\n\n\n\nThe SMS integration enables automated SMS notifications for cart abandonment recovery via Twilio. It includes SMS template management, scheduling, dynamic placeholders, coupon generation, delivery tracking, and built‑in compliance checks.\n\n\n\nThis feature is designed to complement email-based recovery and provides an additional channel to reconnect with potential customers.\n\n\n\nTwilio Integration\n\n\n\nCart Abandonment Recovery uses Twilio as the SMS delivery provider.\n\n\n\nAuthentication Requirements\n\n\n\n\nTwilio Account SID\n\n\n\nTwilio Auth Token\n\n\n\nSend From value (phone number or alphanumeric sender ID in E.164 format)\n\n\n\n\n\n\n\n\nIntegration Settings\n\n\n\nThe SMS integration settings allow you to manage and validate the SMS configuration used for cart recovery:\n\n\n\n\nEnable or disable SMS tracking for abandoned carts\n\n\n\nConfigure the Send From phone number or sender ID\n\n\n\nEnter Twilio Account SID\n\n\n\nEnter Twilio Auth Token (stored securely in encrypted form)\n\n\n\nSend a test SMS to verify the setup\n\n\n\n\n\n\n\n\nThese settings ensure SMS delivery is properly configured before recovery messages are sent to users.\n\n\n\nGDPR Compliance Settings\n\n\n\nTo ensure compliance with privacy regulations, Cart Abandonment Recovery includes dedicated GDPR controls for SMS communication:\n\n\n\n\nPhone number GDPR consent toggle\n\n\n\nCustomizable consent message shown during checkout\n\n\n\nConsent validation before scheduling or sending any SMS\n\n\n\n\n\n\n\n\nSMS follow-ups are only scheduled when explicit consent is available.\n\n\n\nSMS Template Creation &amp; Scheduling\n\n\n\nSMS templates define the content and timing of recovery messages:\n\n\n\n\nCreate, edit, clone, or delete SMS templates\n\n\n\nRestore default SMS templates at any time\n\n\n\nAutomatically trigger SMS when a cart is marked as abandoned\n\n\n\nRespect GDPR consent requirements\n\n\n\nSkip SMS if the user has unsubscribed or the order is completed\n\n\n\nReschedule SMS messages when needed\n\n\n\n\n\n\n\n\n\n\n\n\nTemplates support dynamic placeholders such as customer details, cart data, recovery URLs, and coupon codes.\n\n\n\nPre‑Send Checks\n\n\n\nBefore sending an SMS, Cart Abandonment Recovery performs multiple checks:\n\n\n\n\nOut‑of‑stock product validation\n\n\n\nRule engine evaluation\n\n\n\nFilter hooks for custom logic and conditions\n\n\n\n\nThese checks help ensure recovery messages remain relevant and accurate.\n\n\n\nPreview SMS\n\n\n\nYou can preview and test SMS content before activating templates:\n\n\n\n\nSend a test SMS directly from the template editor\n\n\n\nUses dummy session data for safe previewing\n\n\n\n\n\n\n\n\nThis helps confirm formatting, placeholders, and message tone.\n\n\n\nTest SMS\n\n\n\nA global test option is also available from the integration settings:\n\n\n\n\nSends a test SMS using the configured Twilio credentials\n\n\n\nValidates the complete SMS recovery configuration\n\n\n\n\nPrivacy &amp; Unsubscribe Support\n\n\n\nUser privacy is respected throughout the SMS recovery process:\n\n\n\n\nGDPR consent is required before sending SMS\n\n\n\nBuilt‑in unsubscribe support ensures users can opt out of SMS recovery messages\n\n\n\n\n\n\n\n\nFilter Hooks &amp; Extensibility\n\n\n\nDevelopers can customize and extend Cart Abandonment Recovery SMS behavior using the following hooks.\n\n\n\nAvailable Filters\n\n\n\n\nwcf_ca_should_schedule_sms_template – Control whether an SMS template should be scheduled\n\n\n\nwcf_ca_should_send_sms – Control whether an SMS should be sent\n\n\n\nwoo_ca_recovery_sms_data – Modify SMS payload data\n\n\n\nwcf_ca_sms_body_before_send – Modify the SMS body before sending\n\n\n\nwoo_ca_generate_sms_coupon – Customize generated coupon data\n\n\n\nwcar_followup_sms_data – Modify follow‑up template data\n\n\n\nwcar_admin_sms_template_fields – Customize admin template fields\n\n\n\n\nAvailable Actions\n\n\n\n\nwcf_ca_after_sms_coupon_created – Triggered after an SMS coupon is generated\n\n\n\nwcf_ca_process_abandoned_order – Fired when an order is marked as abandoned\n\n\n\nwcf_ca_send_notices – Cron‑based trigger for sending recovery SMS\n\n\n\n\nThis SMS integration provides a compliant, extensible, and effective way to recover abandoned carts using SMS as part of the Cart Abandonment Recovery workflow.\";s:3:\"url\";s:73:\"https://cartflows.com/docs/sms-integration-for-cart-abandonment-recovery/\";s:4:\"slug\";s:45:\"sms-integration-for-cart-abandonment-recovery\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-12-30T17:42:23+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:75;O:8:\"stdClass\":8:{s:2:\"id\";i:65714;s:5:\"title\";s:41:\"Troubleshooting License Activation Issues\";s:7:\"content\";s:1105:\"If you’re having trouble activating a license, this documentation will help you identify and resolve the most common activation errors. These issues can occur if your site has been migrated, your license key was entered incorrectly, or the key is already linked to another site.\n\n\n\n1. License is already activated for this website\n\n\n\nIf you see this error, your license may already be linked to your site.\n\n\n\nSolution:\n\n\n\n\nLog in to your account.\n\n\n\nClick on API Keys from the sidebar.\n\n\n\nDelete the existing entry for your website.\n\n\n\nTry activating the license again.\n\n\n\n\n\n\n\n\n2. License is activated for the same instance ID\n\n\n\nThis error may occur if you migrated your site or are re-activating the license.\n\n\n\nTo resolve this, follow the steps in this document: How to Resolve “Cannot Activate API Key. Key Already Activated with the same Instance ID” Error Message?\n\n\n\n3. A customer account does not exist for this API Key\n\n\n\nThis error means the License Key is incorrect.\n\n\n\nSolution:\n\n\n\n\nLog in to Membership Area.\n\n\n\nCopy the correct License Key and paste it into the activation field again.\";s:3:\"url\";s:69:\"https://cartflows.com/docs/troubleshooting-license-activation-issues/\";s:4:\"slug\";s:41:\"troubleshooting-license-activation-issues\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-27T14:25:52+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:76;O:8:\"stdClass\":8:{s:2:\"id\";i:65257;s:5:\"title\";s:60:\"How to Install Cart Abandonment Recovery for WooCommerce Pro\";s:7:\"content\";s:1594:\"This documentation explains how to install the Cart Abandonment Recovery for WooCommerce Pro plugin on your website. You can install the plugin by downloading it from your account and uploading it to your WordPress site.\n\n\n\nNote: To use Cart Abandonment Recovery for WooCommerce Pro, the Cart Abandonment Recovery Free plugin must also be installed and activated. Refer to this doc to learn how to install Cart Abandonment Recovery Free.\n\n\n\nSteps to Install Cart Abandonment for WooCommerce Pro\n\n\n\nStep 1: Go to Your Account and Click on Your Products\n\n\n\nIn your account page, go to Your Products to view all your purchased products.\n\n\n\n\n\n\n\nStep 2: Download Cart Abandonment Recovery for WooCommerce Pro\n\n\n\nClick Download to start the .zip file download.\n\n\n\n\n\n\n\nStep 3: Log in to Your WordPress Website\n\n\n\nWhen you log in, you will be in your Dashboard.\n\n\n\nStep 4: In the Plugins Menu, Click on Add New Plugin\n\n\n\nGo to Plugins &gt; Add New Plugin from the WordPress menu.\n\n\n\n\n\n\n\nStep 5: Click Upload Plugin at the Top of the Screen\n\n\n\nThe screen will expand with the option to upload a plugin.\n\n\n\n\n\n\n\nStep 6: Upload the Plugin and Click Install Now\n\n\n\nClick Choose File, select the downloaded .zip file, and then click Install Now to begin the installation.\n\n\n\n\n\n\n\nStep 7: Click Activate Plugin\n\n\n\nOnce the plugin is installed, click Activate Plugin to complete the installation.\n\n\n\n\n\n\n\nWhat\'s Next?\n\n\n\nMake sure to activate your license key to start using the plugin and receive plugin updates. Click here to learn how to activate your Cart Abandonment Recovery for WooCommerce Pro license.\";s:3:\"url\";s:65:\"https://cartflows.com/docs/install-cart-abandonment-recovery-pro/\";s:4:\"slug\";s:37:\"install-cart-abandonment-recovery-pro\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-06T22:08:00+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:77;O:8:\"stdClass\":8:{s:2:\"id\";i:65283;s:5:\"title\";s:73:\"How to Activate Abandonment Cart Recovery for WooCommerce Pro License Key\";s:7:\"content\";s:1218:\"To start using Cart Abandonment Recovery for WooCommerce Pro and receive automatic updates, you need to activate your license. This documentation will guide you through the process.\n\n\n\nBefore You Start\n\n\n\nBefore activating your license, make sure:\n\n\n\n\nThe Cart Abandonment Recovery for WooCommerce Pro plugin is installed and activated on your website.If you haven’t installed it yet, follow this document: How to Install Cart Abandonment Recovery for WooCommerce Pro\n\n\n\nYou have access to your account to retrieve the license key.\n\n\n\n\nHow to Activate Your Cart Abandonment Recovery for WooCommerce Pro License\n\n\n\nStep 1: Get Your License Key\n\n\n\n\nLog in to Membership Area.\n\n\n\nClick on API Keys from the sidebar.\n\n\n\nCopy your License Key.\n\n\n\n\n\n\n\n\nStep 2: Activate Your License in WordPress\n\n\n\n\nLog in to your WordPress dashboard.\n\n\n\nGo to WooCommerce &gt; Cart Abandonment Recovery.\n\n\n\nClick on the My Account tab.\n\n\n\nPaste your License Key into the provided field.\n\n\n\nClick the Activate License button.\n\n\n\n\n\n\n\n\nTroubleshooting License Activation Issues\n\n\n\nIf you’re facing problems while activating your license, refer to this document for detailed troubleshooting steps: Troubleshooting License Activation Issues\";s:3:\"url\";s:74:\"https://cartflows.com/docs/activate-abandonment-cart-recovery-license-key/\";s:4:\"slug\";s:46:\"activate-abandonment-cart-recovery-license-key\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-15T13:58:20+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:78;O:8:\"stdClass\":8:{s:2:\"id\";i:64976;s:5:\"title\";s:56:\"Product Reports in WooCommerce Cart Abandonment Recovery\";s:7:\"content\";s:1931:\"The Product Reports feature in WooCommerce Cart Abandonment Recovery Pro helps you track which products are abandoned and recovered most frequently. It gives store owners valuable insights into product performance so you can make smarter inventory, marketing, and recovery decisions.\n\n\n\nHow It Works\n\n\n\n\nData Collection: Tracks abandoned and recovered products automatically.\n\n\n\nReal-Time Analytics: Updates instantly as events occur.\n\n\n\nEasy Interface: Displays data in a clean table with product names, images, and stats.\n\n\n\nExport: Download data in Excel for deeper analysis.\n\n\n\n\nWhere to Find Product Reports\n\n\n\n\nGo to WordPress Admin &gt; WooCommerce &gt; Cart Abandonment Recovery.\n\n\n\nClick on the Product tab.\n\n\n\nView your Product Reports dashboard.\n\n\n\n\n\n\n\n\nYou can also access a summary widget on the main dashboard with a quick link to View All.\n\n\n\n\n\n\n\nHow It’s Useful\n\n\n\n\nProduct Insights: See which products are abandoned most often.\n\n\n\nRecovery Optimization: Focus recovery campaigns on high-value items.\n\n\n\nInventory Planning: Adjust stock and pricing based on abandonment trends.\n\n\n\nMarketing Strategy: Build targeted campaigns around product-level behavior.\n\n\n\n\nUse Cases:\n\n\n\n\nIdentify products needing better descriptions or offers.\n\n\n\nMeasure recovery success rates for specific items.\n\n\n\nImprove product pages and checkout flow.\n\n\n\nForecast sales and marketing needs.\n\n\n\n\nHow to Use Product Reports\n\n\n\nStep 1: NavigateGo to WooCommerce &gt; Cart Abandonment Recovery &gt; Reports &gt; Product tab.\n\n\n\n\n\n\n\nStep 2: Explore Interface\n\n\n\n\nSearch for products by name.\n\n\n\nUse pagination for large datasets.\n\n\n\nExport data for external analysis.\n\n\n\nClick product links to view them directly.\n\n\n\n\n\n\n\n\nStep 3: Read the DataEach row shows:\n\n\n\n\nProduct name &amp; ID\n\n\n\nThumbnail image\n\n\n\nTimes abandoned (with value)\n\n\n\nTimes recovered (with value)\n\n\n\nActions to view or delete records\n\n\n\n\n\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:43:\"https://cartflows.com/docs/product-reports/\";s:4:\"slug\";s:15:\"product-reports\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-09-30T20:45:39+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:79;O:8:\"stdClass\":8:{s:2:\"id\";i:64935;s:5:\"title\";s:48:\"Dynamic Email Rules in Cart Abandonment Recovery\";s:7:\"content\";s:4438:\"Dynamic Email Rules is a powerful feature in WooCommerce Cart Abandonment Recovery Pro that allows you to apply conditional logic to your abandoned cart email templates. This ensures that emails are only sent when specific cart, customer, or product criteria are met, resulting in more personalized and effective recovery campaigns.\n\n\n\nBy using Dynamic Rules, you can automatically control email delivery and target customers with the right messages at the right time.\n\n\n\nHow It Works\n\n\n\n\nRule Engine: Evaluates conditions before sending each email.\n\n\n\nConditional Logic: Supports AND/OR logic for flexible targeting.\n\n\n\nReal-time Evaluation: Conditions are checked at the time of sending.\n\n\n\nEmail Blocking: Prevents irrelevant emails from being delivered.\n\n\n\n\nWhere to Find This Setting\n\n\n\n1: Go to WordPress Admin > WooCommerce > Cart Abandonment Recovery.\n\n\n\n\n\n\n\n2: Navigate to the Follow-up Emails tab.\n\n\n\n\n\n\n\n3: Click Add New Template or edit an existing template.\n\n\n\n\n\n\n\n4: Scroll down to the Dynamic Conditions section.\n\n\n\n\n\n\n\nWhy It’s Useful\n\n\n\n\nTargeted Marketing: Send tailored emails only to relevant customers.\n\n\n\nReduce Spam: Avoid sending unnecessary emails.\n\n\n\nIncrease Conversions: Improve the impact of recovery campaigns.\n\n\n\nSave Costs: Reduce email volume by targeting effectively.\n\n\n\n\nUse Cases:\n\n\n\n\nHigh-value orders (e.g., send emails only for carts above $100).\n\n\n\nProduct-specific targeting (e.g., electronics or clothing).\n\n\n\nGeographic targeting (e.g., US-based customers).\n\n\n\nCustomer segmentation by user role.\n\n\n\nSeasonal or category-specific campaigns.\n\n\n\n\nPerformance Benefits:\n\n\n\n\nReduced server load.\n\n\n\nBetter analytics and insights.\n\n\n\nImproved deliverability with higher engagement.\n\n\n\n\nHow to Set Up Dynamic Rules for an Email Template\n\n\n\nStep 1: Access Template SettingsNavigate to WooCommerce > Cart Abandonment Recovery > Follow-up Emails. Edit or create a template and fill in its basic details.\n\n\n\n\n\n\n\nStep 2: Enable Dynamic ConditionsScroll down to Dynamic Conditions and toggle it ON. The rule builder will appear.\n\n\n\n\n\n\n\nStep 3: Create Rule Groups\n\n\n\n\nClick Add Rule (groups work with OR logic).\n\n\n\nClick Add Condition within a group, rules must ALL match (AND logic).\n\n\n\n\n\n\n\n\nStep 4: Add Individual RulesEach rule requires:\n\n\n\n\nCondition (e.g., cart total, product, country).\n\n\n\nOperator (e.g., equals, greater than, Exists).\n\n\n\nValue (e.g., $100, US, specific product).\n\n\n\n\n\n\n\n\nStep 5: Available Conditions\n\n\n\n\nCart Total: The total value of the cart.\n\n\n\nProduct: Specific products in the cart.\n\n\n\nProduct Category: Specific product categories in the cart.\n\n\n\nBilling Country: The customer’s billing country.\n\n\n\nNumber of Cart Items: The total number of items in the cart.\n\n\n\n\n\n\n\n\nStep 6: Choose Operators\n\n\n\n\nNumeric Operators: For numbers like cart total or item count. Examples: is equal to, is not equal to, greater than, less than, greater than or equal to, less than or equal to.\n\n\n\nText Operators: For values like product names and categories. Examples: Exists, does not exists.\n\n\n\nList Operators: For conditions with multiple options (like categories or countries). Examples: Equal to, not equal to.\n\n\n\n\n\n\n\n\nStep 7: Configure Values\n\n\n\n\nEnter numbers for conditions like cart total or number of items.\n\n\n\nUse the product search field to select specific products.\n\n\n\nSelect countries or Product Categories from dropdown menus.\n\n\n\n\n\n\n\n\nStep 8: Save &amp; Test\n\n\n\n\nReview rules.\n\n\n\nTest with sample data.\n\n\n\nSave and activate your template.\n\n\n\n\nExample Rule Configurations\n\n\n\n\nHigh-Value Cart: Cart Total greater than $100 → Email only for high-value carts.\n\n\n\nProduct Category Targeting: Product Category contains \"Electronics\" → Target electronics abandonments.\n\n\n\nGeographic Targeting: Country is equal to \"US\" → Target US customers.\n\n\n\nComplex Rule: Cart Total greater than $50 AND Category contains \"Clothing\" AND Items greater than 2 → Target clothing carts over $50 with 2+ items.\n\n\n\n\nTroubleshooting\n\n\n\n\nMake sure Dynamic Conditions is enabled.\n\n\n\nVerify your rules match actual cart/customer data.\n\n\n\nEnsure the email template is active.\n\n\n\n\nDynamic Email Rules in Cart Abandonment Recovery Pro give you complete control over when and to whom your recovery emails are sent. By setting precise conditions, you can build highly targeted campaigns that improve conversions, reduce wasted emails, and deliver a better customer experience.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:47:\"https://cartflows.com/docs/dynamic-email-rules/\";s:4:\"slug\";s:19:\"dynamic-email-rules\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-09-30T20:45:20+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:80;O:8:\"stdClass\":8:{s:2:\"id\";i:64922;s:5:\"title\";s:57:\"Exclude Products from Coupon in Cart Abandonment Recovery\";s:7:\"content\";s:1912:\"The Exclude Products from Coupon feature in Cart Abandonment Recovery Pro allows you to define specific products for which recovery coupons should not be generated or applied in follow-up emails. This ensures better control over discounts and helps avoid unnecessary coupon distribution when restricted products are in the cart.\n\n\n\nWhat is “Exclude Products from Coupon”?\n\n\n\nThis feature lets you select products (or variations) that should be excluded from receiving recovery coupons. When those products are in the cart, the system can skip sending coupon-based recovery emails to prevent confusion or misuse.\n\n\n\nHow It Works\n\n\n\nCart Abandonment Recovery Pro integrates with WooCommerce’s native exclude_product_ids option for coupons. When excluded product IDs are present in the cart, the plugin ensures that:\n\n\n\n\nRecovery coupons generated for the template won’t apply to those products.\n\n\n\nThe follow-up email itself can be skipped to avoid sending a coupon that won’t work.\n\n\n\n\nWhy is it Useful?\n\n\n\n\nPrevents misuse: Protects items that are price-restricted or not meant for discounts.\n\n\n\nCleaner experience: Avoids sending unusable coupons that might frustrate customers.\n\n\n\nCompliance and margin control: Ensures sensitive SKUs maintain profitability.\n\n\n\n\nHow to Set It Up (Step-by-Step)\n\n\n\n1: Navigate to Follow-up Emails in Cart Abandonment Recovery.\n\n\n\n\n\n\n\n2: Add or edit a template.\n\n\n\n\n\n\n\n3: Enable Create Coupon Code and configure the coupon settings.\n\n\n\n\n\n\n\n4: In the Exclude Products field, search and select the products/variations to exclude.\n\n\n\n\n\n\n\n5: Save and activate the template.\n\n\n\nHow Does It Work in Practice?\n\n\n\n\nSelected product IDs are stored with the template.\n\n\n\nThese IDs are added to the coupon’s exclude_product_ids setting.\n\n\n\nIf the cart contains any excluded product, the system can skip sending the coupon email for that template.\n\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:56:\"https://cartflows.com/docs/exclude-products-from-coupon/\";s:4:\"slug\";s:28:\"exclude-products-from-coupon\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-06T19:23:21+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:81;O:8:\"stdClass\":8:{s:2:\"id\";i:63895;s:5:\"title\";s:34:\"How to Install Modern Cart Starter\";s:7:\"content\";s:1053:\"We’re glad you’ve chosen Modern Cart Starter for your website! This documentation will walk you through the steps to install the Modern Cart Starter plugin on your WordPress site.\n\n\n\nIf you’re looking to install Modern Cart for WooCommerce, please see our dedicated documentation.\n\n\n\nHow to install Modern Cart Starter\n\n\n\nTo install the Modern Cart Starter plugin on your WordPress site, follow the steps below.\n\n\n\nStep 1: Log in to your WordPress website\n\n\n\nWhen you log in, you will be in your Dashboard.\n\n\n\nStep 2: In the Plugins menu, click on Add New Plugin\n\n\n\nFrom your WordPress dashboard, go to Plugins &gt; Add New Plugin to open the plugin installation screen.\n\n\n\n\n\n\n\nStep 3: Search for Modern Cart Starter\n\n\n\nIn the search bar, search for Modern Cart Starter.\n\n\n\n\n\n\n\nStep 4: Click Install Now\n\n\n\nIn the Modern Cart Starter card, click Install Now.\n\n\n\n\n\n\n\nStep 5: Click Activate\n\n\n\nOnce the installation has finished, click Activate.\n\n\n\n\n\n\n\nCongratulations! You’ve successfully installed the Modern Cart Starter plugin on your website.\";s:3:\"url\";s:58:\"https://cartflows.com/docs/installing-modern-cart-starter/\";s:4:\"slug\";s:30:\"installing-modern-cart-starter\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-09-23T18:45:52+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:82;O:8:\"stdClass\":8:{s:2:\"id\";i:63377;s:5:\"title\";s:56:\"How to Install Cart Abandonment Recovery for WooCommerce\";s:7:\"content\";s:1115:\"Thank you for choosing Cart Abandonment Recovery for WooCommerce ! This documentation will walk you through the steps to install the plugin on your WordPress site so you can start recovering lost sales right away.\n\n\n\nHow to install Cart Abandonment Recovery for WooCommerce&nbsp;\n\n\n\nTo install the Cart Abandonment Recovery for WooCommerce&nbsp; plugin on your WordPress site, follow the steps below.\n\n\n\nStep 1: Log in to your WordPress website\n\n\n\nWhen you log in, you will be in your Dashboard.\n\n\n\nStep 2: In the Plugins menu, click on Add New Plugin\n\n\n\nFrom your WordPress dashboard, go to Plugins > Add New Plugin to open the plugin installation screen.\n\n\n\n\n\n\n\nStep 3: Search for Cart Abandonment Recovery for WooCommerce \n\n\n\nIn the search bar, search for Cart Abandonment Recovery.\n\n\n\n\n\n\n\nStep 4: Click Install Now\n\n\n\nIn the Cart Abandonment Recovery for WooCommerce  card, click Install Now.\n\n\n\n\n\n\n\nStep 5: Click Activate\n\n\n\nOnce the installation has finished, click Activate.\n\n\n\n\n\n\n\nCongratulations! You’ve successfully installed the Cart Abandonment Recovery for WooCommerce&nbsp; plugin on your website.\";s:3:\"url\";s:61:\"https://cartflows.com/docs/install-cart-abandonment-recovery/\";s:4:\"slug\";s:33:\"install-cart-abandonment-recovery\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-01T18:44:37+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:83;O:8:\"stdClass\":8:{s:2:\"id\";i:63305;s:5:\"title\";s:76:\"Roll Back to a Previous Version of Cart Abandonment Recovery for WooCommerce\";s:7:\"content\";s:1498:\"If you encounter an issue after updating the Cart Abandonment Recovery for WooCommerce plugin, you may want to roll back to an earlier version. This can be done in two ways, either by using a plugin like WP Rollback plugin or by manually downloading a previous version from the WordPress plugin repository.\n\n\n\nMethod 1: Roll Back Using the WP Rollback Plugin\n\n\n\n1. Install and activate the WP Rollback plugin on your site.\n\n\n\n\n\n\n\n2. Go to Plugins &gt; Installed Plugins in your WordPress dashboard.\n\n\n\n3. Locate Cart Abandonment Recovery for WooCommerce in the list, and click the Rollback link.\n\n\n\n\n\n\n\n4. Choose the version you’d like to roll back to, click the Rollback button, and follow the prompts to complete the process.\n\n\n\n\n\n\n\nThe plugin will automatically switch to the version you selected.\n\n\n\nMethod 2: Roll Back Manually\n\n\n\n1. Go to the Cart Abandonment Recovery for WooCommerceplugin page in the WordPress repository.\n\n\n\n2. Scroll down to the Advanced View section.\n\n\n\n\n\n\n\n3. Locate the Previous Versions dropdown, select the version you’d like to install, and download the ZIP file.\n\n\n\n\n\n\n\n4. In your WordPress dashboard, go to Plugins &gt; Installed Plugins and deactivate the current version of Cart Abandonment Recovery for WooCommerce.\n\n\n\n5. Click Delete to remove it from your site.\n\n\n\n6. Next, go to Plugins &gt; Add New &gt; Upload Plugin, choose the ZIP file you downloaded, and install it.\n\n\n\n7. Activate the plugin.\n\n\n\nYour site will now be running the selected version.\";s:3:\"url\";s:70:\"https://cartflows.com/docs/rollback-cart-abandonment-recovery-version/\";s:4:\"slug\";s:42:\"rollback-cart-abandonment-recovery-version\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-08-21T22:01:50+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:84;O:8:\"stdClass\":8:{s:2:\"id\";i:63047;s:5:\"title\";s:18:\"Popup Cart Feature\";s:7:\"content\";s:1994:\"The Popup Cart feature in Modern Cart for WooCommerce provides an interactive, user-friendly way for customers to view and manage their cart without leaving the current page. This helps create a seamless shopping experience and reduces cart abandonment.\n\n\n\nWhen enabled, the Popup Cart appears as a centered modal window whenever a product is added or the floating cart icon is clicked. It shows cart items, supports coupon codes, and can optionally display product recommendations, all without page reloads.\n\n\n\nNote\nThis feature is available only in the Modern Cart Pro version.\n\n\n\n\nWhy Use Popup Cart?\n\n\n\nThis feature enhances the shopping process by making it quicker and more engaging. Here’s why it’s beneficial:\n\n\n\n\nImproved User Interaction: Provides instant feedback when items are added, encouraging customers to keep shopping.\n\n\n\nSeamless Design Integration: Customize the popup cart’s look to match your store’s branding for a consistent experience.\n\n\n\nBoosted Conversions: Eliminates page reloads, helping keep the buying process smooth and reducing cart abandonment.\n\n\n\n\nHow to Enable the Popup Cart?\n\n\n\nStep 1:&nbsp;Navigate to the Modern Cart Settings, then click on the&nbsp;General&nbsp;Tab.\n\n\n\n\n\n\n\nStep 2: Inside the General Tab, you will find the Cart Type setting.\n\n\n\n\n\n\n\nStep 3: Select Popup from the available options of the Cart Type setting.\n\n\n\n\n\n\n\nAfter selecting and saving Popup as your Cart Type, your cart will appear like this on the frontend.\n\n\n\n\n\n\n\nHow to customize the Popup width and animation speed?\n\n\n\nStep 1: From the Modern Cart settings page, click on the Styling tab.\n\n\n\n\n\n\n\nStep 2: Scroll below to find the style settings related to the Popup Cart Type.\n\n\n\n\n\n\n\n\nPopup Width (Desktop): Adjust the width of the popup cart window when viewed on desktop or larger screens.\n\n\n\nPopup Width (Mobile): Adjust the width of the popup cart window when viewed on mobile or smaller screens.\n\n\n\nAnimation Speed: Control how quickly the popup opens and closes.\";s:3:\"url\";s:46:\"https://cartflows.com/docs/popup-cart-feature/\";s:4:\"slug\";s:18:\"popup-cart-feature\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-21T20:36:53+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:85;O:8:\"stdClass\":8:{s:2:\"id\";i:63040;s:5:\"title\";s:22:\"Cart Opening Direction\";s:7:\"content\";s:1298:\"The Cart Opening Direction feature in Modern Cart for WooCommerce lets you control from which side of the screen the slide-out cart appears when opened. This gives you flexibility to match your site’s design and improve user experience.\n\n\n\nYou can choose to open the cart from the left or right side of the screen, making it intuitive for your audience based on reading direction or site layout.\n\n\n\nNote\nThis feature is available only in the Modern Cart Pro version.\n\n\n\n\nWhy Use Cart Opening Direction?\n\n\n\nSetting the correct opening direction helps ensure your cart feels natural and unobtrusive. Here’s why this feature is useful:\n\n\n\n\nUser Experience: Align the cart behavior with your visitors’ reading flow, right side for LTR languages and left side for RTL languages.\n\n\n\nDesign Flexibility: Prevent overlaps with other elements like sticky menus or sidebars.\n\n\n\nAccessibility: Enhance usability for multilingual or RTL-based sites.\n\n\n\n\nHow to Set the Cart Opening Direction?\n\n\n\nStep 1:&nbsp;Navigate to the Modern Cart Settings, then click on the General Tab.\n\n\n\n\n\n\n\nStep 2: Inside the General Tab, you will find the Cart Opening Direction setting.\n\n\n\n\n\n\n\nOnce saved, the cart will always slide in from your chosen side whenever a user clicks the floating cart icon.\n\n\n\nSee it in action\";s:3:\"url\";s:50:\"https://cartflows.com/docs/cart-opening-direction/\";s:4:\"slug\";s:22:\"cart-opening-direction\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-21T20:36:27+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:86;O:8:\"stdClass\":8:{s:2:\"id\";i:63033;s:5:\"title\";s:21:\"Floating Icon Styling\";s:7:\"content\";s:2058:\"The Floating Icon Styling feature in Modern Cart for WooCommerce lets you fully customize the cart icon that appears across your site. This floating icon gives shoppers instant access to their cart from any page, making checkout faster and helping reduce cart abandonment.\n\n\n\nYou can easily adjust its colors, size, shape, and more to match your store’s branding and create a seamless shopping experience.\n\n\n\nNote\nThis feature is available only in the Modern Cart Pro version.\n\n\n\n\nWhy Use Floating Icon Styling?\n\n\n\nA well-designed floating icon can make your site more intuitive and improve cart visibility. Here’s why you’d want to use this feature:\n\n\n\n\nConsistent Branding: Match the cart icon with your site’s color scheme and visual identity.\n\n\n\nImproved UX: Make the icon stand out or blend in, depending on your design goals.\n\n\n\nBetter Engagement: Give users easy access to their cart, increasing the likelihood of completed purchases.\n\n\n\n\nHow to Customize the Floating Icon?\n\n\n\nStep 1: Navigate to the Modern Cart Settings and select Floating Cart Icon tab\n\n\n\n\n\n\n\nStep 2: Start customizing the setting to match your store\'s branding.\n\n\n\n\n\n\n\nLive Preview: Instantly displays a preview of how your floating cart button will look.\n\n\n\n\n\n\n\nCustomization options for Floating Icon\n\n\n\n\nIcon Color: Choose the color of the cart icon. For example, you can match it to your brand’s color for a consistent look.\n\n\n\nIcon Background Color: Set the background color behind the cart icon to match your style or branding.\n\n\n\nCount Text Color: Select the color for the number displayed in the cart’s count badge.\n\n\n\nCount Background Color: Choose the background color for the cart count badge.\n\n\n\nIcon Width: Adjusts the overall size of the cart icon, including both its width and height.\n\n\n\nBorder Radius: Adjusts how rounded the button’s corners are. Lower values make the button look more square, while higher values give it a more rounded shape.\n\n\n\n\nOnce configured, the floating icon will automatically reflect your design changes across your store.\";s:3:\"url\";s:49:\"https://cartflows.com/docs/floating-icon-styling/\";s:4:\"slug\";s:21:\"floating-icon-styling\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-21T20:36:02+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:87;O:8:\"stdClass\":8:{s:2:\"id\";i:62924;s:5:\"title\";s:43:\"Open the Cart Using a Custom Button or Link\";s:7:\"content\";s:1029:\"The Use Custom Trigger feature in Modern Cart lets you open the cart tray using your own button or link, giving you full control over how users interact with the cart.\n\n\n\nThis option is available under the Floating Cart Icon settings and is available only in the Modern Cart Pro version.\n\n\n\nBy using a custom trigger, you can enhance the cart experience by assigning any clickable element, such as a button, icon, or link, with a class or ID that triggers the cart tray.\n\n\n\nHow to Use the Custom Trigger Feature\n\n\n\n\nGo to WooCommerce &gt; Modern Cart &gt; Floating Cart Icon.\n\n\n\nScroll to the Use Custom Trigger setting.\n\n\n\nIn the input field, enter the element selector(s) that will trigger the cart. You can use #id, .class, or multiple selectors separated by commas.\n\n\n\n\nFor example, if you use a custom header created with Ultimate Addons for Elementor Lite, and you’ve added a Cart Widget with a class like .my-custom-cart, you can enter that selector into the field to make it act as the cart trigger.\n\n\n\nSee It in Action\";s:3:\"url\";s:47:\"https://cartflows.com/docs/custom-cart-trigger/\";s:4:\"slug\";s:19:\"custom-cart-trigger\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-09-23T15:52:06+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:88;O:8:\"stdClass\":8:{s:2:\"id\";i:62744;s:5:\"title\";s:53:\"How to Set Custom Product Recommendations in the Cart\";s:7:\"content\";s:975:\"The Custom option under the Increase AOV with Product Recommendations setting in Modern Cart allows you to manually choose which products appear as recommendations in the cart tray.\n\n\n\nWhen you select Custom, a Custom Recommendations section becomes active. If you select any other mode, this section remains visible but is grayed out.\n\n\n\nNote\n1. If Custom is selected but no products are added to the Search products field, random products will be displayed in the product recommendation area.2. This feature is available only in the Modern Cart Pro version.\n\n\n\n\nHow to Add Custom Recommendations\n\n\n\n\nGo to WooCommerce &gt; Modern Cart &gt; Products.\n\n\n\nUnder Increase AOV with Product Recommendations, select Custom from the dropdown.\n\n\n\nIn the Custom Recommendations section, use the Search products field to find products by typing their title.\n\n\n\nSelect the desired product from the search results. You can repeat this step to add multiple products.\n\n\n\n\nSee It in Action\";s:3:\"url\";s:58:\"https://cartflows.com/docs/custom-product-recommendations/\";s:4:\"slug\";s:30:\"custom-product-recommendations\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-21T20:35:22+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:89;O:8:\"stdClass\":8:{s:2:\"id\";i:62701;s:5:\"title\";s:60:\"How to Display Variation Swatches on Non‑WooCommerce Pages\";s:7:\"content\";s:1802:\"By default, the Variation Swatches plugin displays swatches only on the standard WooCommerce Shop, Archive, and Single Product pages. If you add products to a regular WordPress Page (landing page, promo page, content page, etc.), the variation options may not load as swatches.\n\n\n\nThis documentation shows you how to enable swatches on those other pages using a simple PHP filter.\n\n\n\nBefore You Begin\n\n\n\nMake sure:\n\n\n\n\nVariation Swatches is installed and active.\n\n\n\nYour variable products use global attributes with swatch settings configured in WooCommerce &gt; Products &gt; Attributes.\n\n\n\n\nStep 1: Insert Products on the Page\n\n\n\nAdd products to your WordPress Page using WooCommerce product shortcodes. These methods output standard WooCommerce markup that works best with Variation Swatches.\n\n\n\nExamples:\n\n\n\n&#91;products]\n&#91;products ids=\"123,456,789\" columns=\"3\"]\n\n\n\nNote: Using third‑party catalog or grid modules may not trigger swatches because they often bypass WooCommerce templates. If swatches do not appear, switch to WooCommerce shortcodes/blocks and retest.\n\n\n\nStep 2: Enable Swatches on WordPress Pages (PHP Filter)\n\n\n\nAdd this snippet in your child theme functions.php file or via a third-party plugin like Code Snippets. This tells Variation Swatches to load on WordPress Pages.\n\n\n\nadd_filter( \'cfvsw_requires_shop_settings\', function( $status ){\n			if( is_page() ) {\n				return true;\n			}\n			return $status;\n		});\nis_page can be replaced by the desired condition.\n\n\n\nFor step-by-step guidance, see our doc: How &amp; Where to Add Custom JS, CSS &amp; PHP Code.\n\n\n\nStep 3: Clear Cache &amp; Test\n\n\n\n\nSave/activate the PHP snippet.\n\n\n\nClear any caching (plugin, server, CDN).\n\n\n\nView your custom page in a private browser window.\n\n\n\nCheck that variable products now show swatches.\";s:3:\"url\";s:71:\"https://cartflows.com/docs/variation-swatches-on-non-woocommerce-pages/\";s:4:\"slug\";s:43:\"variation-swatches-on-non-woocommerce-pages\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-07-23T19:47:37+05:30\";s:8:\"category\";a:1:{i:0;s:18:\"variation-swatches\";}}i:90;O:8:\"stdClass\":8:{s:2:\"id\";i:62604;s:5:\"title\";s:45:\"Use a Custom Image for the Floating Cart Icon\";s:7:\"content\";s:1859:\"Modern Cart allows you to upload and use a custom image as the floating cart icon, giving you more flexibility in branding your store’s appearance.\n\n\n\nNote\nThis feature is available only in the Modern Cart Pro version.\n\n\n\n\nYou can find this setting under the Floating Cart Icon tab.\n\n\n\n\n\n\n\nSupported file types include .png, .jpg, and .svg.\n\n\n\nThe recommended image size is 36 × 36 pixels to ensure a clear and consistent display.\n\n\n\nSee It in Action\n\n\n\n\n\n\n\nUsing SVG Files\n\n\n\nIf you upload an SVG file, please note that WordPress does not allow SVG uploads by default. This is a WordPress restriction, not a limitation from Modern Cart.\n\n\n\nYou can enable SVG uploads by:\n\n\n\nInstalling a Plugin\n\n\n\nUse a plugin like Safe SVG to allow uploading SVG files safely.\n\n\n\nAdding a Code Snippet\n\n\n\nYou can also enable SVG upload manually with this custom PHP code:\n\n\n\n/**\n * Allow SVG uploads for administrators with basic sanitization.\n */\n\n// Allow SVG uploads for administrators only\nadd_filter(\'upload_mimes\', function($mimes) {\n    if (current_user_can(\'administrator\')) {\n        $mimes&#91;\'svg\'] = \'image/svg+xml\';\n    }\n    return $mimes;\n});\n\n// Basic sanitization: remove &lt;script&gt; tags from uploaded SVGs\nadd_filter(\'wp_handle_upload_prefilter\', function($file) {\n    if ($file&#91;\'type\'] === \'image/svg+xml\') {\n        $svg = file_get_contents($file&#91;\'tmp_name\']);\n\n        // Remove &lt;script&gt; tags\n        $svg = preg_replace(\'/&lt;script.*?&lt;\\/script&gt;/is\', \'\', $svg);\n\n        // Optionally, remove on* event attributes (like onclick, onload)\n        $svg = preg_replace(\'/on\\w+=\"&#91;^\"]*\"/i\', \'\', $svg);\n\n        file_put_contents($file&#91;\'tmp_name\'], $svg);\n    }\n    return $file;\n});\n\n\n\nIf you’re not sure how to add code to your WordPress site, refer to this doc: How and Where to Add the Custom JS, CSS &amp; PHP Codes?\";s:3:\"url\";s:58:\"https://cartflows.com/docs/custom-image-for-floating-cart/\";s:4:\"slug\";s:30:\"custom-image-for-floating-cart\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-21T20:34:40+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:91;O:8:\"stdClass\":8:{s:2:\"id\";i:62565;s:5:\"title\";s:52:\"Control Product Recommendation Source for Empty Cart\";s:7:\"content\";s:1612:\"Modern Cart allows you to show product recommendations when the cart is empty. This can help engage users and guide them toward relevant products, even before anything is added to the cart.\n\n\n\nNote\nThis feature is available only in the Modern Cart Pro version.\n\n\n\n\nThe setting is available under the Products tab of the Modern Cart settings.\n\n\n\n\n\n\n\nProduct Recommendation Source for Empty Cart\n\n\n\nThis option lets you choose where the recommended products are pulled from when the cart is empty. You can choose from:\n\n\n\nDisable\n\n\n\nNo recommendations will appear in the cart when it’s empty.\n\n\n\n\n\n\n\nFrom Upsell Products\n\n\n\nDisplays products you’ve assigned as Upsell products for other products in your store.\n\n\n\nTo learn how to configure up-sell products in WooCommerce, see this doc: How to Configure Upsell and Cross-Sell Products in WooCommerce\n\n\n\nFrom Featured Products\n\n\n\nDisplays WooCommerce products that are marked as Featured.\n\n\n\nTo mark a product as featured:\n\n\n\n\nGo to Products &gt; All Products in your WordPress dashboard.\n\n\n\nClick the star icon next to the product title. When active, the star will appear solid.\n\n\n\n\n\n\n\n\nAlternatively, you can also mark a product as featured using Quick Edit or from the Catalog Visibility settings on the “Edit Product” page.\n\n\n\nFrom Cross-Sell Products\n\n\n\nDisplays products you’ve assigned as Cross-Sell products, typically shown on the Cart page or cart tray.\n\n\n\nTo learn how to configure cross-sell products in WooCommerce, see this doc: How to Configure Upsell and Cross-Sell Products in WooCommerce\n\n\n\nHow the cart looks with a recommended product:\";s:3:\"url\";s:65:\"https://cartflows.com/docs/product-recommendation-for-empty-cart/\";s:4:\"slug\";s:37:\"product-recommendation-for-empty-cart\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-21T20:33:48+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:92;O:8:\"stdClass\":8:{s:2:\"id\";i:62560;s:5:\"title\";s:64:\"How to Configure Upsells and Cross-Sells Products in WooCommerce\";s:7:\"content\";s:1048:\"WooCommerce allows you to manually assign related products for upselling and cross-selling. These settings help guide customers toward relevant products, which can improve conversions and increase order value.\n\n\n\nOnce configured, Modern Cart can use these product associations to display recommendations in the cart tray.\n\n\n\nSet Up Upsells and Cross-Sells in WooCommerce\n\n\n\n\nGo to Products &gt; All Products and click Edit on the product you want to configure.\n\n\n\nScroll down to the Product data section.\n\n\n\nClick the Linked Products tab.\n\n\n\nUnder Upsells, search and select the products you want to recommend as upsell options.These products are usually higher-end alternatives to the current item.\n\n\n\nUnder Cross-sells, search and select the products you want to show on the Cart page or inside the cart tray.These are typically complementary products.\n\n\n\nClick Update to save your changes.\n\n\n\n\n\n\n\n\nOnce set, these products will be used in Modern Cart wherever upsell or cross-sells options are selected as the source for product recommendations.\";s:3:\"url\";s:60:\"https://cartflows.com/docs/upsell-cross-sell-in-woocommerce/\";s:4:\"slug\";s:32:\"upsell-cross-sell-in-woocommerce\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-07-22T19:01:02+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:93;O:8:\"stdClass\":8:{s:2:\"id\";i:62503;s:5:\"title\";s:49:\"Control When the Cart Opens After Adding Products\";s:7:\"content\";s:1159:\"Modern Cart gives you control over when the cart tray opens after a product is added to the cart. This lets you tailor the cart behavior to match your store’s checkout flow, whether you want to encourage quick purchases or reduce distractions.\n\n\n\nThis feature is located under the General settings tab and is available only in the Modern Cart Pro version.\n\n\n\nCart Auto-Open Behavior\n\n\n\nUse this setting to control how the cart tray responds when a product is added to the cart. The default behavior is For every item added.\n\n\n\n\nFor every item addedThe cart tray slides in every time a product is added. This keeps users aware of what’s in their cart and encourages checkout.\n\n\n\nFor the first time addedThe cart tray slides in only when the first product is added to the cart. For any additional products added afterward, the cart tray will not open automatically. This provides a more subtle experience for repeat additions.\n\n\n\nDon’t open automaticallyThe cart tray will never slide in automatically when a product is added. This is useful if you want users to stay focused on browsing.\n\n\n\n\nWatch the video below to see how this setting works in action:\";s:3:\"url\";s:51:\"https://cartflows.com/docs/cart-auto-open-behavior/\";s:4:\"slug\";s:23:\"cart-auto-open-behavior\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-09-23T15:52:00+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:94;O:8:\"stdClass\":8:{s:2:\"id\";i:62415;s:5:\"title\";s:52:\"Refresh the Checkout Page After CartFlows AJAX Calls\";s:7:\"content\";s:1769:\"In some cases, especially when working with dynamic products like subscriptions, the checkout page may not refresh automatically when switching between products or options. This can lead to a mismatch in available payment methods or shipping options.\n\n\n\nTo resolve this, CartFlows provides a filter that forces the checkout to refresh and trigger the necessary AJAX calls, ensuring the correct data is always loaded on the checkout page.\n\n\n\nThis is especially useful when:\n\n\n\n\nSwitching between subscription and non-subscription products\n\n\n\nDynamically changing product options that affect checkout behavior\n\n\n\nEnsuring updated shipping/payment methods based on the product or variation\n\n\n\n\nHow to Enable Checkout Refresh After AJAX Calls\n\n\n\nStep 1: Add the Filter to Your Site\n\n\n\nTo make the checkout page refresh automatically, add the following code to your site’s functions.php file or use a code snippet plugin:\n\n\n\nadd_filter( \'cartflows_checkout_trigger_update_order_review\', \'__return_true\' );\n\n\n\n\nNeed help adding custom code? Here’s how to safely add code snippets to your site.\n\n\n\nStep 2: Save and Test\n\n\n\nAfter adding the filter, visit your checkout page and test switching between different product types or options. The page will now refresh the order review section as expected, showing the correct payment methods and other dynamically updated options.\n\n\n\nWhen to Use This Filter\n\n\n\nThis filter is particularly helpful if you:\n\n\n\n\nUse WooCommerce Subscriptions along with other types of products with CartFlows funnel checkout\n\n\n\nOffer products with conditional logic affecting checkout (e.g., special payment gateways for specific items)\n\n\n\nNeed to ensure the checkout page always reflects the latest data without requiring manual updates/refreshes.\";s:3:\"url\";s:80:\"https://cartflows.com/docs/refresh-the-checkout-page-after-cartflows-ajax-calls/\";s:4:\"slug\";s:52:\"refresh-the-checkout-page-after-cartflows-ajax-calls\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-07-07T21:12:32+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"code-snippets\";}}i:95;O:8:\"stdClass\":8:{s:2:\"id\";i:62353;s:5:\"title\";s:65:\"How to Show Dropdown Instead of Swatches for Specific Attributes?\";s:7:\"content\";s:1104:\"By default, the Variation Swatches plugin replaces WooCommerce’s dropdowns with more visually appealing swatches. However, if you’d like to display specific attributes as dropdowns while using swatches for others, this can be easily done, no custom code required.\n\n\n\nDisable Swatches for a Specific Attribute\n\n\n\nThis method allows you to manage swatches and dropdowns right from the WordPress dashboard.\n\n\n\nStep 1: Go to Attributes\n\n\n\nNavigate to Products &gt; Attributes in your WordPress dashboard.\n\n\n\nStep 2: Edit the Attribute\n\n\n\nFind the attribute you want to display as a dropdown and click Edit.\n\n\n\n\n\n\n\nStep 3: Change Type to Select\n\n\n\nIn the Type dropdown, choose Select and update the attribute.\n\n\n\n\n\n\n\nStep 4: Update Global Settings\n\n\n\nGo to WooCommerce &gt; Variation Swatches &gt; Settings. Under General settings, ensure that the Auto Convert Dropdowns to Label option is disabled.\n\n\n\n\n\n\n\nThis setting ensures attributes set as Select remain dropdowns on product pages.\n\n\n\nWith this method, you can mix and match dropdowns and swatches on the same product for a flexible user experience.\";s:3:\"url\";s:92:\"https://cartflows.com/docs/how-to-show-dropdown-instead-of-swatches-for-specific-attributes/\";s:4:\"slug\";s:64:\"how-to-show-dropdown-instead-of-swatches-for-specific-attributes\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-07-03T21:41:25+05:30\";s:8:\"category\";a:1:{i:0;s:18:\"variation-swatches\";}}i:96;O:8:\"stdClass\":8:{s:2:\"id\";i:60546;s:5:\"title\";s:52:\"Starting out with Variation Swatches for Woocommerce\";s:7:\"content\";s:3775:\"Let\'s start by understanding how to set this plugin up with step by step process.\n\n\n\nStep 1: Setting up attributes of the products\n\n\n\nIn order to use this plugin to create different variants, you will need to set up the different attributes that you need as a differentiator between the variants. For example, color, sizes and labels. Follow the steps below to set up the product attributes:\n\n\n\n\nFirst, navigate to the WordPress dashboard\n\n\n\nClick on Products and select attributes\n\n\n\n\n\n\n\n\n\nTo add an attribute, first give it a name (i.e colors)\n\n\n\nEnter the slug of the attribute (i.e colors)\n\n\n\n\n\n\n\n\n\nSelect the type of the attribute. As of now there are three different types that are available inside the plugin and they are color, label and image.\n\n\n\n\n\n\n\n\n\nSelect the shape of the attributes. There are 4 different types of shapes are available such as default, square, rounded corner and circle.\n\n\n\n\n\n\n\n\nBy default the swatches will be designed as you customize them from the settings page as shown in the image below. You can change the shape of the swatches to rounded corner, square and round as per the requirement.\n\n\n\n\n\n\n\nBy default the size of the swatches will be selected as 24px. You can change the size by clicking on the box and entering the value of the pixels as per your requirement.\n\n\n\n\n\n\n\nFinally, click on the Add Attribute button to add the changes to the site.\n\n\n\nStep 2: Configuring the terms of the Attributes\n\n\n\nOnce the attributes are added, you will need to configure the terms for each of the attributes. You will need to click on the configure terms button next to each attribute.\n\n\n\n\n\n\n\nIn this example, we are going to configure the color options for a particular attribute. There are 4 options that you can select from. These options are the name of the color, slug of the color, a short description of the color and a color selector to select the color. Once you have selected the options as per your requirements, click on Add New button at the bottom to add it to the list.\n\n\n\n\n\n\n\nYou can add as many attributes as you need based on the requirement. Once you have added the terms, the final screen would like the below image.\n\n\n\n\n\n\n\nStep 3: Setting up product variations\n\n\n\nNow that the product attributes are set, you will need to select the product variations in order to display the variation swatches on the front-end of your website.\n\n\n\n\nTo select the product variations, please navigate to the Products and click on All Products.\n\n\n\nClick on Edit next to the product on which you would like to set up the variations\n\n\n\n\n\n\n\n\n\nUnder product data, select the product type as the Variable Product\n\n\n\n\n\n\n\n\n\nClick on the Attribute tab and select the attributes that you would like to be included in the front-end and click on the Add button to get them added to the list\n\n\n\n\n\n\n\n\n\nOnce the attribute is added click on the Select All button to add all the variants to the product.\n\n\n\nEnsure that the Used For Variation button is checked\n\n\n\nClick on the Save Attribute button to save the changes\n\n\n\n\n\n\n\n\n\nOnce the attributes are saved, you will need to set the variation in the product. To do that, please navigate to the Variation Tab.\n\n\n\nClick on the Go button to create the variations\n\n\n\nThis will add the variation to the product based on the attributes that you have selected earlier\n\n\n\n\n\n\n\n\n\nYou can also set a custom image and price for this variant by opening the drop-down menu\n\n\n\nSelect the variation by clicking on the drop-down menu\n\n\n\nAdd a custom price for this variant by entering the amount in the Regular Price field\n\n\n\nAdd an image by clicking on the image button\n\n\n\nRepeat the same process to another variants\n\n\n\n\n\n\n\n\nOnce you are done editing the field, click on Save Changes button at the bottom and update the product.\";s:3:\"url\";s:80:\"https://cartflows.com/docs/starting-out-with-variation-swatches-for-woocommerce/\";s:4:\"slug\";s:52:\"starting-out-with-variation-swatches-for-woocommerce\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-19T22:36:00+05:30\";s:8:\"category\";a:1:{i:0;s:18:\"variation-swatches\";}}i:97;O:8:\"stdClass\":8:{s:2:\"id\";i:60557;s:5:\"title\";s:14:\"Basic Settings\";s:7:\"content\";s:6150:\"Once the plugin is installed you will need to manually set it up in order to get the customized and desired results on your WooCommerce products. To access the settings, you will need to navigate to the WordPress dashboard and click on plugins&gt;installed plugin. Scroll down to the plugin and click on settings to access the settings page.\n\n\n\n\n\n\n\nGeneral Settings:\n\n\n\nUnder general settings, you will find three options which are mentioned below:\n\n\n\n\nEnable for product page: This will enable the features of the plugin in the single product page where the plugin will show the variants available for a particular product\n\n\n\nEnable for Shop Page: This will enable the users to select the different variants of the products directly from the shop/archive pages\n\n\n\nAuto convert the drop downs to labels: Enabling this feature will automatically convert the drop-downs to labels\n\n\n\n\n\n\n\n\nGlobal Styling:\n\n\n\nUnder the global styling options, you will be able to customize the swatches as per your requirements and style segments. Following are the options available:\n\n\n\nSwatch Styling\n\n\n\nSwatch minimum width:\n\n\n\nBy default the minimum width of the swatches are set to 24px. You can change this by clicking on the arrows or by manually typing the number of pixels inside the box.\n\n\n\n\n\n\n\nSwatch minimum height\n\n\n\nBy default the minimum width of the swatches are set to 24px. You can change this by clicking on the arrows or by manually typing the number of pixels inside the box.\n\n\n\n\n\n\n\nSwatch border radius\n\n\n\nThe border radius is by default selected as 3px. You can change this by clicking on the arrows or by manually typing the number of pixels inside the box.\n\n\n\n\n\n\n\nYou can customize the swatches as per your requirements by changing the default value to any value. Please note that the global setting will only be applied to the product if the product attribute settings is set to default. Changing the height, width and the border radius to the same value will change the shape of the swatches as circles.\n\n\n\n\n\n\n\n Font size\n\n\n\nThe font size of the swatch is by default selected as 12px. You can change this by clicking on the arrows or by manually typing the number of pixels inside the box.\n\n\n\n\n\n\n\nPlease note that you can change the font only for the label attribute. This does not work for the color or the size attributes.\n\n\n\nBorder color\n\n\n\nYou can use the color selector to chose the border color of the swatch as per your requirement.\n\n\n\n\n\n\n\nDisabled attribute effect\n\n\n\nThis option will help blur the disabled attributes so that the users can not select the same attribute. There are three major options that you can choose from which are blur, blur with cross and hide it completely from the front end of the website.\n\n\n\n\n\n\n\nTooltip Styling\n\n\n\nTooltip is the option that helps pop up the name of the label, color or the size attribute when the user hovers the mouse cursor over them. There are the following options that you can choose from to customize how Tooltips appear on your website. You can simply choose to turn this option on or off by using the toggle button.\n\n\n\n\n\n\n\nFront End view of the Tooltip\n\n\n\n\n\n\n\nTooltip background color\n\n\n\nThis option will help you customize the background color of the tooltips. In this example, we have set the background color as red.\n\n\n\n\n\n\n\nTooltip font color\n\n\n\nThis option will help you customize the font color of the tooltips. In this example, we have set the background color as white. You can change this by clicking on the “Select Color” option.\n\n\n\n\n\n\n\nTooltip font size\n\n\n\nThis option will let you change the font size of the tooltip. By default this is set to 12px. You can change it by entering the custom value in the box or using the up and down arrow adjacent to it.\n\n\n\n\n\n\n\n Image preview on tooltip\n\n\n\nImage preview will be shown in tooltip if this option is enabled, This setting works only for image type swatches\n\n\n\n\n\n\n\nLabel Styling\n\n\n\nLabel position\n\n\n\nThis option will help you in positioning the label on the product page. Currently there are three settings available to this function. They are None, Inline and stacked.\n\n\n\n\n\n\n\nInline: Inline settings will position the labels in the same line as mentioned in the image below:\n\n\n\n\n\n\n\nStacked: this option will stack the label below the tag as mentioned in the image below\n\n\n\n\n\n\n\nLabel font size\n\n\n\nThis option enables the users to change the font size of the labels\n\n\n\n\n\n\n\nWidgets Styling\n\n\n\n Filters\n\n\n\nEnabling this option will add the swatches to the filter option of the woocommerce that means the users can use the filter option to choose from different swatches on the product archive page.\n\n\n\n\n\n\n\nShop Page Styling\n\n\n\nTo design and style the swatches on the shop page of your website, we have incorporated a few cool styling options.\n\n\n\nSwatch Alignment\n\n\n\nThis option enables you to change the alignment of the swatches on the shop page. Currently, there are three different styles available as left, right and central.\n\n\n\n\n\n\n\nThis is how it looks on the front-end with a right alignment of the swatches\n\n\n\n\n\n\n\n Swatch Position\n\n\n\nThis option enables you to change the position of the swatches on the shop page. Currently there are 4 different positions that you can place the swatches on the shop page and they are After Price, Before Price, After Title and Before Title.\n\n\n\n\n\n\n\nHere is an example of how this looks on the front-end of the website when you place the swatches before price\n\n\n\n\n\n\n\nShow Swatches Label\n\n\n\nTurning this toggle button on will display the labels for the swatches on the shop page. As you can see in the image below that the color and label are visible stacked to the swatches.\n\n\n\n\n\n\n\n Attributes limit\n\n\n\nYou can limit the number of attributes that would be displayed on the shop page using this option. You can either leave it blank or enter 0 in the box to load all the attributes. You can choose any number of attributes that you would like to display on the shop page.\n\n\n\n\n\n\n\nFron-end view\n\n\n\n\n\n\n\nOverride global settings\n\n\n\nThis option overrides any global setting inside the plugin and allows you to set customized width, height, border radius and font size inside the shop page.\";s:3:\"url\";s:42:\"https://cartflows.com/docs/basic-settings/\";s:4:\"slug\";s:14:\"basic-settings\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-19T22:32:59+05:30\";s:8:\"category\";a:1:{i:0;s:18:\"variation-swatches\";}}i:98;O:8:\"stdClass\":8:{s:2:\"id\";i:60549;s:5:\"title\";s:49:\"How to Install Variation Swatches for WooCommerce\";s:7:\"content\";s:1075:\"The Variation Swatches for WooCommerce plugin enhances your product pages by displaying product variations using color, image, or label swatches instead of dropdowns.\n\n\n\nThis documentation shows you how to install and activate the plugin on your WordPress website.\n\n\n\nHow to install Variation Swatches for WooCommerce\n\n\n\nTo install this plugin on your WordPress site, follow the steps below.\n\n\n\nStep 1: Log in to your WordPress website\n\n\n\nWhen you log in, you will be in your Dashboard.\n\n\n\nStep 2: In the Plugins menu, click on Add New Plugin\n\n\n\nFrom your WordPress dashboard, go to Plugins &gt; Add New Plugin to open the plugin installation screen.\n\n\n\n\n\n\n\nStep 3: Search for Variation Swatches\n\n\n\nIn the search bar, search for Variation Swatches.\n\n\n\n\n\n\n\nStep 4: Click Install Now\n\n\n\nIn the Variation Swatches for WooCommerce card, click Install Now.\n\n\n\n\n\n\n\nStep 5: Click Activate\n\n\n\nOnce the installation has finished, click Activate.\n\n\n\n\n\n\n\nThe plugin is now active on your website and you can start using swatches in your WooCommerce products and CartFlows product steps.\";s:3:\"url\";s:61:\"https://cartflows.com/docs/how-to-install-variation-swatches/\";s:4:\"slug\";s:33:\"how-to-install-variation-swatches\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-09-11T11:22:24+05:30\";s:8:\"category\";a:1:{i:0;s:18:\"variation-swatches\";}}i:99;O:8:\"stdClass\":8:{s:2:\"id\";i:59947;s:5:\"title\";s:89:\"Why is Step Editing Disabled When I Try to Edit the CartFlows Checkout or Thank You Page?\";s:7:\"content\";s:1020:\"If you\'re trying to edit the CartFlows Checkout or Thank You step and see the message:\n\n\n\n\nAs the Instant Checkout is enabled in the flow settings, to customize the checkout step, use the Design tab under Step Settings.\n\n\n\n\nIt means the CartFlows Instant Checkout feature is enabled for that funnel. When Instant Checkout is enabled, page builder editing is disabled for that step. However, you can still make design-related changes using the Design tab in the Step Settings.\n\n\n\nHow to Enable Page Builder Editing:\n\n\n\nIf you\'d like to edit the step using your page builder (e.g., Elementor, Gutenberg, etc.), follow these steps to disable Instant Checkout:\n\n\n\n1) Go to your CartFlows Funnel.\n\n\n\n\n\n\n\n2) Click on the gear icon &#x2699;&#xfe0f; on the top right to open the Funnel Settings.\n\n\n\n\n\n\n\n3) In the Settings, locate the Instant Checkout toggle and disable it.\n\n\n\n\n\n\n\n4) Click Save Settings.\n\n\n\n5) Refresh the funnel page.\n\n\n\nNow, you should be able to edit the Checkout (or Thank You) step using your page builder.\";s:3:\"url\";s:116:\"https://cartflows.com/docs/why-is-step-editing-disabled-when-i-try-to-edit-the-cartflows-checkout-or-thank-you-page/\";s:4:\"slug\";s:88:\"why-is-step-editing-disabled-when-i-try-to-edit-the-cartflows-checkout-or-thank-you-page\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-05T21:30:05+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:100;O:8:\"stdClass\":8:{s:2:\"id\";i:59085;s:5:\"title\";s:44:\"Instant Layout for Upsell and Downsell Steps\";s:7:\"content\";s:1434:\"We’ve expanded our Instant Layout support to include Upsell and Downsell steps in your funnel—making it easier than ever to build high-converting funnels without relying on page builders.\n\n\n\nInstant Layout is a clean, fast-loading, conversion-focused layout built right into CartFlows. It\'s ideal for digital products like music, software, and eBooks, and offers a distraction-free experience with an intuitive interface.\n\n\n\nHow to Enable Instant Layout for Upsell/Downsell Steps\n\n\n\nThere’s no additional setup needed!\n\n\n\nIf you already have Instant Layout enabled in your funnel settings:\n\n\n\n\nThe layout will now automatically apply to your Upsell and Downsell steps.\n\n\n\nThere\'s no need to recreate or manually modify those steps.\n\n\n\n\nIf you haven’t enabled Instant Layout yet:\n\n\n\n\nGo to your Funnel &gt; Click the Settings (&#x2699;&#xfe0f;) icon in the top-right.\n\n\n\nEnable the Instant Layout toggle.\n\n\n\n\n\n\n\n\nCustomizing Upsell &amp; Downsell Steps Using Instant Layout\n\n\n\nOnce enabled, you can customize the appearance of your Upsell and Downsell steps directly in CartFlows:\n\n\n\n\nNavigate to the Funnel step list.\n\n\n\nClick Settings on your Upsell or Downsell step.\n\n\n\nA new Design tab will appear.\n\n\n\nUse the Design options to change:\n\nButton labels and styling\n\n\n\nTypography\n\n\n\nColors\n\n\n\nLayout-specific options\n\n\n\n\n\n\n\n\n\n\nThis makes customization easy without needing to open a page builder.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:66:\"https://cartflows.com/docs/instant-layout-for-upsell-and-downsell/\";s:4:\"slug\";s:38:\"instant-layout-for-upsell-and-downsell\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-04-28T23:02:21+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:101;O:8:\"stdClass\":8:{s:2:\"id\";i:58449;s:5:\"title\";s:41:\"How Product Recommendations Feature Works\";s:7:\"content\";s:1364:\"The Product Recommendations feature in Modern Cart helps you boost sales by showing related products in the cart tray. This encourages customers to add more items before checkout and can increase the average order value (AOV).\n\n\n\nNote\n1. The Product Recommendations feature is available only in Modern Cart Pro.2. This feature only works with Simple Products.\n\n\n\n\n\n\n\n\nModes\n\n\n\nThis option includes four available modes:\n\n\n\n\nDisable – Turns off the product recommendation feature.\n\n\n\nCustom – Lets you manually select specific products to display as recommendations. Refer to this doc to know more about this feature.\n\n\n\nFrom Upsells – Displays upsells products configured in WooCommerce for the item added to the cart.\n\n\n\nFrom Cross-Sells – Displays cross-sells products configured in WooCommerce for the item added to the cart.\n\n\n\n\nTo learn how to configure upsell products in WooCommerce, see this doc: How to Configure Upsell and Cross-Sell Products in WooCommerce.\n\n\n\nFrontend view\n\n\n\n\n\n\n\nRecommendation List Style\n\n\n\nAfter selecting the product recommendation source, you can also choose how the recommended products are displayed in the cart tray.\n\n\n\nThe Recommendation List Style option offers two layouts:\n\n\n\n\nStyle 1 – A compact layout suitable for simpler carts.\n\n\n\nStyle 2 – A more detailed layout with enhanced styling.\n\n\n\n\nSee it in action\";s:3:\"url\";s:51:\"https://cartflows.com/docs/product-recommendations/\";s:4:\"slug\";s:23:\"product-recommendations\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-21T20:33:21+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:102;O:8:\"stdClass\":8:{s:2:\"id\";i:58130;s:5:\"title\";s:41:\"Customize General Settings in Modern Cart\";s:7:\"content\";s:3197:\"Modern Cart for WooCommerce allows you to control the core display and cart behavior through its General panel. These options help you define how the cart appears on your store and which features you want to enable or disable.\n\n\n\nThis documentation explains how to access and configure the General settings.\n\n\n\nAccess General Settings\n\n\n\nFrom your WordPress dashboard, go to WooCommerce &gt; Modern Cart, then click on the General tab from the left side of the settings window.\n\n\n\nHere, you’ll find the following options:\n\n\n\n1. Enable Modern Cart\n\n\n\nChoose where to show the floating cart icon. You can select to show it on the entire site, only on WooCommerce pages, or disable it completely.\n\n\n\n2. Cart Type (Pro)\n\n\n\nChoose between Slideout and Popup.\n\n\n\nSlideout Cart\n\n\n\n\n\n\n\nPopup Cart\n\n\n\n\n\n\n\nRefer to this doc to learn more about Popup Cart feature.\n\n\n\n3. Cart Style\n\n\n\nChoose a cart style from six available designs (Style 1 to Style 6) to best match your store layout.Frontend view\n\n\n\n\n\n\n\nNote: Style 3 to Style 6 are available on the Pro version.\n\n\n\n4. Cart Opening Direction (Pro)\n\n\n\nChoose the open direction of the cart tray when Slideout cart type is chosen. Refer to this doc to learn more about how this feature works.\n\n\n\n5. Cart Header Style (Pro)\n\n\n\nPick a cart header design from two available styles (Style 1 and Style 2) that best suits your store\'s look and feel.Frontend view\n\n\n\n\n\n\n\n6. Order Summary Style (Pro)\n\n\n\nChoose how the order summary appears inside the cart tray. Select from two available styles (Style 1 and Style 2) that fit your store’s layout and shopping experience.Frontend view\n\n\n\n\n\n\n\n7. Cart Auto-Open Behavior (Pro)\n\n\n\nAutomatically open the cart after a product is added to help users review their items easily, great for faster checkouts! Refer to this doc to learn more about this feature.\n\n\n\n8. Display Coupon Field\n\n\n\nChoose how you want the coupon field to appear in the cart tray:\n\n\n\n\nDisabled – Hides the coupon field.\n\n\n\nMinimize – Shows the field collapsed by default.\n\n\n\nExpand – Shows the field in full view.\n\n\n\n\nFrontend view\n\n\n\n\n\n\n\n9. Show Product Image in Mobile View (Pro)\n\n\n\nUse this option to show product images in the cart on mobile devices. Disable it to hide images and keep the cart more compact for better performance on smaller screens.\n\n\n\n10. Enable Free Shipping Bar\n\n\n\nToggle this option to display a progress bar showing how close the cart is to qualifying for free shipping. If you haven’t set up Free Shipping in WooCommerce yet, refer to this doc for setup steps.Frontend view\n\n\n\n\n\n\n\n11. Show Shipping (Pro)\n\n\n\nEnable this to display the shipping cost in the cart tray.Frontend view\n\n\n\n\n\n\n\n12. Show Subtotal (Pro)\n\n\n\nEnable this to display a subtotal line in the cart tray.Frontend view\n\n\n\n\n\n\n\n13. Show Total (Pro)\n\n\n\nEnable this to display the total amount in the cart tray.Frontend view\n\n\n\n\n\n\n\n14. Show Discount (Pro)\n\n\n\nEnable this to display the discount in the cart tray, after the coupon is entered.Frontend view\n\n\n\n\n\n\n\n15. Show Tax (Pro)\n\n\n\nEnable this to display the tax in the cart tray, if any.Frontend view\n\n\n\n\n\n\n\nNote\nAll changes are saved automatically, there is no save button in the settings panel.\";s:3:\"url\";s:56:\"https://cartflows.com/docs/modern-cart-general-settings/\";s:4:\"slug\";s:28:\"modern-cart-general-settings\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-11T18:36:38+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:103;O:8:\"stdClass\":8:{s:2:\"id\";i:58113;s:5:\"title\";s:42:\"How to Enable Free Shipping in WooCommerce\";s:7:\"content\";s:595:\"Modern Cart for WooCommerce includes a Free Shipping Progress Bar that shows customers how much more they need to spend to qualify for free shipping. To make this feature work, you need to enable Free Shipping in your WooCommerce settings.\n\n\n\nFree Shipping is a core WooCommerce feature. For a complete explanation and setup steps, refer to the official WooCommerce documentation here: https://woocommerce.com/document/free-shipping/\n\n\n\nIf you prefer a visual walkthrough, you can also watch the video below that shows how to enable free shipping in WooCommerce.\n\n\n\n\nhttps://youtu.be/7s-SHvVR2Os\";s:3:\"url\";s:63:\"https://cartflows.com/docs/enable-free-shipping-in-woocommerce/\";s:4:\"slug\";s:35:\"enable-free-shipping-in-woocommerce\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-08-05T20:12:03+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:104;O:8:\"stdClass\":8:{s:2:\"id\";i:58109;s:5:\"title\";s:41:\"Customize Cart Tray Labels in Modern Cart\";s:7:\"content\";s:1710:\"Modern Cart for WooCommerce allows you to customize the text labels displayed in the cart tray. This helps you personalize the cart language to match your store’s tone and improve your customer’s shopping experience.\n\n\n\nYou can modify titles, placeholders, and button labels directly from the settings — no coding required.\n\n\n\nCustomize Cart Tray Labels\n\n\n\nFrom your WordPress dashboard, go to WooCommerce &gt; Modern Cart, then click on the Text Settings tab from the left side of the settings window.\n\n\n\nHere, you’ll find options to change the following labels:\n\n\n\n\nMain Heading – Sets the main heading for the cart. This is the most important title and helps customers understand what this section is about.\n\n\n\nProduct Recommendation Title (Pro)  – Defines the heading for the recommendation slider to grab customer attention.\n\n\n\nEmpty Cart Recommendation Title – Set a clear and engaging title for your empty cart recommendation area. This appears above the product recommendation when the cart is empty.\n\n\n\nCoupon Field Title – Sets a title above the coupon field so customers know its purpose.\n\n\n\nCoupon Field Placeholder – Defines the placeholder text inside the coupon input field (e.g., \"Enter your coupon code\").\n\n\n\nCheckout Button Text – Customizes the checkout button label to match your store’s style and guide customers clearly.\n\n\n\nFree Shipping Bar Text – Adjusts the text in the free shipping progress bar. Use {amount} to dynamically display the remaining amount required to qualify for free shipping.\n\n\n\nDiscount Label – Defines the label used to display the sale price.\n\n\n\n\n\n\n\n\nNote\nAll changes are saved automatically, there\'s no save button in the settings panel.\";s:3:\"url\";s:56:\"https://cartflows.com/docs/customize-modern-cart-labels/\";s:4:\"slug\";s:28:\"customize-modern-cart-labels\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-21T20:32:54+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:105;O:8:\"stdClass\":8:{s:2:\"id\";i:58103;s:5:\"title\";s:42:\"Customize Cart Tray Styling in Modern Cart\";s:7:\"content\";s:2758:\"Modern Cart for WooCommerce allows you to adjust the visual appearance of the cart tray so it fits your store\'s branding and design. From colors and fonts to animation speed and layout width, the plugin provides flexible styling controls to help you customize the look and feel of the sliding cart.\n\n\n\nThis documentation explains how to access the styling settings and configure the available options.\n\n\n\nFrom your WordPress dashboard, go to WooCommerce &gt; Modern Cart, then click on the Styling tab from the left side of the settings window.\n\n\n\n\n\n\n\nCustomize Cart Tray Styling\n\n\n\nColor\n\n\n\n\nPrimary Color – Sets the main color for key cart elements, allowing you to align it with your store’s branding.\n\n\n\nButton Text Color – Adjusts the text color for buttons inside the cart.\n\n\n\nHeading Color – Controls the color of headings within the cart, helping differentiate key sections.\n\n\n\nBackground Color – Sets the overall background color of the cart tray to blend with your store’s design.\n\n\n\nBody Color – Defines the color of general text in the cart, including product names, prices, and details.\n\n\n\nHeader Font Color – Sets the color of the cart header text to match your brand style.\n\n\n\nHeader Background Color – Sets the background color of the cart header section for a cohesive look.\n\n\n\nQuantity Font Color – Sets the text color used in the quantity badge displayed next to each product.\n\n\n\nQuantity Background Color – Sets the background color of the quantity badge inside the cart tray.\n\n\n\n\nFloating Cart Icon\n\n\n\nRefer to this documentation to know more about this setting.\n\n\n\nWidth\n\n\n\n\nSlide Out Width (Desktop) – Determines how wide the cart tray appears on desktop devices, measured in pixels.\n\n\n\nSlide Out Width (Mobile) – Defines the cart tray width on mobile devices, measured in percentage.Animation Speed – Controls how fast the cart tray opens and closes, allowing for a smoother or snappier effect.\n\n\n\n\nMiscellaneous\n\n\n\n\nProduct Image Size – Defines the display size of product images inside the cart tray.\n\n\n\nCart Item Padding – Controls the spacing around each product entry in the cart tray (in pixels).\n\n\n\nAnimation Speed – Controls how fast the cart tray opens and closes, allowing for a smoother or snappier effect.\n\n\n\n\nAstra Global Color Palette Integration\n\n\n\nIf you’re using our Astra theme, Modern Cart will automatically detect Astra Global Color Palette (GCP). You’ll then have the option to link your cart tray colors with Astra’s palette, helping maintain consistent branding across your store.\n\n\n\n\n\n\n\nTo learn more about Astra’s Global Color Palette settings, refer to this documentation.\n\n\n\nNote\nAll changes are saved automatically, there’s no save button in the settings panel.\";s:3:\"url\";s:57:\"https://cartflows.com/docs/customize-modern-cart-styling/\";s:4:\"slug\";s:29:\"customize-modern-cart-styling\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-21T20:30:09+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:106;O:8:\"stdClass\":8:{s:2:\"id\";i:58096;s:5:\"title\";s:43:\"Customize Cart Icon Settings in Modern Cart\";s:7:\"content\";s:1463:\"The Floating Cart Icon settings in Modern Cart let you control how the cart button looks and behaves on your store. You can manage its visibility, placement, style, and even trigger it with a custom element.\n\n\n\nAccess Floating Cart Icon Settings\n\n\n\nTo access these settings, go to WooCommerce &gt; Modern Cart &gt; Floating Cart Icon.\n\n\n\n\n\n\n\n1. Display Floating Cart Button (Pro)\n\n\n\nUse this option to show or hide the floating cart button. This does not affect any custom triggers you may set.\n\n\n\n2. Floating Cart Button Position\n\n\n\nSelect where you want to display the floating cart button on your website.\n\n\n\n\n\n\n\n3. Hide Cart Button When Empty (Pro)\n\n\n\nEnable this option to hide the floating cart button when the cart is empty. Once a product is added, the button will reappear.\n\n\n\n\n\n\n\n4. Select Floating Cart Button Icon (Pro)\n\n\n\nChoose from predefined icons or upload a custom icon that matches your brand. Supported formats include .png, .jpg, and .svg. The recommended size is 36 × 36 px.\n\n\n\n\n\n\n\nIf you’d like to upload and use your own custom icon, see this doc for detailed steps: Use a Custom Image for the Floating Cart Icon\n\n\n\n5. Use Custom Trigger (Pro)\n\n\n\nEnter an element selector (#id or .class) to use as a custom trigger for opening the cart tray. You can also add multiple selectors separated by commas.\n\n\n\nTo learn more, see this doc: Open the Cart Using a Custom Button or Link\n\n\n\nNote\nAll changes in the settings are saved automatically.\";s:3:\"url\";s:54:\"https://cartflows.com/docs/customize-modern-cart-icon/\";s:4:\"slug\";s:26:\"customize-modern-cart-icon\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-21T20:29:25+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:107;O:8:\"stdClass\":8:{s:2:\"id\";i:58086;s:5:\"title\";s:55:\"How to Activate Modern Cart for WooCommerce License Key\";s:7:\"content\";s:1116:\"To start using Modern Cart for WooCommerce and receive automatic updates, you need to activate your license. This documentation will guide you through the process.\n\n\n\nBefore You Start\n\n\n\nBefore activating your license, make sure:\n\n\n\n\nThe Modern Cart plugin is installed and activated on your website.If you haven’t installed it yet, follow this document: How to Install Modern Cart for WooCommerce\n\n\n\nYou have access to your account to retrieve the license key.\n\n\n\n\nHow to Activate Your Modern Cart for WooCommerce License\n\n\n\nStep 1: Get Your License Key\n\n\n\n\nLog in to Membership Area.\n\n\n\nClick on API Keys from the sidebar.\n\n\n\nCopy your License Key.\n\n\n\n\n\n\n\n\nStep 2: Activate Your License in WordPress\n\n\n\n\nLog in to your WordPress dashboard.\n\n\n\nGo to WooCommerce &gt; Modern Cart.\n\n\n\nClick on the My Account tab.\n\n\n\nPaste your License Key into the provided field.\n\n\n\nClick the Activate License button.\n\n\n\n\n\n\n\n\nTroubleshooting License Activation Issues\n\n\n\nIf you’re facing problems while activating your license, refer to this document for detailed troubleshooting steps: Troubleshooting License Activation Issues\";s:3:\"url\";s:56:\"https://cartflows.com/docs/activate-modern-cart-license/\";s:4:\"slug\";s:28:\"activate-modern-cart-license\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-16T21:51:09+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:108;O:8:\"stdClass\":8:{s:2:\"id\";i:58078;s:5:\"title\";s:42:\"How to Install Modern Cart for WooCommerce\";s:7:\"content\";s:1474:\"This documentation explains how to install the Modern Cart for WooCommerce plugin on your website. You can install the plugin by downloading it from your account and uploading it to your WordPress site.\n\n\n\nNote\nTo use Modern Cart for WooCommerce, the Modern Cart Starter plugin must also be installed and activated. Refer to this doc to learn how to install Modern Cart Starter.\n\n\n\n\nSteps to Install Modern Cart for WooCommerce\n\n\n\nStep 1: Go to Your Account and Click on Your Products\n\n\n\nIn your account page, go to Your Products to view all your purchased products.\n\n\n\n\n\n\n\nStep 2: Download Modern Cart for WooCommerce\n\n\n\nClick Download to start the .zip file download.\n\n\n\n\n\n\n\nStep 3: Log in to Your WordPress Website\n\n\n\nWhen you log in, you will be in your Dashboard.\n\n\n\nStep 4: In the Plugins Menu, Click on Add New Plugin\n\n\n\nGo to Plugins &gt; Add New Plugin from the WordPress menu.\n\n\n\n\n\n\n\nStep 5: Click Upload Plugin at the Top of the Screen\n\n\n\nThe screen will expand with the option to upload a plugin.\n\n\n\n\n\n\n\nStep 6: Upload the Plugin and Click Install Now\n\n\n\nClick Choose File, select the downloaded .zip file, and then click Install Now to begin the installation.\n\n\n\n\n\n\n\nStep 7: Click Activate Plugin\n\n\n\nOnce the plugin is installed, click Activate Plugin to complete the installation.\n\n\n\n\n\n\n\nWhat’s Next?\n\n\n\nMake sure to activate your license key to start using the plugin and receive plugin updates. Click here to learn how to activate your Modern Cart license.\";s:3:\"url\";s:50:\"https://cartflows.com/docs/installing-modern-cart/\";s:4:\"slug\";s:22:\"installing-modern-cart\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-01-22T14:08:16+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:109;O:8:\"stdClass\":8:{s:2:\"id\";i:56555;s:5:\"title\";s:34:\"How to Claim Access to OttoKit Pro\";s:7:\"content\";s:486:\"If you purchase CartFlows Pro, you will receive OttoKit Pro as a bonus product. This documentation explains how you can claim access based on your purchase.\n\n\n\nClaiming Your OttoKit Pro Access\n\n\n\nTo claim your OttoKit Pro subscription:\n\n\n\n\nLog in to your CartFlows account.\n\n\n\nGo to the Your Products section from the sidebar.\n\n\n\nClick on the Redeem Now button.\n\n\n\nAfter a few minutes, you will receive an email from OttoKit with your account details.\n\n\n\n\n\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:62:\"https://cartflows.com/docs/how-to-claim-access-to-ottokit-pro/\";s:4:\"slug\";s:34:\"how-to-claim-access-to-ottokit-pro\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-09-04T17:56:44+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"account-store\";}}i:110;O:8:\"stdClass\":8:{s:2:\"id\";i:55419;s:5:\"title\";s:47:\"How to Rollback to a Previous CartFlows Version\";s:7:\"content\";s:1437:\"In this documentation, we\'ll explain how to use the new Rollback Feature in CartFlows. This feature allows you to revert to a previous version of the CartFlows plugin in case you encounter any issues after an update.\n\n\n\nHow to Use the Rollback Feature\n\n\n\nTo use the Rollback feature in CartFlows, follow the steps below.\n\n\n\n1. Navigate to the CartFlows SettingsGo to CartFlows > Settings.\n\n\n\n2. Locate the Version Control SectionIn the Settings window, find the Version Control section on the sidebar. This section allows you to revert to a previous version of the CartFlows plugin.\n\n\n\n\n\n\n\n3. Select the Version to RollbackIn the Version Control section, you will see a dropdown menu listing the previous versions of CartFlows. Select the version you want to revert to.\n\n\n\n\n\n\n\n4. Click RollbackAfter selecting the desired version, click the Rollback button. The plugin will automatically revert to the selected version.\n\n\n\n\n\n\n\n5. Confirm and Return to Plugins PageOnce the rollback process is complete, you will see a confirmation message. Your CartFlows plugin is now reverted to the selected version. Click the Go to Plugins page link to return to the Plugins page.\n\n\n\n\n\n\n\nNote\nBackup Your Site: Before performing a rollback, it is recommended to take a full backup of your website to avoid any data loss.Compatibility: Ensure that the version you are rolling back to is compatible with your current WordPress and WooCommerce versions.\";s:3:\"url\";s:66:\"https://cartflows.com/docs/rollback-to-previous-cartflows-version/\";s:4:\"slug\";s:38:\"rollback-to-previous-cartflows-version\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-04T18:42:09+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:111;O:8:\"stdClass\":8:{s:2:\"id\";i:55392;s:5:\"title\";s:24:\"How to Install CartFlows\";s:7:\"content\";s:1205:\"Thank you for choosing CartFlows for your website! In this documentation, we’ll explain how to install the CartFlows plugin on your WordPress website. If you are looking for instructions on how to install the CartFlows Pro plugin, we have a separate document.\n\n\n\nHow to install CartFlows\n\n\n\nTo install the free CartFlows plugin on your WordPress site, follow the steps below.\n\n\n\nStep 1: Log in to your WordPress website\n\n\n\nWhen you log in, you will be in your Dashboard.\n\n\n\nStep 2: In the Plugins menu, click on Add New Plugin\n\n\n\nFrom your WordPress dashboard, go to Plugins &gt; Add New Plugin to open the plugin installation screen.\n\n\n\n\n\n\n\nStep 3: Search for CartFlows\n\n\n\nIn the search bar, search for CartFlows.\n\n\n\n\n\n\n\nStep 4: Click Install Now\n\n\n\nIn the WooCommerce Checkout &amp; Funnel Builder by CartFlows card, click Install Now.\n\n\n\n\n\n\n\nStep 5: Click Activate\n\n\n\nOnce the installation has finished, click Activate.\n\n\n\n\n\n\n\nCongratulations! You’ve successfully installed the CartFlows plugin on your website. You can now go and configure the plugin.\n\n\n\nHow do I use CartFlows?\n\n\n\nWant to start using CartFlows immediately? Check out the overall CartFlows guide to get the most out of the plugin!\";s:3:\"url\";s:57:\"https://cartflows.com/docs/how-to-install-cartflows-free/\";s:4:\"slug\";s:29:\"how-to-install-cartflows-free\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-12-25T17:10:06+05:30\";s:8:\"category\";a:1:{i:0;s:20:\"installation-updates\";}}i:112;O:8:\"stdClass\":8:{s:2:\"id\";i:54534;s:5:\"title\";s:51:\"How to Enable Snapchat Pixel Tracking in CartFlows?\";s:7:\"content\";s:1390:\"CartFlows v2.1.0 now includes native integration for Snapchat Pixel, enabling you to track user actions and optimize your Snapchat ad campaigns effortlessly. This article provides a step-by-step guide to setting up and using Snapchat Pixel in CartFlows\n\n\n\nLet\'s get started.\n\n\n\nPre-requisites –\n\n\n\nThere are few Pre-requisites like –\n\n\n\n\nYou need to create a Snapchat ADs account.. Haven\'t Setup yet? – follow the steps here\n\n\n\nNext, you need to get the Snapchat ID, follow the steps here.\n\n\n\nCopy the Snapchat ID, you will need to paste it in the CartFlows Settings\n\n\n\n\nSteps to Add Snapchat Pixel ID in the CartFlows Settings –\n\n\n\nStep 1: From your WordPress dashboard, go to CartFlows &gt; Settings &gt; Integrations\n\n\n\n\n\n\n\n\n\n\n\nStep 2: Scroll down to the Snapchat Pixel Settings and enable the option – Enable for CartFlows pages.\n\n\n\n\n\n\n\n\n\n\n\nStep 3: Now, you will see a field to insert the Snapchat pixel ID. You can paste your Snapchat ID there.\n\n\n\n\n\n\n\nAfter adding the pixel ID you can enable the option to add the Snapchat Tracking code to enable the Snapchat Tracking Code on the whole website.\n\n\n\nStep 4: Next, you can enable the Events which CartFlows provides, they are –\n\n\n\n\nBegin Checkout\n\n\n\nAdd To Cart\n\n\n\nAdd Payment Info\n\n\n\nPurchase\n\n\n\nSubscribe\n\n\n\nOptin Lead\n\n\n\n\n\n\n\n\nStep 5: Just Save the Changes and you have successfully added Snapchat Pixel for the CartFlows.\";s:3:\"url\";s:50:\"https://cartflows.com/docs/snapchat-pixel-support/\";s:4:\"slug\";s:22:\"snapchat-pixel-support\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-04-29T18:37:10+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:113;O:8:\"stdClass\":8:{s:2:\"id\";i:54523;s:5:\"title\";s:51:\"How to Enable Pinterest Pixel Tracking in CartFlows\";s:7:\"content\";s:1236:\"CartFlows lets you connect your funnels with Pinterest Pixel to measure conversions and optimize your Pinterest ad campaigns. By adding your Pinterest Tag ID, you can track key actions like checkout, purchase, and opt-in directly within your funnel steps.\n\n\n\nThis documentation explains how to set up and enable Pinterest Pixel tracking in CartFlows.\n\n\n\nPrerequisites\n\n\n\nBefore you begin, make sure you have:\n\n\n\n\nA Pinterest Business account. Learn how to create one here.\n\n\n\nYour Pinterest Tag ID. Find your Tag ID here.\n\n\n\n\nHow to Enable Pinterest Pixel Tracking\n\n\n\n1. Go to CartFlows > Settings > Integrations tab on the sidebar.\n\n\n\n\n\n\n\n2. Add your Pinterest Tag ID into the field provided.\n\n\n\n\n\n\n\n3. (Optional) Enable the toggle to add Pinterest tracking code across your entire website.\n\n\n\n\n\n\n\n4. Enable the Consent Notice option.\n\n\n\n\n\n\n\nThis displays a short notice on the frontend for users, as required by Pinterest before events can be tracked.\n\n\n\n\n\n\n\n5. Choose the events you want to track. CartFlows supports the following:\n\n\n\n\nBegin Checkout\n\n\n\nAdd to Cart\n\n\n\nAdd Payment Info\n\n\n\nPurchase\n\n\n\nSignup\n\n\n\nOpt-in Lead\n\n\n\n\n\n\n\n\nOnce you’ve saved your settings, Pinterest Pixel tracking will be active for your CartFlows funnels.\";s:3:\"url\";s:51:\"https://cartflows.com/docs/pinterest-pixel-support/\";s:4:\"slug\";s:23:\"pinterest-pixel-support\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-27T16:46:54+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:114;O:8:\"stdClass\":8:{s:2:\"id\";i:54093;s:5:\"title\";s:48:\"How to Enable TikTok Pixel Tracking in CartFlows\";s:7:\"content\";s:1436:\"CartFlows supports TikTok Pixel tracking to help you measure conversions and optimize your ad campaigns. This feature allows you to track important user actions such as checkout, purchases, and opt-ins directly within your CartFlows funnel steps.\n\n\n\nBy adding your TikTok Pixel ID, you can connect your website activity with your TikTok Ads Manager and gain better insights into performance.\n\n\n\nPrerequisites\n\n\n\nBefore enabling TikTok Pixel tracking in CartFlows, make sure you have:\n\n\n\n\nA TikTok Ads Manager Account. Create one here.\n\n\n\nA TikTok Pixel ID.\n\n\n\n\nHow to Enable TikTok Pixel Tracking\n\n\n\n1. Go to CartFlows &gt; Settings &gt; Integrations.\n\n\n\n2. Scroll down to the TikTok Pixel tab and enable the toggle to activate TikTok tracking on CartFlows pages.\n\n\n\n\n\n\n\n3. Enter your TikTok Pixel ID in the field.\n\n\n\n\n\n\n\n4. (Optional) Enable the toggle to add TikTok tracking code across your entire website.\n\n\n\n\n\n\n\n5. Choose the events you want to track. CartFlows supports the following:\n\n\n\n\nBegin Checkout\n\n\n\nAdd To Cart\n\n\n\nView Content\n\n\n\nAdd Payment Info\n\n\n\nPurchase\n\n\n\nOptin Lead\n\n\n\n\n\n\n\n\nAfter saving your settings, TikTok Pixel tracking will automatically start working across your CartFlows funnels.\n\n\n\nHow to Verify TikTok Pixel Tracking\n\n\n\nYou can confirm your TikTok Pixel setup using the TikTok Pixel Helper Chrome extension. This extension will show whether the pixel is firing correctly on your checkout and funnel pages.\";s:3:\"url\";s:48:\"https://cartflows.com/docs/tiktok-pixel-support/\";s:4:\"slug\";s:20:\"tiktok-pixel-support\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-26T20:12:10+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:115;O:8:\"stdClass\":8:{s:2:\"id\";i:54196;s:5:\"title\";s:36:\"CartFlows Bricks Builder Integration\";s:7:\"content\";s:3316:\"CartFlows 2.1.0 introduces full integration with Bricks Builder. This integration allows you to design and customize every step of your sales funnels—including Opt-in, Checkout, Thank You, Upsell, and Downsell—directly within Bricks Builder.\n\n\n\nKey Features of Bricks Builder Integration\n\n\n\n\nEnhanced Design Flexibility: Customize funnel layouts directly without the need for additional tools.\n\n\n\nDynamic Content Tags: Display relevant product information throughout your funnels using dynamic tags.\n\n\n\nPre-Configured Options: Utilize ready-made design options for upsell and downsell steps to streamline the setup process.\n\n\n\n\nThese features enable you to create high-converting, branded sales funnels in WordPress with ease.\n\n\n\nHow to Enable Bricks Builder for CartFlows\n\n\n\nTo start using Bricks Builder with CartFlows, follow these steps to enable it as your default editor:\n\n\n\n\nAccess CartFlows Settings: From your WordPress dashboard, navigate to CartFlows &gt; Settings.\n\n\n\nEnable Bricks Builder:\n\nIn the General tab, locate the Builder Settings section.\n\n\n\nSelect Bricks Builder as your default page builder for CartFlows.\n\n\n\n\n\nSave Changes: Click Save to apply your settings.\n\n\n\n\n\n\n\n\nAfter these steps, Bricks Builder will be available as the primary editor for designing CartFlows steps. You can now customize each step of your funnel using Bricks Builder’s robust tools.\n\n\n\nCartFlows Widgets for Bricks Builder\n\n\n\nWith Bricks Builder enabled, you have access to dedicated CartFlows widgets to customize each part of your funnel:\n\n\n\n\nOpt-in Step: Design a customized opt-in page for lead collection by adding dynamic fields and engaging elements.\n\n\n\nCheckout Step: Create a branded checkout experience by incorporating custom elements and interactive features.\n\n\n\nThank You Step: Personalize your Thank You page with tailored messages, suggested next steps, or additional product recommendations.\n\n\n\nUpsell and Downsell Steps: Use dedicated widgets to build upsell and downsell pages. Customize accept/reject buttons and display relevant product information to create a seamless user experience.\n\n\n\n\n\n\n\n\nDynamic Content Tags\n\n\n\nThe integration introduces dynamic content tags, letting you insert personalized data within each funnel step. Examples include:\n\n\n\n\nProduct Information:\n\nProduct Title: Displays the name of the product.\n\n\n\nProduct Description: Provides detailed product information.\n\n\n\nProduct Price: Shows the current product pricing.\n\n\n\nProduct Quantity: Indicates the number of products, which is useful for bundles.\n\n\n\nProduct Variation: Displays options such as size or color.\n\n\n\n\n\nNext-Step Button: Guides users to the subsequent step in the funnel with a clear call-to-action.\n\n\n\nAccept/Reject Buttons: Particularly useful in upsell and downsell scenarios, these buttons allow users to quickly respond to offers.\n\n\n\n\n\n\n\n\nUsing these dynamic tags, you can tailor the checkout experience to each user, enhancing both functionality and personalization.\n\n\n\nFixed Layout Options for Upsell and Downsell Steps\n\n\n\nCartFlows offers pre-configured layouts for upsell and downsell pages within Bricks Builder. These fixed layouts are designed for quick setup and consistency, ensuring your additional offers are presented in an optimized and cohesive manner.\n\n\n\n\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:65:\"https://cartflows.com/docs/cartlflows-bricks-builder-integration/\";s:4:\"slug\";s:37:\"cartlflows-bricks-builder-integration\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-05T20:38:11+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:116;O:8:\"stdClass\":8:{s:2:\"id\";i:54198;s:5:\"title\";s:32:\"OttoKit Integration in CartFlows\";s:7:\"content\";s:2186:\"CartFlows now offers a seamless OttoKit integration, allowing WooCommerce store owners to automate tasks and enhance customer engagement. With this integration, you can set up workflows to track specific actions like opt-ins, upsell responses, or downsell interactions, all directly from your CartFlows dashboard. This helps with targeted marketing, CRM updates, and triggering emails based on user activity without the need to switch between different tools.\n\n\n\nWhat is OttoKit?\n\n\n\nOttoKit is an automation platform that connects multiple apps and simplifies workflows by triggering actions based on specific events.\n\n\n\nVisit OttoKit website\n\n\n\nHow to Use OttoKit Integration\n\n\n\nStep 1: Access Automation Menu\n\n\n\nIn your CartFlows Settings, locate the new Automations menu under Integrations and Extensions.\n\n\n\n\n\n\n\nStep 2: Install or Access OttoKit\n\n\n\nIf OttoKit is not yet installed, you can do so from the Automations tab. If it’s already installed, click Create Workflow to start.\n\n\n\n\n\n\n\nStep 3: Configure Workflow for Funnel Steps\n\n\n\nTo create workflows for specific funnel steps like Checkout, Upsell, or Downsell:\n\n\n\n1: Open the funnel editor and select the step you want to automate.\n\n\n\n\n\n\n\n2: Click Automation to open the OttoKit window for that step.\n\n\n\n\n\n\n\nPro Tip: Workflows created here will also appear in your OttoKit account. Any updates will sync automatically between CartFlows and OttoKit.\n\n\n\nExample: Add Users Who Declined an Upsell to Google Sheets\n\n\n\n1: In OttoKit, create a workflow using CartFlows as the app and select Upsell Declined as the trigger event.\n\n\n\n\n\n\n\n2: Connect OttoKit to CartFlows. For guidance, refer to OttoKit WordPress Integration.\n\n\n\n\n\n\n\n3: In the Configure tab, select your funnel and the upsell step.\n\n\n\n\n\n\n\n4: Test the connection by clicking Fetch Data, then click Save.\n\n\n\n\n\n\n\n5: Choose your action app—here, select Google Sheets.\n\n\n\n\n\n\n\n6: Connect Google Sheets, choose the action Add New Row, and select your spreadsheet and worksheet.\n\n\n\n\n\n\n\n\n\n\n\n7: Test the connection using Test Action, then activate the workflow.\n\n\n\n\n\n\n\nNow, each time a user declines the upsell, their information is automatically added to your Google Sheets.\";s:3:\"url\";s:60:\"https://cartflows.com/docs/ottokit-integration-in-cartflows/\";s:4:\"slug\";s:32:\"ottokit-integration-in-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-03T18:20:03+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:117;O:8:\"stdClass\":8:{s:2:\"id\";i:54200;s:5:\"title\";s:58:\"CartFlows Instant Layout for Checkout &amp; Thank You Step\";s:7:\"content\";s:3584:\"CartFlows offers an Instant layout for Checkout and Thank you steps designed for a quick and seamless purchase experience. This layout features a clean and minimal user interface, optimized for selling items like e-books, music, and other digital goods. It removes unnecessary distractions and skips the need for page builders, offering a fast and simple checkout process.\n\n\n\nThis layout includes a modern, conversion-focused design with essential customization options. It\'s ideal for users who want a straightforward solution that integrates seamlessly with their existing CartFlows funnels or store checkout.\n\n\n\nHow to Setup Instant Layout\n\n\n\nStep 1: Go to the funnel in which you would like to enable the Instant Layout.\n\n\n\n\n\n\n\nStep 2: Click the Funnel Settings button (cog icon) in the top-right corner of the screen.\n\n\n\n\n\n\n\nStep 5: Navigate to the Instant Layout section on the sidebar and enable the toggle to activate the Instant layout.\n\n\n\n\n\n\n\nWhy&nbsp;the&nbsp;Company&nbsp;Field&nbsp;Isn\'t&nbsp;Visible&nbsp;in&nbsp;the&nbsp;Instant&nbsp;Layout\n\n\n\nWhen the Instant Layout is enabled, the&nbsp;Company&nbsp;field is not displayed on the checkout page. This&nbsp;applies&nbsp;even&nbsp;if&nbsp;the&nbsp;field&nbsp;is&nbsp;turned&nbsp;on&nbsp;in&nbsp;the&nbsp;Checkout&nbsp;Field&nbsp;Editor.\n\n\n\nThis is intentional. As mentioned above, the Instant Layout is built around a minimal, distraction-free checkout aimed at quick purchases of digital products such as e-books, courses, and music. Fields that aren\'t&nbsp;essential to completing the order are left out so buyers see fewer inputs and can complete the purchase faster. The Company field falls into that category, so this layout&nbsp;doesn\'t&nbsp;render&nbsp;it.\n\n\n\nYou\'ll also find this noted directly in the editor. Open your Checkout step, go to&nbsp;the&nbsp;Checkout&nbsp;Field&nbsp;Editor,&nbsp;and&nbsp;hover&nbsp;over&nbsp;the&nbsp;help&nbsp;icon&nbsp;next&nbsp;to&nbsp;the&nbsp;Company&nbsp;field.&nbsp;The&nbsp;tooltip&nbsp;reads:\n\n\n\n\nThe Company field won\'t be visible if you\'re using the Instant Layout Style.\n\n\n\n\n\n\n\n\nIf collecting a company name is a requirement for your store, we recommend using one of the other checkout layouts instead.&nbsp;Those&nbsp;display&nbsp;the&nbsp;Company&nbsp;field&nbsp;normally&nbsp;once&nbsp;it\'s&nbsp;enabled&nbsp;in&nbsp;the&nbsp;Checkout&nbsp;Field&nbsp;Editor.\n\n\n\nWhy Step Editing Is Disabled in the Instant Layout\n\n\n\nWhen the Instant Layout is enabled for a funnel, you won\'t be able to edit its steps directly with a page builder. This is expected rather than a problem. The Instant Layout&nbsp;renders its own ready-made design, which is exactly what lets it skip the page&nbsp;builder,&nbsp;so&nbsp;there&nbsp;is&nbsp;no&nbsp;builder&nbsp;canvas&nbsp;to&nbsp;open.\n\n\n\nHovering over the&nbsp;disabled&nbsp;edit&nbsp;option&nbsp;shows&nbsp;this&nbsp;note:\n\n\n\n\nStep Editing is DisabledYou can\'t edit this step directly because Instant Layout is turned on in the funnel settings. To make design changes, go to the Design tab inside this step\'s settings.\n\n\n\n\n\n\n\n\nAll of the Instant Layout\'s appearance settings live in that Design tab. Open the step, go to&nbsp;Design, and you\'ll find the options for customizing how your Instant&nbsp;page&nbsp;looks.\n\n\n\nIf you need full control&nbsp;over&nbsp;the&nbsp;page&nbsp;with&nbsp;a&nbsp;page&nbsp;builder,&nbsp;turn&nbsp;the&nbsp;Instant&nbsp;Layout&nbsp;toggle&nbsp;off&nbsp;in&nbsp;the&nbsp;funnel&nbsp;settings.&nbsp;The&nbsp;step&nbsp;will&nbsp;then&nbsp;open&nbsp;in&nbsp;your&nbsp;page&nbsp;builder&nbsp;as&nbsp;usual\";s:3:\"url\";s:52:\"https://cartflows.com/docs/cartflows-instant-layout/\";s:4:\"slug\";s:24:\"cartflows-instant-layout\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-12T00:16:30+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:118;O:8:\"stdClass\":8:{s:2:\"id\";i:54153;s:5:\"title\";s:77:\"How to Fix Blank Page Issue When Importing CartFlows Templates with Elementor\";s:7:\"content\";s:1172:\"If you are importing CartFlows Elementor templates and encounter a blank page, don’t worry this guide will help you resolve it.\n\n\n\nThis issue happens because CartFlows’ updated Elementor templates are built using Flexbox and Grid Containers, which are not enabled by default in Elementor. These layout features improve responsiveness and flexibility, but if disabled, Elementor cannot render the templates, resulting in a blank page when importing or editing them.\n\n\n\nHow to Fix the Blank Page Issue\n\n\n\nTo resolve the problem, enable the Flexbox and Grid Container features in Elementor:\n\n\n\n\nLog in to your WordPress dashboard.\n\n\n\nGo to Elementor > Settings.\n\n\n\nOpen the Features tab.\n\n\n\nEnable the Container option.\n\n\n\n\n\n\n\n\nAfter enabling this feature, your templates should display correctly.\n\n\n\nFor more details, you can also check Elementor’s article on experimental features: Elementor Experiments\n\n\n\nWhat to Do if the Issue Persists\n\n\n\nIf enabling Container option doesn’t fix the issue:\n\n\n\n\nUpdate Elementor and CartFlows to the latest versions.\n\n\n\nClear your browser cache and refresh the page.\n\n\n\nIf the problem continues, please contact our support team.\";s:3:\"url\";s:104:\"https://cartflows.com/docs/how-to-fix-the-blank-page-issue-when-importing-cartflows-elementor-templates/\";s:4:\"slug\";s:76:\"how-to-fix-the-blank-page-issue-when-importing-cartflows-elementor-templates\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-15T21:47:28+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:119;O:8:\"stdClass\":8:{s:2:\"id\";i:54122;s:5:\"title\";s:43:\"How to Enable Google Ads Pixel in CartFlows\";s:7:\"content\";s:1816:\"CartFlows supports Google Ads Pixel tracking to help you measure conversions and optimize your campaigns. This feature enables you to track key user actions such as checkouts, purchases, and opt-ins directly within your CartFlows funnel steps.\n\n\n\nBy adding your Google Ads Conversion ID and Label, you can connect website activity with your Google Ads campaigns, giving you valuable insights to improve performance and maximize results.\n\n\n\nPrerequisites\n\n\n\nBefore setting up Google Ads Pixel tracking in CartFlows, make sure to complete the following steps:\n\n\n\n\nCreate a Google Ads Manager account.Not done yet? You can follow the official steps here.\n\n\n\nGenerate your Google Ads Conversion ID and Conversion Label from your Google Ads account.You will need to paste these into the CartFlows settings panel.\n\n\n\n\nHow to Set Up Google Ads Pixel in CartFlows\n\n\n\nStep 1: Access CartFlows Settings\n\n\n\nFrom your WordPress dashboard, go toCartFlows &gt; Settings &gt; Integrations\n\n\n\n\n\n\n\nStep 2: Enable Google Ads Pixel Tracking\n\n\n\nScroll down to the Google Ads Pixel Settings section and toggle the optionEnable Google Ads pixel Tracking.\n\n\n\n\n\n\n\nStep 3: Add Your Conversion ID &amp; Label\n\n\n\nOnce enabled, fields will appear where you can paste yourGoogle Ads Conversion ID and Google Ads Conversion Label.\n\n\n\n\n\n\n\nStep 4: Enable Event Tracking\n\n\n\nCartFlows provides support for multiple tracking events. You can enable the ones you want to track:\n\n\n\n\nBegin Checkout\n\n\n\nAdd To Cart\n\n\n\nView Content\n\n\n\nAdd Payment Info\n\n\n\nPurchase\n\n\n\nOpt-in Lead\n\n\n\n\nHow to Verify the Tracking Setup\n\n\n\nTo confirm that your pixel is working correctly, use the Google Tag Assistant browser extension. It validates the implementation of your Google Ads conversion tags and tracking codes on any page of your site.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:52:\"https://cartflows.com/docs/google-ads-pixel-support/\";s:4:\"slug\";s:24:\"google-ads-pixel-support\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-12T18:08:26+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:120;O:8:\"stdClass\":8:{s:2:\"id\";i:51580;s:5:\"title\";s:29:\"How to import Divi templates?\";s:7:\"content\";s:1788:\"CartFlows offers seamless compatibility with the Divi Builder. While direct importing of Divi templates was discontinued starting from CartFlows version 2.0, you can still use Divi templates by downloading and manually importing them into your funnels.\n\n\n\nThis documentation will walk you through downloading, importing, and using Divi templates within CartFlows.\n\n\n\nStep 1: Download the Divi Templates\n\n\n\nYou can download the available Divi templates as a zip file from the following link: Divi Templates Zip.After downloading, extract the zip file and choose the specific funnel or step JSON file you want to import.\n\n\n\nStep 2: Import the Templates into CartFlows\n\n\n\n2.1 – Set the Page Builder Option\n\n\n\nGo to CartFlows &gt; Settings &gt; General and set the Page Builder option to Other.\n\n\n\n\n\n\n\n2.2 – Access the Funnels Page\n\n\n\nNavigate to CartFlows &gt; Funnels and click the Import button at the top of the screen.\n\n\n\n\n\n\n\n2.3 – Select the Template JSON File\n\n\n\nFrom the extracted zip folder, locate the desired Divi template .json file and select it.\n\n\n\n\n\n\n\n2.4 – Complete the Import\n\n\n\nClick Import to upload and apply the template. Once imported, the funnel will appear in your Funnels list.\n\n\n\n\n\n\n\n2.5 – Edit with Divi\n\n\n\nYou can now begin customizing the imported funnel using the Divi Builder to match your brand and layout preferences.\n\n\n\nFrequently Asked Questions\n\n\n\n1. I’m unable to edit CartFlows pages using Divi. What should I do? Ensure that the CartFlows step type are enabled for editing in the Divi Builder. This allows Divi to properly render and edit CartFlows steps.\n\n\n\n\n\n\n\n2. Where can I find CartFlows page shortcodes? Set the Page Builder option to Other. Then, go to the funnel step’s Settings &gt; Design tab to view the shortcode for that step.\";s:3:\"url\";s:56:\"https://cartflows.com/docs/how-to-import-divi-templates/\";s:4:\"slug\";s:28:\"how-to-import-divi-templates\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-13T13:27:13+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:121;O:8:\"stdClass\":8:{s:2:\"id\";i:49008;s:5:\"title\";s:37:\"Overview: Modern Cart for WooCommerce\";s:7:\"content\";s:1964:\"Modern Cart for WooCommerce enhances the default cart experience by introducing a sleek, distraction-free sliding cart interface. It allows customers to view their cart, apply coupons, see progress toward free shipping, and proceed to checkout, all without leaving the current page.\n\n\n\n\nhttps://youtu.be/jAsON8waa8g\n\n\n\n\nThis documentation provides a quick overview of the plugin’s purpose and key features before moving on to setup and customization options.\n\n\n\nGetting Started:\n\n\n\nTo get started with Modern Cart:\n\n\n\n\nInstall and activate the plugin.\n\n\n\nNavigate to WooCommerce &gt; Modern Cart from your WordPress dashboard.\n\n\n\nConfigure the settings based on your store’s needs and preferences.\n\n\n\n\nKey Features:\n\n\n\nBoost conversions and simplify the checkout experience with the below powerful Modern Cart features.\n\n\n\n\nFloating Cart Interface:A modern and customizable floating cart that appears across your site, allowing customers to access their cart anytime without page reloads.\n\n\n\nFree Shipping Progress Bar:Show customers how much more they need to spend to qualify for free shipping, a simple and effective upsell strategy.\n\n\n\nProduct Recommendations:Highlight linked products such as upsells or cross-sells to increase average order value.\n\n\n\nCustomizable Coupon Field:Choose between a minimized or traditional coupon field style, or disable it entirely.\n\n\n\nSubtotal and Total Display:Show cart subtotal and total directly within the cart panel for price clarity.\n\n\n\nText Customization:Modify cart-related labels, titles, placeholders, and button text to match your store’s tone and branding.\n\n\n\nFloating Cart Icon Positioning:Adjust the position of the floating cart icon (bottom right or left), or disable it if not needed.\n\n\n\nStyling Options:Customize the cart’s color scheme, width, and animation speed to better match your store design.\n\n\n\n\nNeed help installing the plugin? Refer to this documentation: How to Install Modern Cart Starter\";s:3:\"url\";s:55:\"https://cartflows.com/docs/modern-cart-for-woocommerce/\";s:4:\"slug\";s:27:\"modern-cart-for-woocommerce\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-09-23T18:44:50+05:30\";s:8:\"category\";a:1:{i:0;s:27:\"modern-cart-for-woocommerce\";}}i:122;O:8:\"stdClass\":8:{s:2:\"id\";i:48509;s:5:\"title\";s:40:\"Reimagined for Better Accuracy and Speed\";s:7:\"content\";s:1487:\"We’ve completely revamped how funnel analytics works in CartFlows to give you faster, more reliable insights, without any manual setup.\n\n\n\nThe new analytics implementation is now built into CartFlows by default and replaces the older tracking method. Designed for accuracy and performance, this updated approach uses a lightweight combination of API-based tracking and JavaScript to ensure your funnel data is processed efficiently across all steps.\n\n\n\nWhat’s New with Flow Analytics?\n\n\n\n\nImproved tracking accuracy: No more reliance on unstable cookie behavior, analytics now work more reliably across funnels.\n\n\n\nOptimized performance: Faster page transitions and better funnel step tracking, even on high-traffic websites.\n\n\n\nEfficient cookie usage: The new system handles cookies in a smarter way to reduce conflicts with caching tools and server settings.\n\n\n\nSimplified setup: No toggles or settings to enable, this feature is already active in your CartFlows installation.\n\n\n\n\nHow It Works\n\n\n\nThe new flow tracking uses two types of cookies to monitor visitor activity:\n\n\n\n\nwcf-visited-flow-&lt;flow_id>\n\n\n\nwcf-step-visited-&lt;flow_id>\n\n\n\n\nThese cookies are lightweight and used only for tracking how users navigate through your funnels.\n\n\n\nFrequently Asked Questions\n\n\n\n\n\n\n\n\n\n\n\n\n\nContact your hosting provider to confirm if a prefix is needed.\n\n\n\nNo action is required on your end, just keep building funnels and enjoy faster, more reliable analytics tracking with CartFlows!\";s:3:\"url\";s:51:\"https://cartflows.com/docs/improved-flow-analytics/\";s:4:\"slug\";s:23:\"improved-flow-analytics\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-01-23T19:00:12+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"flows-analytics\";}}i:123;O:8:\"stdClass\":8:{s:2:\"id\";i:48338;s:5:\"title\";s:72:\"How to Use the &#8220;Order Custom Field&#8221; Rule with Dynamic Offers\";s:7:\"content\";s:2226:\"CartFlows allows you to display specific upsell or downsell offers based on values customers enter in checkout fields. This can be useful when you want to personalize offers depending on customer selections during checkout.\n\n\n\nThe Order Custom Field rule in Dynamic Offers lets you compare values submitted through checkout fields and then show a specific offer based on those values. This works with:\n\n\n\n\nDefault WooCommerce checkout fields\n\n\n\nCustom fields created using the CartFlows Checkout Field Editor\n\n\n\n\nAdditionally, the Checkout Field Editor includes a Show in Email option. Enabling this option ensures that the custom field value is included in the order email notifications.\n\n\n\nBelow is an example workflow showing how to configure a Dynamic Offer using a custom checkout field.\n\n\n\nBefore You Begin\n\n\n\nMake sure you have already created a custom checkout field. If you are unsure how to create one, refer to the documentation on adding custom fields to the CartFlows checkout page.\n\n\n\nConfigure the Order Custom Field Rule\n\n\n\nStep 1: Open the Checkout Field Editor\n\n\n\nNavigate to the Checkout Field Editor and locate the custom field you want to use for your Dynamic Offer condition.\n\n\n\n\n\n\n\nStep 2: Copy the Field ID\n\n\n\nOnce you find the field, open its options and copy the Field ID. This ID will be used when creating the rule.\n\n\n\n\n\n\n\nStep 3: Open the Checkout Step Settings\n\n\n\nGo to your Funnel, open the Checkout step, and navigate to the Dynamic Offers tab.\n\n\n\nEnable Dynamic Offers if it is not already enabled.\n\n\n\n\n\n\n\nStep 4: Add a New Rule\n\n\n\nAdd a new rule and configure it as follows:\n\n\n\n\nSelect Order Custom Field as the rule type\n\n\n\nChoose the appropriate condition (for example, equals or not equals)\n\n\n\nPaste the Field ID you copied earlier\n\n\n\nEnter the expected value that should trigger the offer\n\n\n\n\nMake sure the expected value exactly matches the value defined in the field options when the custom field was created.\n\n\n\n\n\n\n\nStep 5: Save the Settings\n\n\n\nClick Save Settings to apply the rule.\n\n\n\nOnce saved, CartFlows will evaluate the value entered in the checkout field during the order process. If the condition matches, the configured upsell or downsell offer will be displayed accordingly.\";s:3:\"url\";s:63:\"https://cartflows.com/docs/use-custom-fields-in-dynamic-offers/\";s:4:\"slug\";s:35:\"use-custom-fields-in-dynamic-offers\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-04-28T22:43:47+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:124;O:8:\"stdClass\":8:{s:2:\"id\";i:48413;s:5:\"title\";s:47:\"How to Modify Offer Accept/Reject Popup Strings\";s:7:\"content\";s:1463:\"In CartFlows versions 1.11.5 and 1.11.6, we introduced new options that allow you to customize the text strings displayed on the offer accept/reject popup.This feature was added based on user feedback, making it easier for everyone to personalize the offer messaging without needing custom code.\n\n\n\n\n\n\n\nHow to Update Offer Popup Strings\n\n\n\nStep 1: Open Your Funnel\n\n\n\nGo to your CartFlows dashboard and open the funnel you want to modify.\n\n\n\n\n\n\n\nStep 2: Edit the Upsell or Downsell Step\n\n\n\nClick on the Settings icon (cogwheel) next to the upsell or downsell step you want to edit.\n\n\n\n\n\n\n\nStep 3: Access the Settings Panel\n\n\n\nOnce inside the step settings editor, click on the Settings tab.\n\n\n\n\n\n\n\nStep 4: Find the Offer Popup Strings Section\n\n\n\nUnder the settings, scroll down to locate the Offer Popup Strings section.\n\n\n\n\n\n\n\nHere, you will see four fields where you can customize the popup messages:\n\n\n\n\nOffer Processing: Message displayed while the offer is being processed.\n\n\n\nOffer Success: Message shown when the product is successfully added to the order.\n\n\n\nOffer Failure: Message shown if the offer is rejected or an error occurs.\n\n\n\nOffer Success Note: Additional success note displayed after a successful action.\n\n\n\n\nStep 5: Save Your Changes\n\n\n\nAfter updating the text strings, click the Save Settings button to apply the changes.\n\n\n\nBy updating these fields, you can create a more personalized experience for your customers during the offer process.\";s:3:\"url\";s:54:\"https://cartflows.com/docs/modify-offer-popup-strings/\";s:4:\"slug\";s:26:\"modify-offer-popup-strings\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-04T23:10:19+05:30\";s:8:\"category\";a:1:{i:0;s:17:\"one-click-upsells\";}}i:125;O:8:\"stdClass\":8:{s:2:\"id\";i:48349;s:5:\"title\";s:57:\"How to Fix 5XX Error While Importing Flow/Step Templates?\";s:7:\"content\";s:2680:\"If you\'re trying to import a ready-made funnel or step template in CartFlows and encounter a 5XX error (such as 500, 501, 502, or 503), this documentation will help you troubleshoot and resolve the issue.\n\n\n\nA common error message might look like:\n\n\n\nError: Allowed memory size of X bytes exhausted (tried to allocate X bytes)\n\n\n\nWhy This Happens\n\n\n\nThis error typically occurs due to one or more of the following reasons:\n\n\n\n\nPlugin conflicts or PHP errors on your site\n\n\n\nServer limitations or outdated PHP versions\n\n\n\nInsufficient resources configured in your hosting environment\n\n\n\n\nBelow are several points you can follow to fix this issue.\n\n\n\n1. Avoid Plugin Conflicts\n\n\n\nTemporarily deactivate all plugins except CartFlows, CartFlows Pro, and WooCommerce.\n\n\n\nThen try importing the template again.\n\n\n\n\nIf it works: one of the other plugins is likely causing a conflict.\n\n\n\nIf it doesn\'t: move on to the next point.\n\n\n\n\n2. Enable Debug Mode to Check for Errors\n\n\n\nEnable WordPress debugging using the WP Debugging plugin. After activating it, try importing a template again. This will create or update your debug.log file so you can check for specific PHP errors.\n\n\n\nStill not working? Continue below.\n\n\n\n3. Update Your PHP Version\n\n\n\nUsing an outdated PHP version can lead to performance issues and 5XX errors.\n\n\n\nWe recommend using PHP 7.3 or higher.\n\n\n\nTo check your PHP version:\n\n\n\n\nGo to Tools &gt; Site Health in your WordPress admin.\n\n\n\nClick the Info tab > Server.\n\n\n\nLook for PHP version.\n\n\n\n\n\n\n\n\nIf you\'re not using at least PHP 7.3, ask your hosting provider to update it for you.\n\n\n\n4. Increase Hosting Resource Limits\n\n\n\nIf your server’s PHP configuration limits are too low, imports may fail. Updating the following PHP values may help:\n\n\n\nmemory_limit = 512M\nmax_execution_time = 900\nmax_input_time = 900\npost_max_size = 256M\nupload_max_filesize = 720M\n\n\n\nIf you’re unsure how to make these changes, contact your hosting provider.\n\n\n\nHere’s an email you can send to your hosting provider:\n\n\n\nSubject: Help with PHP Configuration for CartFlows Template Import\n\n\n\nHello,\n\nI’m trying to import a CartFlows ready-made funnel or step template and I’m receiving a 5XX error.\n\nCould you please:\n\n1. Enable WordPress debug mode\n2. Check the error logs\n3. Share the log file with me?\n\nAlso, here are the recommended PHP configuration values:\n\n* PHP Version: 7.3 or later\n* memory_limit = 512M\n* max_execution_time = 900\n* max_input_time = 900\n* post_max_size = 256M\n* upload_max_filesize = 720M\n\nI’d appreciate your help. Thanks!\n\n\n\nStill Need Help?\n\n\n\nIf you\'re still experiencing issues, feel free to reach out to our support team. We’re happy to help!\";s:3:\"url\";s:67:\"https://cartflows.com/docs/fix-5xx-error-while-importing-templates/\";s:4:\"slug\";s:39:\"fix-5xx-error-while-importing-templates\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-04-14T21:34:59+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:126;O:8:\"stdClass\":8:{s:2:\"id\";i:48130;s:5:\"title\";s:31:\"How to View the CartFlows logs?\";s:7:\"content\";s:1457:\"Logs are crucial for diagnosing issues, tracking workflows, and identifying warnings or errors in any online software or application. CartFlows provides two types of logs:\n\n\n\nTypes of Logs in CartFlows\n\n\n\n1. Template Import Logs: These logs record the steps performed while importing templates on your website. They are only generated when WP_DEBUG is set to true. To track these logs, you need to enable WP_DEBUG. Refer to this documentation for guidance on enabling it.\n\n\n\n2. CartFlows Logs: These logs store records of activities when visiting funnel steps. They also capture errors related to CartFlows and supported payment gateways for upsells and downsells.\n\n\n\nLogs can be downloaded and shared with support for troubleshooting. Below are the steps to view, download, or delete logs on your website.\n\n\n\nHow to View the Logs\n\n\n\nStep 1: Open CartFlows Pages\n\n\n\nGo to CartFlows > Settings.\n\n\n\n\n\n\n\nStep 2: Click on the Logs Link\n\n\n\nClick on Logs to open the log management interface.\n\n\n\nStep 3: Select the Log File\n\n\n\nFrom the dropdown menu, choose the log file you want to check. Each log is labeled with its generation date. \n\n\n\n\n\n\n\nAdditional Actions\n\n\n\nAt the top of the log view page, you will find options to:\n\n\n\n\nCopy: Copy the log content.\n\n\n\nDownload: Download the log file for sharing or backup.\n\n\n\nDelete: Permanently remove the log file.\n\n\n\n\n\n\n\n\nThese options are useful when troubleshooting or when support requests detailed log information.\";s:3:\"url\";s:47:\"https://cartflows.com/docs/view-cartflows-logs/\";s:4:\"slug\";s:19:\"view-cartflows-logs\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-04-29T22:49:05+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:127;O:8:\"stdClass\":8:{s:2:\"id\";i:46384;s:5:\"title\";s:52:\"How to Show the Order Summary Open on Mobile Devices\";s:7:\"content\";s:707:\"Starting with CartFlows version 1.9.0, the Modern Checkout templates collapse the order summary by default on mobile devices to create a cleaner and more focused layout.\n\n\n\nIf you’d prefer the order summary to appear open by default on mobile (while still allowing users to collapse it), you can use the following PHP filter:\n\n\n\nadd_filter( \'cartflows_show_mobile_order_summary_collapsed\', \'__return_false\' );\n\n\n\nYou can add this code using the Code Snippets plugin (recommended) or by placing it in your child theme’s functions.php file.\n\n\n\n\n&#x1f4a1; Make sure to select PHP as the snippet type if you\'re using the Code Snippets plugin.\n\n\n\n\nFor guidance, check out: How to Add Custom Code to WordPress\";s:3:\"url\";s:80:\"https://cartflows.com/docs/how-to-show-the-order-summary-open-on-mobile-devices/\";s:4:\"slug\";s:52:\"how-to-show-the-order-summary-open-on-mobile-devices\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-04-29T13:46:03+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"code-snippets\";}}i:128;O:8:\"stdClass\":8:{s:2:\"id\";i:46372;s:5:\"title\";s:47:\"How to Enable the Product Tab on Store Checkout\";s:7:\"content\";s:1026:\"With the release of CartFlows version 1.10.0, we introduced the new Store Checkout feature, which replaces the default WooCommerce checkout and follows a standard, streamlined checkout process.\n\n\n\nAs part of this transition, the Product tab was removed from the Store Checkout funnel to maintain simplicity and alignment with typical eCommerce flows. However, if you have a unique use case where you want to want the product tab on Store checkout, you can bring back the Product tab by using the following PHP filter:\n\n\n\nadd_filter( \'cartflows_show_store_checkout_product_tab\', \'__return_true\' );\n\n\n\nYou can add this code using the Code Snippets plugin or by placing it in your child theme’s functions.php file.\n\n\n\nNeed help adding custom code? Here’s how to safely add code snippets to your site.\n\n\n\nNote: The Product Options feature does not behave the same way in the Store Checkout due to the structure of the store checkout. Some features may have limitations or may not be supported when the Product tab is enabled.\";s:3:\"url\";s:61:\"https://cartflows.com/docs/enable-product-tab-store-checkout/\";s:4:\"slug\";s:33:\"enable-product-tab-store-checkout\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-07-07T21:52:17+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"code-snippets\";}}i:129;O:8:\"stdClass\":8:{s:2:\"id\";i:46257;s:5:\"title\";s:44:\"Overview: Variation Swatches for WooCommerce\";s:7:\"content\";s:1427:\"Variation Swatches for WooCommerce replaces the default variation dropdowns with customizable color, image, or label swatches. It enhances the product selection experience on your product and shop pages by making variation choices more intuitive and visually appealing.\n\n\n\nThis documentation provides a quick overview of the plugin’s purpose and key features before moving on to setup and customization options.\n\n\n\nTo get started with Variation Swatches:\n\n\n\n\nInstall and activate the plugin.\n\n\n\nCreate global attributes and terms using Products > Attributes.\n\n\n\nAssign attributes to variable products and configure swatches as needed.\n\n\n\n\nMake product variations easier to browse with the following features:\n\n\n\nKey Features:\n\n\n\n\nSwatch TypesChoose between color, image, or label swatches for variation display.\n\n\n\nSwatch Shapes and SizesCustomize the shape (circle, square, etc.) and size of swatches to match your store design.\n\n\n\nTooltip and Hover EffectsAdd tooltips and optional image previews for swatches.\n\n\n\nShop Page DisplayShow swatches on shop or archive pages in addition to single product pages.\n\n\n\nWidget and Filter SupportEnable swatches in product filter widgets for better navigation.\n\n\n\nCustom Styling OptionsFine-tune font size, border styles, and alignment for swatches and labels.\n\n\n\n\nNeed help installing the plugin? Refer to this documentation: How to Install and Activate the Variation Swatches Plugin\";s:3:\"url\";s:69:\"https://cartflows.com/docs/variation-swatches-for-woocommerce-plugin/\";s:4:\"slug\";s:41:\"variation-swatches-for-woocommerce-plugin\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-19T22:35:34+05:30\";s:8:\"category\";a:1:{i:0;s:18:\"variation-swatches\";}}i:130;O:8:\"stdClass\":8:{s:2:\"id\";i:46122;s:5:\"title\";s:29:\"Offers JS Triggers Shortcodes\";s:7:\"content\";s:3507:\"In the CartFlows and CartFlows Pro, we’ve introduced new JavaScript variables (shortcodes) and triggers that can be used within custom JavaScript. These enhancements make it easier to access order and offer-related data for tracking, analytics, and custom automation requirements.\n\n\n\nThis feature is especially useful if you want to integrate third-party tracking tools, send data to external services, or run custom logic based on user actions within your flows.\n\n\n\nAvailable JavaScript Variables\n\n\n\nBelow is the list of JavaScript variables that can be used on CartFlows pages.\n\n\n\nVariables Available in CartFlows Free\n\n\n\nThe following variables are available in the free version of CartFlows:\n\n\n\n\n{{order_id}}\n\n\n\n{{txn_id}}\n\n\n\n{{order_total}}\n\n\n\n\nThese variables can be used on all CartFlows steps except the Checkout page. This is because order-related values are generated only after the order has been successfully placed.\n\n\n\nVariables Available in CartFlows Pro\n\n\n\nThe following variables are available with CartFlows Pro:\n\n\n\n\n{{offer_product_name}}\n\n\n\n{{offer_product_qty}}\n\n\n\n{{offer_product_price}}\n\n\n\n\nThese variables are specific to offers and are available only on Upsell and Downsell steps, as they relate directly to the accepted or rejected offer.\n\n\n\nPractical Use Case Example\n\n\n\nYou might be wondering how these variables can be used in real-world scenarios.\n\n\n\nFor example, if you want to trigger a custom Facebook Pixel or Google Analytics event on an Upsell or Downsell page and pass values such as the Order ID, Transaction ID, or Product ID, you can directly reference variables like {{order_id}}, {{txn_id}}, or {{product_id}} within your custom JavaScript. These values can then be sent dynamically to your tracking or analytics scripts.\n\n\n\nJS Triggers for Upsell &amp; Downsell Acceptance or Rejection\n\n\n\nAlong with JavaScript variables, CartFlows also provides built-in triggers that automatically run when an Upsell or Downsell offer is accepted or rejected.\n\n\n\nThis allows you to perform actions such as sending offer data to a CRM, triggering custom automation, or firing third-party tracking events based on the customer’s decision.\n\n\n\nThese script options are available only on Upsell and Downsell steps.\n\n\n\nHow to Add Offer Accepted or Rejected Scripts\n\n\n\nFollow the steps below to add custom JavaScript for offer acceptance or rejection:\n\n\n\nStep 1: Navigate to the CartFlows &gt; Funnels menu in your WordPress dashboard.\n\n\n\nStep 2: Click Edit on the funnel where you want to add the custom script.\n\n\n\n\n\n\n\nStep 3: Open the settings for the relevant Upsell or Downsell step.\n\n\n\n\n\n\n\nStep 4: Go to the Custom Script section on the sidebar.\n\n\n\n\n\n\n\nStep 5: Add your custom JavaScript code in the Offer Accepted or Offer Rejected script field, depending on your requirement.\n\n\n\n\n\n\n\nStep 6: Click Save Settings to apply the changes.\n\n\n\nJavaScript Variables Available in Offer Scripts\n\n\n\nWhile adding offer accepted or rejected scripts, you can use the following variables to access offer and order-related data:\n\n\n\n\n{{order_id}}\n\n\n\n{{flow_id}}\n\n\n\n{{step_id}}\n\n\n\n{{product_id}}\n\n\n\n{{variation_id}}\n\n\n\n{{quantity}}\n\n\n\n{{offer_type}}\n\n\n\n\nOnce added, these scripts will run automatically at the appropriate time. The Offer Accepted script will execute when an upsell or downsell is accepted, while the Offer Rejected script will run when the offer is declined.\n\n\n\nThis ensures your custom logic or tracking is executed precisely based on the customer’s action within the funnel.\";s:3:\"url\";s:57:\"https://cartflows.com/docs/offers-js-triggers-shortcodes/\";s:4:\"slug\";s:29:\"offers-js-triggers-shortcodes\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-05T19:00:08+05:30\";s:8:\"category\";a:1:{i:0;s:14:\"developer-docs\";}}i:131;O:8:\"stdClass\":8:{s:2:\"id\";i:46140;s:5:\"title\";s:17:\"User role manager\";s:7:\"content\";s:1224:\"CartFlows now includes a User Role Manager feature that gives you control over who can access and manage different parts of CartFlows on your website. This feature is especially helpful for teams and agencies who want to assign specific roles and responsibilities when working on funnels.\n\n\n\nWith this setting, you can easily define access levels for each user role, whether it’s full control, limited editing, or no access at all.\n\n\n\nHow to Manage User Roles in CartFlows\n\n\n\nStep 1: Navigate to CartFlows Settings\n\n\n\nGo to CartFlows > Settings > User Role Manager tab on the sidebar.\n\n\n\nStep 2: Set Access Level\n\n\n\nChoose from the following access levels for the user roles listed:\n\n\n\n\nNo Access – Restricts the user role from accessing CartFlows entirely.\n\n\n\nLimited Access – Allows access to funnels and steps only (no access to global settings).\n\n\n\nFull Access – Grants complete access including creating, editing, importing, and exporting funnels and steps.\n\n\n\n\nStep 3: Save Changes\n\n\n\nOnce you\'ve configured access levels, click the Save Settings button to apply your settings.\n\n\n\n\n\n\n\nBy default, all existing user roles will have access to CartFlows when this feature is enabled.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:45:\"https://cartflows.com/docs/user-role-manager/\";s:4:\"slug\";s:17:\"user-role-manager\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-27T16:30:22+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:132;O:8:\"stdClass\":8:{s:2:\"id\";i:45479;s:5:\"title\";s:29:\"CartFlows Pro WP CLI Commands\";s:7:\"content\";s:664:\"CartFlows adds support for managing certain actions via WP-CLI — a powerful tool for developers and advanced users who prefer working from the command line.\n\n\n\nActivate License Key via WP-CLI\n\n\n\nTo activate your CartFlows Pro license using WP-CLI, use the following command:\n\n\n\nwp cartflows license activate your-license-key-here\n\n\n\nReplace your-license-key-here with your actual license key.\n\n\n\nWe’ll continue to add support for more WP-CLI commands in the future.\n\n\n\nNote\nThis feature is available with the CartFlows Pro plugin. To use the following WP-CLI commands, ensure both the CartFlows Free and Pro plugins are installed and activated on your website.\";s:3:\"url\";s:43:\"https://cartflows.com/docs/wp-cli-commands/\";s:4:\"slug\";s:15:\"wp-cli-commands\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-08-05T14:18:31+05:30\";s:8:\"category\";a:1:{i:0;s:14:\"developer-docs\";}}i:133;O:8:\"stdClass\":8:{s:2:\"id\";i:44704;s:5:\"title\";s:36:\"How to create Google Address API Key\";s:7:\"content\";s:922:\"To enable Google Autocomplete for address fields on your CartFlows Checkout page, follow these steps:\n\n\n\nStep 1: Enable Google Maps Platform\n\n\n\n\nVisit the Google Maps Platform.\n\n\n\nClick the Get Started button at the top-right corner.\n\n\n\n\n\n\n\n\nStep 2: Create or Select a Project\n\n\n\n\nIf this is your first time, you\'ll need to create a new project.\n\n\n\nEnter a name for your project.\n\n\n\nClick Next to continue.\n\n\n\n\nStep 3: Set Up Billing\n\n\n\n\nChoose your country and accept the Terms of Service.\n\n\n\nClick Continue.\n\n\n\n\n\n\n\n\n\nEnter your customer and billing information to activate the account.\n\n\n\n\n\n\n\n\n\n\n\n\nStep 4: Generate Your API Key\n\n\n\n\nGo to APIs &amp; Services > Credentials.\n\n\n\n\n\n\n\n\n\nClick on CREATE CREDENTIALS and select API Key.\n\n\n\n\n\n\n\n\n\nYour new API key will be generated and displayed.\n\n\n\n\n\n\n\n\nYou can now copy this key and paste it into the appropriate field in the CartFlows settings to enable address autocomplete.\";s:3:\"url\";s:57:\"https://cartflows.com/docs/create-google-address-api-key/\";s:4:\"slug\";s:29:\"create-google-address-api-key\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-05T19:52:15+05:30\";s:8:\"category\";a:1:{i:0;s:14:\"developer-docs\";}}i:134;O:8:\"stdClass\":8:{s:2:\"id\";i:44695;s:5:\"title\";s:40:\"Enabling the Google Address Autocomplete\";s:7:\"content\";s:1808:\"CartFlows now includes a powerful new feature: Google Address Autocomplete for billing and shipping fields. This enhancement streamlines the checkout experience by allowing users to quickly search and select their address, which then auto-fills the relevant fields.\n\n\n\nThis feature leverages Google’s Places API to provide accurate address suggestions based on user input. It reduces manual typing and improves checkout speed, especially on mobile devices.\n\n\n\nNote: Some address components may be missing in certain suggestions, depending on what data is returned by Google. This is a known limitation of the API. Here is an actual&nbsp;demonstration&nbsp;from Google.\n\n\n\nWhat Is Google Address Autocomplete?\n\n\n\nGoogle Address Autocomplete is a service provided by Google’s Places API. It predicts and suggests address entries as users begin typing, using real-time location data.\n\n\n\nIn CartFlows, we’ve integrated this API to auto-fill billing and shipping fields with just a single selection—making your checkout process faster and more convenient.\n\n\n\nHow to Enable Google Address Autocomplete\n\n\n\nStep 1: Get Your Google API Key\n\n\n\nFirst, set up your Google account and generate an API key. Follow this guide for step-by-step instructions.\n\n\n\nStep 2: Add the API Key to CartFlows\n\n\n\n\nNavigate to CartFlows → Settings → Integrations.\n\n\n\nClick the Google Address Autocomplete tab.\n\n\n\nPaste your API key and save the changes.\n\n\n\n\n\n\n\n\nStep 3: Enable on Specific Checkout Pages\n\n\n\n\nEdit the Checkout step where you want this feature enabled.\n\n\n\nClick the Settings icon (gear icon).\n\n\n\nOpen the Checkout Form tab.\n\n\n\nClick on the Form Settings section and toggle on the Enable Google Address Autocomplete option.\n\n\n\n\n\n\n\n\nOnce enabled, your customers will benefit from a faster, smarter checkout form.\";s:3:\"url\";s:65:\"https://cartflows.com/docs/enabling-google-address-autocompletes/\";s:4:\"slug\";s:37:\"enabling-google-address-autocompletes\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-14T19:56:30+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:135;O:8:\"stdClass\":8:{s:2:\"id\";i:40585;s:5:\"title\";s:45:\"How to Override the WooCommerce Checkout Page\";s:7:\"content\";s:1323:\"The Override Store Checkout feature in CartFlows Pro allows you to replace WooCommerce’s default Checkout page with your CartFlows Store Checkout, without changing the page URL.\n\n\n\nThis is useful if you want the benefits of a CartFlows-optimized Checkout while keeping the familiar WooCommerce checkout URL structure.\n\n\n\nHow It Works\n\n\n\nWhen the Store Checkout is set and the Override option is enabled, CartFlows takes over the default WooCommerce Checkout page.\n\n\n\nThe page’s URL remains the same as WooCommerce’s default checkout page, but its content and functionality come entirely from your CartFlows Store Checkout.\n\n\n\nRequirements\n\n\n\nBefore you can enable the override:\n\n\n\n\nYou must set a Store Checkout in CartFlows (CartFlows &gt; Store Checkout). Refer to this document to know more about Store Checkout.\n\n\n\nThe Override option depends on the Store Checkout setting. If no Store Checkout is set, the Override option will not work.\n\n\n\n\nHow to Enable Override Store Checkout\n\n\n\n\nGo to CartFlows &gt; Settings &gt; General.\n\n\n\nEnable the Override Store Checkout option.\n\n\n\nSave your changes.\n\n\n\n\n\n\n\n\nOnce enabled, customers visiting your WooCommerce Checkout page will see the CartFlows Store Checkout, with the URL unchanged.\n\n\n\nBefore enabling the Override option:\n\n\n\n\n\n\n\nAfter enabling the Override option:\";s:3:\"url\";s:52:\"https://cartflows.com/docs/override-global-checkout/\";s:4:\"slug\";s:24:\"override-global-checkout\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-19T21:23:47+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"global-checkout\";}}i:136;O:8:\"stdClass\":8:{s:2:\"id\";i:40363;s:5:\"title\";s:33:\"Dynamic (Conditional) Order Bumps\";s:7:\"content\";s:2673:\"CartFlows allows you to display Order Bumps dynamically based on specific conditions set on the checkout page. This feature is known as Dynamic (Conditional) Order Bumps.\n\n\n\nWith this functionality, you can control when an order bump should appear by defining rules based on factors such as products in the cart, order value, discounts, and other checkout conditions.\n\n\n\nThis helps you present the most relevant offer to customers and improves the chances of increasing the average order value.\n\n\n\nHow Dynamic Order Bumps Work\n\n\n\nDynamic Order Bumps use a rule-based condition system to determine whether an order bump should be displayed to the customer.\n\n\n\nTo make rule management easier, conditions can be organized into groups.\n\n\n\nA Condition Group contains one or more rules that work together.\n\n\n\n\nConditions inside the same group follow an AND relationship.\n\n\n\nMultiple groups follow an OR relationship.\n\n\n\n\nThis means the order bump will be displayed if any condition group is satisfied.\n\n\n\nYou can create multiple groups and conditions depending on your requirements, allowing you to build advanced targeting scenarios for your offers.\n\n\n\nWhere to Configure Dynamic Order Bumps\n\n\n\nThe condition settings for Dynamic Order Bumps are available within the Order Bump settings on the checkout step.\n\n\n\nInside the Conditions tab, you can add rules and organize them into groups to control when the order bump should be shown.\n\n\n\nHow to Set Up Dynamic Order Bumps\n\n\n\nFollow the steps below to configure conditional order bumps.\n\n\n\nStep 1: Navigate to CartFlows &gt; Funnels.Step 2: Open the funnel where you want to add or modify the order bump.\n\n\n\n\n\n\n\nStep 3: Move to the Order Bump section. If an order bump is not yet created, click Add Order Bump.Step 4: Click Edit Order Bump on the order bump you want to configure.\n\n\n\n\n\n\n\nStep 5: On the Order Bumps section edit the Order Bump by clicking the order bump settings.Step 6: Enable the Conditions option to activate rule-based display.\n\n\n\n\n\n\n\nStep 7: Select the required conditions values to define the first rule.Step 8: Click Add Condition to add more rules within the same condition group.Step 9: Click Add Conditions Group if you want to create another group of rules.\n\n\n\n\n\n\n\nStep 10: Click Save Settings to apply the configuration.\n\n\n\nReordering Condition Groups\n\n\n\nCondition groups can be reordered to control priority.\n\n\n\nYou can simply drag and drop the groups to arrange them according to how you want the conditions to be evaluated.\n\n\n\nIndividual rules cannot be moved directly between groups. If you want to move a rule to another group, you will need to delete it and recreate it within the desired group.\";s:3:\"url\";s:47:\"https://cartflows.com/docs/dynamic-order-bumps/\";s:4:\"slug\";s:19:\"dynamic-order-bumps\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-05T14:22:58+05:30\";s:8:\"category\";a:1:{i:0;s:10:\"order-bump\";}}i:137;O:8:\"stdClass\":8:{s:2:\"id\";i:40154;s:5:\"title\";s:47:\"How to Renew Your Expired CartFlows Pro License\";s:7:\"content\";s:1041:\"If your CartFlows Pro license has expired, you can renew it easily by following the steps below.\n\n\n\nRenewing Your Expired License\n\n\n\nTo renew your CartFlows Pro license:\n\n\n\nStep 1: Log in to your Account\n\n\n\nVisit the CartFlows Store and log in using your credentials.\n\n\n\nStep 2: Go to the Subscriptions  from the sidebar\n\n\n\nClick on the Subscriptions section from the sidebar and click the Resubscribe button.\n\n\n\n\n\n\n\nStep 3: Billing details\n\n\n\nOn the Checkout page, verify your billing information.\n\n\n\n\n\n\n\nStep 4: Your order\n\n\n\nOnce you confirm your billing information is correct, verify the Your order section.\n\n\n\n\n\n\n\nStep 5: Coupon and Payment method\n\n\n\nEnter the coupon code if you have one, then choose your preferred payment method. Make sure to tick the I have read and agree to the website Terms and Conditions checkbox. Finally, click the Place Order button.\n\n\n\n\n\n\n\nCongratulations! You have successfully renewed your CartFlows Pro license. A confirmation email with your order details will be sent to your registered email address.\";s:3:\"url\";s:77:\"https://cartflows.com/docs/steps-to-renew-your-cartflows-pro-expired-license/\";s:4:\"slug\";s:49:\"steps-to-renew-your-cartflows-pro-expired-license\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-08-11T18:59:38+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"account-store\";}}i:138;O:8:\"stdClass\":8:{s:2:\"id\";i:39884;s:5:\"title\";s:38:\"CartFlows Dynamic Offers (Rule Engine)\";s:7:\"content\";s:2895:\"CartFlows includes a powerful feature called Dynamic Offers, also known as the Rule Engine, which allows you to control the redirection to upsell or downsell steps based on specific conditions set on the checkout page.\n\n\n\nUsing this feature, you can define custom rules that determine which upsell or downsell page a customer should see after completing the checkout step.\n\n\n\nHow Dynamic Offers Work\n\n\n\nDynamic Offers allow you to create conditional redirects based on various checkout conditions. These conditions can include details such as products in the cart, order value, customer information, and more.\n\n\n\nTo make rule creation more flexible, Dynamic Offers support grouped conditions.\n\n\n\nA Group is a collection of one or more conditions.\n\n\n\n\nConditions within the same group work using an AND relationship.\n\n\n\nMultiple groups work using an OR relationship.\n\n\n\n\nThis means that if any group of conditions is satisfied, the corresponding redirect rule will be applied.\n\n\n\nThis structure allows you to create advanced scenarios while keeping the rule setup organized and easy to manage.\n\n\n\nHow to Set Up Dynamic Offers\n\n\n\nFollow these steps to configure Dynamic Offers for your checkout step.\n\n\n\nStep 1: Navigate to CartFlows &gt; Funnels.Step 2: Open the funnel where you want to add or modify the conditions.\n\n\n\n\n\n\n\nStep 3: Click the settings icon of the Checkout step.\n\n\n\n\n\n\n\nStep 4: Open the Dynamic Offers section in the checkout settings.Step 5: Enable the Dynamic Offers option.Step 6: Click Add Condition if you want to include additional conditions within the same group.Step 7: Click Add Dynamic Offer to create another group of conditions.Step 8: Click Save Settings to apply the rules.\n\n\n\n\n\n\n\nReordering Dynamic Offer Groups\n\n\n\nYou can reorder condition groups to prioritize which rules should be evaluated first.\n\n\n\nSimply drag and drop the groups to rearrange them according to your requirements.\n\n\n\nNote that individual conditions cannot be moved between groups. If you want a condition in another group, you will need to delete it and recreate it in the desired group.\n\n\n\nDefault Redirection\n\n\n\nIf none of the defined condition groups match the customer\'s checkout scenario, you can configure a default redirection step.\n\n\n\n\n\n\n\nThis ensures that every customer is redirected to a specific upsell or downsell step even when no conditions are met.\n\n\n\nUsing Dynamic Offers with Upsell and Downsell Steps\n\n\n\nOnce a customer is redirected to the appropriate upsell or downsell step using Dynamic Offers, you can still apply conditional redirects on the upsell or downsell steps to further control the flow. This allows you to create more advanced funnel paths depending on the customer’s actions.\n\n\n\nRefer to this documentation for more details about conditional Upsell and Downsell: https://cartflows.com/docs/create-conditional-upsell-downsell/\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:64:\"https://cartflows.com/docs/cartflows-dynamic-offers-rule-engine/\";s:4:\"slug\";s:36:\"cartflows-dynamic-offers-rule-engine\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-04-29T19:08:01+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:139;O:8:\"stdClass\":8:{s:2:\"id\";i:39790;s:5:\"title\";s:25:\"List of CartFlows Cookies\";s:7:\"content\";s:1294:\"CartFlows uses several cookies to ensure smooth operation of checkout flows, session handling, and analytics. These small files are stored on the user’s local device and are sent with each page request to help maintain consistent user sessions and tracking.\n\n\n\nBelow are the cookies used by CartFlows:\n\n\n\n\ncartflows_session_Set when a user visits a CartFlows page. It creates a unique session ID for each user to enable a seamless checkout experience.\n\n\n\nwcf_active_checkout Determines which checkout page is currently open and stores relevant cart data for that specific checkout.\n\n\n\nwcf-visited-flow- Tracks which CartFlows funnel (flow) the user has interacted with.\n\n\n\nwcf-step-visited- Tracks which step of the funnel the user has visited.\n\n\n\ncartflows-ab-test- \n\n\n\nUsed only when the A/B Split Testing feature is active to track the variant shown to the user.\n\n\n\n\nCustom Cookie Prefix\n\n\n\nIf your server requires cookies to use a specific prefix (e.g., for caching compliance), you can define a custom prefix by adding the following line to your wp-config.php file:\n\n\n\ndefine( \'CARTFLOWS_COOKIE_PREFIX\', \'your_prefix_\' );\n\n\n\nNote: Add this line just above the “That’s all, stop editing! Happy publishing.” line in the wp-config.php file, located in your website’s root directory.\";s:3:\"url\";s:53:\"https://cartflows.com/docs/list-of-cartflows-cookies/\";s:4:\"slug\";s:25:\"list-of-cartflows-cookies\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-09-02T22:04:17+05:30\";s:8:\"category\";a:1:{i:0;s:14:\"developer-docs\";}}i:140;O:8:\"stdClass\":8:{s:2:\"id\";i:39759;s:5:\"title\";s:40:\"Cart Abandonment Cookies/GDPR Compliance\";s:7:\"content\";s:1296:\"We introduced a dedicated Cart Abandonment plugin to help website administrators recover lost sales by sending follow-up emails to users who abandon their carts. This is an optional feature that you can enable or disable as per your store’s requirements.\n\n\n\nData Processing &amp; Consent\n\n\n\nAbandoned cart emails fall under legitimate interest for data processing under GDPR guidelines. This means:\n\n\n\n\nNo special consent is required to send abandoned cart recovery emails.\n\n\n\nYou can use this feature confidently without additional consent checkboxes, though transparency in your privacy policy is recommended.\n\n\n\n\nOptional GDPR Confirmation Setting\n\n\n\nTo give store owners more control, the plugin includes an optional setting:\n\n\n\nYou can enable this feature by following these steps:\n\n\n\n\nNavigate to WooCommerce &gt; Cart Abandonment\n\n\n\nClick on the Settings tab\n\n\n\nGo to the GDPR tab\n\n\n\nToggle the option: Enable GDPR Integration\n\n\n\n\n\n\n\n\nNote\nWhen enabled, a confirmation message will appear below the email field on the checkout page. This informs the user about tracking and gives them the option to opt out by clicking “No thanks.”\n\n\n\n\n\n\n\n\nThis provides a balance between compliance and conversion, allowing you to recover lost sales while respecting your users\' privacy preferences.\";s:3:\"url\";s:52:\"https://cartflows.com/docs/cart-abandonment-cookies/\";s:4:\"slug\";s:24:\"cart-abandonment-cookies\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-02-18T19:47:48+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:141;O:8:\"stdClass\":8:{s:2:\"id\";i:38862;s:5:\"title\";s:80:\"VAT Field of WooCommerce EU/UK VAT Compliance (Premium) Plugin is not Displaying\";s:7:\"content\";s:2543:\"If you\'re using the WooCommerce EU/UK VAT Compliance (Premium) plugin by David Anderson and the VAT field is not appearing on your CartFlows Checkout page, this documentation will help you display it correctly.\n\n\n\nThis plugin adds a VAT number field on the WooCommerce checkout page to support tax compliance for EU and UK customers. However, due to how CartFlows customizes the checkout fields, the VAT field may not display by default.\n\n\n\nEnsure VAT Field is Displayed on WooCommerce Checkout\n\n\n\nBefore checking CartFlows compatibility, make sure the VAT field is visible on the default WooCommerce checkout page. If it\'s not displayed there, it won’t appear on CartFlows either.\n\n\n\nYou can confirm this by temporarily switching to the default WooCommerce checkout page and testing whether the VAT field appears as expected.\n\n\n\nWhy the Field Might Not Show on CartFlows Checkout\n\n\n\nCartFlows customizes the WooCommerce checkout form, including billing and shipping fields, using standard WooCommerce hooks and filters. Because of this, fields added by third-party plugins may not always appear in the intended position.\n\n\n\nFortunately, the WooCommerce EU/UK VAT Compliance (Premium) plugin provides a filter that allows you to change the position of the VAT field.\n\n\n\nAdd the Filter to Display VAT Field on CartFlows Checkout\n\n\n\nAdd the following filter to your child theme’s functions.php file:\n\n\n\nadd_filter( \'wc_eu_vat_number_position\', \'eu_change_vat_number_position\', 10, 1 ); \n\n/**\n* Function to change the position of VAT field only for the CartFlows checkout page.\n* \n* @param $current_page current visited page\n* @return $current_page current page.\n*/\nfunction eu_change_vat_number_position( $position ){\n\n  /* Get global post object */\n	global $post;\n\n	/* Get current post type */\n	$post_type = get_post_type();\n	\n	/* Check the current type of the page */\n	$is_checkout = get_post_meta( $post-&gt;ID, \'wcf-step-type\', true );\n		\n	/* Change position only of the CartFlows checkout page */\n	if( \'cartflows_step\' == $post_type &amp;&amp; \'checkout\' === $is_checkout){\n		$position = \'woocommerce_after_order_notes\';\n	}\n\n  return $position;\n\n}\n\n\n\n\n\n&#x1f4a1; Need help adding custom code? Here’s how to safely add custom snippets to your site.\n\n\n\n\nAfter adding this filter, the VAT field will display on your CartFlows checkout page in the correct position. If you’ve followed the steps and the field still doesn’t appear, double-check your plugin settings and ensure the field is visible on the standard WooCommerce checkout.\";s:3:\"url\";s:65:\"https://cartflows.com/docs/vat-field-of-eu-uk-vat-not-displaying/\";s:4:\"slug\";s:37:\"vat-field-of-eu-uk-vat-not-displaying\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-15T18:38:06+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"code-snippets\";}}i:142;O:8:\"stdClass\":8:{s:2:\"id\";i:38729;s:5:\"title\";s:95:\"How to Fix “Cannot Activate API Key. Key Already Activated with the Same Instance ID” Error\";s:7:\"content\";s:2025:\"While activating the CartFlows Pro license, you may encounter the following error message:\n\n\n\nCannot Activate API Key. The API Key has already been activated with the same Unique Instance ID sent with this request.\n\n\n\nThis typically happens when your site setup causes CartFlows to send the same instance ID that was already linked to a previous activation. This documentation explains why this error occurs and how to fix it.\n\n\n\nWhy This Error Occurs\n\n\n\nThere are a few common scenarios that may trigger this issue:\n\n\n\n1. Site Migration or Cloning\n\n\n\nIf the website has been migrated or cloned to a new domain or hosting environment, the old instance ID may still be stored. When you activate the license on the new site, it sends the same instance ID — leading to a conflict.\n\n\n\n2. Plugin Reinstallation Without Deactivation\n\n\n\nIf the CartFlows Pro plugin was deleted or removed without first deactivating the license, then re-uploaded, the license system may still associate the instance ID with the original domain.\n\n\n\n3. Caching Issues\n\n\n\nWhen caching is enabled (including local, server-side, or browser cache), the instance ID may not be correctly stored. This can cause repeated requests to send the same old instance ID, even if the site has changed.\n\n\n\nHow to Fix the Issue\n\n\n\nFollow these steps to clear the old instance ID and reactivate your CartFlows Pro license:\n\n\n\n1. Log in to your account at my.cartflows.com2. Navigate to the API Keys tab3. Locate the entry for the domain you’re working with4. Delete that entry\n\n\n\n\n\n\n\n5. Log in to your WordPress admin6. Clear all site cache, including\n\n\n\n\nLocal cache\n\n\n\nServer-side cache\n\n\n\nBrowser cache\n\n\n\n\n7. Go to the Plugins menu8. Deactivate any cache plugin temporarily9. Deactivate the CartFlows Pro plugin10. Reactivate the CartFlows Pro plugin11. Click the Activate License button12. Enter your license/API key13. Click Activate\n\n\n\nNote: Always clear all cache and temporarily disable any cache plugins before activating the CartFlows Pro license/API key.\";s:3:\"url\";s:73:\"https://cartflows.com/docs/how-to-resolve-same-instance-id-error-message/\";s:4:\"slug\";s:45:\"how-to-resolve-same-instance-id-error-message\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-02-18T15:14:24+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:143;O:8:\"stdClass\":8:{s:2:\"id\";i:38187;s:5:\"title\";s:53:\"How to Delete Plugin Data When Uninstalling CartFlows\";s:7:\"content\";s:1304:\"CartFlows includes an option that allows you to automatically delete its data when uninstalling the plugin. This is useful if you want to fully remove CartFlows and clean up your WordPress database.\n\n\n\nThis documentation explains how to enable that setting and what it does.\n\n\n\nWhat Gets Deleted?\n\n\n\nWhen this option is enabled, uninstalling CartFlows will:\n\n\n\n\nDelete all CartFlows settings and options (including Global Settings)\n\n\n\nWill not delete funnels or steps from the database automatically\n\n\n\n\nIf you want to completely remove everything, including existing funnels and steps, make sure to delete them manually first before uninstalling the plugin.\n\n\n\nWhere to Find This Option\n\n\n\nYou can find this setting by going to CartFlows &gt; Settings &gt; Advanced tab\n\n\n\n\n\n\n\nSteps to Enable the Delete Plugin Data Option\n\n\n\n\nNavigate to CartFlows &gt; Settings &gt; Advanced tab\n\n\n\nClick the toggle to enable Delete plugin data on plugin deletion\n\n\n\nA confirmation alert will appear\n\n\n\nEnter DELETE (in all caps) to confirm\n\n\n\nClick the Save Settings button\n\n\n\n\nOnce this option is enabled, uninstalling the plugin will automatically clean up CartFlows data from the database.\n\n\n\nWatch It in Action\n\n\n\nPrefer a quick demo? Watch the short video below that shows how to enable this option step by step:\";s:3:\"url\";s:72:\"https://cartflows.com/docs/delete-plugin-data-while-uninstalling-plugin/\";s:4:\"slug\";s:44:\"delete-plugin-data-while-uninstalling-plugin\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-20T18:49:09+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:144;O:8:\"stdClass\":8:{s:2:\"id\";i:37722;s:5:\"title\";s:48:\"How to Add Products to the Checkout Page via URL\";s:7:\"content\";s:2084:\"CartFlows Pro includes a feature that allows you to add products directly to the Checkout page using URL parameters. This makes it easy to dynamically pre-fill the cart based on the link a user clicks — great for personalized offers, email campaigns, and landing pages.\n\n\n\nThis documentation explains how the feature works, how to structure your URLs, and how to find the product ID required for this functionality.\n\n\n\nHow the Feature Works\n\n\n\nThis feature is enabled by default in CartFlows Pro — there’s no need to activate it manually. All you need to do is:\n\n\n\n\nUse a product ID in the URL to add that item to the cart on the Checkout page\n\n\n\nOptionally include the quantity for each item\n\n\n\n\nWhen a user opens the Checkout page URL with the appropriate parameter(s), the specified product(s) will automatically appear in the cart.\n\n\n\nURL Parameters Format\n\n\n\nTo add a product to the Checkout page via URL, use the following parameters:\n\n\n\n\n?wcf-add-to-cart=product_id\n\n\n\n&amp;wcf-qty=quantity (optional – defaults to 1 if not specified)\n\n\n\n\nSingle Product Example\n\n\n\nIf you want to add Product ID 3 with a quantity of 4, the URL would look like:\n\n\n\nhttps:&#47;&#47;yourdomain.com/checkout-page/?wcf-add-to-cart=3&amp;wcf-qty=4\n\n\n\nIf you omit the wcf-qty parameter, the default quantity will be 1.\n\n\n\nMultiple Products Example\n\n\n\nTo add multiple products with different quantities, separate each ID and quantity with commas. For example:\n\n\n\nhttps:&#47;&#47;yourdomain.com/checkout-page/?wcf-add-to-cart=3,6&amp;wcf-qty=4,8\n\n\n\nThis will add Product ID 3 with quantity 4 and Product ID 6 with quantity 8.\n\n\n\nImportant Notes\n\n\n\nIf you’ve already selected products in the backend of the Checkout step, and you also pass product IDs via URL — only the products from the URL will be used. The backend-selected products will be ignored.\n\n\n\nHow to Find the Product ID\n\n\n\nTo locate a product’s ID in WooCommerce:\n\n\n\n\nGo to Products > All Products in your WordPress admin\n\n\n\nHover your mouse over the product title\n\n\n\nYou’ll see the product ID appear below the product title\";s:3:\"url\";s:80:\"https://cartflows.com/docs/how-to-add-the-products-on-the-checkout-page-via-url/\";s:4:\"slug\";s:52:\"how-to-add-the-products-on-the-checkout-page-via-url\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-04-15T19:08:27+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:145;O:8:\"stdClass\":8:{s:2:\"id\";i:38212;s:5:\"title\";s:61:\"How to Regenerate the Step&#8217;s Dynamic CSS for Shortcodes\";s:7:\"content\";s:1561:\"CartFlows includes an optimization that improves how dynamic inline CSS is generated for pages using shortcodes. Instead of regenerating CSS every time a page loads, CartFlows now stores it efficiently to improve performance.\n\n\n\nThis documentation explains when and how to manually regenerate the dynamic CSS for Steps using shortcodes.\n\n\n\nWhen to Use This Option\n\n\n\nYou may want to regenerate the CSS when:\n\n\n\n\nDesign changes made to the step are not showing up on the frontend\n\n\n\nYou are using CartFlows shortcodes instead of regular funnel pages\n\n\n\nThe page loads correctly, but styling appears broken or outdated\n\n\n\n\nThis option only affects CSS generated from the Design Settings of a Step and only for pages using shortcodes.\n\n\n\n\n\n\n\nHow It Works\n\n\n\nCartFlows stores dynamic CSS for each Step in the page’s metadata and loads it directly instead of regenerating it on every page load. This improves performance across your site.\n\n\n\nWhen a design change is made to a Step, the CSS is deleted and automatically regenerated on the next page load.\n\n\n\nHowever, if you’re using shortcodes and styling doesn’t update as expected, you may need to trigger CSS regeneration manually.\n\n\n\nHow to Regenerate the CSS\n\n\n\nStep 1: Go to CartFlows &gt; Settings &gt; Advanced tab\n\n\n\nStep 2: Click the Regenerate Now button\n\n\n\n\n\n\n\nThis will clear the stored CSS and regenerate it the next time the page is visited.\n\n\n\nNeed Help?\n\n\n\nIf the styling still doesn’t reflect properly after regenerating the CSS, feel free to contact our support team. We’re happy to help.\";s:3:\"url\";s:75:\"https://cartflows.com/docs/regenerate-the-steps-dynamic-css-for-shortcodes/\";s:4:\"slug\";s:47:\"regenerate-the-steps-dynamic-css-for-shortcodes\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-18T17:54:16+05:30\";s:8:\"category\";a:1:{i:0;s:14:\"developer-docs\";}}i:146;O:8:\"stdClass\":8:{s:2:\"id\";i:37699;s:5:\"title\";s:45:\"How to Set Default Product in Product Options\";s:7:\"content\";s:1701:\"CartFlows lets you offer multiple product options on the checkout page. With this feature, you can also control which product appears selected by default.\n\n\n\nThis documentation explains two ways to set a default product in the product options:\n\n\n\n\nFrom the checkout page settings in the backend\n\n\n\nUsing a URL parameter\n\n\n\n\nMethod 1: Set Default Product from Checkout Page Settings\n\n\n\nUse this method if you want to choose a default product when multiple products are added to the Checkout Step.\n\n\n\n1. Go to CartFlows &gt; Funnels.\n\n\n\n2. Open the Funnel where you\'d like to apply the setting.\n\n\n\n\n\n\n\n3. Click the Settings icon (cog icon) of the Checkout step.\n\n\n\n\n\n\n\n4. Go to the Products Options section under the Products tab.\n\n\n\n\n\n\n\n5. Enable the Product Options and choose “Let user select multiple products from all options” under the Enable Conditions\n\n\n\n\n\n\n\n6. Use the toggle or radio buttons next to each product to choose which one should be selected by default.\n\n\n\n\n\n\n\nClick Save Settings, and view the checkout page to see the default product selected.\n\n\n\nMethod 2: Set Default Product Using URL Parameter\n\n\n\nUse this method if you want to control the default selection dynamically through a link, for example, from a landing page or a custom button.To set a default product, add the wcf-default parameter to your checkout page URL.\n\n\n\nFormat:\n\n\n\nyourdomain.com/checkout-page/?wcf-default=1\n\n\n\nHere, the 1 refers to the position of the product (in order) as listed in your product options. You can link this URL to buttons or anchor tags to direct users to a specific product preselected at checkout. Refer to this doc for further details about this method.\n\n\n\nFrequently Asked Question\";s:3:\"url\";s:66:\"https://cartflows.com/docs/set-default-product-in-product-options/\";s:4:\"slug\";s:38:\"set-default-product-in-product-options\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-20T12:17:53+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:147;O:8:\"stdClass\":8:{s:2:\"id\";i:37707;s:5:\"title\";s:41:\"How to Start a Funnel from a Product Page\";s:7:\"content\";s:2025:\"CartFlows allows you to start a funnel directly from a WooCommerce product page. This feature lets users be redirected to a CartFlows funnel immediately after adding a product to their cart.\n\n\n\nHow Does It Work?\n\n\n\nWhen this feature is enabled:\n\n\n\n\nUsers clicking Add to Cart on a product page are redirected to the first step of a selected CartFlows funnel.\n\n\n\nYou can choose a specific funnel for each product in the WooCommerce product settings.\n\n\n\nThis method works well for custom pricing, booking, and appointment-based products.\n\n\n\n\nImportant: We recommend not using a Landing Page as the first step to ensure users go directly to checkout.\n\n\n\nWhen to Use This Feature?\n\n\n\nThis feature is useful when:\n\n\n\n\nYou want to send users directly to checkout after adding a product to the cart.\n\n\n\nYou’re selling booking or appointment-based products where users need to select details before checkout.\n\n\n\nYou want to customize the checkout experience for specific products without requiring users to visit the default WooCommerce cart page.\n\n\n\n\nHow to Enable This Feature\n\n\n\n1. Create a Funnel\n\n\n\nEnsure you have a CartFlows funnel with the Checkout step as the first step.\n\n\n\n2. Edit the WooCommerce Product\n\n\n\n\nGo to Products and select the product you want to connect to a funnel.\n\n\n\nOpen the CartFlows tab in the product settings.\n\n\n\n\n\n\n\n\n3. Link the Product to a Funnel\n\n\n\n\nSearch for the funnel you want to connect.\n\n\n\nOptionally, customize the Add to Cart button text for this product.\n\n\n\n\n\n\n\n\n4. Save Changes\n\n\n\nClick Update to apply the changes.\n\n\n\n\n\n\n\nImportant Notes\n\n\n\n\nDo not assign a product in the backend of the Checkout step when using this feature.\n\n\n\nFor booking and appointment product types, ensure users provide the necessary details on the product page before checkout.\n\n\n\nThe Start a Funnel from Product Page feature is designed to work only with default WooCommerce product pages. It doesn’t function the same way with custom-designed sales pages created outside of WooCommerce’s product system.\";s:3:\"url\";s:65:\"https://cartflows.com/docs/how-to-start-a-flow-from-product-page/\";s:4:\"slug\";s:37:\"how-to-start-a-flow-from-product-page\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-30T15:46:05+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"getting-started\";}}i:148;O:8:\"stdClass\":8:{s:2:\"id\";i:37450;s:5:\"title\";s:36:\"How to Apply the Coupon from the URL\";s:7:\"content\";s:1368:\"CartFlows Pro supports applying WooCommerce coupons directly from the checkout page URL. This feature allows you to share the separate coupons for each checkout page for different users or products.\n\n\n\nIt is enabled by default and does not require any additional configuration.\n\n\n\nCreate a WooCommerce Coupon\n\n\n\nTo use this feature, start by creating a coupon in WooCommerce:\n\n\n\n\nGo to Marketing &gt; Coupons.\n\n\n\nClick Add Coupon and configure your discount settings.\n\n\n\nSave the coupon.\n\n\n\n\n\n\n\n\nIf needed, refer to WooCommerce\'s coupon documentation for detailed instructions.\n\n\n\nAdd the Coupon to a Checkout Page URL\n\n\n\nOnce the coupon is created, append the coupon code to the URL of your Checkout page.\n\n\n\nFormat:\n\n\n\nyourdomain.com/checkout-page/?coupon=COUPONCODE\n\n\n\nWhen someone visits this link, the coupon will automatically apply at checkout.\n\n\n\n\n\n\n\nCombine with Other Parameters\n\n\n\nYou can also combine the coupon with other supported URL parameters such as product and quantity.\n\n\n\nExample:\n\n\n\nyourdomain.com/checkout-page/?product=252&amp;quantity=1&amp;coupon=DISCOUNT10\n\n\n\nThis will:\n\n\n\n\nAdd the product with ID 252\n\n\n\nSet the quantity to 1\n\n\n\nApply the DISCOUNT10 coupon\n\n\n\n\nHow to Find a Product ID\n\n\n\n\nGo to Products &gt; All Products in your WordPress dashboard.\n\n\n\nHover over the product title. You’ll see the Product ID displayed below the title.\";s:3:\"url\";s:64:\"https://cartflows.com/docs/how-to-apply-the-coupon-from-the-url/\";s:4:\"slug\";s:36:\"how-to-apply-the-coupon-from-the-url\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-09T15:18:54+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:149;O:8:\"stdClass\":8:{s:2:\"id\";i:37378;s:5:\"title\";s:39:\"Complete List of WordPress Locale Codes\";s:7:\"content\";s:2341:\"Hint – You can CTRL / CMD + F to find your language\n\n\n\nLanguage NameLanguage CodeWordPress Locale CodeAfrikaansafafAkanakakAlbaniansqsqAmharicamamArabicararArmenianhyhyAromanianruprup_MKAssameseasasAzerbaijaniazazAzerbaijani (Turkey)az-traz_TRBashkirbabaBasqueeueuBelarusianbelbelBengalibnbn_BDBosnianbsbs_BABulgarianbgbg_BGBurmesemyamy_MMCatalancacaCatalan (Balear)balbalChinese (China)zh-cnzh_CNChinese (Hong Kong)zh-hkzh_HKChinese (Taiwan)zh-twzh_TWCorsicancocoCroatianhrhrCzechcscs_CZDanishdada_DKDhivehidvdvDutchnlnl_NLDutch (Belgium)nl-benl_BEEnglishenen_USEnglish (Australia)en-auen_AUEnglish (Canada)en-caen_CAEnglish (UK)en-gben_GBEsperantoeoeoEstonianetetFaroesefofoFinnishfifiFrench (Belgium)fr-befr_BEFrench (France)frfr_FRFrisianfyfyFulahfucfucGalicianglgl_ESGeorgiankaka_GEGermandede_DEGerman (Switzerland)de-chde_CHGreekelelGuaranígngnGujaratigugu_INHawaiianhawhaw_USHazaragihazhazHebrewhehe_ILHindihihi_INHungarianhuhu_HUIcelandicisis_ISIdoidoidoIndonesianidid_IDIrishgagaItalianitit_ITJapanesejajaJavanesejvjv_IDKannadaknknKazakhkkkkKhmerkmkmKinyarwandakinkinKirghizkyky_KYKoreankoko_KRKurdish (Sorani)ckbckbLaololoLatvianlvlvLimburgishliliLingalalinlinLithuanianltlt_LTLuxembourgishlblb_LUMacedonianmkmk_MKMalagasymgmg_MGMalaymsms_MYMalayalammlml_INMarathimrmrMingrelianxmfxmfMongolianmnmnMontenegrinmeme_MENepalinene_NPNorwegian (Bokmål)nbnb_NONorwegian (Nynorsk)nnnn_NOOriyaoryoryOsseticososPashtopspsPersianfafa_IRPersian (Afghanistan)fa-affa_AFPolishplpl_PLPortuguese (Brazil)pt-brpt_BRPortuguese (Portugal)ptpt_PTPunjabipapa_INRohingyarhgrhgRomanianroro_RORussianruru_RURussian (Ukraine)ru-uaru_UARusynruerueSakhasahsahSanskritsa-insa_INSardiniansrdsrdScottish GaelicgdgdSerbiansrsr_RSSindhisdsd_PKSinhalasisi_LKSlovaksksk_SKSlovenianslsl_SISomalisoso_SOSouth AzerbaijaniazbazbSpanish (Argentina)es-ares_ARSpanish (Chile)es-cles_CLSpanish (Colombia)es-coes_COSpanish (Mexico)es-mxes_MXSpanish (Peru)es-pees_PESpanish (Puerto Rico)es-pres_PRSpanish (Spain)eses_ESSpanish (Venezuela)es-vees_VESundanesesusu_IDSwahiliswswSwedishsvsv_SESwiss GermangswgswTagalogtltlTajiktgtgTamazight (Central Atlas)tzmtzmTamiltata_INTamil (Sri Lanka)ta-lkta_LKTatartttt_RUTeluguteteThaiththTibetanboboTigrinyatirtirTurkishtrtr_TRTurkmentuktukUighurugug_CNUkrainianukukUrduururUzbekuzuz_UZVietnameseviviWalloonwawaWelshcycyYorubayoryor\";s:3:\"url\";s:67:\"https://cartflows.com/docs/complete-list-of-wordpress-locale-codes/\";s:4:\"slug\";s:39:\"complete-list-of-wordpress-locale-codes\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2024-11-15T21:04:56+05:30\";s:8:\"category\";a:1:{i:0;s:14:\"developer-docs\";}}i:150;O:8:\"stdClass\":8:{s:2:\"id\";i:33306;s:5:\"title\";s:42:\"How to Translate CartFlows Using GlotPress\";s:7:\"content\";s:4228:\"CartFlows is translation-ready and includes .po and .mo files, which can be translated using tools like Poedit or GlotPress. We recommend GlotPress, the official WordPress translation platform.\n\n\n\nGlotPress is a web-based tool where anyone can contribute, suggest improvements, or help validate translations, making the process faster and more accurate.\n\n\n\nThis documentation will guide you through the steps to translate CartFlows into your language using GlotPress.\n\n\n\nGetting Started with Translations\n\n\n\nStep 1: Visit the GlotPress Project\n\n\n\nGlotPress for CartFlows Free is hosted on the WordPress repository here: https://translate.wordpress.org/projects/wp-plugins/cartflows/\n\n\n\nGlotPress for CartFlows Pro is available on our internal portal here: https://translate.cartflows.com/\n\n\n\nStep 2: Log in or Register a New Account\n\n\n\nYou’ll need to log in to your account to contribute translations. If you don’t have one, you can create it for free.\n\n\n\nStep 3: Select Your Language\n\n\n\nFrom the list of available languages, choose the one you want to contribute to.\n\n\n\n\n\n\n\nOn the language page, you will see the current state of the translation and a list of other contributors who have already translated part of the project.\n\n\n\nStep 4: Open the Translation Project\n\n\n\nAfter selecting your language, click on it to open the translation project. Here, you’ll see different sets of strings available for translation. Choose Stable (latest release) to work on the latest version of CartFlows.\n\n\n\n\n\n\n\nStep 5: Understand the Translation Interface\n\n\n\nOnce you’ve opened the translation set (e.g., Stable (latest release)), you’ll see a list of strings and a set of filters at the top of the page. These help you navigate and manage the translation status.\n\n\n\nHere’s what each filter means:\n\n\n\n\nAll – Shows all strings in the project.\n\n\n\nTranslated – Strings that have been translated and approved.\n\n\n\nUntranslated – Strings that haven’t been translated yet.\n\n\n\nWaiting – Translations submitted by contributors, awaiting approval.\n\n\n\nChanges requested – Translations that require edits based on reviewer feedback.\n\n\n\nFuzzy – Translations that may be inaccurate or partially matching and need review.\n\n\n\nWarnings – Strings with formatting issues or errors such as placeholders not matching.\n\n\n\n\n\n\n\n\nStep 6: Click on Any String and Translate It\n\n\n\n\n\n\n\nOnce you submit translations, they will be reviewed and approved by validators. After approval, they’ll be automatically included in future updates via the WordPress dashboard (for projects hosted on WordPress.org).\n\n\n\nWould You Like to Become a Translation Validator of CartFlows Pro?\n\n\n\nIf you’re interested in becoming a validator, please get in touch with us with the following details:\n\n\n\n\nYour WordPress.org username\n\n\n\nYour username on our CartFlows GlotPress Portal\n\n\n\nThe locale you would like to become a validator for\n\n\n\nDetails of your previous translations (if any)\n\n\n\n\nAfter your request is submitted, our team can grant you translation validator access.\n\n\n\nAs a validator, you\'ll be able to review and approve submitted translations, ensuring they are included in future plugin updates for all users.\n\n\n\nNeed to Add Translation in Your Project Immediately?\n\n\n\nExport Translation Files\n\n\n\nIf you want to implement a translation immediately on your site, you can export the current translation files in .po and .mo formats from GlotPress.\n\n\n\n\nGo to the language translation set.\n\n\n\nUse the Export option to download the .po and .mo files.\n\n\n\n\n\n\n\n\nUpload Translation Files to Your Website\n\n\n\nOnce downloaded, upload the files to the following location on your server via FTP or SFTP: /wp-content/languages/plugins/\n\n\n\n\n\n\n\nUsing the correct file naming convention is important so WordPress can detect the files properly. The filename must start with the text domain, followed by the locale code.\n\n\n\nExamples of file names for CartFlows:\n\n\n\n\nFor Indonesian: cartflows-id_ID.po and cartflows-id_ID.mo\n\n\n\nFor French: cartflows-fr_FR.po and cartflows-fr_FR.mo\n\n\n\n\nImportant: Always upload translation files to the /wp-content/languages/plugins/ directory. Avoid placing them inside the plugin folder, as they may be lost during plugin updates.\";s:3:\"url\";s:91:\"https://cartflows.com/docs/how-to-translate-cartflows-in-your-own-language-using-glotpress/\";s:4:\"slug\";s:63:\"how-to-translate-cartflows-in-your-own-language-using-glotpress\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-07-18T23:55:09+05:30\";s:8:\"category\";a:1:{i:0;s:19:\"translate-cartflows\";}}i:151;O:8:\"stdClass\":8:{s:2:\"id\";i:34934;s:5:\"title\";s:45:\"How to Move a Step from One Funnel to Another\";s:7:\"content\";s:1294:\"CartFlows includes an Import/Export feature to move complete funnels between websites. However, if you only need to move a single step from one funnel to another, you can do that manually using your page builder’s export and import tools.\n\n\n\n1. Export the Step Design\n\n\n\n\nGo to CartFlows &gt; Funnels and open the funnel that contains the step you want to move.\n\n\n\nOpen the step in your page builder and use its built-in export option to save the design:\n\nElementor: Refer to this guide on how to save a page as a template.\n\n\n\nBeaver Builder: Refer to this guide on saving templates.\n\n\n\nBricks Builder: Refer to this guide on saving templates.\n\n\n\n\n\n\n2. Create a Blank Step in the Target Funnel\n\n\n\n\nGo to the destination funnel where you want to move the step.\n\n\n\nAdd a new blank step of the same type (Landing, Checkout, Upsell, Downsell, or Thank You).\n\nFor example, to move a Landing page step, create a new Landing page step in the new funnel.\n\n\n\n\n\n\n\n\n\n\n3. Import the Step Design\n\n\n\n\nOpen the new blank step in the same page builder you used earlier.\n\n\n\nUse the import or template loading option to apply the previously exported design.\n\n\n\n\nIf you need help importing templates using your page builder, refer to this article: How to Import and Export CartFlows Pages with Your Page Builder\";s:3:\"url\";s:44:\"https://cartflows.com/docs/how-to-move-step/\";s:4:\"slug\";s:16:\"how-to-move-step\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-05T13:07:23+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"flow-step-clone\";}}i:152;O:8:\"stdClass\":8:{s:2:\"id\";i:37319;s:5:\"title\";s:73:\"How to Fix Request Timeout Errors When Importing Funnel or Step Templates\";s:7:\"content\";s:2852:\"If you\'re seeing a Request Timeout error while importing ready-made funnel or step templates in CartFlows, it usually means your website is having trouble connecting to our templates server.\n\n\n\nThis documentation explains what causes the issue and how to fix it.\n\n\n\nWhat Causes This Error?\n\n\n\nWhen you import a template in CartFlows, a request is made from your website to our templates server at: https://templates.cartflows.com/\n\n\n\nWordPress uses a core function called wp_remote_get() (through cURL) to handle this request.\n\n\n\nIf your server or host blocks this outgoing connection — usually due to firewalls, security rules, or server misconfiguration — the request will time out and the template will not be imported.\n\n\n\nWhere You\'ll See the Error\n\n\n\n\nThe “Import Template” button may appear stuck on “Importing Template”\n\n\n\nA timeout message may appear directly in the popup\n\n\n\n\n\n\n\n\n\nYou may also see a cURL error in the browser console or in plugin like Query Monitor\n\n\n\n\nHow to Fix It\n\n\n\nFollow these steps to troubleshoot and resolve the timeout issue:\n\n\n\n1. Check Security Plugins or Firewall\n\n\n\n\nTemporarily disable any firewall or security-related plugins on your site\n\n\n\nMake sure they are not blocking outgoing API requests\n\n\n\n\n2. Contact Your Hosting Provider\n\n\n\nAsk your hosting provider to check for:\n\n\n\n\nAny firewall rules (e.g. mod_security) that block outgoing cURL requests\n\n\n\nWhether outgoing requests to https://templates.cartflows.com/ are blocked\n\n\n\n\nIf needed, ask them to whitelist that domain to allow template imports.\n\n\n\n3. Check Server Requirements\n\n\n\nMake sure your server:\n\n\n\n\nIs running a recent version of PHP\n\n\n\nHas the cURL library installed and up to date\n\n\n\nHas sufficient memory (increase your PHP memory limit if needed)\n\n\n\nHas an adequate cURL timeout limit\n\n\n\n\nYou may also want to ask your host to check:\n\n\n\n\nIf wp-cron is disabled\n\n\n\nIf loopback requests are blocked or restricted\n\n\n\n\n4. Use the Query Monitor Plugin\n\n\n\nInstall Query Monitor and view the HTTP API Calls under the admin page where the error occurs. It can help you identify blocked or failed requests.\n\n\n\n5. Special Note for Managed WordPress Hosting\n\n\n\nIf you\'re using managed hosting, providers may apply strict limits on:\n\n\n\n\nExecution time\n\n\n\nMemory usage\n\n\n\nHTTP API requests\n\n\n\n\nAsk your host whether WordPress REST API requests or cURL operations are restricted — and request an exemption for our templates domain.\n\n\n\n6. Still Not Working?\n\n\n\nIf the above steps don’t resolve the issue, contact your hosting provider and ask them to confirm that your server can communicate with: https://templates.cartflows.com/ via cURL without limitations.If needed, you can also contact our support team and provide your website’s IP address. We\'ll check if it has been mistakenly blocked on our server — although this is rare.\";s:3:\"url\";s:89:\"https://cartflows.com/docs/request-timeout-error-while-importing-the-flow-step-templates/\";s:4:\"slug\";s:61:\"request-timeout-error-while-importing-the-flow-step-templates\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-04-17T21:43:43+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:153;O:8:\"stdClass\":8:{s:2:\"id\";i:37316;s:5:\"title\";s:55:\"How to Pre-Fill the Checkout Fields via URL Parameters?\";s:7:\"content\";s:2136:\"CartFlows now includes a feature to pre-fill checkout fields by passing customer information through URL parameters. After many requests, we have integrated this functionality directly into CartFlows to help you streamline the checkout experience and boost conversions.\n\n\n\nHow It Works\n\n\n\nThis feature is enabled by default in CartFlows. To use it, simply send the customer data as URL parameters to your CartFlows Checkout page. The fields will automatically be populated with the provided values when the page loads.\n\n\n\n\nImportant: This feature only works on the CartFlows Checkout page and will not function on any other page.\n\n\n\n\nHow to Use URL Parameters for Pre-Filling\n\n\n\nYou can use any contact form or external source that can redirect or link to your checkout page with URL parameters appended.\n\n\n\nFor example, if you want to pre-fill the customer\'s first name and email address, your checkout page URL should look like this:\n\n\n\nhttps://yourdomain.com/checkout-page/?billing_first_name=John&amp;billing_email=admin@admindomain.com\n\n\n\n\nSupported Field Names\n\n\n\nBelow is the list of billing and shipping field names you can use in the URL parameters to pre-fill the checkout fields.\n\n\n\n\n\n\n\nList of Billing Fields\n\n\n\n\nbilling_email\n\n\n\nbilling_first_name\n\n\n\nbilling_last_name\n\n\n\nbilling_phone\n\n\n\nbilling_address_1\n\n\n\nbilling_address_2\n\n\n\nbilling_city\n\n\n\nbilling_postcode\n\n\n\nbilling_country\n\n\n\nbilling_state\n\n\n\nbilling_company\n\n\n\n\n\n\nList of Shipping Fields\n\n\n\n\nshipping_email\n\n\n\nshipping_first_name\n\n\n\nshipping_last_name\n\n\n\nshipping_phone\n\n\n\nshipping_address_1\n\n\n\nshipping_address_2\n\n\n\nshipping_city\n\n\n\nshipping_postcode\n\n\n\nshipping_country\n\n\n\nshipping_state\n\n\n\nShipping_company\n\n\n\n\n\n\n\n\nDisabling the Pre-Fill Feature\n\n\n\nIf you prefer to disable this feature, you can do so by adding the following code snippet to your child theme’s functions.php file. This will disable the pre-fill functionality on all CartFlows Checkout pages:\n\n\n\nadd_filter( \'cartflows_auto_prefill_checkout_fields\', \'__return_false\' );\n\n\n\nTo use the above code, please refer to this documentation on how to safely add custom PHP code to your WordPress site.\";s:3:\"url\";s:82:\"https://cartflows.com/docs/how-to-pre-fill-the-checkout-fields-via-url-parameters/\";s:4:\"slug\";s:54:\"how-to-pre-fill-the-checkout-fields-via-url-parameters\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-27T19:22:44+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:154;O:8:\"stdClass\":8:{s:2:\"id\";i:34944;s:5:\"title\";s:29:\"CartFlows Block Editor Blocks\";s:7:\"content\";s:3725:\"CartFlows now includes native WordPress blocks, making it easier to build and customize your funnel steps using the Block Editor.\n\n\n\nThese blocks are designed to streamline the funnel-building process and are categorized into blocks available in both the Free and Pro versions.\n\n\n\nAvailable Blocks\n\n\n\nYou’ll find dedicated blocks for each CartFlows funnel step:\n\n\n\n\nNext Step Button / Link Block\n\n\n\nOpt-in Form Block\n\n\n\nCheckout Form Block\n\n\n\nUpsell &amp; Downsell Offer Blocks (includes variations and Accept/Reject options)\n\n\n\nOrder Review Block (for Thank You page)\n\n\n\n\nNote: Each block only appears within its relevant funnel step in the editor. For example, the Next Step Button block will only show when editing a Landing Page.\n\n\n\nStep-Wise Breakdown of Blocks &amp; Settings\n\n\n\n1. Landing Page – Next Step Button Block\n\n\n\nThis block allows you to guide users to the next funnel step.\n\n\n\n\n\n\n\n\nGeneral Tab: Adjust alignment, add icons, and customize text.\n\n\n\nStyle Tab: Modify block and text colors, padding, margins, and icon styles.\n\n\n\nContent Tab: Customize font size, typography, and content styling.\n\n\n\nAdvanced Tab: Add custom links or apply custom CSS for further control.\n\n\n\n\n2. Opt-in Page – Opt-in Form Block\n\n\n\nUse this block to collect lead information.\n\n\n\n\n\n\n\n\nGeneral Tab: Control the primary color and global typography.\n\n\n\nInput Field Tab: Style input fields including color, alignment, and typography.\n\n\n\nSubmit Button Tab: Customize the appearance of the submit button.\n\n\n\nAdditional Tab: Add custom CSS to personalize the design.\n\n\n\n\n3. Checkout Page – Checkout Form Block\n\n\n\nDesigned to handle everything from product details to payments.\n\n\n\n\n\n\n\n\nLayout Tab: Choose between One-Column, Two-Column, or Two-Step layouts.\n\n\n\nGlobal Tab: Set global colors and typography for the entire form.\n\n\n\nHeading Tab: Style headings within the checkout form.\n\n\n\nInput Fields Tab: Adjust the look and feel of form fields.\n\n\n\nButton Tab: Design checkout and continue buttons.\n\n\n\nPayment Section Tab: Control the design of the payment methods section.\n\n\n\nSuccess/Error Messages Tab: Style messages that appear after submission.\n\n\n\nProduct Options Tab: Customize how product variations are displayed.\n\n\n\nOrder Bump Tab: Style and manage the Order Bump layout.\n\n\n\nAdditional Tab: Add custom CSS for advanced tweaks.\n\n\n\n\n4 &amp; 5. Upsell &amp; Downsell Pages – Offer Blocks\n\n\n\nThese pages support product variations and feature dynamic Offer Blocks for streamlined offer handling.\n\n\n\n\n\n\n\nAvailable blocks for the Upsell &amp; Downsell Pages :\n\n\n\n\nOffer Accept/Reject Button\n\n\n\nOffer Accept/Reject Link\n\n\n\nOffer Product Title\n\n\n\nOffer Product Price\n\n\n\nOffer Product Description\n\n\n\nProduct Variations\n\n\n\nQuantity Selector\n\n\n\n\nAll content is dynamically rendered based on the offered product.\n\n\n\n6. Thank You Page – Order Review Block\n\n\n\nThis block is used to display post-purchase information and order details.\n\n\n\n\n\n\n\n\nGeneral Tab: Show or hide order review sections.\n\n\n\nSpacing Tab: Adjust spacing between headings and sections.\n\n\n\nHeading Tab: Style the heading text and typography.\n\n\n\nSection Tab: Customize the text, colors, and fonts for each section.\n\n\n\nOrder Review Tab: Manage order item styling.\n\n\n\nDownloads Tab: Display and style downloadable product info (if available).\n\n\n\nOrder Details Tab: Customize text and design for order metadata.\n\n\n\nCustomer Details Tab: Style billing and shipping details.\n\n\n\nAdditional Tab: Add custom CSS as needed.\n\n\n\n\nThese Gutenberg blocks give you full control over the design of each step, without needing shortcodes. However, if you are using another page builder, you can continue using it with guidance from our dedicated documentation on shortcode placement.\";s:3:\"url\";s:54:\"https://cartflows.com/docs/cartflows-gutenberg-blocks/\";s:4:\"slug\";s:26:\"cartflows-gutenberg-blocks\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-20T23:44:07+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:155;O:8:\"stdClass\":8:{s:2:\"id\";i:33520;s:5:\"title\";s:56:\"How to Update Your Payment Method on the CartFlows Store\";s:7:\"content\";s:515:\"In this documentation, we’ll walk you through updating your payment method on the CartFlows store in a few simple steps.\n\n\n\nSteps to update your payment method:\n\n\n\nStep 1: Log in to your Account\n\n\n\nVisit the CartFlows Store and log in using your credentials.\n\n\n\nStep 2: Add a Payment Method\n\n\n\nClick on the Subscriptions section from the sidebar and click the Add payment button.\n\n\n\n\n\n\n\nStep 3: Enter your payment details\n\n\n\nFill in your updated payment details and click on the Add payment method button to save.\";s:3:\"url\";s:54:\"https://cartflows.com/docs/update-your-payment-method/\";s:4:\"slug\";s:26:\"update-your-payment-method\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-03-13T23:43:40+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"account-store\";}}i:156;O:8:\"stdClass\":8:{s:2:\"id\";i:34943;s:5:\"title\";s:45:\"How to Renew your CartFlows Pro License Early\";s:7:\"content\";s:737:\"If you want to renew your CartFlows Pro license before the renewal date or before it expires, you can do so by following the steps below.\n\n\n\nRenewing Your License Early\n\n\n\nTo renew your CartFlows Pro license early:\n\n\n\n\nLog in to your CartFlows account.\n\n\n\nGo to the Subscriptions from the sidebar.\n\n\n\nClick the Renew now button.\n\n\n\nComplete the payment process, and your license will be renewed.\n\n\n\n\n\n\n\n\nWhat Happens After an Early Renewal?\n\n\n\nWhen you renew early, your next payment date will be extended by one full billing period.\n\n\n\nFor example, if your license renews annually on May 15, 2020, and your next payment is scheduled for May 15, 2021, renewing early on November 1, 2020, will move your next payment date to May 15, 2022.\";s:3:\"url\";s:66:\"https://cartflows.com/docs/renew-your-cartflows-pro-license-early/\";s:4:\"slug\";s:38:\"renew-your-cartflows-pro-license-early\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-02-25T16:12:58+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"account-store\";}}i:157;O:8:\"stdClass\":8:{s:2:\"id\";i:34941;s:5:\"title\";s:32:\"CartFlows Beaver Builder Modules\";s:7:\"content\";s:4592:\"CartFlows provides dedicated Beaver Builder modules that allow you to design and customize funnel pages more easily within the Beaver Builder editor. These modules offer enhanced styling options and greater flexibility compared to using shortcodes alone.\n\n\n\nThe modules are included in CartFlows and CartFlows Pro, and they correspond to the different funnel steps available in CartFlows.\n\n\n\nEach module is available only on its relevant funnel step, making it easier to design the page without manually inserting shortcodes.\n\n\n\nAvailable CartFlows Beaver Builder Modules\n\n\n\nCartFlows provides modules for the key funnel elements, including:\n\n\n\n\nNext Step Button / Link\n\n\n\nOpt-in Form\n\n\n\nCheckout Form\n\n\n\nUpsell and Downsell Offer Elements\n\n\n\nOrder Review (Thank You Page)\n\n\n\n\nWhen editing a step with Beaver Builder, the modules related to that specific step will appear in the Beaver Builder module list.\n\n\n\n\n\n\n\nModules by Funnel Step\n\n\n\nBelow is an overview of the modules available for each funnel step and the options you can configure.\n\n\n\nLanding Step – Next Step Button Module\n\n\n\nThe Landing step includes the Next Step Button module, which allows users to proceed to the next step in the funnel.\n\n\n\n\n\n\n\nWithin this module, you can configure:\n\n\n\nGeneral Tab\n\n\n\n\nChange the button text\n\n\n\nAdd or modify icons\n\n\n\nAdjust button link behavior\n\n\n\n\n\n\n\n\nStyle Tab\n\n\n\n\nControl the visual styling of the button content\n\n\n\nCustomize button appearance\n\n\n\nAdjust colors, spacing, and layout\n\n\n\n\n\n\n\n\nTypography Tab\n\n\n\n\nModify font family\n\n\n\nAdjust font size\n\n\n\nCustomize other typography settings\n\n\n\n\n\n\n\n\nAdvanced Tab\n\n\n\n\nConfigure spacing, margins, and layout options for the module section\n\n\n\n\n\n\n\n\nOpt-in Step – Opt-in Form Module\n\n\n\nThe Opt-in step includes the Opt-in Form module, which allows you to capture user information.\n\n\n\nWithin this module, you can configure:\n\n\n\nStyle Tab\n\n\n\n\nCustomize form text styling\n\n\n\nAdjust field text appearance\n\n\n\nModify button styling\n\n\n\n\n\n\n\n\nAdvanced Tab\n\n\n\n\nControl section spacing and layout options for the module\n\n\n\n\n\n\n\n\nCheckout Step – Checkout Form Module\n\n\n\nThe Checkout step includes the Checkout Form module, which displays the complete checkout form on the page.\n\n\n\nWithin this module, you can configure:\n\n\n\nGeneral Tab\n\n\n\n\nConfigure billing and shipping field display\n\n\n\nEnable or manage Order Bump and Pre-Checkout Offers\n\n\n\nManage product display options\n\n\n\nSelect the checkout layout\n\n\n\n\n\n\n\n\nStyle Tab\n\n\n\n\nCustomize headings\n\n\n\nAdjust input field styling\n\n\n\nStyle buttons\n\n\n\nModify payment section appearance\n\n\n\nConfigure validation error message styling\n\n\n\n\n\n\n\n\n\n\n\n\nAdvanced Tab\n\n\n\n\nControl margins, padding, and layout for the module container\n\n\n\n\n\n\n\n\nUpsell and Downsell Steps – Offer Modules\n\n\n\nThe Upsell and Downsell steps support several modules used to display and manage offer elements. These modules also support product variations.\n\n\n\n\n\n\n\nAvailable modules include:\n\n\n\n\nOffer Yes / No Button – Displays buttons for accepting or rejecting the offer\n\n\n\nOffer Yes / No Link – Displays links for accepting or rejecting the offer\n\n\n\nOffer Product Title – Dynamically displays the offer product title\n\n\n\nOffer Product Price – Dynamically displays the product price\n\n\n\nOffer Product Description – Displays the product description\n\n\n\nOffer Product Variations – Displays product variation options when available\n\n\n\nOffer Product Quantity Field – Allows customers to select the quantity of the offered product\n\n\n\n\nEach module includes styling controls within the Style tab to customize its appearance.\n\n\n\nThank You Step – Order Review Module\n\n\n\nThe Thank You step includes the Order Details Form module, which displays the order details after the purchase is completed.\n\n\n\n\n\n\n\nWithin this module, you can configure:\n\n\n\nGeneral Tab\n\n\n\n\nModify the heading displayed on the Thank You page\n\n\n\nEnable or disable specific order review sections\n\n\n\n\n\n\n\n\nStyle Tab\n\n\n\n\nCustomize the appearance of the order review form\n\n\n\nAdjust colors, layout, and styling options\n\n\n\n\n\n\n\n\nAdvanced Tab\n\n\n\n\nControl spacing and layout for the module section\n\n\n\n\n\n\n\n\nAdditional Notes\n\n\n\nThese Beaver Builder modules provide a more flexible way to design CartFlows funnel pages without manually inserting shortcodes.\n\n\n\nHowever, if you prefer to build your pages using shortcodes, you can still do so by adding the appropriate CartFlows shortcodes to your page layouts. Refer to the following documentation to learn where each shortcode should be placed for different funnel steps: https://cartflows.com/docs/placing-shortcode-in-the-right-places/\";s:3:\"url\";s:63:\"https://cartflows.com/docs/beaver-builder-modules-of-cartflows/\";s:4:\"slug\";s:35:\"beaver-builder-modules-of-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-03-14T01:54:04+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:158;O:8:\"stdClass\":8:{s:2:\"id\";i:33291;s:5:\"title\";s:69:\"How to Setup Square Gateway for the Cartflows Upsell &#038; Downsell?\";s:7:\"content\";s:1733:\"Starting with CartFlows Pro version 1.5.10, we’ve added custom support for the much-requested Square Payment Gateway. You can now use Square to offer both upsell and downsell offers in your CartFlows funnels.\n\n\n\nFollow the steps below to configure Square Gateway with your CartFlows setup.\n\n\n\nPrerequisites\n\n\n\nBefore you begin, please make sure you have the following ready:\n\n\n\n\nA registered Square Payment Gateway account. If you don’t have one, you can create it here.\n\n\n\nAfter logging in, navigate to My Applications to retrieve your Application ID, and go to the Account section to get your Access Token.\n\n\n\nDownload and install the Square Payment Gateway plugin for WooCommerce. If you need help installing plugins, refer to this guide.\n\n\n\nYour website must have SSL enabled, and all URLs should be forced to use HTTPS.\n\n\n\n\nSteps to Enable Square Gateway\n\n\n\nStep 1: Enable Square in WooCommerce\n\n\n\n\nFrom your WordPress dashboard, go to: WooCommerce → Settings → Payments tab\n\n\n\nLocate Square – Credit Card and toggle it to Enable.\n\n\n\nClick Save Changes at the bottom of the page.\n\n\n\n\n\n\n\n\nStep 2: Configure Square Settings\n\n\n\nAfter enabling, a Square tab will appear under the Payments section. Click on it to begin configuration.\n\n\n\n\n\n\n\nStep 3: Add Credentials\n\n\n\n\nIf you’re testing, enable the Sandbox mode checkbox.\n\n\n\nEnter the corresponding Application ID and Access Token (for either Sandbox or Live, depending on your setup).\n\n\n\n\n\n\n\n\nOnce configured, your CartFlows upsell and downsell offers will be ready to accept payments via Square, giving your customers a secure and seamless checkout experience.\n\n\n\nFor more details about Square’s WooCommerce settings, you can refer to this WooCommerce documentation.\";s:3:\"url\";s:62:\"https://cartflows.com/docs/setup-square-gateway-for-cartflows/\";s:4:\"slug\";s:34:\"setup-square-gateway-for-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-28T17:54:21+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:159;O:8:\"stdClass\":8:{s:2:\"id\";i:34936;s:5:\"title\";s:27:\"CartFlows Elementor Widgets\";s:7:\"content\";s:3332:\"CartFlows provides Elementor widgets that give you greater flexibility and control when designing your CartFlows pages. These widgets allow you to customize shortcode and build your funnel steps visually using Elementor, making the design process easier and more intuitive.\n\n\n\nThese widgets are developed by the CartFlows team and not by Elementor, and are divided into two groups, Free and Pro, to enhance your design experience.\n\n\n\nYou’ll find Elementor widgets for all CartFlows shortcodes in both Free and Pro versions:\n\n\n\n\nNext Step Button/Link Widget\n\n\n\nOptin Form Widget\n\n\n\nCheckout Form Widget\n\n\n\nUpsell &amp; Downsell Widgets (Product variations, Offer Accept/Reject buttons/links)\n\n\n\nOrder Review Widget (for Thank You page)\n\n\n\n\n\n\n\n\nEach widget only appears on its respective page type when editing in Elementor — for example, the Next Step Button widget appears on the Landing Page, while the Checkout Form widget appears on the Checkout Page.\n\n\n\nPage-Wise Widget Details\n\n\n\nLanding Page – Next Step Widget\n\n\n\nThis page includes one widget: Next Step Button/Link.\n\n\n\n\n\n\n\nContent Tab: Customize the button text and icon.\n\n\n\n\n\n\n\nStyle Tab: Includes General and Content sections for full design control of the button/link.\n\n\n\n\n\n\n\nAdvanced Tab: Modify the styling of the section that contains the widget.\n\n\n\nOptin Page – Optin Form Widget\n\n\n\nThis page includes the Optin Form Widget. Ensure your product is Simple, Virtual, and Downloadable to use this form.\n\n\n\n\n\n\n\nStyle Tab: Customize form fields, and button appearance.\n\n\n\n\n\n\n\nAdvanced Tab: Control the styling of the section where the form is placed.\n\n\n\nCheckout Page – Checkout Form Widget\n\n\n\nThe Checkout Form Widget allows customization for billing, shipping, and order elements.\n\n\n\n\n\n\n\nContent Tab: Manage Checkout Layout and Product Options settings\n\n\n\n\n\n\n\nStyle Tab: Adjust the layout and design for checkout form components.\n\n\n\n\n\n\n\nAdvanced Tab: Fine-tune section-level styling and spacing.\n\n\n\nUpsell &amp; Downsell Pages – Offer Widgets\n\n\n\nThese pages support variation products and include widgets to dynamically display offer details.\n\n\n\n\n\n\n\nAvailable widgets:\n\n\n\n\nOffer Accept/Reject Buttons\n\n\n\nOffer Accept/Reject Links\n\n\n\nOffer Product Title\n\n\n\nOffer Product Price\n\n\n\nOffer Product Description\n\n\n\nOffer Product Variations\n\n\n\nOffer Product Quantity Field\n\n\n\nStyle Tab: Customize the appearance of each widget.\n\n\n\nAdvanced Tab: Adjust section-level styling for the displayed content.\n\n\n\n\nThank You Page – Order Review Widget\n\n\n\nThis widget allows you to design the order review section and control the visibility of elements displayed on the Thank You page.\n\n\n\nContent Tab: Control the actual content of the order review form, such as layout, text, and what elements are shown or hidden.\n\n\n\n\n\n\n\nStyle Tab: Modify the overall look and feel of the order review form.\n\n\n\n\n\n\n\nAdvanced Tab: Adjust layout and design of the containing section.\n\n\n\nWhy Use CartFlows Elementor Widgets\n\n\n\nThese widgets provide a streamlined way to design CartFlows pages without manually inserting shortcodes. They make it easier to control styling directly in Elementor, ensuring your funnel pages look professional and consistent.\n\n\n\nIf you prefer to use shortcodes instead of Elementor, refer to our shortcode documentation to see where each shortcode should be added.\";s:3:\"url\";s:58:\"https://cartflows.com/docs/elementor-widgets-of-cartflows/\";s:4:\"slug\";s:30:\"elementor-widgets-of-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-12-24T21:55:32+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:160;O:8:\"stdClass\":8:{s:2:\"id\";i:34940;s:5:\"title\";s:43:\"How to Refresh / Flush WordPress Permalinks\";s:7:\"content\";s:724:\"In some cases, especially when a plugin creates a new Custom Post Type (CPT) or custom URL structure, WordPress permalinks may need to be refreshed. This ensures that your pages and steps load correctly and avoid 404 or layout-related errors.\n\n\n\nThis documentation explains how to manually flush or refresh WordPress permalinks.\n\n\n\nRefresh / Flush Permalinks in WordPress\n\n\n\nFollow the steps below to refresh your site\'s permalinks:\n\n\n\n\nIn your WordPress admin area, go to Settings &gt; Permalinks.\n\n\n\nWithout changing any settings, click the Save Changes button.\n\n\n\n\n\n\n\n\nThis action will flush the rewrite rules and refresh your permalinks automatically.\n\n\n\nThat’s it — your permalinks have been successfully refreshed.\";s:3:\"url\";s:56:\"https://cartflows.com/docs/refresh-wordpress-permalinks/\";s:4:\"slug\";s:28:\"refresh-wordpress-permalinks\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-04-11T14:25:37+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:161;O:8:\"stdClass\":8:{s:2:\"id\";i:34938;s:5:\"title\";s:66:\"How to Replace First Product on the Checkout Page with Order Bump?\";s:7:\"content\";s:2858:\"CartFlows Pro order bumps normally add an extra product alongside whatever the customer is already buying. There\'s also a setting that lets an order bump replace the customer\'s original checkout product instead, which is perfect for \"upgrade your order\" style offers, like swapping a Basic plan for a Pro plan right at checkout.\n\n\n\nThis guide walks you through how the replacement works, how to turn it on for an order bump, and what your customers see when they use it.\n\n\n\nHow Replacing a Product Works\n\n\n\nWhen an order bump is set up this way, checking the bump\'s box doesn\'t just add a new line to the cart, it swaps out the original product for the bump product.\n\n\n\n\nIf the customer leaves the bump unchecked, checkout works exactly as normal with the original product.\n\n\n\nIf the customer checks the bump, the original product is removed from the order and the bump product takes its place, with the total updating instantly.\n\n\n\nIf the customer changes their mind and unchecks the bump again, the original product is added back automatically, at the same quantity it had before.\n\n\n\n\nThe customer never has to manually remove anything from their order, the swap happens for them in the background.\n\n\n\nHow to Set Up Product Replacement\n\n\n\nStep 1. From the WordPress admin, go to CartFlows → Funnels and open the funnel that contains the checkout step you want to update.\n\n\n\n\n\n\n\nStep 2. Click the checkout step settings(cog icon) to open its settings.\n\n\n\n\n\n\n\nStep 3. In the left sidebar, click Order Bumps, then open the order bump you want to configure (or create a new one).\n\n\n\nStep 4. Click the Product tab.\n\n\n\nStep 5. Scroll down to the Settings section, below the product picker.\n\n\n\n\n\n\n\nStep 6. Turn on Replace First Product. This replaces the first product configured on your checkout step with the order bump product whenever the bump is accepted.\n\n\n\nStep 7. Optionally, configure the related settings in the same section:\n\n\n\n\nShow Pre-Checked — Automatically selects the bump (and triggers the replacement) as soon as the checkout page loads, so the customer doesn\'t need to check anything themselves.\n\n\n\nEnable Quantity Field — Lets the customer choose how many of the bump product they want. Whatever quantity they pick carries over to the replacement.\n\n\n\n\nStep 8. Click Save at the top right.\n\n\n\nProduct replacement is now active on that order bump.\n\n\n\nThe Replacement in Action\n\n\n\nWhen a customer reaches the checkout page, they see the order bump offer wherever it\'s positioned on the page, before their details, after them, in the order summary, or right before the payment button.\n\n\n\n\n\n\n\nAs soon as the customer checks the box, the order summary updates immediately, no page reload needed. The original product disappears and the bump product appears in its place, with the total recalculated to match.\n\n\n\n\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:79:\"https://cartflows.com/docs/replace-first-product-with-order-bump-checkout-page/\";s:4:\"slug\";s:51:\"replace-first-product-with-order-bump-checkout-page\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-09-21T19:10:30+05:30\";s:8:\"category\";a:1:{i:0;s:10:\"order-bump\";}}i:162;O:8:\"stdClass\":8:{s:2:\"id\";i:34937;s:5:\"title\";s:64:\"How to Replace the Main Checkout Order with the Upsell/Downsell?\";s:7:\"content\";s:1996:\"With CartFlows Pro version 1.6.0, we’re excited to introduce the Replace Main Order feature, designed to help you offer upgrade options directly from your Upsell or Downsell pages by replacing the original purchase made on the checkout page.\n\n\n\nWhat does this feature do?\n\n\n\nThis feature allows you to offer an upgraded plan or product on your Upsell/Downsell pages and replace the main product purchased during checkout. For example, if a customer buys an Annual Plan at checkout, you can offer them a Lifetime Plan as an upsell and replace the original order with this upgraded plan seamlessly.\n\n\n\nHow does it work?\n\n\n\nLet’s say you have two products:\n\n\n\n\nProduct A: Annual Plan (sold on the checkout page)\n\n\n\nProduct B: Lifetime Plan (offered as an upsell or downsell)\n\n\n\n\nIf you want to replace Product A with Product B after checkout, simply select Product B on your Upsell/Downsell page and enable the Cancel Main Order option.\n\n\n\nWhen enabled, CartFlows will:\n\n\n\n\nCharge the price difference between the upsell/downsell product and the original checkout product\n\n\n\nCancel the original order\n\n\n\nReplace it with the upgraded product from the Upsell/Downsell page\n\n\n\n\nImportant Requirements\n\n\n\nTo use this feature successfully, please note the following:\n\n\n\n\nThe Create a new child order option must be enabled in CartFlows > Settings > Order tab\n\n\n\nThe upsell/downsell product price must be greater than the main checkout product price\n\n\n\nWhen using multiple upsells, the main order will be replaced only by the first upsell/downsell offer that meets the criteria\n\n\n\n\nHow to enable the Replace Main Order feature\n\n\n\nFollow these simple steps:\n\n\n\n1: Go to CartFlows > Settings and click Order tab on the sidebar then enable Create a new child order\n\n\n\n\n\n\n\n2: Open the backend settings of the Upsell/Downsell page where you want to enable the replacement\n\n\n\n3: Select the product you want to offer as the upgrade\n\n\n\n4: Enable the Replace Main Order option\n\n\n\n\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:76:\"https://cartflows.com/docs/replace-main-checkout-order-with-upsell-downsell/\";s:4:\"slug\";s:48:\"replace-main-checkout-order-with-upsell-downsell\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-06T12:38:25+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:163;O:8:\"stdClass\":8:{s:2:\"id\";i:33192;s:5:\"title\";s:41:\"How to Use A/B Split Testing in CartFlows\";s:7:\"content\";s:2669:\"Split testing (A/B testing) in CartFlows allows you to test different versions of a funnel step to determine which version performs better. You can create variations of a step and distribute traffic between them to measure conversions and optimize your funnel performance.\n\n\n\nThis documentation explains how to create and manage a split test for a funnel step in CartFlows.\n\n\n\nStep 1: Open the Funnel\n\n\n\n\nLog in to your WordPress dashboard.\n\n\n\nNavigate to CartFlows &gt; Funnels.\n\n\n\nLocate the funnel where you want to run the split test.\n\n\n\nClick on the funnel to open its steps.\n\n\n\n\n\n\n\n\nYou will now see the Funnel Steps screen where all steps of the funnel are listed.\n\n\n\nStep 2: Create a Variation of the Step\n\n\n\nTo run a split test, you first need a second variation of the step.\n\n\n\n\nLocate the step you want to test (for example, a Checkout step).\n\n\n\nClick the three dot icon next to the step nad select A/B Test\n\n\n\n\nCartFlows will create a duplicate version of that step, which will act as the variation for testing.\n\n\n\nYou can edit the cloned step and modify elements such as:\n\n\n\n\nPage design\n\n\n\nCopy or messaging\n\n\n\nLayout\n\n\n\nProduct details\n\n\n\nOffers or order bumps\n\n\n\n\n\n\n\n\nThis allows you to test different versions of the same step.\n\n\n\nStep 3: Configure Traffic Distribution\n\n\n\nInside the split test settings popup, you can control how traffic is distributed between the variations.\n\n\n\n\nClick Split Test Settings (cog icon) and a popup window will open.\n\n\n\nUse the sliders to adjust the traffic percentage for each variation.\n\n\n\nFor example:\n\nStep A – 50%\n\n\n\nStep B – 50%\n\n\n\n\n\n\nYou can adjust the percentages depending on how you want to distribute visitors between the variations.\n\n\n\n\n\n\n\nAfter configuring the traffic distribution click Save Settings.\n\n\n\nStep 4: Start Split Testing\n\n\n\nOnce you have multiple versions of the step:\n\n\n\n\nIn the Funnel Steps section, locate the step that now has multiple variations.\n\n\n\nClick Start Split Test.\n\n\n\n\n\n\n\n\nCartFlows will activate the split test and begin sending traffic to the different step variations according to the distribution you configured.\n\n\n\nMonitoring Split Test Results\n\n\n\nOnce the split test is running, CartFlows will track performance metrics for each variation, including:\n\n\n\n\nViews\n\n\n\nConversions\n\n\n\nRevenue (when applicable)\n\n\n\n\n\n\n\n\nYou can monitor these metrics directly in the Funnel Steps area to determine which variation performs better.\n\n\n\nEnding a Split Test\n\n\n\nAfter collecting enough data:\n\n\n\n\nReview the performance of each variation.\n\n\n\nSelect the version that performs best.\n\n\n\nDeclare the winner&nbsp; to End the split test and keep the winning variation active in your funnel.\";s:3:\"url\";s:51:\"https://cartflows.com/docs/cartflows-split-testing/\";s:4:\"slug\";s:23:\"cartflows-split-testing\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-06T12:11:00+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:164;O:8:\"stdClass\":8:{s:2:\"id\";i:34935;s:5:\"title\";s:56:\"How Does CartFlows Work with and without Store Checkout?\";s:7:\"content\";s:1830:\"CartFlows provides two ways to handle the checkout process, with or without Store Checkout. This documentation explains how each method works and which one is best suited for your store.\n\n\n\nHow CartFlows Works without Store Checkout\n\n\n\nBy default, CartFlows funnels work independently. You can send users directly to a Landing Page or Checkout Page via ads, social media, or your website’s navigation.\n\n\n\nDefault Funnel Process:\n\n\n\nLanding Page > Checkout Page > Upsell Page (Pro) > Downsell Page (Pro) > Thank You Page\n\n\n\nYou can use this method to:\n\n\n\n\nPromote individual products via ads and social media.\n\n\n\nLink users directly to a custom Landing Page or Checkout Page.\n\n\n\nAdd custom navigation to direct users to specific funnels.\n\n\n\n\n\n\n\n\nHow CartFlows Works with Store Checkout\n\n\n\nWith Store Checkout, CartFlows replaces WooCommerce’s default Checkout page. This allows you to:\n\n\n\n\nSend all WooCommerce purchases through a CartFlows Checkout Page.\n\n\n\nSupport multiple products without creating a separate funnel for each one.\n\n\n\nOffer upsells and downsells for store-wide products, increasing average order value.\n\n\n\nUse a custom checkout experience across your entire store.\n\n\n\n\nStore Checkout Process:\n\n\n\nShop Page > Cart Page (optional) > CartFlows Checkout Page > Thank You Page\n\n\n\nThis method is best if you:\n\n\n\n\nHave a large number of products and want to use a single, optimized checkout page.\n\n\n\nWant to redirect users from any page (product pages, social media, or ads) to a custom CartFlows checkout.\n\n\n\n\n\n\n\n\nWhich One Should You Use?\n\n\n\n\nUse Store Checkout if you sell multiple products and want a single, optimized checkout.\n\n\n\nUse funnels without Store Checkout if you need a custom sales journey for individual products.\n\n\n\n\nFor more details on setting up Store Checkout, see: Store Checkout Documentation\";s:3:\"url\";s:79:\"https://cartflows.com/docs/how-cartflows-work-with-and-without-global-checkout/\";s:4:\"slug\";s:51:\"how-cartflows-work-with-and-without-global-checkout\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-01-30T15:31:42+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"getting-started\";}}i:165;O:8:\"stdClass\":8:{s:2:\"id\";i:33122;s:5:\"title\";s:66:\"How to Enable the CartFlows Step Post Types for the Page Builders?\";s:7:\"content\";s:1263:\"CartFlows steps like Landing, Checkout, Upsell, and Thank You are built using a custom post type called cartflows_step. To visually edit these steps using a page builder, that builder must support custom post types.\n\n\n\nMost page builders automatically detect and support custom post types, including cartflows_step. However, in certain cases, you may need to manually enable it from your page builder’s settings panel.\n\n\n\nBelow is an example using the DIVI builder.The process is similar in other popular page builders like Elementor, Beaver Builder, and Brizy — typically found in their post type or integration settings.\n\n\n\nHow to Enable CartFlows Steps in DIVI?\n\n\n\nIf you\'re using the DIVI Builder, follow these steps to enable editing for CartFlows steps:\n\n\n\nUsing the DIVI Builder Plugin:\n\n\n\n\nNavigate to the DIVI menu in your WordPress dashboard.\n\n\n\nClick on Plugin Options.\n\n\n\nGo to the Post Type Integration tab.\n\n\n\nEnable the checkbox for Steps.\n\n\n\n\n\n\n\n\nUsing the DIVI Theme:\n\n\n\n\nNavigate to the DIVI menu in your WordPress dashboard.\n\n\n\nClick on Theme Options.\n\n\n\nGo to the Builder tab.\n\n\n\nEnable the checkbox for Steps.\n\n\n\n\n\n\n\n\nOnce enabled, you’ll be able to launch the DIVI builder when editing any CartFlows step.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:78:\"https://cartflows.com/docs/enable-cartflows-step-post-types-for-page-builders/\";s:4:\"slug\";s:50:\"enable-cartflows-step-post-types-for-page-builders\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-08-02T18:31:09+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:166;O:8:\"stdClass\":8:{s:2:\"id\";i:33099;s:5:\"title\";s:84:\"How to Display the &#8220;Account Creation Fields&#8221; on CartFlows Checkout Page?\";s:7:\"content\";s:1588:\"Allowing users to create an account directly on the checkout page is a great way to streamline the purchase process and improve the overall shopping experience. With this setup, users don’t have to register separately, they can create their account while completing their purchase.\n\n\n\nHow does it work?\n\n\n\nWooCommerce provides built-in options to collect account creation details such as username and password directly on the checkout page. These fields are displayed based on your configuration in the WooCommerce > Settings > Accounts &amp; Privacy section.\n\n\n\nSteps to enable account creation fields\n\n\n\nTo show the account fields on the CartFlows checkout page, follow these steps:\n\n\n\n\nNavigate to WooCommerce > Settings > Accounts &amp; Privacy\n\n\n\nUnder the Account creation section, enable:\n\nAllow customers to create an account during checkout\n\n\n\n(Optional) Enable additional options such as allowing account creation from the “My Account” page or automatically generating usernames/passwords\n\n\n\n\n\nSave changes\n\n\n\n\nOnce enabled, WooCommerce will display the account creation fields on the checkout page when a non-logged-in user attempts to place an order.\n\n\n\nSince CartFlows uses the native WooCommerce checkout functionality, the account creation fields will appear on your CartFlows checkout page as well, no additional setup is required.\n\n\n\nHelpful Resources\n\n\n\n\nFor a detailed explanation of each option, check out WooCommerce’s official documentation\n\n\n\nPrefer a visual walkthrough? Watch this step-by-step video guide.\n\n\n\n\n\nhttps://www.youtube.com/watch?v=AGZSeX5I-wo\";s:3:\"url\";s:74:\"https://cartflows.com/docs/display-account-creation-fields-with-cartflows/\";s:4:\"slug\";s:46:\"display-account-creation-fields-with-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-01T22:21:35+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:167;O:8:\"stdClass\":8:{s:2:\"id\";i:32997;s:5:\"title\";s:56:\"How to Change the &#8220;Choose A variation&#8221; text?\";s:7:\"content\";s:1290:\"When using the Product Options feature in CartFlows, customers may see a “Choose a variation” link (if there is a variable product) that opens a variation selection popup. This label can be customized to better match your store’s language, branding, or product tone.\n\n\n\nCartFlows does not provide a setting in the dashboard to change this text, but it can be easily modified using a filter we provided.\n\n\n\nStep 1: Choose How to Add Custom Code\n\n\n\nYou can use either of the following methods to add the filter:\n\n\n\n\nUse a child theme and place the code in the functions.php file.\n\n\n\nUse a code snippet plugin like Code Snippets for safer and easier management.\n\n\n\n\nStep 2: Add the Filter Code\n\n\n\nCopy and paste the following snippet into your chosen method:\n\n\n\nadd_filter( \'cartflows_variation_popup_toggle_text\', \'change_variation_toggle_text\', 10, 1 );/** * Change Choose a variation text. * * @return text. */function change_variation_toggle_text( $text ) {	return \"Add your choice of text here\";}\n\n\n\nStep 3: Save Changes and Test\n\n\n\nAfter saving the changes, visit your checkout page where the Product Options popup appears and confirm that the new text displays as expected.\n\n\n\nNote: For detailed guidance on adding custom code to your site, please refer to our documentation here.\";s:3:\"url\";s:49:\"https://cartflows.com/docs/change-variation-text/\";s:4:\"slug\";s:21:\"change-variation-text\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-11T22:14:55+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"code-snippets\";}}i:168;O:8:\"stdClass\":8:{s:2:\"id\";i:32995;s:5:\"title\";s:56:\"How to Allow Cache Plugins to Cache the CartFlows Pages?\";s:7:\"content\";s:1776:\"By default, CartFlows prevents its pages from being cached by common caching plugins. This is done to avoid potential conflicts and ensure that funnel steps work correctly out of the box.\n\n\n\nHowever, if you understand the implications and want to allow caching on CartFlows pages for performance reasons, this documentation explains how to do it.\n\n\n\nWhy CartFlows Pages Are Not Cached\n\n\n\nCartFlows includes special constants in its code that instruct caching plugins to skip its pages:\n\n\n\n\nDONOTCACHEPAGE\n\n\n\nDONOTCACHEOBJECT\n\n\n\nDONOTCACHEDB\n\n\n\n\nMany popular caching plugins look for these constants, and when detected, they automatically exclude the page from being cached.\n\n\n\nHow to Allow Caching for CartFlows Pages\n\n\n\nYou can disable this restriction by using a filter provided by CartFlows. This filter allows you to override the default behavior and selectively allow caching for specific step pages.\n\n\n\nAdd This Filter to Your Child Theme\n\n\n\nTo allow caching, add the following code to your child theme’s functions.php file:\n\n\n\nadd_filter( \'cartflows_do_not_cache_step\', \'cache_CartFlows_pages\' );\n\nfunction cache_CartFlows_pages( $post_id ) {\n \n// If you want to remove more pages from the cache then add those page\'s id in the array.\n\n	if( in_array( $post_id , array( \'add_your_landing_page_ids_comma_separated_id_more_than_one\' ) ) ){\n		return false; // Cache the Pages.\n	}\n\n	return true; // Do Not cache.\n}\n\n\n\nYou can find your step page IDs by going to CartFlows &gt; Funnels, opening the Funnel, then hovering over the Step name to view the ID in the URL.\n\n\n\n\n\n\n\nIn the screenshot above, the Step ID is 68.\n\n\n\nHow to Add Custom Code Safely\n\n\n\nIf you’re not sure how to add code to your functions.php file, follow this guide: How to Add Custom Code to WordPress\";s:3:\"url\";s:72:\"https://cartflows.com/docs/allow-cache-plugins-to-cache-cartflows-pages/\";s:4:\"slug\";s:44:\"allow-cache-plugins-to-cache-cartflows-pages\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-26T20:01:44+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"code-snippets\";}}i:169;O:8:\"stdClass\":8:{s:2:\"id\";i:32963;s:5:\"title\";s:79:\"How to Collect the User&#8217;s Contact Data and Redirect to the Checkout Page?\";s:7:\"content\";s:1750:\"If you\'re looking to collect a user’s basic information before sending them to the checkout page, you can achieve this easily using either the CartFlows Optin step or a custom form on a landing page.\n\n\n\nOption 1: Using the CartFlows Optin Step\n\n\n\nCartFlows provides a built-in Optin step designed for lead generation. When a user submits the Optin form, an order is automatically created in WooCommerce. The user\'s name and email are captured and stored as part of that order.\n\n\n\nIf you’re using a CRM, you can integrate it with WooCommerce. Once integrated, your CRM plugin can sync with WooCommerce and receive the user’s contact details as soon as the order is created.\n\n\n\nFor a complete guide on setting up the Optin step, refer to this documentation.\n\n\n\nOption 2: Using a Custom Form and Redirect\n\n\n\nIf you prefer to use your own form module (e.g., from a page builder like Elementor), you can still capture user information and redirect to the checkout page. Here’s how:\n\n\n\nStep 1: Create a Landing Page\n\n\n\nDesign a landing page with details about your product or offer.\n\n\n\nStep 2: Add a Contact Form\n\n\n\nUse your page builder’s form module (e.g., Elementor Form, WPForms, etc.) to collect basic information like name and email.\n\n\n\nStep 3: Set a Redirect URL\n\n\n\nIn the form settings, configure the redirect action so that once the form is submitted, users are sent directly to your Checkout page URL.\n\n\n\nStep 4: Done!\n\n\n\nWhen users submit the form, their data is captured by the form plugin, and they are redirected to your checkout step to complete the purchase.\n\n\n\nNote: This method does not create a WooCommerce order automatically. If you need the lead data synced to your CRM, make sure your form plugin supports that integration.\";s:3:\"url\";s:84:\"https://cartflows.com/docs/collect-users-contact-data-and-redirect-to-checkout-page/\";s:4:\"slug\";s:56:\"collect-users-contact-data-and-redirect-to-checkout-page\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-30T20:17:13+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:170;O:8:\"stdClass\":8:{s:2:\"id\";i:32955;s:5:\"title\";s:46:\"How to Duplicate a Funnel or Step in CartFlows\";s:7:\"content\";s:1307:\"CartFlows allows you to quickly duplicate funnels or individual steps with just one click. This is useful when you want to reuse existing layouts, settings, or configurations without building everything from scratch.\n\n\n\nThis documentation shows you how to duplicate a funnel or step from the CartFlows dashboard.\n\n\n\nHow to Duplicate a Funnel\n\n\n\nTo duplicate an entire funnel:\n\n\n\n\nGo to CartFlows &gt; Funnels in your WordPress admin.\n\n\n\nHover over the funnel you want to copy.\n\n\n\nClick Duplicate.\n\n\n\n\n\n\n\n\nCartFlows will create a new funnel with the same steps and configurations. You can rename or modify it as needed.\n\n\n\nHow to Duplicate a Step\n\n\n\nTo duplicate a specific step:\n\n\n\n\nGo to CartFlows &gt; Funnels.\n\n\n\nClick on the funnel that contains the step you want to duplicate.\n\n\n\nHover over the step and click Duplicate.\n\n\n\n\n\n\n\n\nThe duplicated step will appear at the bottom of the funnel and will have the word “Clone” added to its title. You can rename it and drag it to a different position within the funnel if needed.\n\n\n\nThings to Keep in Mind\n\n\n\n\nDuplicating a funnel copies all its steps and their settings.\n\n\n\nDuplicating a step copies only that step — not the entire funnel.\n\n\n\nIf you\'re using a page builder (like Elementor or Gutenberg), the design inside the step will also be copied.\";s:3:\"url\";s:56:\"https://cartflows.com/docs/clone-flow-step-in-cartflows/\";s:4:\"slug\";s:28:\"clone-flow-step-in-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-20T18:37:42+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"flow-step-clone\";}}i:171;O:8:\"stdClass\":8:{s:2:\"id\";i:32938;s:5:\"title\";s:57:\"How to Enable/Add Coupons on the CartFlows Checkout page?\";s:7:\"content\";s:2469:\"CartFlows makes it easy to allow your customers to apply discount coupons directly at checkout. You can control the visibility of the coupon field, and even customize the field and button text to better match your brand.\n\n\n\nStep 1: Enable Coupons in WooCommerce\n\n\n\nBefore displaying coupons on your CartFlows checkout page, make sure coupons are enabled in WooCommerce:\n\n\n\n\nNavigate to WooCommerce &gt; Settings &gt; General.\n\n\n\nCheck the option “Enable the use of coupon codes”.\n\n\n\nCreate and configure your coupons under WooCommerce &gt; Marketing &gt; Coupons.\n\n\n\n\nIf you\'re new to WooCommerce coupons, you can refer to this official WooCommerce guide for detailed steps.\n\n\n\nOnce your coupons are set up, the coupon field will automatically appear on your CartFlows checkout pages.\n\n\n\nStep 2: Show or Hide the Coupon Field on a Specific Checkout Page\n\n\n\nYou can choose to enable or disable the coupon field for each individual checkout page.\n\n\n\nHere\'s how:\n\n\n\n1: Go to CartFlows > Funnels. If you\'re using the Store Checkout, open the Store Checkout tab instead.\n\n\n\n\n\n\n\n2: Click on the Settings (cog icon) for the Checkout step.\n\n\n\n\n\n\n\n3: Navigate to the Checkout Form tab. Toggle the Enable Coupon Field option as needed.\n\n\n\n\n\n\n\nStep 3: Customize Coupon Field and Button Text (Optional)\n\n\n\nNeed to change the default placeholder or button label? CartFlows provides a developer-friendly filter to help you personalize the coupon field text.\n\n\n\nAdd the following code to your child theme’s functions.php file:\n\n\n\n/** * Change the CartFlows Coupon Field text and Button text. * * @param array $coupon_field array of field strings/texts. * @return array */add_filter( \'cartflows_coupon_field_options\', \'change_cartFlows_coupon_field_strings\', 10, 1 );function change_cartFlows_coupon_field_strings( $coupon_field ){	$coupon_field = array(		\'field_text\'  =&gt; __( \'Coupon Code\', \'cartflows\' ), // Coupon input field text/placeholder.		\'button_text\' =&gt; __( \'Apply\', \'cartflows\' ), // Apply coupon button text.		\'class\'       =&gt; \'\', // Coupon input field class.	);	return $coupon_field; // Returning the modified data with new strings.}\n\n\n\n\n&#x1f4a1; Need help adding custom code to your site? Here’s a guide to walk you through the process safely.\n\n\n\n\nWith these settings in place, you’ll have full control over how coupons appear and function on your CartFlows checkout pages, improving the customer experience and supporting your promotional campaigns.\";s:3:\"url\";s:60:\"https://cartflows.com/docs/enable-coupons-on-cartflows-page/\";s:4:\"slug\";s:32:\"enable-coupons-on-cartflows-page\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-05T19:10:05+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:172;O:8:\"stdClass\":8:{s:2:\"id\";i:32945;s:5:\"title\";s:64:\"Why is the Upsell/Downsell not Working or it is Getting Skipped?\";s:7:\"content\";s:2356:\"Sometimes, you may notice that even after configuring your Upsell / Downsell offers correctly, customers are redirected straight to the Thank You page without seeing those offers. Let’s look into the common reasons for this and how you can resolve them.\n\n\n\nCases Where Upsell / Downsell Pages Get Skipped\n\n\n\nCase 1: Cart Total is Zero\n\n\n\nIf you’re selling a free product (cart total is zero), WooCommerce will not display payment gateway options at Checkout. Since there’s no gateway selected, the Upsell / Downsell page cannot process an additional charge, and the customer will be redirected directly to the Thank You page.\n\n\n\nCase 2: Unsupported Payment Gateway\n\n\n\nCartFlows currently supports specific payment gateways with Upsell/Downsell. If you use a payment gateway that is not supported, the Upsell / Downsell page will be skipped. You can review the list of supported gateways in our documentation.\n\n\n\nCase 3: Upsell / Downsell Placed Before Checkout\n\n\n\nIf you add Upsell / Downsell pages directly after an Optin step (before the Checkout), they will be skipped. This is because the Optin step only handles free products, and no payment gateway is available at that stage.\n\n\n\nCase 4: Checkout Modified by Other Plugins\n\n\n\nSome third-party plugins may alter the Checkout or thank you process. If such a plugin interferes, the Upsell / Downsell steps may be bypassed. Disabling conflicting plugins and testing your flow can help identify the cause.\n\n\n\nCase 5: Misconfigured Dynamic Offers on Checkout Step\n\n\n\nIf you’ve set up dynamic offers directly on the Checkout step, but the configuration is incorrect, it may cause the Upsell / Downsell sequence to be skipped. Double-check your dynamic offer rules and ensure they are set up properly to trigger Upsell after the main Checkout purchase.\n\n\n\nSolution\n\n\n\nTo ensure Upsell / Downsell offers are displayed:\n\n\n\n\nPlace Upsell / Downsell steps after the Checkout page in your funnel.\n\n\n\nMake sure the cart value is at least $1 so that payment gateway options appear at Checkout.\n\n\n\nUse one of the supported payment gateways for processing Upsell/Downsell.\n\n\n\nVerify that any dynamic offers are configured correctly to trigger after Checkout.\n\n\n\n\nWith this setup, your customers will complete checkout using a supported gateway, and then they’ll see the Upsell / Downsell offers as intended.\";s:3:\"url\";s:65:\"https://cartflows.com/docs/resolve-upsell-downsell-skipped-issue/\";s:4:\"slug\";s:37:\"resolve-upsell-downsell-skipped-issue\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-09-25T22:28:24+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:173;O:8:\"stdClass\":8:{s:2:\"id\";i:32911;s:5:\"title\";s:107:\"How to Show or Hide Shipping Fields and the Ship to Different Address Option on the CartFlows Checkout Page\";s:7:\"content\";s:1349:\"When selling physical products, you’ll often need to collect the customer’s shipping details and sometimes apply shipping charges based on location. CartFlows allows you to manage when the shipping fields and the Ship to a Different Address option appear on your Checkout pages.\n\n\n\nStep 1: Set Up Shipping in WooCommerce\n\n\n\nShipping fields are controlled by WooCommerce. To display them on the Checkout page, you’ll first need to set up shipping zones and rates:\n\n\n\n\nGo to WooCommerce &gt; Settings &gt; Shipping.\n\n\n\nCreate Shipping Zones based on the regions where you ship.\n\n\n\nAdd the appropriate Shipping Methods and rates.\n\n\n\n\nIf shipping zones and methods are not set up, the shipping fields will not appear on your Checkout page.\n\n\n\nFor a detailed guide, refer to WooCommerce’s Shipping Documentation.\n\n\n\nStep 2: Enable or Disable Shipping Fields in CartFlows\n\n\n\nOnce your shipping setup is ready, you may want to enable or hide the shipping fields on specific CartFlows Checkout pages. Here’s how:\n\n\n\n1: Go to CartFlows &gt; Funnels &gt; Your Funnel.\n\n\n\n\n\n\n\n2: Open the Checkout step and click Settings.\n\n\n\n\n\n\n\n3: Navigate to the Checkout Form > Form Settings tab.\n\n\n\n4: Toggle Enable Ship to Different Address on or off, depending on your preference.\n\n\n\n\n\n\n\n5: Click Save Settings to update your page.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:63:\"https://cartflows.com/docs/ship-to-different-address-cartflows/\";s:4:\"slug\";s:35:\"ship-to-different-address-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-05T20:33:50+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:174;O:8:\"stdClass\":8:{s:2:\"id\";i:32885;s:5:\"title\";s:66:\"How to Fix &#8220;Page Not Found&#8221; on Checkout During Payment\";s:7:\"content\";s:1063:\"If you see a “Page Not Found” message when a customer is redirected to the payment gateway from the CartFlows Checkout page, it’s likely caused by a missing default WooCommerce page setting.\n\n\n\nThis documentation explains the cause and how to resolve it.\n\n\n\nWhy This Happens\n\n\n\nSome payment gateways use the default WooCommerce Checkout page to process payments. During checkout, when the customer is redirected to the payment gateway’s form, WooCommerce uses the order-pay endpoint on its default checkout page.\n\n\n\nIf the WooCommerce Checkout page is not created or not assigned correctly under WooCommerce settings, this will result in a “Page Not Found” error.\n\n\n\nHow to Fix the Error\n\n\n\nTo resolve the issue:\n\n\n\n\nGo to WooCommerce &gt; Settings &gt; Advanced.\n\n\n\nUnder the Page setup section, find the Checkout page dropdown.\n\n\n\nSelect a valid page from the dropdown. This should be a standard page created by WooCommerce.\n\n\n\n\nClick Save changes.\n\n\n\n\n\n\n\nIf the Checkout page is missing, follow this WooCommerce guide to recreate the default pages.\";s:3:\"url\";s:68:\"https://cartflows.com/docs/resolve-page-not-found-message-cartflows/\";s:4:\"slug\";s:40:\"resolve-page-not-found-message-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-14T22:56:29+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:175;O:8:\"stdClass\":8:{s:2:\"id\";i:32887;s:5:\"title\";s:49:\"How to Turn Off the Auto-fill of Checkout Fields?\";s:7:\"content\";s:1322:\"By default, CartFlows helps improve the checkout experience by automatically filling in previously entered billing or shipping information. This feature is designed to make it faster and easier for returning users to complete their purchase.\n\n\n\nCartFlows stores this data locally in the user’s browser—nothing is saved on the server or shared with others. This means the information will only auto-fill for the same user using the same browser and device.\n\n\n\nWhile this improves convenience, there may be scenarios where you prefer to disable this auto-fill behavior—especially on shared devices or for privacy-focused setups.\n\n\n\nHow to Disable Auto-Fill Using a Filter\n\n\n\nTo turn off the auto-fill feature, you can use the following filter in your child theme’s functions.php file:\n\n\n\n/** * Filter to enable/disable the auto-fill of checkout fields  * * @param  string $allow having yes/no * @return string $allow yes or no */add_filter( \'cartflows_allow_persistence\', \'do_not_store_persistance_data\', 10, 1 );function do_not_store_persistance_data( $allow ){	$allow = \'no\';	return $allow;}\n\n\n\n\n&#x1f4a1; Need help adding custom code? Here’s how to safely add code snippets to your site.\n\n\n\n\nOnce this filter is in place, CartFlows will no longer pre-fill any checkout field data from a user\'s previous session.\";s:3:\"url\";s:62:\"https://cartflows.com/docs/turn-off-auto-fill-checkout-fields/\";s:4:\"slug\";s:34:\"turn-off-auto-fill-checkout-fields\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-07-07T17:45:56+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"code-snippets\";}}i:176;O:8:\"stdClass\":8:{s:2:\"id\";i:32873;s:5:\"title\";s:89:\"How to Enable the Theme&#8217;s Scripts &#038; Styles without Changing the Page Template?\";s:7:\"content\";s:1619:\"By default, CartFlows intentionally does not load your theme’s header, footer, or styling on funnel pages. This ensures maximum flexibility and avoids design conflicts—especially helpful when creating focused, distraction-free checkout experiences.\n\n\n\nWhy the Header &amp; Footer Are Hidden\n\n\n\nTo maintain full design control and prevent potential layout issues, CartFlows uses its own template for funnel pages. If you\'d prefer to show your theme’s header and footer, the recommended approach is to set the page template to Default in the page editor. Here’s how to do that.\n\n\n\nHowever, in some cases, you may notice that the header and footer appear without styling—especially when not using a Default template. If you’d like to load your theme’s CSS and JavaScript files without changing the page template, you can use the following filters.\n\n\n\nHow to Load Theme Scripts &amp; Styles with a Filter\n\n\n\nAdd the following code snippet to your child theme’s functions.php file:\n\n\n\n/** * Filter to load theme\'s styles &amp; scripts.  * * @param  bool $remove_styles true/false * @return bool $remove_styles true/false */add_filter( \'cartflows_remove_theme_styles\', \'wcf_load_theme_files\', 10, 1 );add_filter( \'cartflows_remove_theme_scripts\', \'wcf_load_theme_files\', 10, 1 );function wcf_load_theme_files( $remove_styles ){		$remove_styles = false;	return $remove_styles;}\n\n\n\n\n&#x1f4a1; Need help adding custom code? Follow this guide to safely insert custom code into WordPress.\n\n\n\n\nOnce added, your theme’s styles and scripts will load on CartFlows pages—even if you\'re not using a Default template.\";s:3:\"url\";s:67:\"https://cartflows.com/docs/enable-themes-style-for-existing-layout/\";s:4:\"slug\";s:39:\"enable-themes-style-for-existing-layout\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-04T17:49:22+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"code-snippets\";}}i:177;O:8:\"stdClass\":8:{s:2:\"id\";i:32870;s:5:\"title\";s:69:\"How to Turn Off the Auto-fill of Address Fields on Entering Zip-Code?\";s:7:\"content\";s:1372:\"CartFlows includes a convenient feature that automatically fills in the Country, State, and City fields on your checkout page based on the zip code entered by the customer. This functionality is powered by the Zippopotam API, which looks up location details for recognized zip codes and auto-fills the corresponding fields to streamline the checkout process.\n\n\n\nHowever, in some scenarios, you may want to disable this behavior, for example, when using custom fields or serving regions where this data is unreliable.\n\n\n\nDisable Auto-Fill Using a Filter\n\n\n\nTo turn off this auto-fill functionality, you can use the following WordPress filter:\n\n\n\n/** * Filter to enable/disable the address auto-fill using the zip code.  * * @param  string $allow having yes/no * @return string $allow yes or no */add_filter( \'cartflows_autocomplete_zip_data\', \'wa_disable_autocomplete_zipcode\', 10, 1 );function wa_disable_autocomplete_zipcode( $allow ) {    $allow = \'no\';    return $allow;}\n\n\n\nHow to Add This Code\n\n\n\nTo apply this filter, add the snippet to your child theme’s functions.php file or use Code Snippets plugin. If you\'re unsure how to safely add custom code to your site, we recommend reviewing this guide on adding custom code.\n\n\n\nOnce added, CartFlows will no longer auto-fill the address fields when a zip code is entered, allowing full manual input from the customer.\";s:3:\"url\";s:61:\"https://cartflows.com/docs/turn-off-auto-fill-address-fields/\";s:4:\"slug\";s:33:\"turn-off-auto-fill-address-fields\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-12T22:24:27+05:30\";s:8:\"category\";a:1:{i:0;s:13:\"code-snippets\";}}i:178;O:8:\"stdClass\":8:{s:2:\"id\";i:32891;s:5:\"title\";s:51:\"How to Fix Recovery Emails Going to the Spam Folder\";s:7:\"content\";s:2441:\"If your recovery emails from the Cart Abandonment Recovery for WooCommerce plugin are landing in the Spam folder, it\'s important to understand that the plugin does not send emails directly.\n\n\n\nThe emails are delivered through your website host or an SMTP plugin if one is set up. That means the issue is related to how emails are sent from your site, not how Cart Abandonment is configured.\n\n\n\nWhy Recovery Emails Go to Spam\n\n\n\nEmail providers automatically filter emails that look suspicious, poorly configured, or lack important authentication. Here are common reasons why recovery emails may be flagged as spam:\n\n\n\n1. Missing SPF, DKIM, or DMARC Records\n\n\n\nThese DNS records help verify that your site is authorized to send email from your domain. Without them, email services may not trust the message and send it to spam.\n\n\n\n2. Using a Free Email Address\n\n\n\nSending emails from an address like yourstore@gmail.com or yourname@yahoo.com lowers deliverability. Always use an email based on your own domain (e.g., support@yourdomain.com).\n\n\n\n3. Spam-Triggering Words in Subject or Content\n\n\n\nWords like “Buy now,” “Click here,” or “Limited offer” - especially in all caps - can increase the chances of emails being flagged. Keep your messaging clean, helpful, and aligned with your brand voice.\n\n\n\n4. Poor Sender Reputation\n\n\n\nIf your domain has a history of bounced or reported emails, email services may treat all future messages from it as suspicious. This includes sending emails too frequently or to invalid addresses.\n\n\n\n5. Lack of User Consent\n\n\n\nSending emails to users who didn’t explicitly opt-in can lead to spam complaints, which damages your sender reputation. Always get clear consent and provide a way to unsubscribe.\n\n\n\n6. Low-Quality Content or Layout\n\n\n\nEmails that are just one big image, have broken links, or include poor formatting can be flagged by spam filters. Use a mix of clean text and minimal design.\n\n\n\nWhat You Can Do to Fix It\n\n\n\n\nUse an SMTP plugin like SureMail to improve email delivery.\n\n\n\nSet up and verify your domain’s SPF, DKIM, and DMARC records. Your hosting provider can help with this.\n\n\n\nAlways use a domain-based sender email address.\n\n\n\nAvoid using aggressive marketing language in subject lines and content.\n\n\n\nTest your emails using a service like mail-tester.com to identify problems.\n\n\n\nContact your hosting provider for help reviewing your server’s email configuration.\";s:3:\"url\";s:61:\"https://cartflows.com/docs/resolve-recovery-email-spam-issue/\";s:4:\"slug\";s:33:\"resolve-recovery-email-spam-issue\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-08-21T21:52:44+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:179;O:8:\"stdClass\":8:{s:2:\"id\";i:32811;s:5:\"title\";s:59:\"How to Use WooCommerce Subscription Products with CartFlows\";s:7:\"content\";s:2099:\"Subscription products allow you to sell access to a product or service on a recurring basis whether daily, monthly, or yearly. With CartFlows, you can easily include subscription products in your funnels, but the first step is to create them using WooCommerce.\n\n\n\nWhat Are Subscription Products?\n\n\n\nSubscription products are items that customers purchase with a recurring payment schedule. Instead of a one-time payment, they are billed automatically at the chosen interval (for example, every month or year) to continue receiving the product or service.\n\n\n\nStep 1: Install WooCommerce Subscriptions\n\n\n\nTo create subscription products, you’ll need the official WooCommerce Subscriptions plugin. You can download it directly from WooCommerce and follow their step-by-step guide here: WooCommerce Subscriptions Documentation.\n\n\n\nStep 2: Create a Subscription Product\n\n\n\nOnce the plugin is installed, you can create a new subscription product in WooCommerce. During setup, define the product name, pricing, billing interval (daily, monthly, yearly, etc.), and other relevant options.\n\n\n\nStep 3: Assign Subscription Products in CartFlows\n\n\n\nAfter creating your subscription product, you can assign it to CartFlows checkout or offer pages.\n\n\n\n1: Navigate to CartFlows &gt; Funnels &gt; Your Funnel.\n\n\n\n\n\n\n\n2: Open the Checkout, Upsell, or Downsell step where you want to assign the subscription product.\n\n\n\n\n\n\n\n3: Go to the Product tab and search for your subscription product and Add it\n\n\n\n\n\n\n\n4: If you’re using multiple simple or variable subscription products, enable Product Options.\n\n\n\n5: For variable subscription products, enable the Variation Option to display choices on the checkout page.\n\n\n\n\n\n\n\nNote: On Upsell and Downsell pages, use shortcodes to display product variations. Refer to the dedicated shortcodes documentation for details.\n\n\n\n6: Click Save Settings to apply changes.\n\n\n\nYou’ve successfully created and assigned subscription products in CartFlows. Now you can sell subscriptions directly through your funnels, giving your customers a seamless recurring payment experience.\";s:3:\"url\";s:68:\"https://cartflows.com/docs/use-subscription-product-cartflows-pages/\";s:4:\"slug\";s:40:\"use-subscription-product-cartflows-pages\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-06T11:39:21+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:180;O:8:\"stdClass\":8:{s:2:\"id\";i:32836;s:5:\"title\";s:65:\"How to Resolve the “CartFlows Pro: Download not found.” Error\";s:7:\"content\";s:1746:\"If you see the error message “CartFlows Pro: Download not found.” while updating the plugin, follow the steps below to resolve the issue.\n\n\n\nWhy Does This Error Occur?\n\n\n\nThis error happens because of cache-related issues. When updating the CartFlows Pro plugin, your website may still be using an outdated instance ID stored in the cache instead of the latest one. As a result, WordPress cannot retrieve the correct update package, leading to the Download not found error.\n\n\n\nFixing the Error\n\n\n\nTo update CartFlows Pro successfully, follow these steps:\n\n\n\nStep 1: Clear all cache\n\n\n\n\nClear your browser cache.\n\n\n\nClear your website’s cache and server-side cache.\n\n\n\n\nStep 2: Deactivate caching plugins\n\n\n\nTemporarily disable caching plugins (e.g., WP Rocket, SG Optimizer).\n\n\n\nStep 3: Deactivate the CartFlows Pro license\n\n\n\nGo to CartFlows settings and deactivate your license.\n\n\n\n\n\n\n\nStep 4: Deactivate the CartFlows Pro plugin\n\n\n\nNavigate to Plugins and deactivate CartFlows Pro.\n\n\n\n\n\n\n\nStep 5: Reactivate the CartFlows Pro plugin\n\n\n\nActivate the plugin again from the Plugins page.\n\n\n\n\n\n\n\nStep 6: Re-activate your license\n\n\n\nClick on the Activate License button to reactivate your license.\n\n\n\n\n\n\n\nStep 7: Check for updates manually\n\n\n\nGo to Dashboard &gt; Updates to check available update manually.\n\n\n\n\n\n\n\nStep 8: Update the CartFlows Pro plugin\n\n\n\nTry updating the plugin again and it should now work without errors.\n\n\n\nStep 9: Re-enable caching plugins\n\n\n\nReactivate any caching plugins you previously disabled.\n\n\n\nNote\nSome caching plugins (such as WP Rocket or SG Optimizer) cache your database, which can interfere with plugin updates.Always clear cache and disable caching plugins before updating CartFlows Pro to avoid issues.\";s:3:\"url\";s:68:\"https://cartflows.com/docs/resolve-download-not-found-error-message/\";s:4:\"slug\";s:40:\"resolve-download-not-found-error-message\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-06T12:52:36+05:30\";s:8:\"category\";a:1:{i:0;s:20:\"installation-updates\";}}i:181;O:8:\"stdClass\":8:{s:2:\"id\";i:32820;s:5:\"title\";s:56:\"How to Import Ready-Made Templates for Funnels and Steps\";s:7:\"content\";s:2174:\"CartFlows provides a library of professionally designed templates for full funnels and individual steps. You can use these templates to quickly set up your funnels using the page builder of your choice.\n\n\n\nCurrently, CartFlows offers ready-made templates for the following page builders:\n\n\n\n\nElementor\n\n\n\nDivi (requires manual import – see this doc)\n\n\n\nBeaver Builder\n\n\n\nBlock Editor (Gutenberg)\n\n\n\n\nBefore You Begin\n\n\n\nMake sure to select your preferred page builder in CartFlows &gt; Settings, under the Page Builder option. This ensures that only compatible templates will appear when importing.\n\n\n\nHow to Import a Ready-Made Funnel Template\n\n\n\n\nGo to CartFlows &gt; Funnels.\n\n\n\nClick the Create New Funnel button.\n\n\n\nA template library will open. Browse through the available templates based on your selected page builder.\n\n\n\nClick the View All Steps button on the template you want to use.\n\n\n\nClick the Import Funnel button to begin importing the funnel.\n\n\n\n\n\n\n\n\nThe full funnel will be imported, including steps like Landing, Checkout, Thank You, and more all pre-designed and ready for customization.\n\n\n\nHow to Import a Ready-Made Step Template\n\n\n\n\nOpen the funnel where you want to add a new step.\n\n\n\nClick Add New Step.\n\n\n\nThe step template library will open, showing designs for different step types: Landing, Checkout, Upsell, Downsell, Thank You, and Opt-in.\n\n\n\nUse the filter to select the type of step you want to import.\n\n\n\nHover over the template you want and click Import.\n\n\n\n\n\n\n\n\nThis action will add the selected step design directly into your funnel.\n\n\n\nTroubleshooting Template Import Errors\n\n\n\nIf you encounter an error while importing, here are the most common causes:\n\n\n\n\nFailed to import the templateReload the page and try again. This often resolves temporary connectivity or cache-related issues.\n\n\n\nInternal Server Error (500) Check the debug.log file in your /wp-content/ directory for details.\n\n\n\nUnder maintenanceThis may happen if the CartFlows template server is under maintenance or if an API call was blocked. Check your browser’s console for more information.\n\n\n\n\nIf the issue continues, try reloading the page or contact our support.\";s:3:\"url\";s:70:\"https://cartflows.com/docs/import-cartflows-templates-for-flows-steps/\";s:4:\"slug\";s:42:\"import-cartflows-templates-for-flows-steps\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-04T18:58:36+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:182;O:8:\"stdClass\":8:{s:2:\"id\";i:32841;s:5:\"title\";s:45:\"Supported Multi-Currency Plugin for CartFlows\";s:7:\"content\";s:1364:\"CartFlows supports the official WooCommerce Multi-Currency plugin. This documentation explains how to use it with CartFlows and what to expect when placing the currency switcher on CartFlows pages.\n\n\n\nDownload and Set Up the Plugin\n\n\n\nYou can download the WooCommerce Multi-Currency plugin from its page on the official WooCommerce marketplace: https://woocommerce.com/products/multi-currency/\n\n\n\nTo configure the plugin, follow the setup guide provided by its developer: WooCommerce Multi-Currency Setup Guide\n\n\n\nDisplay the Currency Switcher on CartFlows Pages\n\n\n\nThe plugin includes shortcodes that allow you to display a currency switcher anywhere on your site. You can place this shortcode on the Landing or Checkout page used in your CartFlows Funnel.\n\n\n\nNote: The multi-currency shortcode cannot be embedded inside the CartFlows shortcode. Both are separate and need to be placed independently.\n\n\n\nUsing the Switcher in the Header, Footer, or Widgets\n\n\n\nCartFlows does not load your theme’s header, footer, or widget areas by default. So if you add the currency switcher in those locations, it may not appear on CartFlows pages.\n\n\n\nTo display the switcher in these areas:\n\n\n\n\nEdit the page used in your CartFlows step.\n\n\n\nChange the page template to Default.\n\n\n\n\nFor more details, refer to this doc: How to Use Your Theme’s Header &amp; Footer in a Step\";s:3:\"url\";s:68:\"https://cartflows.com/docs/use-multi-currency-plugin-with-cartflows/\";s:4:\"slug\";s:40:\"use-multi-currency-plugin-with-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-20T18:30:34+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:183;O:8:\"stdClass\":8:{s:2:\"id\";i:32847;s:5:\"title\";s:92:\"How to Fix &#8220;The Following Required Query String Data is Missing: Instance&#8221; Error\";s:7:\"content\";s:1626:\"If you see the error message “The Following Required Query String Data is Missing: Instance” while activating your CartFlows Pro license, it usually means the plugin is unable to generate or retrieve a required instance ID.\n\n\n\nThis documentation explains what causes this error and how to resolve it.\n\n\n\nWhen This Error Occurs\n\n\n\nThis message typically appears in the license activation popup on the Plugins page when one of the following conditions exists:\n\n\n\n1. The Site Was Cloned or Migrated\n\n\n\nIf your website was cloned or migrated to another domain or host, the instance ID tied to your original site may no longer be valid. The plugin may not be able to generate a new instance correctly during license activation.\n\n\n\n2. Caching Is Preventing the Instance from Being Stored\n\n\n\nSometimes caching (local, plugin-based, or server-level) prevents the instance ID from being stored in the database. When the API call is made to validate the license, it fails because the required instance value is missing.\n\n\n\nHow to Fix the Issue\n\n\n\nFollow these steps to resolve the error and activate your CartFlows Pro license:\n\n\n\n\nClear all cache on your site - including your browser, local, and server-side cache.\n\n\n\nTemporarily deactivate any cache plugin you have installed.\n\n\n\nDeactivate the CartFlows Pro plugin.\n\n\n\nReactivate the CartFlows Pro plugin.\n\n\n\nClick the Activate License button.\n\n\n\nEnter your license key or API key.\n\n\n\nClick Activate.\n\n\n\n\nNote: Always make sure to clear all cache and disable any cache plugins before activating your CartFlows Pro license to avoid conflicts with the license instance generation.\";s:3:\"url\";s:93:\"https://cartflows.com/docs/resolve-required-query-string-data-missing-instance-error-message/\";s:4:\"slug\";s:65:\"resolve-required-query-string-data-missing-instance-error-message\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-14T23:12:31+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:184;O:8:\"stdClass\":8:{s:2:\"id\";i:32791;s:5:\"title\";s:61:\"What to Do if the Order Status is Stuck at MainOrderAccepted?\";s:7:\"content\";s:2449:\"If some of your orders remain stuck at the \"MainOrderAccepted\" status, this documentation will help you understand why it happens and how to resolve it.\n\n\n\n\n\n\n\nWhy Orders Get the \"Main Order Accepted\" Status\n\n\n\nThis status occurs when the Order Settings in CartFlows are set to Add to main order. This option merges all accepted upsell/downsell offers into the main order. The MainOrderAccepted status is assigned by CartFlows after a purchase is made on the checkout page. This temporary status exists because CartFlows may display additional upsell or downsell offers after checkout.\n\n\n\n\nIf the customer completes the funnel (including upsells/downsells), the order will move forward normally.\n\n\n\nIf the customer abandons the process by closing the upsell/downsell page or browser window, the order may remain in MainOrderAccepted.\n\n\n\n\nTo handle this, CartFlows uses a scheduled task (WP-Cron) to automatically update the order status after 30 minutes.\n\n\n\nWhy the Status Might Be Stuck\n\n\n\nIf the WP-Cron job does not run as expected, orders may stay in the MainOrderAccepted status. This usually happens due to:\n\n\n\n\nPlugin Conflicts – Another plugin may be interfering with the WP-Cron execution.\n\n\n\nDisabled Cron Service – Some hosting providers disable the cron service by default.\n\n\n\n\nHow to Troubleshoot\n\n\n\nStep 1: Verify the WP-Cron\n\n\n\n\nInstall and activate the WP Crontrol plugin.\n\n\n\nSearch for the cron event named cartflows_schedule_normalize_order_status.\n\n\n\nCheck the Next Run Time to confirm whether it’s scheduled correctly.\n\n\n\n\nStep 2: Test for Plugin Conflicts\n\n\n\n\nTemporarily deactivate all plugins except WooCommerce, CartFlows, and your page builder.\n\n\n\nPlace a test order and close the browser as soon as the upsell/downsell page loads.\n\n\n\nRe-check the cron event in WP Crontrol and wait 30 minutes.\n\n\n\nIf the order status updates correctly, another plugin is conflicting. Reactivate plugins one by one to find the culprit.\n\n\n\n\nStep 3: Check Hosting Cron Settings\n\n\n\nIf the cron job is missing or not running:\n\n\n\n\nContact your hosting provider and ask them to enable the server cron service.\n\n\n\nOnce enabled, CartFlows’ scheduled tasks will run automatically and update order statuses.\n\n\n\n\nImportant Note\n\n\n\nIn many cases, hosting providers include cron services but keep them disabled by default. A quick request to enable it will resolve the issue and ensure orders move out of the MainOrderAccepted status as expected.\";s:3:\"url\";s:60:\"https://cartflows.com/docs/order-stuck-at-mainorderaccepted/\";s:4:\"slug\";s:32:\"order-stuck-at-mainorderaccepted\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-09-18T16:50:14+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:185;O:8:\"stdClass\":8:{s:2:\"id\";i:32739;s:5:\"title\";s:50:\"How and Where to Add Custom JS, CSS, and PHP Codes\";s:7:\"content\";s:1408:\"You may sometimes need to add custom JavaScript, CSS, or PHP code to your site for custom functionality or styling. Below are the methods to safely do this.\n\n\n\nUse a Plugin (Recommended for Most Users)\n\n\n\nFor simplicity and safety, you can use a plugin that allows adding custom code without touching theme files. This works for JavaScript, CSS, and PHP.\n\n\n\nWe recommend:\n\n\n\n\nCode Snippets&nbsp;\n\n\n\nWPCode\n\n\n\nWoody code snippets\n\n\n\n\nThese plugins let you manage your code snippets in a user-friendly way, and they remain active even after theme updates.\n\n\n\nAdd Custom JavaScript\n\n\n\nCartFlows Funnels Only\n\n\n\nGo to Funnel Setting > General section. The script will only apply to the specific funnel.\n\n\n\n\n\n\n\nAdd Custom CSS\n\n\n\nCustom CSS can be added to two places, either add it to a specific funnel or to the Customizer.\n\n\n\nAdding custom CSS to a specific funnel can be done similar like adding JavaScript to a funnel. Go to Funnel Settings > General section. The CSS will be applied only to the specific funnel.\n\n\n\n\n\n\n\nAdding custom CSS to the Customizer can be done by going to to Appearance > Customize > Additional CSS.\n\n\n\n\n\n\n\nAdd Custom PHP\n\n\n\nUsing a Child Theme\n\n\n\nAdd your PHP code inside the functions.php file of your child theme.\n\n\n\n\n\n\n\nUsing a child theme ensures your custom code won’t be lost when updating the theme. If you’re not familiar with what a child theme is, refer to this article.\";s:3:\"url\";s:44:\"https://cartflows.com/docs/add-custom-codes/\";s:4:\"slug\";s:16:\"add-custom-codes\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-05T13:30:39+05:30\";s:8:\"category\";a:1:{i:0;s:14:\"developer-docs\";}}i:186;O:8:\"stdClass\":8:{s:2:\"id\";i:32710;s:5:\"title\";s:58:\"Introducing the “Separate Orders” Feature in CartFlows\";s:7:\"content\";s:2230:\"CartFlows has a powerful new option called Separate Orders, available in CartFlows Pro. This feature gives you the ability to create individual orders for Upsell and Downsell purchases instead of combining them into a single WooCommerce order.\n\n\n\nThis can help streamline order management, improve refund handling, and ensure proper email notifications are sent for each order stage.\n\n\n\nOrder Setting\n\n\n\nThe Create a new child order option allows separate orders to be generated for each accepted offer.\n\n\n\nYou’ll find this setting under CartFlows &gt; Settings &gt; Order\n\n\n\nHere, you\'ll see two available options:\n\n\n\n\nCreate a new child orderThis creates individual orders for each Upsell or Downsell product. The original checkout order becomes the parent order, and each subsequent accepted offer is logged as a separate WooCommerce order.\n\n\n\nAdd to the main orderThis is the default behavior, where all accepted Upsell and Downsell products are merged into the original checkout order.\n\n\n\n\n\n\n\n\nWhere the Orders Appear\n\n\n\nEach new child order will be visible in WooCommerce &gt; Orders, making it easy to track, manage, and take action on each order individually.\n\n\n\n\n\n\n\nCartFlows Parent Order\n\n\n\n\n\n\n\nCartFlows Upsell / Downsell Order\n\n\n\nWhy Use Separate Orders?\n\n\n\nEnabling this feature can help in several key areas:\n\n\n\n\nSimplified refundsProcess returns for Upsell or Downsell products without affecting the main order.\n\n\n\nEmail notificationsWooCommerce will automatically send order-related emails for each child order, ensuring timely communication with your customers.\n\n\n\nImproved access for digital productsIf you\'re selling courses or memberships as upsells, customers will gain access immediately upon purchase since each product has its own completed order.\n\n\n\nBetter status trackingSolves the issue where incomplete funnel exits (e.g., closing the browser during an Upsell) previously left the order in an intermediate MainOrderAccepted status.\n\n\n\n\nThis feature provides greater flexibility for store owners who want more granular control over how upsell and downsell purchases are handled in WooCommerce. You can now decide whether to keep everything in a single order or split them based on your business needs.\";s:3:\"url\";s:63:\"https://cartflows.com/docs/introducing-separate-orders-feature/\";s:4:\"slug\";s:35:\"introducing-separate-orders-feature\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-05T15:29:35+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:187;O:8:\"stdClass\":8:{s:2:\"id\";i:32737;s:5:\"title\";s:75:\"How to Resolve Large Stripe Payment Icons and Uneditable Credit Card Fields\";s:7:\"content\";s:3201:\"If you\'re seeing oversized Stripe payment icons or the credit card fields are unresponsive on the checkout page, this guide will walk you through resolving the issue.This behavior is usually related to caching problems, where Stripe\'s AJAX call fails to fetch required styling and form fields. Let’s break down the common causes and how to fix them.\n\n\n\nWhat Causes This Issue?\n\n\n\nStripe uses dynamic JavaScript to load its CSS and payment fields. If this AJAX call is cached or blocked, it can result in:\n\n\n\n\nCard icons appearing unusually large\n\n\n\nCard input fields not responding or editable\n\n\n\n\nIn most cases, the browser’s developer console will show a 403 error response from Stripe, which prevents the card fields and styles from loading correctly.\n\n\n\nHow to Identify the 403 Error\n\n\n\nFollow these steps to check for the error:\n\n\n\n\nOpen the affected checkout page.\n\n\n\nRight-click on the page and select Inspect.\n\n\n\nGo to the Console tab.\n\n\n\nLook for any error messages, especially ones related to Stripe or 403 errors.\n\n\n\n\nPossible Reasons and Solutions\n\n\n\n1. Page Caching (Local or Server-Side)\n\n\n\nDynamic requests like Stripe’s payment fields should not be cached. Make sure your CartFlows checkout page is excluded from:\n\n\n\n\nPage caching\n\n\n\nServer-level caching (e.g., Varnish, NGINX, or hosting-level rules)\n\n\n\nCDN-level caching (e.g., Cloudflare)\n\n\n\n\nTip: Most cache plugins allow you to exclude specific pages. Ensure both CartFlows’ Checkout and Thank You pages are excluded.\n\n\n\n2. Firewall or Security Plugins\n\n\n\nSecurity/firewall plugins (like Wordfence or Sucuri) may block Stripe’s requests if flagged as suspicious. Whitelist the checkout page and allowlist Stripe\'s script URLs if necessary.\n\n\n\n3. Hosting Restrictions\n\n\n\nSome hosting setups only allow payment requests on the default WooCommerce checkout page. Since CartFlows uses a custom page, your host may require manual exclusion rules for it. Contact your hosting provider to:\n\n\n\n\nExclude the CartFlows Checkout page from security rules\n\n\n\nAllow dynamic AJAX calls on custom URLs\n\n\n\n\n4. Plugin or Theme Conflicts\n\n\n\nIf the above steps don’t solve the issue, perform a conflict test:\n\n\n\n\nDisable all other plugins except WooCommerce, CartFlows, and Stripe\n\n\n\nSwitch to a default theme (like Storefront)\n\n\n\nRe-test the checkout page\n\n\n\nGradually re-enable plugins to identify the conflict\n\n\n\n\nTo find out the conflict you can also follow these troubleshooting steps.\n\n\n\nWhat Is a 403 Error?\n\n\n\nA 403 Forbidden error means the server understands your request but is refusing to authorize it. In the case of Stripe, this often means the server or a plugin is blocking access to essential resources due to caching or security rules.\n\n\n\nStill Seeing the Issue?\n\n\n\nIf the issue persists:\n\n\n\n\nOpen the checkout page in a new tab\n\n\n\nInspect the console again for updated error messages\n\n\n\nNote the filename or script generating the error\n\n\n\nReach out to the plugin author or submit a ticket through the CartFlows support portal\n\n\n\n\nNote\nPayment gateway scripts rely on real-time data and should never be cached. Ensuring dynamic checkout pages are excluded from all caching mechanisms is crucial for proper functionality.\";s:3:\"url\";s:74:\"https://cartflows.com/docs/resolve-stripe-icons-issue-fields-not-editable/\";s:4:\"slug\";s:46:\"resolve-stripe-icons-issue-fields-not-editable\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-15T13:14:01+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:188;O:8:\"stdClass\":8:{s:2:\"id\";i:32731;s:5:\"title\";s:65:\"How to Resolve “No product is selected&#8230;” error message?\";s:7:\"content\";s:697:\"In this article, you will get to know how to resolve the error message that you are currently facing on your checkout page -\n\n\n\nThe meaning of this error message is, there is no product selected in the backend settings of the CartFlows Checkout page and the same checkout page is opened directly via URL / Link / Permalink.\n\n\n\n\n\n\n\n\n\n\n\nNow, if you open the checkout page with this setting then you will see the “No product is selected. Please select products from the checkout meta settings to continue” error message on the checkout page.\n\n\n\n\n\n\n\nTo solve this error message you need to make sure the funnel is in the Test Mode or select the product in the backend setting of the Checkout Page.\";s:3:\"url\";s:69:\"https://cartflows.com/docs/resolve-no-product-selected-error-message/\";s:4:\"slug\";s:41:\"resolve-no-product-selected-error-message\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-20T19:14:32+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:189;O:8:\"stdClass\":8:{s:2:\"id\";i:32735;s:5:\"title\";s:88:\"How to Add Custom Payment Gateway Support for One-Click Upsell and Downsell in CartFlows\";s:7:\"content\";s:2265:\"You can integrate your own payment gateway with CartFlows to support one-click Upsell and Downsell functionality. This requires a few steps to register your gateway and handle the payment process through code.\n\n\n\nFollow the steps below to add custom support:\n\n\n\nStep 1: Register Your Payment Gateway\n\n\n\nYou’ll need to define a custom class and file name, then register them with CartFlows.\n\n\n\nTo do this, either:\n\n\n\nOption A: Manually add them inside the CartFlows Pro plugin\n\n\n\n\nGo to the cartflows-pro/classes/class-cartflows-pro-gateways.php file\n\n\n\nFind the get_supported_gateways function\n\n\n\nAdd your class and file to the returned array\n\n\n\n\nOption B: Use the available filter (recommended if adding support via a plugin or theme):\n\n\n\nadd_filter( \'cartflows_offer_supported_payment_gateways\', \'your_function_name\' );\n\n/**\n * Add new payment gateway in Supported Gateways.\n *\n * @param array $supported_gateways Supported Gateways by CartFlows.\n * @return array.\n */\nfunction your_function_name( $supported_gateways ){\n	\n	$supported_gateways&#91;\'payment_gateway_slug\'] = array(\n		\'file\'  =&gt; \'yourfilename.php\', // Your Custom code\'s file name\n		\'class\' =&gt; \'YourClassName\',   // Class name used in the Custom Code\'s file.\n                \'path\'  =&gt; \'FullDirectoryPathofTheFile\', // Full directory path of the custom code\'s file.\n	);\n\n	return $supported_gateways; // Adding the payment gateway name.\n}\n\n\n\n\nNote: Use the path only if your file is located outside the CartFlows Pro plugin directory.\n\n\n\nStep 2: Write the Payment Processing Function\n\n\n\nInside your custom file, create a function named process_offer_payment. CartFlows will call this automatically when processing the Upsell or Downsell.\n\n\n\nThis is where your payment logic goes. It should handle charging the customer after the main checkout is completed and the offer is accepted.\n\n\n\nStep 3: Place the Custom File in the Correct Directory\n\n\n\nIf you’re not using a custom path, place your file in:\n\n\n\ncartflows-pro/modules/gateways/\n\n\n\nYou can refer to existing gateway files in that directory to understand how to structure your implementation.\n\n\n\nNote: We also offer a sample plugin you can use as a reference when building your own custom gateway integration. Download Sample Plugin\";s:3:\"url\";s:69:\"https://cartflows.com/docs/add-custom-support-of-any-payment-gateway/\";s:4:\"slug\";s:41:\"add-custom-support-of-any-payment-gateway\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-07-08T16:53:15+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:190;O:8:\"stdClass\":8:{s:2:\"id\";i:32700;s:5:\"title\";s:87:\"How to Resolve &#8220;Order Does not Exist Error&#8221; on Upsell &#038; Downsell Page?\";s:7:\"content\";s:1490:\"If you see the error message “Order does not exist” on your upsell or downsell pages, this documentation will help you understand why it occurs and how to fix it.\n\n\n\n\n\n\n\nWhy This Error Appears\n\n\n\nThis message is specific to upsell and downsell pages in CartFlows. It usually means the checkout process was not completed before trying to access the upsell or downsell page. In other words, the system could not find a valid order to attach the upsell/downsell offer to.\n\n\n\nCommon Scenarios That Trigger the Error\n\n\n\nCase 1: Accessing Upsell/Downsell Pages Directly\n\n\n\nIf you open the upsell or downsell page directly by its URL (without first completing the checkout) and then click Accept Offer, the error will be displayed.\n\n\n\n\nNote: This happens only when you are logged in.\n\n\n\n\nCase 2: Placing Upsell/Downsell Before Checkout\n\n\n\nIf an upsell or downsell step is placed before the checkout page in the funnel, the system has no main order to connect the offer with. As a result, attempting to accept the offer will show the error message.\n\n\n\n\nTip: Upsell and downsell pages should always be placed after the checkout step.\n\n\n\n\nHow to Fix\n\n\n\n\nEnsure upsell and downsell steps are positioned after the checkout page in your CartFlows funnel.\n\n\n\nDo not test upsell/downsell steps by directly opening their URL; instead, go through the full checkout process first.\n\n\n\n\nBy following these practices, the error will no longer appear, and your upsell/downsell offers will function correctly.\";s:3:\"url\";s:62:\"https://cartflows.com/docs/resolve-order-does-not-exist-error/\";s:4:\"slug\";s:34:\"resolve-order-does-not-exist-error\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-09-18T17:39:10+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:191;O:8:\"stdClass\":8:{s:2:\"id\";i:32688;s:5:\"title\";s:30:\"Abandoned Orders Not Capturing\";s:7:\"content\";s:1746:\"If your Cart Abandonment Recovery for WooCommerce plugin is not capturing abandoned orders, this documentation will guide you through the possible causes and solutions.\n\n\n\nWhy Abandoned Orders Might Not Be Captured\n\n\n\nThe most common reason for abandoned orders not being recorded is a disabled WP-Cron on your WordPress site.\n\n\n\nWhat Is WP-Cron?\n\n\n\nWP-Cron is WordPress’s built-in system for scheduling time-based tasks, such as publishing scheduled posts or running automated plugin functions. It acts as a task scheduler that allows WordPress to perform actions at specific intervals.\n\n\n\nFor more information, refer to this detailed article on WP-Cron.\n\n\n\nWhy WP-Cron Is Important for the Plugin\n\n\n\nThe Cart Abandonment Recovery for WooCommerce plugin relies on WP-Cron to detect and mark abandoned carts.\n\n\n\nIt uses a scheduled cron job named cartflows_ca_update_order_status_action that runs every 15 minutes to check for incomplete orders and mark them as abandoned when appropriate.\n\n\n\nIf WP-Cron is disabled, this job will not run, and abandoned orders will not be captured.\n\n\n\nHow to Enable WP-Cron\n\n\n\nTo re-enable WP-Cron, locate the wp-config.php file in your website’s root directory and add the following line right after the define(\'DB_COLLATE\', \'\'); line:\n\n\n\ndefine(\'DISABLE_WP_CRON\', false);\n\n\n\nThis ensures that WP-Cron is active and can execute the necessary tasks for Cart Abandonment Recovery.\n\n\n\nAdding an External Cron Job Using cPanel\n\n\n\nIf you prefer to use an external cron job instead of WordPress’s built-in scheduler, you can set it up through cPanel. Below are a few helpful resources that explain how to do this:\n\n\n\n\nSet Up Cron Jobs in cPanel (GreenGeeks)\n\n\n\nVideo: How to Set Up Cron Jobs in cPanel (YouTube)\";s:3:\"url\";s:58:\"https://cartflows.com/docs/abandoned-orders-not-capturing/\";s:4:\"slug\";s:30:\"abandoned-orders-not-capturing\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-03-25T22:06:46+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:192;O:8:\"stdClass\":8:{s:2:\"id\";i:32683;s:5:\"title\";s:32:\"Cart Recovery Emails Not Sending\";s:7:\"content\";s:1945:\"If your Cart Abandonment Recovery for WooCommerce plugin is not sending recovery (follow-up) emails, this documentation will help you understand the possible causes and guide you through the recommended solutions.\n\n\n\nOverview\n\n\n\nRecovery emails are automated messages sent to customers who abandon their carts before completing a purchase. These emails are triggered based on the schedule you set in the plugin’s settings and are key to recovering potential lost sales.\n\n\n\nIf recovery emails are not being sent, it’s usually related to how your website is configured to deliver outgoing emails.\n\n\n\nWhy SMTP Is Important for Recovery Emails\n\n\n\nBy default, WordPress uses your hosting server’s email function (PHP mail) to send emails. However, this method is often unreliable and can lead to messages being blocked, delayed, or marked as spam.\n\n\n\nTo ensure reliable email delivery, we recommend using an SMTP plugin such as SureMail. SMTP (Simple Mail Transfer Protocol) routes your website’s outgoing messages through a proper email server, improving deliverability and ensuring that recovery emails reach your customers’ inboxes.\n\n\n\nFor setup details, refer to the SureMail Knowledge Base.\n\n\n\nHow to Verify Recovery Email Delivery\n\n\n\nOnce you’ve installed and configured SureMail or another SMTP plugin, you can confirm that recovery emails are working properly by following these steps:\n\n\n\n1: Send a Test EmailGo to your recovery email template settings in the plugin and use the Send Test Email option to send a sample message to your inbox.\n\n\n\n\n\n\n\n2: Check Spam and Promotions FolderIf the test email does not appear in your inbox, check your spam or promotions folders. If it lands there or doesn’t arrive at all, follow the steps in Fix Recovery Emails Going to Spam for troubleshooting.\n\n\n\nIf the test email is delivered successfully, your SMTP setup is functioning correctly and recovery emails should now send as expected.\";s:3:\"url\";s:55:\"https://cartflows.com/docs/recovery-emails-not-sending/\";s:4:\"slug\";s:27:\"recovery-emails-not-sending\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-10-16T20:42:20+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:193;O:8:\"stdClass\":8:{s:2:\"id\";i:32662;s:5:\"title\";s:46:\"How to Use the Permalink Settings in CartFlows\";s:7:\"content\";s:1953:\"CartFlows includes its own permalink settings that let you change the slugs used in funnel and step URLs. This is different from the default WordPress permalink settings.\n\n\n\nThis documentation explains the difference between the two and how to change the CartFlows slug structure.\n\n\n\nWordPress vs CartFlows Permalink Settings\n\n\n\n\nThe WordPress Permalink Settings are located under Settings &gt; Permalinks. These apply to the entire website, including CartFlows pages.\n\n\n\nThe CartFlows Permalink Settings are located under CartFlows &gt; Settings &gt; Permalink &nbsp;and control only the slugs used for CartFlows funnel and step URLs.\n\n\n\n\nIf your WordPress permalink structure is set to anything other than Post name, you may see URLs like:\n\n\n\nyourdomain.com/cartflows_step/checkout-page/\n\n\n\nChange the Permalink Slugs for CartFlows\n\n\n\nTo change the default slugs used in funnel and step URLs:\n\n\n\n\nGo to CartFlows &gt; Settings in your WordPress dashboard.\n\n\n\nClick on the Permalink tab.\n\n\n\nChoose one of the available options:\n\nDefault Permalinks – Resets to cartflows_funnel and cartflows_step\n\n\n\nFunnel and Step Slug – Lets you rename both funnel and step slugs at once\n\n\n\nFunnel Slug – Lets you rename only the funnel slug\n\n\n\nStep Slug – Lets you rename only the step slug\n\n\n\n\n\nEnter your preferred slug values.\n\n\n\nClick Save Changes.\n\n\n\n\n\n\n\n\nThis will update the structure of your CartFlows URLs across the site.\n\n\n\nHow to Remove cartflows_step from the URL\n\n\n\nTo remove cartflows_step from the URL of your funnel steps:\n\n\n\n\nSet your WordPress permalink structure to Post name under Settings &gt; Permalinks.\n\n\n\nIn CartFlows &gt; Settings &gt; Permalink, choose the Default Permalinks option.\n\n\n\nUnder Post Type Permalink Base, set the step base to cartflows_step and the funnel base to cartflows_base.\n\n\n\nClick Save Changes.\n\n\n\n\n\n\n\n\nFor help configuring your WordPress permalink settings, refer to this doc: Recommended Permalink Settings\";s:3:\"url\";s:56:\"https://cartflows.com/docs/cartflows-permalink-settings/\";s:4:\"slug\";s:28:\"cartflows-permalink-settings\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-04-28T22:51:54+05:30\";s:8:\"category\";a:1:{i:0;s:18:\"permalink-settings\";}}i:194;O:8:\"stdClass\":8:{s:2:\"id\";i:32570;s:5:\"title\";s:48:\"How to Use the Refund Offer Feature in CartFlows\";s:7:\"content\";s:1948:\"Refund Offer is a feature in CartFlows Pro that allows you to process refunds for offer products, specifically those purchased through Upsell and Downsell steps in your funnel. It simplifies post-purchase management by enabling store admins to refund offer products directly from the order details screen in WooCommerce.\n\n\n\nSupported Payment Gateways\n\n\n\nThe Refund Offer feature works only with supported online payment gateways. These include:\n\n\n\n\nPayPal\n\n\n\nStripe\n\n\n\nAuthorize.net\n\n\n\n\nIt does not support offline gateways such as:\n\n\n\n\nCash on Delivery\n\n\n\nBACS\n\n\n\nCheque\n\n\n\n\nHow to Use the Refund Offer Feature\n\n\n\nImportant: The CartFlows Offer Refund section is only available when the Order option under CartFlows > Settings > Order is set to Add to main order. If this setting is configured differently, the refund metabox will not appear in the order details.\n\n\n\n\n\n\n\nStep 1: Open the Order\n\n\n\nGo to WooCommerce &gt; Orders, and click on the order where the offer product was purchased.\n\n\n\nStep 2: Locate the Offer Refund Section\n\n\n\nIf the order includes products from Upsell or Downsell steps, a CartFlows Offer Refund section will appear in the order details.\n\n\n\n\n\n\n\nStep 3: Initiate the Refund\n\n\n\nNext to each eligible product, you’ll see a Refund button. Click the button for the product you wish to refund.\n\n\n\nStep 4: Provide a Refund Reason\n\n\n\nA popup will appear asking you to enter a reason for the refund. Fill in the reason and confirm.\n\n\n\n\n\n\n\nStep 5: Refund is Processed\n\n\n\nThe refund will be processed using the same payment gateway used during the original transaction. Upon successful completion:\n\n\n\n\nA confirmation popup is shown\n\n\n\n\n\n\n\n\n\nA note is added to the Order Notes section\n\n\n\n\n\nThe refunded status is reflected on the same page after it reloads\n\n\n\n\n\n\n\n\nBy using this feature, you can ensure smoother refund processing for Upsell/Downsell offers, improving customer satisfaction and reducing manual steps for your team.\";s:3:\"url\";s:48:\"https://cartflows.com/docs/refund-offer-feature/\";s:4:\"slug\";s:20:\"refund-offer-feature\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-25T17:35:42+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:195;O:8:\"stdClass\":8:{s:2:\"id\";i:32572;s:5:\"title\";s:56:\"How to Fix the &#8220;Checkout ID Not Found&#8221; Error\";s:7:\"content\";s:1722:\"If you’re seeing the \"Checkout ID Not Found\" message on your Checkout page, it usually means the CartFlows step is not correctly linked to the page where the shortcode is placed.\n\n\n\n\n\n\n\nThis documentation explains when this error occurs and how to resolve it.\n\n\n\nWhen This Happens\n\n\n\nThis error can happen in the following situations:\n\n\n\nCase 1: Editing the Checkout Page in a Page Builder\n\n\n\nYou may see the error while editing your Checkout page inside a page builder. In editor mode, some WooCommerce functions may not be available, which prevents CartFlows from detecting the proper Checkout step.\n\n\n\nSolution:\n\n\n\n\nExit the page builder and return to the WordPress dashboard.\n\n\n\nEdit the checkout step in CartFlows > Funnels, select your funnel, and open the Checkout step.\n\n\n\nMake sure at least one product is selected, or set the funnel to Test Mode if you’re just designing the layout.\n\n\n\nUpdate the page, then visit the checkout page from the frontend.\n\n\n\n\nNote: To see the checkout fields on the page, there must be at least one product assigned to the step or the funnel must be in Test Mode.\n\n\n\nRefer to this guide for help: How to Use Test Mode\n\n\n\nCase 2: Shortcode Placed on the Wrong Page\n\n\n\nThis error can also occur if the [cartflows_checkout] shortcode is placed on a regular WordPress page that isn’t connected to a CartFlows Checkout step.\n\n\n\nSolution:\n\n\n\nOnly place the [cartflows_checkout] shortcode on a page that is assigned as a Checkout step within a CartFlows funnel.\n\n\n\nNote: The [cartflows_checkout] shortcode does not work on upsell, downsell, opt-in, or thank you pages. It is intended for Checkout steps only. For more details, refer to this doc: Placing Shortcodes in the Right Places\";s:3:\"url\";s:63:\"https://cartflows.com/docs/resolve-checkout-id-not-found-error/\";s:4:\"slug\";s:35:\"resolve-checkout-id-not-found-error\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-20T18:51:43+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:196;O:8:\"stdClass\":8:{s:2:\"id\";i:32551;s:5:\"title\";s:65:\"How to Set Quantity and Discount for Product on the Checkout Page\";s:7:\"content\";s:2558:\"CartFlows allows you to predefine product quantities and apply discounts directly on the Checkout page, giving you greater control over pricing and enabling powerful bulk-purchase offers without additional configuration.\n\n\n\nWith this feature, you can configure the quantity and discount for each product added to the Checkout step, ensuring a consistent and optimized purchasing experience for your customers.\n\n\n\nHow Product Quantity and Discounts Work\n\n\n\nWhen configuring products in the Funnel Checkout step settings, you’ll see two key options:\n\n\n\n\nProduct Quantity – Lets you set a predefined quantity for the selected product.\n\n\n\nDiscount Type – Allows you to apply a discount to that product based on the quantity you’ve defined.\n\n\n\n\nThis setup is especially useful for bulk pricing strategies. For example, if you’re selling a product and want to offer a discount only when customers purchase two units, you can set the quantity to 2 and apply a discount specifically for that purchase.\n\n\n\nHow to Configure Quantity and Discount on the Checkout Page\n\n\n\n\nGo to CartFlows → Funnels and open your desired funnel.\n\n\n\nClick Settings on the Checkout step.\n\n\n\nOpen the Products tab.\n\n\n\nExpand a product by clicking the downward arrow next to it.\n\n\n\nSet the Product Quantity and choose the appropriate Discount Type.\n\n\n\n\n\n\n\n\nOnce saved, the predefined quantity will automatically appear on the Checkout page.\n\n\n\nCustomer Experience on Checkout\n\n\n\n\nThe quantity you set in the backend will be prefilled on the Checkout page.\n\n\n\nIf the customer increases the quantity, it will increment based on the predefined quantity you’ve configured.\n\n\n\nDiscounts configured here apply directly on the Checkout page.\n\n\n\n\nIf a product already has a discount set from WooCommerce, the CartFlows discount will be applied on top of the amount received from WooCommerce.\n\n\n\nAvailable Discount Types\n\n\n\nThe Discount Type dropdown includes the following options:\n\n\n\n\nOriginal – No discount is applied.\n\n\n\nDiscount Percentage – Applies a percentage-based discount to the product.\n\n\n\nDiscount Price – Applies a fixed discount amount to the product price.\n\n\n\n\nCommon Use Cases\n\n\n\n\nOffer bulk purchase discounts such as Buy 2 and get 20% off.\n\n\n\nApply CartFlows discounts on top of WooCommerce sale prices.\n\n\n\nCombine Checkout page discounts with coupons applied via Checkout settings or the coupon field.\n\n\n\n\nThis flexible setup helps you create targeted pricing strategies directly within your Checkout flow, improving conversions while keeping the setup simple.\";s:3:\"url\";s:61:\"https://cartflows.com/docs/set-product-quantity-and-discount/\";s:4:\"slug\";s:33:\"set-product-quantity-and-discount\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-04-30T20:08:24+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:197;O:8:\"stdClass\":8:{s:2:\"id\";i:32601;s:5:\"title\";s:43:\"How to Style the Highlight Product Section?\";s:7:\"content\";s:2033:\"CartFlows allows you to highlight a product on the checkout page to make it more noticeable to customers. This feature helps draw attention to specific products by displaying custom highlight text and styling.\n\n\n\nYou can customize the text, border color, text color, and background color of the highlighted product section to match your checkout design.\n\n\n\nHow to Access the Highlight Product Styling Options\n\n\n\nStep 1: Open Funnels\n\n\n\nFrom the WordPress dashboard, navigate to CartFlows &gt; Funnels and edit a funnel.\n\n\n\n\n\n\n\nStep 2: Open the Checkout Step\n\n\n\nSelect the required funnel and locate the Checkout step.\n\n\n\nClick the Settings (Cog icon) on the checkout step to open its settings.\n\n\n\n\n\n\n\nStep 3: Add Products to Checkout\n\n\n\nGo to the Products tab and add the product you want to display to the checkout page.\n\n\n\n\n\n\n\nOnce products are added, go to the Product Options section and enable the Enable Product Options toggle.\n\n\n\n\n\n\n\nStep 4: Enable Highlight for a Product\n\n\n\nUnder the Selected Products section, click the Settings (Cog icon) for the product you want to highlight.\n\n\n\nEnable the Highlight option and enter the highlight text according to your requirements.\n\n\n\n\n\n\n\nStep 5: Customize the Highlight Styling\n\n\n\nTo further customize the highlight section, open the Design tab in the checkout step settings.\n\n\n\nIn the Design tab, you can modify the styling of the highlighted product, including:\n\n\n\n\nHighlight text color\n\n\n\nHighlight background color\n\n\n\nHighlight border color\n\n\n\n\n\n\n\n\nThese options allow you to adjust the appearance of the highlighted product so it stands out on the checkout page.\n\n\n\nIf you are using CartFlows native Gutenberg, Elementor, or Beaver Builder checkout forms, the Product Options styling will be available while editing the checkout form inside the respective page builder. This allows you to customize the product option styling directly within the page builder interface.\n\n\n\nStep 6: Save the Changes\n\n\n\nAfter making the required changes, click Save Settings to apply the settings.\";s:3:\"url\";s:70:\"https://cartflows.com/docs/how-to-style-the-highlight-product-section/\";s:4:\"slug\";s:42:\"how-to-style-the-highlight-product-section\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-02T20:59:25+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:198;O:8:\"stdClass\":8:{s:2:\"id\";i:32553;s:5:\"title\";s:66:\"How to &#8220;Highlight Product&#8221; in CartFlows Checkout Page?\";s:7:\"content\";s:2694:\"Highlight Product lets you draw attention to a specific product variation on the CartFlows checkout page by applying a visually appealing layout. This feature displays a selected product prominently based on the settings you choose in the checkout step’s product options.\n\n\n\nThis documentation will guide you through using the Highlight Product feature and customizing it for your checkout page.\n\n\n\nWhat is Highlight Product?\n\n\n\nThe Highlight Product feature allows you to emphasize a chosen product variation on the checkout page. This helps draw customer attention to specific products or variations you want to promote.\n\n\n\n\n\n\n\nNote: This feature works only on the CartFlows checkout page when the Product Option toggle is enabled from the Product Options tab.\n\n\n\n\n\n\n\nAccessing Product Options\n\n\n\n1: Navigate to Checkout Settings &gt; Products to view all products added to the checkout.\n\n\n\n\n\n\n\n2: Click the small settings icon next to a product to access its product-specific options.\n\n\n\n\n\n\n\n3: Here, you will find the Highlight Product option.\n\n\n\nAvailable Product Option Settings\n\n\n\n\nSelected Products: Displays all products selected for the checkout.\n\n\n\nShortcodes: Use these shortcodes in the product subtext for dynamic content:\n\n{{product_name}} – Displays the product name.\n\n\n\n{{quantity}} – Shows the selected quantity.\n\n\n\n{{discount_value}} – Displays the discount amount.\n\n\n\n{{discount_percent}} – Shows the discount percentage.\n\n\n\n\n\nProduct Option Conditions: Set rules for displaying the highlighted product and variations.\n\n\n\n\n\n\n\n\nLayout Options\n\n\n\nIn the checkout step settings, go to Design &gt; Product Options to customize the layout:\n\n\n\n\nSection Title: Change the title of the product options section.\n\n\n\nSection Position: Place the section before checkout, after customer details, or before order review.\n\n\n\nSkin: Choose between Classic and Cards layout styles.\n\n\n\nShow Product Images: Toggle product image display on or off.\n\n\n\n\n\n\n\n\nNote\nThe Design tab is only visible when your page builder is set to Other in CartFlows settings. If you\'re using Elementor, Beaver Builder, Bricks Builder, or the Block Editor, these page builders have native CartFlows modules where product options design can be managed directly within the module settings.\n\n\n\n\nDesign Options\n\n\n\nUse the design settings to customize colors and styling of the Highlight Product section, including text and background colors.\n\n\n\n\n\n\n\nNote\nThe Highlight Product feature does not work on the CartFlows Store Checkout page. This is because the Store Checkout replaces the default WooCommerce checkout, and product variations are already selected and added to the cart from the single product page.\";s:3:\"url\";s:72:\"https://cartflows.com/docs/highlight-product-in-cartflows-checkout-page/\";s:4:\"slug\";s:44:\"highlight-product-in-cartflows-checkout-page\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-03T17:06:31+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:199;O:8:\"stdClass\":8:{s:2:\"id\";i:31375;s:5:\"title\";s:51:\"How to Create a Marketing Sales Funnel in CartFlows\";s:7:\"content\";s:5662:\"This documentation explains how to create a marketing sales funnel using WordPress, WooCommerce, and CartFlows. The process includes installing the required tools, creating a funnel, configuring the Checkout page, and testing the funnel before going live.\n\n\n\n1. Get a Domain Name and Hosting\n\n\n\nefore creating your website, you need a domain name and hosting.\n\n\n\nA domain name is your website address, and hosting is the service that stores your website files and makes them accessible on the internet.\n\n\n\nOnce you have purchased both, you can proceed with installing WordPress.\n\n\n\nIf you want to speed up the process of creating your website, you can also use ZipWP. It can generate a complete WordPress website with pages, design, and content that you can customize and use for your funnel.\n\n\n\n2. Install and Set Up WordPress\n\n\n\nMost hosting providers offer a one click WordPress installation.\n\n\n\nAfter installing WordPress, ensure that your site is configured properly.\n\n\n\nNavigate to: Settings &gt; Permalinks then select Post name, then click Save Changes.\n\n\n\nThis structure creates clean and readable URLs for your website.\n\n\n\n3. Install the Required Theme and Plugins\n\n\n\nInstall a WordPress Theme\n\n\n\nNavigate to: Appearance &gt; Themes &gt; Add Theme\n\n\n\nInstall and activate the Astra theme. Astra is a lightweight and flexible theme that works well with CartFlows.\n\n\n\nAstra theme: https://wordpress.org/themes/astra/\n\n\n\n\n\n\n\nInstall WooCommerce\n\n\n\nWooCommerce is required to create and sell products in your funnel.\n\n\n\nNavigate to: Plugins &gt; Add Plugin\n\n\n\nSearch for WooCommerce, then install and activate it.\n\n\n\nRefer to this documentation to know more details about WooCommerce and how to install it: https://cartflows.com/docs/how-to-install-woocommerce/\n\n\n\nInstall a Page Builder\n\n\n\nCartFlows works with multiple page builders. You can install any builder you prefer. The most popular page builders are:\n\n\n\n\nElementor\n\n\n\nBlock Editor (Gutenberg)\n\n\n\nBeaver Builder\n\n\n\n\nNavigate to: Plugins &gt; Add Plugin\n\n\n\nSearch for your preferred page builder, then install and activate it. The Block Editor is the default WordPress page editor, so you do not need to install it.\n\n\n\nInstall CartFlows\n\n\n\nNext, install the CartFlows plugin.\n\n\n\nNavigate to: Plugins &gt; Add Plugin\n\n\n\nSearch for CartFlows, then install and activate it.\n\n\n\nThe free version allows you to build funnels and customize WooCommerce checkout pages. The Pro version adds advanced features such as:\n\n\n\n\nOrder Bumps\n\n\n\nOne Click Upsells and Downsells\n\n\n\nCheckout field customization\n\n\n\n\nFor a complete walkthrough on installing the plugin, refer to this documentation: https://cartflows.com/docs/how-to-install-cartflows-free/\n\n\n\nAfter activation, configure the page builder integration.\n\n\n\nNavigate to: CartFlows &gt; Settings &gt; General\n\n\n\nSelect the page builder you installed earlier.\n\n\n\n\n\n\n\n4. Create a New Funnel\n\n\n\nNavigate to: CartFlows &gt; Funnels &gt; Create New Funnel\n\n\n\n\n\n\n\nYou can either import a ready made funnel template or start from scratch. Refer to this documentation for more details about creating funnel: https://cartflows.com/docs/how-to-create-your-first-cartflows-funnel/\n\n\n\n5. Configure the Checkout Step\n\n\n\nSelect the Checkout step in your funnel and click Edit.\n\n\n\nFrom this screen, you can:\n\n\n\n\nAssign a product to the Checkout step\n\n\n\nCustomize the page layout using your page builder\n\n\n\nAdjust checkout settings\n\n\n\n\nFor a detailed explanation of assigning products and configuring the Checkout step, see this documentation: https://cartflows.com/docs/how-to-add-assign-products-to-a-checkout-step-in-cartflows/\n\n\n\n6. Add Upsell or Downsell Offers\n\n\n\nYou can increase the average order value by adding upsell or downsell offers.\n\n\n\nTo add a new step click Add New Step inside your funnel. Select either Upsell or Downsell then choose a template.\n\n\n\n\n\n\n\nFor a complete walkthrough on creating these offers, refer to: https://cartflows.com/docs/create-oneclick-upsell-downsell-offers/\n\n\n\n7. Set the Landing Page as Your Homepage\n\n\n\nIf your funnel landing page will be the main entry point for visitors, you can set it as the homepage.\n\n\n\nNavigate to: Settings &gt; Reading. Select A static page, then choose your funnel landing page.\n\n\n\n\n\n\n\nThis ensures visitors land directly on your funnel.\n\n\n\n8. Test Your Funnel\n\n\n\nBefore launching your funnel, it is important to test the entire process.\n\n\n\nNavigate to: CartFlows &gt; Funnels. Edit your funnel and enable Sandbox Mode from the Funnel Settings panel.\n\n\n\n\n\n\n\nSandbox Mode allows you to simulate purchases and confirm that:\n\n\n\n\nCheckout works correctly\n\n\n\nUpsells and downsells function as expected\n\n\n\nPayments are processed properly\n\n\n\n\nIf you are using Stripe as the payment gateway and sandbox (test) mode is enabled, you can use the test card numbers: 4242 4242 4242 4242 &nbsp;on the Checkout page. Refer to this Stripe documentation to know more about the test number: https://docs.stripe.com/testing\n\n\n\nOnce everything works as expected, you can disable the Sandbox Mode and start accepting real orders.\n\n\n\nLearn More in the Video Below\n\n\n\nIf you prefer a visual walkthrough, watch the video below to see how to create a marketing sales funnel using CartFlows.\n\n\n\n\nhttps://www.youtube.com/watch?v=cagYPks1LLk\n\n\n\n\nDid You Know?\n\n\n\nCartFlows can also be used to create funnels that are not related to eCommerce. For example, you can build a simple lead generation funnel using just two steps:\n\n\n\n\nA landing page with a lead generation form\n\n\n\nA Thank You page\n\n\n\n\nThis approach is commonly used to collect leads, offer free resources, or allow visitors to sign up for newsletters and other offers.\";s:3:\"url\";s:66:\"https://cartflows.com/docs/how-to-create-a-marketing-sales-funnel/\";s:4:\"slug\";s:38:\"how-to-create-a-marketing-sales-funnel\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-05T21:09:17+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:200;O:8:\"stdClass\":8:{s:2:\"id\";i:31241;s:5:\"title\";s:66:\"How to Activate the CartFlows Pro License on a WordPress Multisite\";s:7:\"content\";s:1020:\"If you are using CartFlows Pro on a WordPress Multisite, you can network activate both the CartFlows Free and CartFlows Pro plugins. However, the license activation must be done from each child site. This documentation will walk you through the process.\n\n\n\nInstalling CartFlows on a Multisite Network\n\n\n\nStep 1: Network Activate CartFlows Free &amp; Pro\n\n\n\n\nLog in to your Network Admin Dashboard.\n\n\n\nGo to Plugins > Add New.\n\n\n\nInstall both CartFlows Free and CartFlows Pro plugins.\n\n\n\nClick Network Activate to activate them across all child sites.\n\n\n\n\n\n\n\n\nStep 2: Activate the License on Each Child Site\n\n\n\nOnce CartFlows Pro is network activated, the license must be activated individually on each child site. Follow the steps in this document: How to Activate Your CartFlows Pro License\n\n\n\nImportant Notes\n\n\n\n\nBoth CartFlows Free and Pro can be network-activated, but the Pro license must be activated per child site.\n\n\n\nLicense activation is required for CartFlows Pro to function on any child site in the network.\";s:3:\"url\";s:78:\"https://cartflows.com/docs/how-to-activate-cartflows-pro-license-on-multisite/\";s:4:\"slug\";s:50:\"how-to-activate-cartflows-pro-license-on-multisite\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-03-17T14:24:29+05:30\";s:8:\"category\";a:1:{i:0;s:20:\"installation-updates\";}}i:201;O:8:\"stdClass\":8:{s:2:\"id\";i:31435;s:5:\"title\";s:44:\"How to Enable Paypal Reference Transactions?\";s:7:\"content\";s:1196:\"Before, when using One-Click Upsell for WooCommerce with CartFlows, it is required that you enable PayPal reference transactions for it to work. But now, you can already offer WooCommerce One-Click Upsells even without enabling it. Learn more about this here.\n\n\n\nAlthough enabling PayPal reference transactions is not required, but if you are offering Upsell / Downsell from CartFlows here are the steps on how you can get this enabled for one-click Upsell -\n\n\n\nSteps to Enable PayPal Reference Transactions\n\n\n\nStep 1: Log into PayPal\n\n\n\nEnsure you are using a Business Account and log in to your PayPal account.\n\n\n\nStep 2: Access PayPal Support\n\n\n\nGo to PayPal Contact.\n\n\n\nStep 3: Call Support\n\n\n\nScroll down to the button and select the option to Call the support.\n\n\n\n\n\n\n\nStep 4: Follow Dialing Instructions\n\n\n\nYou will be redirected to a page with instructions for calling PayPal.\n\n\n\n\n\n\n\nStep 5: Request Reference Transactions\n\n\n\nChoose Technical Support and request to enable PayPal Reference Transactions for your account.\n\n\n\nStep 6: Enable in CartFlows\n\n\n\nAfter PayPal confirms the activation, go to your CartFlows settings and enable reference transactions if needed for specific features.\";s:3:\"url\";s:71:\"https://cartflows.com/docs/how-to-enable-paypal-reference-transactions/\";s:4:\"slug\";s:43:\"how-to-enable-paypal-reference-transactions\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-20T19:42:57+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:202;O:8:\"stdClass\":8:{s:2:\"id\";i:32517;s:5:\"title\";s:26:\"Upsell Downsell Shortcodes\";s:7:\"content\";s:2975:\"Upsell and Downsell shortcodes give you more flexibility and control over how product details are displayed on your offer pages, especially when working with Variable Products.\n\n\n\nUsing these shortcodes, you can customize your upsell and downsell pages by displaying product information, adjusting layouts, and creating more engaging offers that match your design and marketing needs.\n\n\n\nNote\nShortcodes for Upsell and Downsell are available only when the Page Builder setting is set to Other.\n\n\n\n\nWhat Can You Display Using These Shortcodes?\n\n\n\nYou can now add and display the following product details dynamically on your Upsell and Downsell pages:\n\n\n\n\nProduct Variation\n\n\n\nProduct Quantity\n\n\n\nProduct Title\n\n\n\nProduct Description (Long)\n\n\n\nProduct Short Description\n\n\n\nProduct Price\n\n\n\nProduct Image\n\n\n\n\nThese shortcodes ensure your customers know exactly what they’re buying and help boost conversions by presenting clear product information.\n\n\n\nNote\nThese shortcodes only work on Upsell and Downsell pages within CartFlows. Using them on other pages (e.g., regular WordPress or WooCommerce pages) can result in errors or unexpected content display.\n\n\n\n\nWhere to Find the Shortcodes\n\n\n\nYou can find these shortcodes by navigating to:\n\n\n\nUpsell / Downsell Settings → Shortcodes section\n\n\n\n\n\n\n\nAvailable Shortcodes and Usage\n\n\n\nAccept Offer Link\n\n\n\nUse this link to allow users to accept the offer. When clicked, the funnel moves to the next step with the offer accepted.\n\n\n\n\nUsage: Add this link to a button, &lt;a&gt; tag, or image.\n\n\n\nRecommended Element: Button or anchor.\n\n\n\n\nDecline Offer Link\n\n\n\nA link to decline the offer and continue to the next step in the funnel without accepting it.\n\n\n\n\nUsage: Add to a button, &lt;a&gt; tag, or image.\n\n\n\nRecommended Element: Button or anchor.\n\n\n\n\nProduct Variation\n\n\n\n[cartflows_offer_product_variation]Displays variation options (dropdown style) for variable products.\n\n\n\n\nUse on: Shortcode widget or text editor.\n\n\n\n\nProduct Quantity\n\n\n\n[cartflows_offer_product_quantity]Allows customers to select product quantity.\n\n\n\n\nUse on: Shortcode widget or text editor.\n\n\n\n\nProduct Title\n\n\n\n[cartflows_offer_product_title]Shows the product title.\n\n\n\n\nUse on: Heading, shortcode widget, or text editor.\n\n\n\n\nProduct Description\n\n\n\n[cartflows_offer_product_desc]Displays the full (long) description of the selected product.\n\n\n\n\nUse on: Shortcode widget or text editor.\n\n\n\n\nProduct Short Description\n\n\n\n[cartflows_offer_product_short_desc]Displays the excerpt or short description of the selected product.\n\n\n\n\nUse on: Shortcode widget or text editor.\n\n\n\n\nProduct Price\n\n\n\n[cartflows_offer_product_price]Shows the product price. If a discount is applied, the discounted price is shown.\n\n\n\n\nUse on: Shortcode widget, text editor, or heading.\n\n\n\n\nProduct Image\n\n\n\n[cartflows_offer_product_image]Displays product images. For variable products, the image updates based on selected variation.\n\n\n\n\nUse on: Shortcode widget or text editor.\";s:3:\"url\";s:66:\"https://cartflows.com/docs/introducing-upsell-downsell-shortcodes/\";s:4:\"slug\";s:38:\"introducing-upsell-downsell-shortcodes\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-20T19:30:07+05:30\";s:8:\"category\";a:1:{i:0;s:14:\"developer-docs\";}}i:203;O:8:\"stdClass\":8:{s:2:\"id\";i:32458;s:5:\"title\";s:102:\"How to Fix the &#8220;We can&#8217;t seem to find an order for you.&#8221; Error on the Thank You Page\";s:7:\"content\";s:1025:\"If you see the message “We can’t seem to find an order for you” on the Thank You page, it usually means the page is being accessed without a valid order or session.\n\n\n\nThis documentation explains why this happens and how to avoid it.\n\n\n\nWhen This Happens\n\n\n\nThis error appears if the Thank You page is visited directly without completing a purchase, while the funnel is live. CartFlows requires an order ID or session ID to display order details on the Thank You page. Without that data, the page cannot load the order and shows the error message.\n\n\n\n\n\n\n\nHow to View the Thank You Page Without an Order\n\n\n\nIf you’re only checking the design of the Thank You page and not placing an actual order, you can use Test Mode.\n\n\n\nSolution:\n\n\n\n\nGo to CartFlows &gt; Funnels.\n\n\n\nOpen your Funnel and enable Test Mode.\n\n\n\nWhile logged in, open the Thank You page directly to preview the layout.\n\n\n\n\nFor help, see this guide: How to Use Test Mode in CartFlows\n\n\n\nNote: Be sure to turn off Test Mode before making the funnel live.\";s:3:\"url\";s:81:\"https://cartflows.com/docs/solve-order-not-found-error-message-on-thank-you-page/\";s:4:\"slug\";s:53:\"solve-order-not-found-error-message-on-thank-you-page\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-03-19T13:25:12+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:204;O:8:\"stdClass\":8:{s:2:\"id\";i:32453;s:5:\"title\";s:47:\"How to Fix Endless Loading on the Checkout Page\";s:7:\"content\";s:1063:\"If your CartFlows Checkout page is stuck loading and the form never appears, it’s usually caused by caching.\n\n\n\nWhat Causes the Issue\n\n\n\nThis issue commonly happens when:\n\n\n\n\nThe Checkout page is cached by a plugin or server\n\n\n\nA 403 error occurs due to security rules or restrictions\n\n\n\n\nCaching can prevent dynamic parts of the Checkout page from working properly, which leads to endless loading or missing content.\n\n\n\nHow to Fix It\n\n\n\n\nClear all cache, including browser cache, plugin cache, and any server-side caching set by your host.\n\n\n\nTemporarily disable any caching plugin you’re using and test the Checkout page again.\n\n\n\nIf the issue persists, contact your hosting provider and ask them to clear any remaining cache at the server level.\n\n\n\n\nIf you’re seeing a 403 error, share the exact error message with your hosting provider. They may need to whitelist certain requests or adjust security settings to allow the checkout page to work correctly.\n\n\n\nFor help excluding CartFlows pages from being cached, refer to this doc: How to Disable Caching\";s:3:\"url\";s:64:\"https://cartflows.com/docs/solve-loading-issue-on-checkout-page/\";s:4:\"slug\";s:36:\"solve-loading-issue-on-checkout-page\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-27T19:27:02+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:205;O:8:\"stdClass\":8:{s:2:\"id\";i:32348;s:5:\"title\";s:76:\"How to Setup Authorize.net Gateway for the Cartflows Upsell &#038; Downsell?\";s:7:\"content\";s:1675:\"CartFlows support for Authorize.Net Credit Card payments specifically for Upsell and Downsell offers. Follow the steps below to set up Authorize.Net in your CartFlows funnels.\n\n\n\nPre-Requisites\n\n\n\nBefore setting up Authorize.Net, make sure you have the following:\n\n\n\n\nAuthorize.Net Account – Create an account if you don’t have one. During setup, obtain your Transaction Key, which will be needed in the WooCommerce settings.\n\n\n\nWooCommerce Authorize.Net Gateway Plugin – Install and activate the official plugin available on the WooCommerce store or the Authorize.Net website.\n\n\n\n\nSteps to Set Up Authorize.Net in WooCommerce\n\n\n\nStep 1: Enable Authorize.Net Payment Gateway\n\n\n\n\nFrom your WordPress Dashboard, navigate to WooCommerce → Settings → Payments Tab.\n\n\n\nEnable the Authorize.Net Credit Card option.\n\n\n\n\n\n\n\n\nStep 2: Enter Transaction Key\n\n\n\n\nPaste the Transaction Key obtained from your Authorize.Net account into the designated field.\n\n\n\nClick Save to store your settings.\n\n\n\n\nStep 3: Configure Important Fields\n\n\n\n\nTransaction Type: Set to Charge.\n\n\n\nTokenization: Enable this option so that credit card fields appear on Checkout, Upsell, and Downsell pages.\n\n\n\nDebug Mode: Set to Save to Log to capture any error logs.\n\n\n\n\n\n\n\n\nStep 4: Verify Setup\n\n\n\n\nVisit your Checkout page. You should see the credit card fields provided by Authorize.Net available for payment.\n\n\n\n\n\n\n\n\nNote\nEnsure your website has a valid SSL certificate and all URLs are using HTTPS. Without HTTPS, the payment fields will not work and may display errors.\n\n\n\n\nFollowing these steps will enable secure Authorize.Net credit card payments for all CartFlows Upsell and Downsell offers.\";s:3:\"url\";s:69:\"https://cartflows.com/docs/setup-authorize-net-gateway-for-cartflows/\";s:4:\"slug\";s:41:\"setup-authorize-net-gateway-for-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-01-05T22:12:40+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:206;O:8:\"stdClass\":8:{s:2:\"id\";i:32341;s:5:\"title\";s:60:\"How to Enable Enfold Avia Layout Builder in CartFlows Steps?\";s:7:\"content\";s:2141:\"By default, the Enfold theme’s Avia Layout Builder is not available on CartFlows steps. However, with a simple code addition, you can enable support and start designing your CartFlows pages using the Avia Builder.\n\n\n\nMethod 1: Add Code to Your Child Theme\n\n\n\nFollow these steps to enable the builder by adding custom code to your child theme:\n\n\n\nStep 1: Copy the Code Below\n\n\n\n// Do not include this if already open!/* * How to add the custome code. * * Please follow below instructions:* 1. Copy the below code.* 2. Open your child theme\'s functions.php file.* 3. Paste the copied code at the very bottom of it &amp; save the file OR upload it on your server/hosting.*//** * Function to allow Enfold theme to edit the CartFlows pages using it\'s page builder. *  * @param array $supported_post_types 	Array of supported post type by the theme. *  * @return array $supported_post_types 	Modified array of supported post type by the theme. */function avf_add_cartflows_post_type_in_theme( array $supported_post_types ) {	$supported_post_types[] = \'cartflows_step\';	return $supported_post_types;}add_filter( \'avf_alb_supported_post_types\', \'avf_add_cartflows_post_type_in_theme\', 10, 1 );add_filter( \'avf_metabox_layout_post_types\', \'avf_add_cartflows_post_type_in_theme\', 10, 1 );\n\n\n\nStep 2: Paste Into Your Child Theme\n\n\n\n\nGo to Appearance > Theme File Editor\n\n\n\nOpen your child theme’s functions.php file\n\n\n\nScroll to the bottom and paste the copied code\n\n\n\nSave the changes\n\n\n\n\nMethod 2: Use the Code Snippets Plugin\n\n\n\nIf you prefer not to modify theme files directly, you can use the Code Snippets plugin:\n\n\n\n\nInstall and activate the Code Snippets plugin (free from WordPress.org).\n\n\n\nCreate a new snippet and paste the same code shown above.\n\n\n\nSet the snippet to run on both front-end and back-end.\n\n\n\nSave and activate the snippet.\n\n\n\n\nHere is a video tutorial on how to add custom functions to your website.\n\n\n\n\nhttps://www.youtube.com/watch?v=c56d84Eek5M\n\n\n\n\nAfter applying either method, the Avia Layout Builder will be available for all CartFlows steps, allowing you to design your funnel pages with Enfold’s native builder.\";s:3:\"url\";s:47:\"https://cartflows.com/docs/enfold-avia-builder/\";s:4:\"slug\";s:19:\"enfold-avia-builder\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-25T23:20:21+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:207;O:8:\"stdClass\":8:{s:2:\"id\";i:32313;s:5:\"title\";s:39:\"Personalization Shortcodes in CartFlows\";s:7:\"content\";s:3049:\"Personalization shortcodes in CartFlows let you display dynamic customer and order information on your funnel steps. This helps you show relevant messages to users based on the data available during the checkout process.\n\n\n\nYou can add these shortcodes inside text elements, headings, or HTML blocks using your preferred page builder.\n\n\n\nWhy Use Personalization Shortcodes\n\n\n\nPersonalized content helps customers feel acknowledged and confident during checkout. Instead of showing a generic message, you can display information such as the customer email or name to make the message more relevant.\n\n\n\nExample: Thank you john@example.com for your order.\n\n\n\nTypes of Personalization Shortcodes\n\n\n\nCartFlows provides two types of personalization shortcodes.\n\n\n\n\nDisplay values submitted on the checkout page\n\n\n\nDisplay values passed through the URL\n\n\n\n\nDisplay Checkout Field Values\n\n\n\nUse this shortcode to show values entered by the customer on the CartFlows Checkout page, such as first name, last name, or email address.\n\n\n\nShortcode Format\n\n\n\n&#91;cartflows_order_fields field=\"first_name\" default=\"Dear\"]\n\n\n\nParameters\n\n\n\nfield: The checkout field value you want to display\n\n\n\ndefault: Text shown when the field value is not available\n\n\n\nExamples\n\n\n\nDisplay the customer first name\n\n\n\n&#91;cartflows_order_fields field=\"first_name\" default=\"My Name\"]\n\n\n\nDisplay the customer last name\n\n\n\n&#91;cartflows_order_fields field=\"last_name\" default=\"My Surname\"]\n\n\n\nYou can use the same shortcode structure to display any checkout field value.\n\n\n\nDisplay URL Parameter Values\n\n\n\nUse this shortcode to display values passed through URL parameters. This is useful when sending users to a CartFlows step from another page while passing data dynamically.\n\n\n\nShortcode Format\n\n\n\n&#91;cartflows_url_fields field=\"first_name\" default=\"Dear\"]\n\n\n\nParameters\n\n\n\nfield: The URL parameter you want to display\n\n\n\ndefault: Text shown when the parameter does not exist\n\n\n\nExamples\n\n\n\nDisplay first name from the URL\n\n\n\n&#91;cartflows_url_fields field=\"first_name\" default=\"My Name\"]\n\n\n\nDisplay last name from the URL\n\n\n\n&#91;cartflows_url_fields field=\"last_name\" default=\"My Surname\"]\n\n\n\nYou can use this shortcode for any value passed in the URL.\n\n\n\nNote\nWooCommerce checkout fields usually include prefixes such as billing or shipping. When using personalization shortcodes in CartFlows, make sure to remove these prefixes.\n\n\n\n\nFor example\n\n\n\nUse first_name instead of billing_first_name\n\n\n\nUse last_name instead of shipping_last_name\n\n\n\nWhere You Can Use These Shortcodes\n\n\n\nYou can add personalization shortcodes on the following CartFlows steps.\n\n\n\n\nCheckout step\n\n\n\nUpsell step\n\n\n\nDownsell step\n\n\n\nThank You step\n\n\n\n\nThese shortcodes work inside your page builder content elements and display values only when the related data is available.\n\n\n\nSummary\n\n\n\nPersonalization shortcodes allow you to show checkout data and URL values dynamically on your CartFlows steps. This helps you create clearer, more relevant messages and improves the overall user experience.\";s:3:\"url\";s:64:\"https://cartflows.com/docs/personalization-shortcodes-cartflows/\";s:4:\"slug\";s:36:\"personalization-shortcodes-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-01-14T15:09:02+05:30\";s:8:\"category\";a:1:{i:0;s:14:\"developer-docs\";}}i:208;O:8:\"stdClass\":8:{s:2:\"id\";i:32316;s:5:\"title\";s:52:\"How to Enable Google Analytics Tracking in CartFlows\";s:7:\"content\";s:1945:\"CartFlows includes built-in support for Google Analytics. You can track funnel performance using predefined events that help you monitor user behavior across the Checkout page, Opt-in page, and more.\n\n\n\nThis documentation shows how to enable Google Analytics tracking in CartFlows and where to enter your measurement ID.\n\n\n\nBefore You Begin\n\n\n\nMake sure you have:\n\n\n\n\nA Google Analytics account (Universal or GA4)\n\n\n\nYour Tracking ID (for Universal Analytics) or Measurement ID (for GA4)\n\n\n\n\nIf you haven’t set it up yet, refer to these official guides:\n\n\n\n\nHow to set up the Analytics Google tag (Legacy)\n\n\n\nHow to set up Google Analytics 4 (GA4)\n\n\n\n\nEnable Google Analytics in CartFlows\n\n\n\n1. From your WordPress dashboard, go to CartFlows &gt; Settings &gt; Integrations.2. Click the Google Analytics Pixel tab.3. Enable the toggle for Enable for CartFlows Pages.\n\n\n\n\n\n\n\n4. Enter your Tracking ID (Universal) or Measurement ID (GA4) in the Enter Google Analytics ID field.\n\n\n\n\n\n\n\n5. To track CartFlows events across the entire website, enable the second toggle: Enable for the whole site.\n\n\n\n\n\n\n\nOnce set up, CartFlows will start sending tracking events to Google Analytics.\n\n\n\nEvents Tracked by CartFlows\n\n\n\nThe following are the available events:\n\n\n\n\nBegin Checkout\n\n\n\nAdd to Cart\n\n\n\nAdd Payment Info\n\n\n\nPurchase\n\n\n\nOpt-in Lead\n\n\n\n\nIs CartFlows Compatible with GA4?\n\n\n\nYes. CartFlows is fully compatible with Google Analytics 4 (GA4).\n\n\n\nTo get your GA4 Measurement ID:\n\n\n\n\nGo to the Admin Panel in your GA4 property.\n\n\n\nPick the Analytic Account.\n\n\n\nSelect your Property.\n\n\n\nYou will see your Measurement ID, which begins with G-.\n\n\n\n\n\n\n\n\nEnter this ID in the Enter Google Analytics ID field in CartFlows settings.\n\n\n\nTroubleshooting\n\n\n\nIf tracking is not working, check that your Measurement ID is correct and that the toggle is enabled.\n\n\n\nRefer to this article for more help: How to Troubleshoot Google Analytics Tracking in CartFlows\";s:3:\"url\";s:70:\"https://cartflows.com/docs/enable-google-analytics-tracking-cartflows/\";s:4:\"slug\";s:42:\"enable-google-analytics-tracking-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-20T00:39:53+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"flows-analytics\";}}i:209;O:8:\"stdClass\":8:{s:2:\"id\";i:32315;s:5:\"title\";s:58:\"How to Troubleshoot Google Analytics Tracking in CartFlows\";s:7:\"content\";s:1091:\"If your Google Analytics tracking is not working in CartFlows, the most common reason is that your Tracking ID or Measurement ID is missing or incorrect.\n\n\n\nThis documentation shows how to check your settings and ensure tracking is enabled.\n\n\n\nStep 1: Check if Tracking Is Enabled\n\n\n\n\nGo to CartFlows &gt; Settings &gt; Integrations.\n\n\n\nClick the Google Analytics Pixel tab.\n\n\n\nMake sure the toggle for Enable for CartFlows Pages is turned on.\n\n\n\n\n\n\n\n\nStep 2: Confirm the Analytics ID\n\n\n\n\nIn the same tab, check the Enter Google Analytics ID field.\n\n\n\nMake sure the ID is entered correctly:\n\nUniversal Analytics IDs start with UA-\n\n\n\nGA4 Measurement IDs start with G-\n\n\n\n\n\n\nIf this field is blank or incorrect, tracking will not work.\n\n\n\n\n\n\n\nStep 3: Test Tracking on the Frontend\n\n\n\n\nUsing the Chrome browser, open your site in Incognito mode.\n\n\n\nUse the Tag Assistant browser extension to confirm that tracking events are firing on CartFlows pages.\n\n\n\n\nNote\nMake sure your CartFlows funnel is set to live, or you’re logged in with Test Mode enabled if you’re checking a non-live funnel.\";s:3:\"url\";s:76:\"https://cartflows.com/docs/troubleshooting-google-analytics-tracking-issues/\";s:4:\"slug\";s:48:\"troubleshooting-google-analytics-tracking-issues\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-18T17:45:13+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"flows-analytics\";}}i:210;O:8:\"stdClass\":8:{s:2:\"id\";i:32274;s:5:\"title\";s:87:\"How to Resolve the &#8220;Please select a Simple, Virtual and Free product&#8221; Error\";s:7:\"content\";s:1003:\"Do you notice an Error Message - Please select a Simple, Virtual and Free product.\n\n\n\n\n\n\n\nSolution: \n\n\n\nFollowing are the steps using which you can select the free Simple and Virtual product on the optin page of the CartFlows.\n\n\n\nStep 1: Go to CartFlows &gt; Funnels and edit the funnel.\n\n\n\n\n\n\n\nStep 2: Click the Settings icon (cog icon) on the Optin step.\n\n\n\n\n\n\n\nStep 3: Navigate to the Products Tab and Search and select your free simple or virtual product for the optin page. Add and save the settings.\n\n\n\n\n\n\n\nIn a nutshell, to resolve this issue, you will need to select Simple and Virtual Product.\n\n\n\nThe Optin Step type only allows selling the above-mentioned type of products. This Step Type provides only three fields such as First Name, Last Name, Email ID.\n\n\n\nSo the user cannot make a payment in this scenario, this is the reason you need to set the zero price value Simple / Virtual product.\n\n\n\nIf you need to add more custom fields in the Optin Type you will need the CartFlows Pro version.\";s:3:\"url\";s:68:\"https://cartflows.com/docs/select-a-simple-virtual-and-free-product/\";s:4:\"slug\";s:40:\"select-a-simple-virtual-and-free-product\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-30T19:41:43+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:211;O:8:\"stdClass\":8:{s:2:\"id\";i:32272;s:5:\"title\";s:52:\"How to Pass Variables as Query Parameters to the URL\";s:7:\"content\";s:1239:\"CartFlows allows you to pass field values from the Opt-in step to the next page using URL query parameters.\n\n\n\nThis feature is helpful when you want to:\n\n\n\n\nPersonalize the content on the next step\n\n\n\nUse custom code to display dynamic messages\n\n\n\nSend user data to an external service (like a CRM)\n\n\n\n\nHow to Enable the Feature\n\n\n\n\nGo to CartFlows &gt; Funnels and open your funnel.\n\n\n\nClick the gear icon on the Opt-in step to access its settings.\n\n\n\nGo to the Settings tab &gt; Optin Settings.\n\n\n\nEnable the toggle labeled Pass Fields as URL Parameters.\n\n\n\n\nOnce enabled, you’ll see first_name added by default. This means the value entered in the First Name field will be passed to the next step via the URL.\n\n\n\n\n\n\n\nHow to Add More Fields\n\n\n\nYou can pass multiple fields by entering their names in a comma-separated format, such as:\n\n\n\nfirst_name, last_name, email\n\n\n\nThis also works for custom fields created using the CartFlows Custom Field Editor (Pro feature).\n\n\n\nNote: The opt-in page field name starts with the “billing_” prefix, such as billing_first_name or billing_last_name. When adding field names to the setting, make sure to exclude the “billing_” part. For example, use first_name instead of billing_first_name.\";s:3:\"url\";s:68:\"https://cartflows.com/docs/pass-variable-as-query-parameters-to-url/\";s:4:\"slug\";s:40:\"pass-variable-as-query-parameters-to-url\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-20T00:43:51+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:212;O:8:\"stdClass\":8:{s:2:\"id\";i:32256;s:5:\"title\";s:35:\"Introducing CartFlows Optin Feature\";s:7:\"content\";s:1646:\"Creating lead generation forms can sometimes be challenging, unexpected errors, too many fields, or difficulty connecting with tools like Mailchimp. To solve this, CartFlows now includes an Optin Step, making it easy to create streamlined, high-converting opt-in funnels.\n\n\n\nWhat Is the CartFlows Optin Step?\n\n\n\nThe Optin Step is a dedicated step type in CartFlows, designed specifically for lead generation funnels. It allows you to collect user information and connect seamlessly with your email marketing tools.\n\n\n\nHow to Import and Set Up the Optin Step\n\n\n\nStep 1: Import the Optin Step\n\n\n\nNavigate to your WordPress Dashboard > CartFlows > Edit your flow and add a new step.From the available step templates, choose either:\n\n\n\n\nReady Templates that include the Optin step\n\n\n\nOr select Create Your Own > Optin Woo\n\n\n\n\nStep 2: Edit the Optin Step\n\n\n\nOpen the step settings to begin configuring your form and product.\n\n\n\nStep 3: Assign a Free Virtual Product\n\n\n\nSelect a product that is:\n\n\n\n\nSimple\n\n\n\nVirtual / Downloadable\n\n\n\nPriced at 0\n\n\n\n\nThis ensures users can complete the step without making a payment.\n\n\n\nStep 4: Form Submission and Lead Capture\n\n\n\nOnce the user fills out the form, their details will be captured and passed to your configured email marketing tool through WooCommerce (e.g., Mailchimp, ConvertKit, etc.).\n\n\n\nNote: Adding custom form fields is available in the CartFlows Pro version.\n\n\n\n\n\n\n\nWhen Should You Use the Optin Step?\n\n\n\nThe Optin Step is perfect for creating lead generation funnels. It’s commonly used to offer free digital products (e.g., ebooks, PDFs, downloads) in exchange for user contact information.\";s:3:\"url\";s:63:\"https://cartflows.com/docs/introducing-cartflows-optin-feature/\";s:4:\"slug\";s:35:\"introducing-cartflows-optin-feature\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-25T23:17:03+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:213;O:8:\"stdClass\":8:{s:2:\"id\";i:32233;s:5:\"title\";s:60:\"How to Create Conditional Upsell &amp; Downsell in CartFlows\";s:7:\"content\";s:2518:\"What is Conditional Redirect?\n\n\n\nConditional Redirect allows you to control where a customer is redirected after interacting with an Upsell or Downsell offer.\n\n\n\nUsing this setting, you can send users to a specific next step in the funnel depending on whether they accept (Yes) or decline (No) the offer.\n\n\n\nFor example:\n\n\n\n\nIf the user accepts the Upsell → Redirect them to another Upsell, Downsell, or Thank You page.\n\n\n\nIf the user declines the Upsell → Redirect them directly to a Downsell or the Thank You page.\n\n\n\n\n\n\n\n\nThis helps create smarter funnels where the next step depends on the user’s decision.\n\n\n\nHow Conditional Upsell &amp; Downsell Helps\n\n\n\nUpsells and Downsells are an essential part of any sales funnel because they help increase the average order value.\n\n\n\nBy using Conditional Redirect, you can create more strategic funnels where customers are shown the most relevant next offer instead of following a fixed path.\n\n\n\nThis makes the funnel more dynamic and improves conversion opportunities.\n\n\n\nHow to Set Up Conditional Redirect in CartFlows Pro\n\n\n\nStep 1: Add Upsell and Downsell Steps\n\n\n\nFrom the WordPress dashboard, navigate to CartFlows > Funnels and edit the funnel in which an Upsell / Downsell has been created or will be created.\n\n\n\n\n\n\n\nStep 2: Open the Offer Step Settings\n\n\n\nLocate the Upsell or Downsell step in the funnel and open click the Settings (cog icon).\n\n\n\n\n\n\n\nStep 3: Access the Conditional Redirect Option\n\n\n\nInside the step settings Settings Tab > Conditional Redirect\n\n\n\n\n\n\n\nThis option allows you to define where users will be redirected based on their choice.\n\n\n\nStep 4: Configure Redirect Paths\n\n\n\nSet the destination for both options:\n\n\n\n\nYes (Accept Offer) → Select the step where the user should be redirected after accepting the offer.\n\n\n\nNo (Decline Offer) → Select the step where the user should be redirected after rejecting the offer.\n\n\n\n\nYou can redirect users to another Upsell, Downsell, or Thank You step depending on your funnel strategy.\n\n\n\n\n\n\n\nStep 5: Save the Settings\n\n\n\nAfter configuring the redirect paths, save the settings.\n\n\n\nYour funnel will now redirect users to different steps depending on whether they accept or decline the offer.\n\n\n\nNote\nIf you do not see any options in the Conditional Redirect dropdown, it means there are no available offer steps after the current step in the funnel.\n\n\n\nTo resolve this, add the required Upsell or Downsell steps after the current offer step, and they will become available in the dropdown.\";s:3:\"url\";s:62:\"https://cartflows.com/docs/create-conditional-upsell-downsell/\";s:4:\"slug\";s:34:\"create-conditional-upsell-downsell\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-20T20:16:50+05:30\";s:8:\"category\";a:1:{i:0;s:17:\"one-click-upsells\";}}i:214;O:8:\"stdClass\":8:{s:2:\"id\";i:32213;s:5:\"title\";s:41:\"How to Enable Collapsible Checkout Fields\";s:7:\"content\";s:957:\"CartFlows Pro allows you to make specific Checkout fields collapsible. This helps create a cleaner layout by letting customers expand only the sections they need to interact with.\n\n\n\nNote: You must enable the Custom Field Editor to access this feature.\n\n\n\nWhere to Find the Setting\n\n\n\n\nGo to CartFlows &gt; Funnels and open your funnel.\n\n\n\nOpen setting of the Checkout step.\n\n\n\nGo to the Checkout Form tab.\n\n\n\nGo to the Field Editor section and enable the Enable Custom Field Editor toggle.\n\n\n\n\nHow to Enable Collapsible Fields\n\n\n\n\nLocate the field you want to collapse.\n\n\n\nMake sure the field is not required.\n\n\n\nEnable the Collapsible toggle.\n\n\n\nClick Save/Update.\n\n\n\n\n\n\n\n\nThe selected field will now be hidden under a toggle on the Checkout page.\n\n\n\nMake Coupon and Additional Field Collapsible\n\n\n\n\nEnable the Coupon Field or Additional Field setting first.\n\n\n\nOnce enabled, the Collapsible toggle will appear.\n\n\n\nEnable the toggle and save your changes.\";s:3:\"url\";s:62:\"https://cartflows.com/docs/enable-collapsible-checkout-fields/\";s:4:\"slug\";s:34:\"enable-collapsible-checkout-fields\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-02T21:23:20+05:30\";s:8:\"category\";a:1:{i:0;s:21:\"checkout-field-editor\";}}i:215;O:8:\"stdClass\":8:{s:2:\"id\";i:32147;s:5:\"title\";s:58:\"How to Translate CartFlows Using the Loco Translate Plugin\";s:7:\"content\";s:1301:\"You can translate CartFlows using the Loco Translate plugin, which allows you to edit plugin strings directly from your WordPress dashboard.\n\n\n\nFollow the steps below to translate text like button labels, coupon fields, or any other CartFlows string.\n\n\n\nInstall and Access Loco Translate\n\n\n\n\nInstall and activate the Loco Translate plugin from the WordPress repository.\n\n\n\nNavigate to Loco Translate > Plugins.\n\n\n\nSelect CartFlows from the list\n\n\n\n\n\n\n\n\nAdd a New Language\n\n\n\n1. If the language you want to translate into is not listed, click the New Language button.2. Select the language you want to use.\n\n\n\n\n\n\n\n3. Choose Custom location under the file location options.4. Click Start Translating.\n\n\n\n\n\n\n\nYou may choose a different location if needed, depending on your site setup.\n\n\n\nTranslate CartFlows Strings\n\n\n\n\nUse the search bar to find the text you want to translate (for example, “Coupon”).\n\n\n\nSelect the string, then add your translation in the bottom translation field.\n\n\n\nClick Save.\n\n\n\n\n\n\n\n\nPreview Translations on Frontend\n\n\n\nOnce saved, your translated strings will appear on the frontend according to your site’s language.\n\n\n\nNote: Make sure your WordPress site language matches the language you added in Loco Translate. You can set this from Settings > General > Site Language.\";s:3:\"url\";s:68:\"https://cartflows.com/docs/translate-cartflows-using-loco-translate/\";s:4:\"slug\";s:40:\"translate-cartflows-using-loco-translate\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-07-07T23:59:49+05:30\";s:8:\"category\";a:1:{i:0;s:19:\"translate-cartflows\";}}i:216;O:8:\"stdClass\":8:{s:2:\"id\";i:32131;s:5:\"title\";s:52:\"How to Enable Fusion Page Builder on CartFlows Steps\";s:7:\"content\";s:470:\"If you’re using Fusion Page Builder, you can enable it to work with CartFlows steps by updating the Fusion Builder settings.\n\n\n\nEnable Fusion Builder for CartFlows Steps\n\n\n\n\nGo to Settings > Fusion in your WordPress dashboard.\n\n\n\nUnder the Post Types section, tick the Steps checkbox.\n\n\n\nClick Save Changes.\n\n\n\n\n\n\n\n\nOnce enabled, the Edit with Fusion Builder button will appear when editing a CartFlows step. You can now design your step using the Fusion Page Builder.\";s:3:\"url\";s:54:\"https://cartflows.com/docs/enable-fusion-page-builder/\";s:4:\"slug\";s:26:\"enable-fusion-page-builder\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-13T22:46:52+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:217;O:8:\"stdClass\":8:{s:2:\"id\";i:32088;s:5:\"title\";s:38:\"Setup Pre-Checkout Upsell in CartFlows\";s:7:\"content\";s:1425:\"The Pre-Checkout Upsell feature allows you to display an offer directly on the Checkout page when a customer clicks the Place Order or Proceed to Checkout button.\n\n\n\nThis helps you present an additional product before the order is placed, without interrupting the checkout flow. Since the offer is shown before payment processing, it works seamlessly with almost all WooCommerce payment gateways available on your checkout page.\n\n\n\nHow to Enable Pre-Checkout Upsell\n\n\n\nStep 1: Open the Checkout Step Settings\n\n\n\n\nGo to WordPress Dashboard &gt; CartFlows &gt; Funnels.\n\n\n\nOpen your funnel and click Settings on the Checkout step.\n\n\n\nNavigate to the Checkout Offer tab.\n\n\n\n\n\n\n\n\nStep 2: Enable Checkout Offer\n\n\n\n\nToggle the Enable Checkout Offer option.\n\n\n\nSelect the product you want to offer from the Select Product dropdown.\n\n\n\n\n\n\n\n\nYou can further customize the offer behavior using the additional settings available in the Checkout Offer section.\n\n\n\n\n\n\n\nHow It Works on the Frontend\n\n\n\nAfter enabling the Pre-Checkout Upsell:\n\n\n\n\nVisit the Checkout page on the frontend.\n\n\n\nFill in the required checkout details.\n\n\n\nClick Proceed to Checkout or Place Order.\n\n\n\n\nAt this point, a popup offer will be displayed, allowing the customer to accept or decline the additional product before completing the order.\n\n\n\n\n\n\n\nNote\nThe Pre-Checkout Upsell works with almost all WooCommerce payment gateways.\n\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:53:\"https://cartflows.com/docs/setup-pre-checkout-upsell/\";s:4:\"slug\";s:25:\"setup-pre-checkout-upsell\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-12T18:54:56+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:218;O:8:\"stdClass\":8:{s:2:\"id\";i:32083;s:5:\"title\";s:57:\"How to Troubleshoot a Conflict with the Plugin and Theme?\";s:7:\"content\";s:1725:\"If you\'re experiencing issues such as:\n\n\n\n\nCSS not applying properly\n\n\n\nCheckout page continuously loading\n\n\n\nCart not displaying or updating correctly\n\n\n\nLayout issues (e.g., cart items misaligned or stacked)\n\n\n\nUnexpected product replacements in the cart\n\n\n\n\nThese are often caused by conflicts with your theme or other installed plugins.\n\n\n\nBefore reaching out to support, here are some quick and effective steps you can take to identify and resolve the issue:\n\n\n\nStep 1: Switch to a Default Theme\n\n\n\nTemporarily switch your website theme to a default WordPress theme like Twenty Twenty-One or Twenty Twenty-Three. Check if the issue still occurs. If the problem disappears, your theme may be conflicting with CartFlows or WooCommerce.\n\n\n\nStep 2: Deactivate Other Plugins\n\n\n\nDeactivate all plugins except CartFlows and WooCommerce.Then, test the functionality again. If the issue is resolved, re-enable your plugins one by one to identify the conflicting plugin.\n\n\n\nNote: This is a standard debugging approach followed by most WordPress support teams and helps identify over 90% of issues. We recommend taking a full backup of your site before proceeding.\n\n\n\nStep 3: Review Custom Code\n\n\n\nIf you’ve added custom code to your theme or through third-party plugins, consider temporarily disabling it to rule out conflicts.\n\n\n\nWatch: Troubleshooting in Action\n\n\n\nHere’s a quick video walkthrough to guide you through this process:\n\n\n\n\nhttps://www.youtube.com/watch?v=yWEnKnzwc0U\n\n\n\n\nIf the issue persists after trying the above steps, feel free to reach out to our Technical Support team. If possible, please share a staging site or grant temporary access to your live site so we can help debug the issue more effectively.\";s:3:\"url\";s:49:\"https://cartflows.com/docs/troubleshooting-steps/\";s:4:\"slug\";s:21:\"troubleshooting-steps\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-25T23:18:45+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:219;O:8:\"stdClass\":8:{s:2:\"id\";i:31733;s:5:\"title\";s:41:\"How PayPal and Stripe Work with CartFlows\";s:7:\"content\";s:3460:\"This documentation explains how PayPal and Stripe work with CartFlows when processing payments through WooCommerce.\n\n\n\nCartFlows integrates with WooCommerce payment gateways. Once a payment gateway is enabled in WooCommerce, it can be used on CartFlows Checkout pages.\n\n\n\nThe following gateways are commonly used with CartFlows:\n\n\n\n\nPayPal Standard\n\n\n\nPayPal Express Checkout (PayPal Checkout)\n\n\n\nStripe\n\n\n\n\nPayPal Standard\n\n\n\nNote\nPayPal Standard is no longer suggested by PayPal. WooCommerce strongly encourages switching to the PayPal Payments extension instead. Support for PayPal Standard is very limited, and it is hidden for new installations since WooCommerce 5.5.0.\n\n\n\n\nTo accept payments using PayPal Standard, make sure the following settings are configured in WooCommerce.\n\n\n\n\nEnable PayPal Standard.\n\n\n\nEnable Sandbox Mode if you want to test payments. Disable it when accepting live payments.\n\n\n\nEnable Logging to record potential errors.\n\n\n\nEnable IPN Email Notifications.\n\n\n\nIf IPN email notifications are enabled, add the PayPal Identity Token.\n\n\n\nSet Payment Action to Capture.\n\n\n\nEnter the required API credentials.\n\n\n\nAdd Sandbox API credentials when testing payments.\n\n\n\nAdd Live API credentials when accepting real payments.\n\n\n\n\nFor more details, refer to the WooCommerce documentation: https://docs.woocommerce.com/document/paypal-standard/\n\n\n\nPayPal Express Checkout\n\n\n\nNote\nPayPal Express Checkout (PayPal Checkout) is no longer suggested by PayPal. It is no longer available for download via the WooCommerce Marketplace and support ended on 1 March, 2022. WooCommerce encourages upgrading to the PayPal Payments extension instead.\n\n\n\n\nTo use PayPal Express Checkout with CartFlows, configure the following settings.\n\n\n\n\nEnable PayPal Checkout.\n\n\n\nSet the Environment to Live or Sandbox.\n\n\n\nEnter the corresponding API credentials for the selected environment.\n\n\n\nEnable Debug Log in the Advanced Settings.\n\n\n\nEnable Reference Transactions in CartFlows.\n\n\n\n\nTo enable Reference Transactions in CartFlows, navigate to: CartFlows &gt; Settings\n\n\n\nThen enable Reference Transactions.\n\n\n\nReference Transactions are required to enable true one click upsells with PayPal.\n\n\n\nFor more information about PayPal Express Checkout, refer to: https://docs.woocommerce.com/document/paypal-express-checkout/\n\n\n\nStripe\n\n\n\nTo accept payments using Stripe, configure the following settings.\n\n\n\n\nEnable Stripe.\n\n\n\nEnable Test Mode when testing payments.\n\n\n\nAdd the Test Publishable Key and Test Secret Key.\n\n\n\nAdd the Live Publishable Key and Live Secret Key.\n\n\n\n\nFor more information about Stripe configuration, refer to: https://docs.woocommerce.com/document/stripe/\n\n\n\nFrequently Asked Questions\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nHow can I enable Reference Transactions in PayPal?\n\n\n\nTo request Reference Transactions for your PayPal account:\n\n\n\n\nLog in to your PayPal account.\n\n\n\nGo to the Email Contact Form.\n\n\n\nChoose My Account as the topic.\n\n\n\nChoose Changing or Updating Account Information as the sub topic.\n\n\n\nSend a request asking PayPal to enable Reference Transactions.\n\n\n\n\nExample message:\n\n\n\nHello Team,I would like to enable Reference Transactions on my PayPal account.My PayPal email address is: your@email.com.I need this feature to support post purchase upsells or one click upsells via WooCommerce.Kind regardsYour Name\n\n\n\nAfter submitting the request, wait for PayPal to confirm the activation. The approval process may vary depending on the country.\";s:3:\"url\";s:67:\"https://cartflows.com/docs/working-of-paypal-stripe-with-cartflows/\";s:4:\"slug\";s:39:\"working-of-paypal-stripe-with-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-03-13T18:07:28+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:220;O:8:\"stdClass\":8:{s:2:\"id\";i:31729;s:5:\"title\";s:58:\"How to Translate CartFlows Using the TranslatePress Plugin\";s:7:\"content\";s:1032:\"CartFlows can be translated using the TranslatePress plugin, allowing you to localize your funnel steps and content directly from the frontend.\n\n\n\nFollow the steps below to translate your CartFlows funnel pages.\n\n\n\nConfigure TranslatePress Settings\n\n\n\n\nFrom your WordPress dashboard, go to Settings &gt; TranslatePress.\n\n\n\nUnder the General tab, find the All Languages section.\n\n\n\nAdd the language(s) you want to translate your website into.\n\n\n\n\n\n\n\n\nOnce added, the new language will appear in your site’s language switcher.\n\n\n\nTranslate CartFlows Funnel Steps\n\n\n\n1. Open the CartFlows step or page you want to translate.2. From the top admin bar, click the Translate Page button.\n\n\n\n\n\n\n\n3. Click the text you want to translate and click on it.\n\n\n\n\n\n\n\n4. Enter your translated text in the field that appears.5. Click the Save translation button to apply your translation.\n\n\n\n\n\n\n\nRepeat this for each string you want to translate on the page.\n\n\n\nWatch a Video Tutorial\n\n\n\nOr refer to the following video to see how you can do this:\";s:3:\"url\";s:67:\"https://cartflows.com/docs/translate-cartflows-with-translatepress/\";s:4:\"slug\";s:39:\"translate-cartflows-with-translatepress\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-07-08T00:00:40+05:30\";s:8:\"category\";a:1:{i:0;s:19:\"translate-cartflows\";}}i:221;O:8:\"stdClass\":8:{s:2:\"id\";i:31682;s:5:\"title\";s:56:\"Shortcode Reference for Email Fields in Cart Abandonment\";s:7:\"content\";s:1762:\"You can personalize your abandoned cart recovery emails using the shortcodes listed below. These shortcodes allow you to dynamically insert customer details, cart contents, and other relevant information into your emails.\n\n\n\nAvailable Shortcodes\n\n\n\nNo First Name Shortcode  Description 1Admin Firstname{{admin.firstname}}It displays the name of the shop owner or an administrator.2Admin Company{{admin.company}}It displays the name of the shop or company.3Abandoned Product Details Table{{cart.product.table}}It displays the details of products that were abandoned with Product name, Product image, Quantity, Price and Line subtotal in table format.4Abandoned Product Names{{cart.product.names}}It displays only product names that were abandoned. 5Cart Checkout URL{{cart.checkout_url}}It is the URL that redirects to the checkout page.6Coupon Code{{cart.coupon_code}}It is the coupon code that can be used on the checkout page for the discount.7Customer First Name{{customer.firstname}}It displays the First name of the Customer.8Customer Last Name{{customer.lastname}}It displays the Last name of the Customer.9Customer Full Name{{customer.fullname}}It displays the Full name of the Customer.10Cart Abandonment Date{{cart.abandoned_date}}It displays the date on which the cart is abandoned.11Site URL{{site.url}}It displays the Main Site URL of the shop or company.12Unsubscribe Link{{cart.unsubscribe}}It allows customers to unsubscribe from the email of cart abanded. If a customer unsubscribes from this link then they will not receive future emails for an abandoned cart.\n\n\n\nThese shortcodes can be used in the email templates within the Cart Abandonment Recovery for WooCommerce plugin to create personalized and relevant email content for your customers.\";s:3:\"url\";s:64:\"https://cartflows.com/docs/shortcode-reference-for-email-fields/\";s:4:\"slug\";s:36:\"shortcode-reference-for-email-fields\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-08-21T21:46:18+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:222;O:8:\"stdClass\":8:{s:2:\"id\";i:31688;s:5:\"title\";s:34:\"Filters to Customize Product Table\";s:7:\"content\";s:1476:\"Cart Abandonment Recovery for WooCommerce allows customization of the email template styles using WordPress filters. This is especially helpful if you want to match the design of your product table and images to your brand.\n\n\n\nModify Product Table &amp; Image Styles\n\n\n\nYou can use the following filter to adjust the styles applied to the product table and product image inside the recovery emails:\n\n\n\n/* * The woo_ca_email_template_table_style filter allows you to change the default styles of  * Product table &amp; product image provided by Cart Abandonment Recovery for WooCommerce plugin. * */add_filter( \'woo_ca_email_template_table_style\', \'wcar_product_table_styles\', 10 ); function wcar_product_table_styles( $style ){    $style[\'product_image\'][\'style\'] = \'height: 42px; width: 42px;\';        $style[\'table\'][\'style\'] = \'color: #636363; border: 1px solid #e5e5e5; width:250px;\';        $style[\'table\'][\'attribute\'] = \'align=\"center\" \';        return $style;}\n\n\n\nInclude Cart Total with Tax and Shipping\n\n\n\nIf you\'d like the product table in the recovery email to also display the cart total including tax and shipping, you can use the filter below:\n\n\n\n// Show product table with cart total including tax and shipping costadd_filter( \'woo_ca_recovery_enable_cart_total\', \'__return_true\' );\n\n\n\nNote: These filters should be added to your child theme’s functions.php file. If you’re not sure how to add custom code, please refer to this guide on adding custom code.\";s:3:\"url\";s:62:\"https://cartflows.com/docs/filters-to-customize-product-table/\";s:4:\"slug\";s:34:\"filters-to-customize-product-table\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-08-21T21:47:58+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:223;O:8:\"stdClass\":8:{s:2:\"id\";i:31676;s:5:\"title\";s:67:\"How to Enable Webhooks in Cart Abandonment Recovery for WooCommerce\";s:7:\"content\";s:2483:\"The Cart Abandonment Recovery plugin for WooCommerce includes webhook support to help automate actions like sending coupon codes or follow-up notifications when a customer abandons the checkout process.\n\n\n\nThis allows seamless integration with automation tools like Zapier, so you can customize what happens after an abandonment event, for example, automatically emailing a unique coupon code.\n\n\n\nWhere to Find the Webhook Setting\n\n\n\nTo enable Webhooks, follow these steps:\n\n\n\n\nGo to your WordPress dashboard.\n\n\n\nNavigate to WooCommerce &gt; Cart Abandonment.\n\n\n\nClick on the Settings tab.\n\n\n\nLocate the Webhook section and enable the Webhook Toggle.\n\n\n\n\n\n\n\n\nOnce enabled, you’ll be able to paste a webhook URL from your preferred automation platform.\n\n\n\nHow Webhooks Work\n\n\n\nA webhook acts like a listener. When a shopper abandons the checkout, the plugin triggers the webhook to perform an action — such as:\n\n\n\n\nSending an email with a coupon code.\n\n\n\nNotifying your CRM or marketing tool.\n\n\n\nLogging the event in an external system.\n\n\n\n\nYou can create and manage this logic using services like Zapier.\n\n\n\nHow to Set Up a Webhook with Zapier\n\n\n\nHere’s how to configure a webhook using Zapier:\n\n\n\nStep 1: Create a Zap\n\n\n\n\nLog in to Zapier and click My Zaps.\n\n\n\nClick Create Zap.\n\n\n\n\n\n\n\n\nStep 2: Add a Webhook Trigger\n\n\n\n\nFor the trigger app, search and select Webhooks by Zapier.\n\n\n\nChoose the Catch Raw Hook trigger and click Continue.\n\n\n\n\n\n\n\n\nStep 3: Copy the Webhook URL\n\n\n\n\nZapier will generate a webhook URL. Copy it.\n\n\n\n\n\n\n\n\nStep 4: Paste the Webhook URL in Plugin Settings\n\n\n\n\nGo back to WooCommerce &gt; Cart Abandonment &gt; Settings &gt; Webhook.\n\n\n\nPaste the Zapier webhook URL.\n\n\n\n\n\n\n\n\nStep 5: Trigger a Sample\n\n\n\n\nIn the Cart Abandonment plugin, use the Trigger Sample option.\n\n\n\n\n\n\n\n\n\nYou can review the webhook data as shown below –\n\n\n\n\n\n\n\n\nStep 6: Set the Action\n\n\n\n\nAdd an Action Step in your Zap (e.g., Send Email etc.).\n\n\n\n\n\n\n\n\n\nCustomize the action according to your workflow.\n\n\n\n\nSending Coupons via Webhook\n\n\n\nIf you’ve enabled the Auto-Generate Coupon Code feature in the plugin:\n\n\n\n\nAbandoned users will receive a personalized email with a discount.\n\n\n\nYou can choose between a fixed or percentage discount and set an expiry timer for the coupon.\n\n\n\n\nNeed More Customization?\n\n\n\nYou can create multiple Zaps with different triggers and actions depending on your needs — whether it\'s CRM integration, SMS alerts, or adding users to a mailing list.\";s:3:\"url\";s:69:\"https://cartflows.com/docs/enable-webhooks-cart-abandonment-recovery/\";s:4:\"slug\";s:41:\"enable-webhooks-cart-abandonment-recovery\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-06-23T15:37:48+05:30\";s:8:\"category\";a:1:{i:0;s:25:\"cart-abandonment-recovery\";}}i:224;O:8:\"stdClass\":8:{s:2:\"id\";i:31534;s:5:\"title\";s:39:\"Facebook Pixel Integration in CartFlows\";s:7:\"content\";s:1364:\"CartFlows supports native integration with Facebook Pixel, allowing you to track user behavior and conversions directly within your CartFlows funnels.\n\n\n\nIf you already use the PixelYourSite plugin, CartFlows automatically integrates with these plugins, no additional setup needed.\n\n\n\nHowever, if you’re not using either plugin, CartFlows provides a built-in Facebook Pixel integration that makes connecting your pixel simple.\n\n\n\nHow to Enable Facebook Pixel Integration\n\n\n\n1. Go to CartFlows &gt; Settings &gt; Integrations2. Locate the Facebook Pixel section3. Enable the toggle to activate Facebook Pixel integration\n\n\n\n\n\n\n\n4. Enter your Facebook Pixel ID in the field provided and choose which events you’d like to track5. Click Save Changes to apply your settings\n\n\n\n\n\n\n\nOnce configured, Facebook Pixel will start tracking key user interactions within your CartFlows funnels.\n\n\n\nUsing Third-Party Plugins\n\n\n\nIf you prefer using a dedicated plugin, CartFlows seamlessly integrates with the PixelYourSite plugin.\n\n\n\nYou can continue using your existing setup, CartFlows automatically detects and works with this plugin.\n\n\n\nHow to Test or Verify the Working of Facebook Pixel Support\n\n\n\nFor testing the working of Facebook Pixel on your Checkout Page with Google Chrome browser, you will need to have the following Google browser extension: Meta Pixel Helper\";s:3:\"url\";s:54:\"https://cartflows.com/docs/facebook-pixel-integration/\";s:4:\"slug\";s:26:\"facebook-pixel-integration\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-14T19:45:21+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:225;O:8:\"stdClass\":8:{s:2:\"id\";i:31238;s:5:\"title\";s:46:\"How to Display a Terms and Conditions Checkbox\";s:7:\"content\";s:676:\"If you want customers to agree to your Terms &amp; Conditions before completing their order, you can enable a checkbox on the Checkout page.\n\n\n\nCartFlows uses WooCommerce for the Checkout page, so this feature is handled through WooCommerce settings.\n\n\n\nAdd a Terms &amp; Conditions Checkbox\n\n\n\n1. Create a new page and add your Terms &amp; Conditions content to it.2. Go to WooCommerce > Settings > Advanced.3. Under the Page setup section, look for the Terms and conditions dropdown.4. Select the page you created.\n\n\n\n\n\n\n\n5. Save the changes.\n\n\n\nWooCommerce will now automatically add a checkbox to your Checkout page with a link to the selected Terms &amp; Conditions page.\";s:3:\"url\";s:70:\"https://cartflows.com/docs/how-to-a-display-terms-conditions-checkbox/\";s:4:\"slug\";s:42:\"how-to-a-display-terms-conditions-checkbox\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-03T14:40:46+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:226;O:8:\"stdClass\":8:{s:2:\"id\";i:31178;s:5:\"title\";s:44:\"How To Enable ActiveCampaign With CartFlows?\";s:7:\"content\";s:568:\"Using CartFlows with WooCommerce enables you to integrate your marketing automation tools. If you\'re using ActiveCampaign, depending on which plan you purchase, you\'ll be able to integrate WooCommerce with it.\n\n\n\nIf your ActiveCampaign Plan is either Plus, Professional, or Enterprise, integration with WooCommerce is supported.\n\n\n\nHere is the link on how to setup WooCommerce Integration with ActiveCampaign.\n\n\n\nIf your ActiveCampaign Plan is not supported, you might want to try the following alternative marketing automation tools.\n\n\n\nZapier for WooCommerceWPFusion\";s:3:\"url\";s:71:\"https://cartflows.com/docs/how-to-enable-activecampaign-with-cartflows/\";s:4:\"slug\";s:43:\"how-to-enable-activecampaign-with-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2024-11-12T15:17:37+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:227;O:8:\"stdClass\":8:{s:2:\"id\";i:31086;s:5:\"title\";s:33:\"How To Add Order Bump To A Funnel\";s:7:\"content\";s:2409:\"An Order Bump allows you to offer an additional product directly on the checkout page. This is a simple yet powerful way to increase your average order value. Customers can add the extra product with a single click while completing their purchase.\n\n\n\nHow to Add an Order Bump\n\n\n\nStep 1: Edit Your Funnel\n\n\n\nFrom your WordPress dashboard, navigate to CartFlows &gt; Funnels and edit the Funnel where you want to add the Order Bump.\n\n\n\n\n\n\n\nStep 2: Open the Checkout Step\n\n\n\nLocate your Checkout step and click on the Settings icon (cog icon).\n\n\n\n\n\n\n\nStep 3: Add an Order Bump\n\n\n\nGo to the Order Bump section on the sidebar.\n\n\n\nType the name of your Order Bump and click Add.\n\n\n\n\n\n\n\nOnce added, click on the Settings icon (cog icon) of the newly created Order Bump to configure it.\n\n\n\nOrder Bump Settings Overview\n\n\n\nThe Order Bump settings are divided into four tabs:\n\n\n\n\nProduct\n\n\n\nContent\n\n\n\nStyles\n\n\n\nConditions\n\n\n\n\nBelow is a detailed explanation of each section.\n\n\n\n1. Product Tab\n\n\n\nHere, you can select the product you want to offer as an Order Bump.\n\n\n\nProduct – Type the name of the product you want to add and select it from the search results.\n\n\n\n\n\n\n\n2. Content Tab\n\n\n\nThis section allows you to control the text and basic display options of the Order Bump.\n\n\n\n\nCheckbox Label – Customize the checkbox text customers click to add the offer.\n\n\n\nHighlight Text – Add a compelling headline to grab attention.\n\n\n\nDescription – Provide additional details about the product.\n\n\n\nEnable Image Options – Enable or disable the product image display.\n\n\n\n\n\n\n\n\n3. Styles Tab\n\n\n\nCustomize the appearance of your Order Bump to match your brand.\n\n\n\nLayout\n\n\n\n\nOrder Bump Skin – Choose the design style for the Order Bump.\n\n\n\nWidth – Adjust the width of the Order Bump section.\n\n\n\nPosition – Control where the Order Bump appears on the checkout page.\n\n\n\n\nColors\n\n\n\n\nAdjust available color settings to match your design preferences.\n\n\n\n\nBorders\n\n\n\n\nCustomize border styles and appearance.\n\n\n\n\nShadows\n\n\n\n\nAdd or modify shadow effects for better visual emphasis.\n\n\n\n\n\n\n\n\n4. Conditions Tab\n\n\n\n\nEnable Conditional Order Bump – Display the Order Bump only when specific conditions are met.\n\n\n\n\n\n\n\n\nOnce configured, don\'t forget to enable the Order Bump and save the settings to apply the changes. Your Order Bump will now appear on the checkout page, helping you increase conversions and overall revenue.\";s:3:\"url\";s:78:\"https://cartflows.com/docs/how-to-add-order-bumps-to-woocommerce-sales-funnel/\";s:4:\"slug\";s:50:\"how-to-add-order-bumps-to-woocommerce-sales-funnel\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-08T17:40:00+05:30\";s:8:\"category\";a:1:{i:0;s:10:\"order-bump\";}}i:228;O:8:\"stdClass\":8:{s:2:\"id\";i:31077;s:5:\"title\";s:41:\"How to Import and Export Funnels and Step\";s:7:\"content\";s:1576:\"CartFlows lets you export and import your funnels, making it easy to reuse them across different websites. You can also export and import the design templates for individual funnel steps using your preferred page builder.\n\n\n\nExport a Funnel\n\n\n\n\nGo to CartFlows &gt; Funnels.\n\n\n\nTick the checkbox next to the funnel title then click the Export button that is visible after you tick the checkbox or click the three dots of the funnel and click the Export button.\n\n\n\n\n\n\n\n\nFunnel can also be exported from inside the funnel.\n\n\n\nGo to the funnel you would like to export and click the Export button at the top.\n\n\n\n\n\n\n\nThis will download a .json file to your local computer.\n\n\n\nNote: If you’re exporting from a local site, import may not work on a live website. Funnel exports are supported only between live sites.\n\n\n\nImport a Funnel\n\n\n\n1. Click the Import button at the top of the Funnels page.\n\n\n\n\n\n\n\n2. Upload the .json file that contains your exported funnel.\n\n\n\n3. Click Import Funnel button.\n\n\n\n\n\n\n\nOnce complete the imported funnel will show up in your Funnels list.\n\n\n\nImport or Export Step\n\n\n\nIf you want to move the design of an individual funnel step, you can do so using your page builder’s template import or export options.\n\n\n\n\nGo to the funnel step you want to modify.\n\n\n\nClick Edit Funnel to open the page in your page builder\n\n\n\nUse the builder’s import/export tool to upload or download the template.\n\n\n\n\nEach page builder handles templates differently. Use the following guides to learn more:\n\n\n\n\nElementor&nbsp;\n\n\n\nBeaver Builder\n\n\n\nBricks Builder\n\n\n\nDivi\";s:3:\"url\";s:70:\"https://cartflows.com/docs/import-export-flows-page-builder-templates/\";s:4:\"slug\";s:42:\"import-export-flows-page-builder-templates\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-26T22:38:12+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:229;O:8:\"stdClass\":8:{s:2:\"id\";i:31205;s:5:\"title\";s:30:\"How Coupons Work in CartFlows?\";s:7:\"content\";s:3705:\"Coupons are a powerful way to offer discounts to your customers and encourage more purchases. When a coupon code is applied on the checkout page—either manually by the customer or automatically—the discount amount (fixed or percentage) is deducted from the order subtotal.\n\n\n\nUsing coupons strategically can help boost conversions, increase average order value, and drive more sales through your checkout flow.\n\n\n\nEnable Coupon Usage in WooCommerce\n\n\n\n1: Before creating coupons, make sure coupon functionality is enabled in WooCommerce.\n\n\n\n2: From your WordPress dashboard, navigate to WooCommerce &gt; Settings.\n\n\n\n\n\n\n\n3: Under the General tab, locate the General options section.\n\n\n\n4: Check the Enable the use of coupon codes option.\n\n\n\n\n\n\n\n5: Save your changes.\n\n\n\nCreating Coupons\n\n\n\nYou can create and manage coupons directly from WooCommerce.\n\n\n\n1: Go to WooCommerce &gt; Coupons.\n\n\n\n2: Click Add Coupon.\n\n\n\n\n\n\n\n3: Enter a coupon code manually or use the Generate coupon code button.\n\n\n\n4: (Optional) Add a description to help you identify the purpose of the coupon later.\n\n\n\n\n\n\n\nOnce created, configure the coupon settings from the Coupon Data panel.\n\n\n\nCoupon Data Settings\n\n\n\nGeneral\n\n\n\n\nDiscount type – Choose between percentage discount, fixed cart discount, or fixed product discount.\n\n\n\nCoupon amount – Specify the discount value or percentage.\n\n\n\nAllow free shipping – Enable this option if the coupon should remove shipping charges.\n\n\n\nCoupon expiry date – Set an expiration date for the coupon.\n\n\n\n\nUsage Restrictions\n\n\n\n\nMinimum spend – Minimum order subtotal required to apply the coupon.\n\n\n\nMaximum spend – Maximum order subtotal allowed to use the coupon.\n\n\n\nIndividual use only – Prevents the coupon from being combined with other coupons.\n\n\n\nExclude sale items – Prevents the coupon from applying to discounted products.\n\n\n\nProducts – Select specific products where the coupon is valid.\n\n\n\nExclude products – Select products where the coupon should not apply.\n\n\n\nProduct categories – Limit the coupon to specific categories.\n\n\n\nExclude categories – Exclude certain categories from using the coupon.\n\n\n\nAllowed emails – Restrict coupon usage to specific email addresses.\n\n\n\n\n\n\n\n\nUsage Limits\n\n\n\n\nUsage limit per coupon – Total number of times the coupon can be used.\n\n\n\nUsage limit per user – Number of times a single customer can use the coupon.\n\n\n\n\n\n\n\n\nAfter completing the setup, click Publish to make the coupon active.\n\n\n\nApplying Coupons on a CartFlows Checkout Page\n\n\n\nCoupons can be applied on a CartFlows checkout page in two ways:\n\n\n\n\nManually by the customer\n\n\n\nAutomatically by pre-applying the coupon\n\n\n\n\nTo edit your checkout step:\n\n\n\n\nGo to CartFlows &gt; Funnels from your WordPress dashboard.\n\n\n\nOpen the desired Funnel.\n\n\n\nClick Settings on the Checkout step.\n\n\n\n\n\n\n\n\nManual Coupon Application\n\n\n\nTo allow customers to enter a coupon code themselves:\n\n\n\n\nOpen the Checkout Settings.\n\n\n\nOpen the Checkout Form > Form Settings.\n\n\n\nToggle the Enable Coupon Field option.\n\n\n\nClick Save Settings.\n\n\n\n\n\n\n\n\nThis displays a coupon input field on the checkout page, allowing customers to apply a coupon manually.\n\n\n\n\n\n\n\nAutomatic Coupon Application\n\n\n\nYou can automatically apply a coupon so customers don’t need to enter a code.\n\n\n\n\n In the checkout settings, open the Products and click on Auto Apply Coupon tab.\n\n\n\nType and choose a coupon from the Auto Apply Coupon dropdown.\n\n\n\nClick Save Settings.\n\n\n\n\n\n\n\n\n(Optional) To prevent customers from applying additional coupons, disable the Coupon Field option in the Checkout Form tab.\n\n\n\nWhen enabled, the discount is applied automatically, and customers cannot add another coupon code.\";s:3:\"url\";s:44:\"https://cartflows.com/docs/how-coupons-work/\";s:4:\"slug\";s:16:\"how-coupons-work\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-14T19:40:11+05:30\";s:8:\"category\";a:1:{i:0;s:8:\"features\";}}i:230;O:8:\"stdClass\":8:{s:2:\"id\";i:31070;s:5:\"title\";s:19:\"Flatsome UX Builder\";s:7:\"content\";s:1249:\"To use the Flatsome UX Builder on CartFlows steps, you\'ll need to add a small piece of code to your child theme’s functions.php file. This will allow the builder to be available when editing CartFlows steps.\n\n\n\nStep 1: Add Code to Your Child Theme’s functions.php\n\n\n\n\nOpen your child theme’s functions.php file.\n\n\n\nAdd the following code:\n\n\n\n\n// Do not include this if already open!\n/**\n * Code goes in theme functions.php\n */\nadd_action( \'init\', function () {\n	if( function_exists( \'add_ux_builder_post_type\' ) ) {\n		add_ux_builder_post_type( \'cartflows_step\' );\n	}\n} );\n\n\n\nThis code will enable the Flatsome UX Builder for CartFlows steps so you can use it for editing your checkout and other funnel pages.\n\n\n\nStep 2: Alternatively, Use the Code Snippets Plugin\n\n\n\nIf you’re not comfortable editing theme files, you can use the free Code Snippets plugin to add this custom function. The plugin allows you to safely add custom PHP code without directly modifying your theme files.\n\n\n\nFor more details on adding custom functions to your website, you can follow this tutorial.\n\n\n\n\nhttps://www.youtube.com/watch?v=c56d84Eek5M\n\n\n\n\nThis will make the Flatsome UX Builder available for editing CartFlows steps, giving you more design flexibility.\";s:3:\"url\";s:47:\"https://cartflows.com/docs/flatsome-ux-builder/\";s:4:\"slug\";s:19:\"flatsome-ux-builder\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-07-02T14:59:29+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:231;O:8:\"stdClass\":8:{s:2:\"id\";i:30659;s:5:\"title\";s:19:\"Funnel in Test Mode\";s:7:\"content\";s:1281:\"CartFlows includes a Test Mode option that allows you to preview your funnel steps—like the Checkout and Thank You pages—without needing to place real orders. This is especially useful when you\'re designing or reviewing the funnel.\n\n\n\nNote: Test Mode does not control sandbox settings for payment gateways. To test payments, you’ll need to enable sandbox/test mode from the payment gateway settings separately.\n\n\n\nHow to Enable or Disable Test Mode\n\n\n\nStep 1: Navigate to CartFlows &gt; Funnels\n\n\n\nFrom your WordPress dashboard, go to CartFlows > Funnels. Select the desired funnel and click Edit.\n\n\n\n\n\n\n\nStep 2: Toggle Test Mode\n\n\n\nAt the top right of the funnel editor, you will find a mode selector. Click on it and choose between Sandbox Mode\n\n\n\n\n\n\n\nWhen Test Mode is active:\n\n\n\n\nYou can preview all funnel steps without assigning real products.\n\n\n\nCartFlows automatically assigns a random WooCommerce product to simulate the checkout process.\n\n\n\nYou can share preview links with your team for collaboration or design review.\n\n\n\nA notification banner will appear at the bottom of the page indicating that Test Mode is active.\n\n\n\n\n\n\n\n\nOnce you\'re done designing or testing, simply disable the toggle and click Update to make the funnel live.\n\n\n\nFrequently Asked Questions\";s:3:\"url\";s:45:\"https://cartflows.com/docs/flow-in-test-mode/\";s:4:\"slug\";s:17:\"flow-in-test-mode\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-04T22:35:48+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"troubleshooting\";}}i:232;O:8:\"stdClass\":8:{s:2:\"id\";i:30612;s:5:\"title\";s:26:\"Creating Variable Products\";s:7:\"content\";s:2049:\"If you sell products that come in different sizes, colors, or styles — like a t-shirt in multiple sizes and colors — you don’t need to create separate products for each variation. Instead, you can use Variable Products in WooCommerce to handle this more efficiently.\n\n\n\nCartFlows fully supports variable products and lets you display product options directly on the checkout page.\n\n\n\nExample Use Case\n\n\n\nLet’s say you sell a panda-themed t-shirt. This shirt is available in three sizes (S, M, L) and four colors. Instead of creating 12 different products, you can create one product with two attributes: Size and Color, and define variations for each combination.\n\n\n\nHow to Set Up Variable Products in CartFlows\n\n\n\nStep 1: Create a Variable Product in WooCommerce\n\n\n\nIn your WordPress dashboard, create a new product or edit an existing one. Set the Product Data to \"Variable Product\", add attributes (like Size or Color), and create your variations.\n\n\n\nIf you\'re new to WooCommerce variations, here\'s a helpful video tutorial that starts directly at the section on setting up variable products.\n\n\n\n\nhttps://youtu.be/CWSb-aWovqE?t=3142\n\n\n\n\nStep 2: Assign the Product to Your Checkout Step\n\n\n\n\nNavigate to CartFlows &gt; Funnels and edit your funnel.\n\n\n\nOpen the Checkout step and go to the Checkout Setting (cog igon).\n\n\n\nGo to the Product Options section on the sidebar.\n\n\n\nEnable the Product Options as well as the Variations.\n\n\n\n\n\n\n\n\nOnce enabled, your product variations will automatically display on the checkout page.\n\n\n\nStep 3: Choose a Layout for Product Options\n\n\n\nCartFlows offers three display layouts for variable product options:\n\n\n\nCard Layout – A modern visual layout using cards for each option.\n\n\n\n\n\n\n\nClassic Layout – A more traditional list-style layout.\n\n\n\n\n\n\n\nCard Inline Layout – Offering a more modern and streamlined look.\n\n\n\n\n\n\n\nNote: If you’re using a page builder (such as Elementor or Gutenberg), you can directly customize the design of the variation selector using CartFlows’ widget or block settings.\";s:3:\"url\";s:54:\"https://cartflows.com/docs/creating-variable-products/\";s:4:\"slug\";s:26:\"creating-variable-products\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-06T13:15:28+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:233;O:8:\"stdClass\":8:{s:2:\"id\";i:30539;s:5:\"title\";s:27:\"CartFlows Funnel Step Types\";s:7:\"content\";s:1584:\"A funnel consists of multiple steps that guide users through the buying journey. CartFlows offers several step types, each serving a specific purpose.\n\n\n\nAvailable Step Types\n\n\n\nLanding Page Step\n\n\n\nThe Landing Page step is used to create lead generation or sales pages. You can have multiple landing pages in a single funnel.\n\n\n\nCheckout Step\n\n\n\nThe Checkout step is where buyers complete their orders. It includes options to:\n\n\n\n\nLink to a product.\n\n\n\nAdd an upsell (Pro feature).\n\n\n\nAdjust checkout fields (Pro feature).\n\n\n\nStyle the Checkout form.\n\n\n\n\nA funnel can have only one Checkout step.\n\n\n\nUpsell Step (Pro Feature)\n\n\n\nThe Upsell step appears after the Checkout step. This is where you can offer an additional product after the initial purchase.\n\n\n\nA funnel can have multiple Upsell steps.\n\n\n\nDownsell Step (Pro Feature)\n\n\n\nThe Downsell step appears after an Upsell step. If a buyer declines the upsell offer, they are directed to the Downsell step, where you can present a lower-cost or alternative offer.\n\n\n\nA funnel can have multiple Downsell steps.\n\n\n\nThank You Step\n\n\n\nThe Thank You step is the final step in a funnel. It is used to:\n\n\n\n\nDisplay order details (if a Checkout step is included).\n\n\n\nProvide next steps or instructions to buyers.\n\n\n\n\nOpt-in Step (Free/Pro)\n\n\n\nThe Opt-in step is used to collect leads and provide free products. It is placed between the Landing Page and the Checkout step.\n\n\n\n\nRequires free Simple Virtual/Downloadable products.\n\n\n\nUsers enter their details to gain access to the product.\n\n\n\nAdditional custom fields require CartFlows Pro.\";s:3:\"url\";s:48:\"https://cartflows.com/docs/cartflows-step-types/\";s:4:\"slug\";s:20:\"cartflows-step-types\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-03-04T16:01:23+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"getting-started\";}}i:234;O:8:\"stdClass\":8:{s:2:\"id\";i:30397;s:5:\"title\";s:35:\"How to Use LearnDash with CartFlows\";s:7:\"content\";s:1957:\"his documentation explains how to use LearnDash with CartFlows to sell online courses through WooCommerce.\n\n\n\nLearnDash is a course builder plugin for WordPress that allows you to create and manage online courses. These courses can be sold using WooCommerce products.\n\n\n\nSince CartFlows works with WooCommerce products, you can use it to create optimized checkout pages and funnels for selling your courses.&nbsp;\n\n\n\nVideo Overview\n\n\n\nThe video below demonstrates how to integrate LearnDash with WooCommerce and use CartFlows to sell your course.\n\n\n\n\nhttps://www.youtube.com/watch?v=thb2tyMFCEA\n\n\n\n\nSelling LearnDash Courses with CartFlows\n\n\n\nOnce LearnDash is integrated with WooCommerce, you can sell your course using CartFlows by following the steps below.\n\n\n\n1. Create a Course Product in WooCommerce\n\n\n\nFirst, create your course in LearnDash.\n\n\n\nNext, create a WooCommerce product that will be used to sell the course.\n\n\n\nNavigate to: Products &gt; Add New\n\n\n\nConfigure the product details such as title, description, and price.\n\n\n\n2. Attach the Course to the Product\n\n\n\nAfter creating the WooCommerce product, attach the LearnDash course to that product.\n\n\n\nThis ensures that when a customer purchases the product, they are automatically enrolled in the corresponding course.\n\n\n\n3. Add the Product to Your Funnel\n\n\n\nOnce the product is configured in WooCommerce, you can add it to your funnel.\n\n\n\nNavigate to: CartFlows &gt; Funnels\n\n\n\nOpen your funnel and edit the step where you want to sell the course, such as the Checkout, Upsell, or Downsell step.\n\n\n\n4. Select the Course Product\n\n\n\nIn the settings of the Checkout, Upsell, or Downsell step, select the WooCommerce product that is linked to your LearnDash course.\n\n\n\n5. Save the Changes\n\n\n\nSave the changes to your funnel step.\n\n\n\nYour LearnDash course can now be sold through CartFlows, allowing you to use features such as optimized checkout pages, order bumps, and upsell or downsell offers.\";s:3:\"url\";s:37:\"https://cartflows.com/docs/learndash/\";s:4:\"slug\";s:9:\"learndash\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-03-13T17:57:10+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:235;O:8:\"stdClass\":8:{s:2:\"id\";i:30371;s:5:\"title\";s:43:\"How to Exclude CartFlows Pages from Caching\";s:7:\"content\";s:1420:\"To ensure CartFlows works correctly, it’s important to exclude specific funnel steps from being cached. Caching may interfere with CartFlows functionality, especially on Checkout, Upsell, Downsell, and Thank You pages.\n\n\n\nHow to Exclude Funnel Steps from Caching\n\n\n\nEach caching plugin offers its own method for excluding URLs. Below are links to official documentation for popular caching plugins:\n\n\n\n\nWP Rocket: Exclude pages from the cache and optimizations\n\n\n\nW3 Total Cache: How to Exclude Specific Pages from W3 Total Cache\n\n\n\nWP Fastest Cache: Exclude Page\n\n\n\nWP-Optimize: How do I enable/use page cache\n\n\n\nSwift Performance: Cache Exceptions\n\n\n\nComet Cache: Exclude the Home Page (and others) from being cached\n\n\n\n\nIf you are using a caching plugin that is not listed here, please refer to its documentation or contact the plugin developer to learn how to exclude specific URLs from caching.\n\n\n\nExcluding Pages in the Breeze Plugin\n\n\n\nIf you’re using the Breeze caching plugin, the video below shows how to exclude CartFlows funnel steps from being cached:\n\n\n\n\nhttps://www.youtube.com/watch?v=v72mdEY-HIQ\n\n\n\n\nServer-Level Caching by Web Hosts\n\n\n\nSome hosting providers apply caching at the server level, which cannot be controlled by plugins. If you’re using a host that applies caching automatically, contact their support team and ask them to exclude your CartFlows funnel steps from server-side caching.\";s:3:\"url\";s:43:\"https://cartflows.com/docs/disable-caching/\";s:4:\"slug\";s:15:\"disable-caching\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-05T12:25:01+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:236;O:8:\"stdClass\":8:{s:2:\"id\";i:30365;s:5:\"title\";s:38:\"How To Connect Stripe Payment Gateway?\";s:7:\"content\";s:1195:\"CartFlows offers built-in compatibility with the official WooCommerce Stripe Payment Gateway plugin, making it easy to accept online payments through Stripe. This integration also supports advanced features like order bumps, upsells, and downsells.\n\n\n\nFollow the steps below to install and configure Stripe on your website:\n\n\n\n&#x25b6;&#xfe0f; Watch: Stripe Integration Overview\n\n\n\nBefore getting started with the setup steps, we recommend watching the video below for a quick overview of the process:\n\n\n\n\nhttps://www.youtube.com/watch?v=5rMDGdkmSGU\n\n\n\n\nStep-by-Step Setup\n\n\n\nStep 1: Install the Stripe Payment Plugin\n\n\n\n\nFrom your WordPress dashboard, go to Plugins > Add New.\n\n\n\nSearch for WooCommerce Stripe Payment Gateway.\n\n\n\nLocate the plugin by WooCommerce, then click Install and Activate.\n\n\n\n\nStep 2: Configure Stripe Settings\n\n\n\n\nGo to WooCommerce > Settings > Payments.\n\n\n\nClick Manage next to Stripe.\n\n\n\nChoose your environment (Live or Test/Sandbox).\n\n\n\nEnter your Stripe API credentials and click Save Changes.\n\n\n\n\n&#x1f4cc; You can download the plugin for free from the WordPress.org repository.\n\n\n\nLooking for more details? Check out the full Stripe setup guide from WooCommerce.\";s:3:\"url\";s:65:\"https://cartflows.com/docs/how-to-connect-stripe-payment-gateway/\";s:4:\"slug\";s:37:\"how-to-connect-stripe-payment-gateway\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-13T22:44:13+05:30\";s:8:\"category\";a:1:{i:0;s:12:\"integrations\";}}i:237;O:8:\"stdClass\":8:{s:2:\"id\";i:30331;s:5:\"title\";s:15:\"GDPR Compliance\";s:7:\"content\";s:1831:\"CartFlows includes features that help store owners collect and manage data in ways that align with GDPR principles. This documentation outlines the three main areas where CartFlows interacts with customer data.\n\n\n\n1. Checkout Forms\n\n\n\nCartFlows uses WooCommerce checkout forms and stores the entered data in the browser’s local storage. This ensures that if a user accidentally refreshes the Checkout page, their input won’t be lost.\n\n\n\nAs far as we understand, this does not violate GDPR compliance. However, if you prefer to disable this feature, refer to this guide: How to Turn Off Auto-Fill on Checkout Fields\n\n\n\n2. Analytics\n\n\n\nCartFlows provides built-in analytics to help you monitor and improve your funnel performance. This feature does not track personal data of website visitors.\n\n\n\nTo power analytics, CartFlows uses a few cookies — none of which collect contact or sensitive information.\n\n\n\nAnalytics Cookies:\n\n\n\n\nwcf-visited-flow- – Tracks which funnel is currently being viewed\n\n\n\nwcf-step-visited- – Tracks the current step being viewed\n\n\n\ncartflows-ab-test- – Set only when A/B split testing is enabled\n\n\n\n\nAdditional Cookies:\n\n\n\n\ncartflows_session_ – Sets a unique session ID per user to support a smoother checkout\n\n\n\nwcf_active_checkout – Tracks which Checkout page is currently active, along with cart data\n\n\n\n\nThese cookies are designed to support funnel functionality and do not contain personal data.\n\n\n\nDisclaimer\n\n\n\nCartFlows is not a legal advisor. For full GDPR compliance, we recommend consulting with your legal counsel regarding how you use these features.\n\n\n\nFor more on WooCommerce and GDPR, refer to: https://woocommerce.com/posts/gdpr-compliance-woocommerce/ \n\n\n\nFor cookie use in our Cart Abandonment plugin, refer to this article: Cart Abandonment Cookies &amp; GDPR Compliance\";s:3:\"url\";s:43:\"https://cartflows.com/docs/gdpr-compliance/\";s:4:\"slug\";s:15:\"gdpr-compliance\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-02T17:45:44+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:238;O:8:\"stdClass\":8:{s:2:\"id\";i:30328;s:5:\"title\";s:36:\"How to Set a Funnel as Your Homepage\";s:7:\"content\";s:458:\"If you’re building a website exclusively for a funnel, you may want to set the landing page step of your CartFlows funnel as the homepage.\n\n\n\nHere’s how to do it:\n\n\n\n\nGo to Settings > Reading in your WordPress dashboard.\n\n\n\nUnder Your homepage displays, select A static page.\n\n\n\nFrom the Homepage dropdown, choose your CartFlows landing page step.\n\n\n\nClick Save Changes.\n\n\n\n\n\n\n\n\nYou’ll now see the selected landing page as the homepage of your website.\";s:3:\"url\";s:48:\"https://cartflows.com/docs/set-flow-as-homepage/\";s:4:\"slug\";s:20:\"set-flow-as-homepage\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-02T17:53:13+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:239;O:8:\"stdClass\":8:{s:2:\"id\";i:30183;s:5:\"title\";s:32:\"How To Add An Affiliate Program?\";s:7:\"content\";s:684:\"If you\'re planning to launch an affiliate program for your store or funnel, you\'re in luck, any affiliate plugin that integrates with WooCommerce will also work seamlessly with CartFlows.\n\n\n\nWe recommend using AffiliateWP for a robust and feature-rich setup. You can explore their offering at affiliatewp.com.\n\n\n\nLooking for a free solution? You can consider the Affiliates Manager plugin available on the WordPress repository: wordpress.org/plugins/affiliates-manager\n\n\n\nOnce installed and configured, these plugins will track referrals, manage commissions, and help you grow your sales through affiliate marketing, all while working smoothly alongside your CartFlows-powered funnel.\";s:3:\"url\";s:59:\"https://cartflows.com/docs/how-to-add-an-affiliate-program/\";s:4:\"slug\";s:31:\"how-to-add-an-affiliate-program\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-06-20T23:44:13+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:240;O:8:\"stdClass\":8:{s:2:\"id\";i:30165;s:5:\"title\";s:20:\"Using Pricing Tables\";s:7:\"content\";s:1611:\"CartFlows works seamlessly with any pricing table you wish to use, making it easy to direct customers to different funnels based on their selected pricing option.\n\n\n\nBy linking each pricing table option to its own unique funnel, you can customize the entire purchase journey, from checkout to upsells and thank you pages, based on the pricing plan selected.\n\n\n\nHow to Set Up Funnels for Pricing Tables\n\n\n\nStep 1: Create a Pricing Page\n\n\n\nStart by creating a standard WordPress page where you will add your pricing table. You can use any page builder to design this.\n\n\n\n\n\n\n\nStep 2: Build the First Funnel\n\n\n\nCreate a new funnel in CartFlows for your first pricing option. Set the first step as the Checkout page and add any additional steps you’d like, such as Order Bumps, Upsells, Downsells, and the Thank You page.\n\n\n\nStep 3: Assign the Product\n\n\n\nIn the checkout step, assign the product that corresponds to this specific pricing plan.\n\n\n\nStep 4: Clone the Funnel\n\n\n\nUse the Duplicate feature to duplicate the funnel for each additional pricing option. This saves time and ensures a consistent structure across all plans.\n\n\n\n\n\n\n\nStep 5: Update the Product\n\n\n\nIn each cloned funnel, update the checkout step with the product linked to the respective pricing plan.\n\n\n\nStep 6: Link Buttons to Funnels\n\n\n\nCopy the checkout step URL from each funnel and link it to the corresponding button in your pricing table.\n\n\n\n\n\n\n\nWith this setup, customers clicking on a pricing option will be directed to the tailored checkout experience for that plan, helping you deliver a more personalized and high-converting funnel.\";s:3:\"url\";s:48:\"https://cartflows.com/docs/using-pricing-tables/\";s:4:\"slug\";s:20:\"using-pricing-tables\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-19T22:15:07+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:241;O:8:\"stdClass\":8:{s:2:\"id\";i:30161;s:5:\"title\";s:42:\"How to Hide WooCommerce Pages and Products\";s:7:\"content\";s:887:\"If you want to sell products exclusively through CartFlows funnels, you may not want those products or the default WooCommerce shop page to be publicly visible on your site.\n\n\n\nThis documentation shows you how to hide individual product pages and the WooCommerce shop page.\n\n\n\nHiding Individual Product Pages\n\n\n\nTo hide a specific product page:\n\n\n\n\nEdit the product in your WordPress dashboard.\n\n\n\nUnder the Publish section, click the Edit link next to Catalog visibility.\n\n\n\nSelect Hidden from the available options.\n\n\n\nClick OK, then click Update to save your changes.\n\n\n\n\n\n\n\n\nHiding the WooCommerce Shop Page\n\n\n\nTo remove the default WooCommerce shop page:\n\n\n\n\nGo to WooCommerce > Settings > Products tab.\n\n\n\nIn the Shop page dropdown, click the small X icon to unassign the page and leave the dropdown blank.\n\n\n\n\n\n\n\n\nFor more details, refer to the official WooCommerce documentation.\";s:3:\"url\";s:66:\"https://cartflows.com/docs/how-to-hide-woocommerce-pages-products/\";s:4:\"slug\";s:38:\"how-to-hide-woocommerce-pages-products\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-29T20:09:10+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:242;O:8:\"stdClass\":8:{s:2:\"id\";i:30158;s:5:\"title\";s:44:\"Recommended Permalink Settings for CartFlows\";s:7:\"content\";s:503:\"CartFlows works best when WordPress permalinks are set to use a compatible structure.\n\n\n\nFollow the steps below to configure the correct permalink setting.\n\n\n\nSet the Permalink Structure\n\n\n\n\nGo to Settings > Permalinks in your WordPress dashboard.\n\n\n\nUnder Permalink structure, select Post name.\n\n\n\nClick Save Changes.\n\n\n\n\n\n\n\n\nNote: If your permalink settings are not set to Post name, you may see URLs like yourdomain.com/cartflows_step/checkout-page/. Using the recommended structure helps avoid this.\";s:3:\"url\";s:52:\"https://cartflows.com/docs/best-permalinks-settings/\";s:4:\"slug\";s:24:\"best-permalinks-settings\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-05-22T21:31:19+05:30\";s:8:\"category\";a:1:{i:0;s:18:\"permalink-settings\";}}i:243;O:8:\"stdClass\":8:{s:2:\"id\";i:30149;s:5:\"title\";s:54:\"How To Use Your Themes Header &#038; Footer In A Step?\";s:7:\"content\";s:1442:\"By default, CartFlows steps use CartFlows-specific page templates designed to offer more control over the layout. However, if you\'d like to display your theme’s header and footer on a step, you can switch to your theme’s default template.\n\n\n\nThis documentation explains how to use your theme’s header and footer in a CartFlows step.\n\n\n\nAvailable Page Templates in CartFlows\n\n\n\nCartFlows includes two page templates:\n\n\n\n\nCartFlows - Boxed – Displays the page in a boxed layout.\n\n\n\nTemplate for Page Builder – Displays the page in a full-width layout, allowing flexibility when using a page builder.\n\n\n\n\nWhen you create a new step, CartFlows will automatically assign the CartFlows template. You can change it at any time.\n\n\n\nHow to Use Your Theme’s Header and Footer\n\n\n\nTo switch from the CartFlows template to your theme’s template:\n\n\n\n\nEdit the step by clicking the Edit Step button.\n\n\n\nIn the Page Attributes section (on the right sidebar), look for the Template dropdown.\n\n\n\nSelect Default Template (or your theme’s template, if labeled differently).\n\n\n\nClick Update / Save to save your changes.\n\n\n\n\n\n\n\n\nUsing Page Builders\n\n\n\nThe instructions above are based on the Block Editor (Gutenberg).If you\'re using a different page builder (like Elementor, Beaver Builder, etc.), the method to select a page template may vary. Please refer to your page builder’s documentation for the correct steps.\n\n\n\nFrequently Asked Question\";s:3:\"url\";s:74:\"https://cartflows.com/docs/how-to-use-your-themes-header-footer-in-a-step/\";s:4:\"slug\";s:46:\"how-to-use-your-themes-header-footer-in-a-step\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-03-24T20:45:53+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:244;O:8:\"stdClass\":8:{s:2:\"id\";i:30065;s:5:\"title\";s:30:\"Getting Started with CartFlows\";s:7:\"content\";s:272:\"This video offers an introduction to CartFlows and its core features. It\'s a helpful starting point if you\'re new to the plugin or want a quick overview of how it works.\n\n\n\nWatch the video below to learn more about the basics of CartFlows.\n\n\n\n\nhttps://youtu.be/tCm60PWOd0M\";s:3:\"url\";s:53:\"https://cartflows.com/docs/general-settings-overview/\";s:4:\"slug\";s:25:\"general-settings-overview\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-03-24T19:39:17+05:30\";s:8:\"category\";a:1:{i:0;s:15:\"getting-started\";}}i:245;O:8:\"stdClass\":8:{s:2:\"id\";i:29970;s:5:\"title\";s:27:\"How to Install WooCommerce?\";s:7:\"content\";s:553:\"CartFlows requires the WooCommerce plugin to work. If WooCommerce is not installed, CartFlows will prompt you to install it during the setup.\n\n\n\nThe installation process is exactly the same as installing the CartFlows Free plugin. You can refer to this documentation as guidance: How to Install CartFlows Free\n\n\n\nThe only difference is in Step 3, where you’ll need to search for “WooCommerce” instead of “CartFlows” in the search bar.\n\n\n\nFor additional information about WooCommerce, you can refer to this documentation: How to Use WooCommerce\";s:3:\"url\";s:54:\"https://cartflows.com/docs/how-to-install-woocommerce/\";s:4:\"slug\";s:26:\"how-to-install-woocommerce\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-03-14T21:08:50+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:246;O:8:\"stdClass\":8:{s:2:\"id\";i:29967;s:5:\"title\";s:23:\"How to Use WooCommerce?\";s:7:\"content\";s:451:\"CartFlows requires the WooCommerce plugin to work. WooCommerce is one of the most widely used eCommerce platforms, powering millions of websites globally.\n\n\n\nIf you’re new to WooCommerce or want to explore its features further, you can refer to the official documentation here: https://docs.woocommerce.com\n\n\n\nIf you prefer a visual walkthrough, you can also watch the video below that shows how to install and configure WooCommerce on your website.\";s:3:\"url\";s:50:\"https://cartflows.com/docs/how-to-use-woocommerce/\";s:4:\"slug\";s:22:\"how-to-use-woocommerce\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2025-03-19T22:41:46+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:247;O:8:\"stdClass\":8:{s:2:\"id\";i:29922;s:5:\"title\";s:39:\"How to Hide Fields on the Checkout Page\";s:7:\"content\";s:1037:\"CartFlows allows you to customize the checkout form by hiding fields you don’t want to display. You can easily manage this through the Checkout Form settings within the Checkout step.\n\n\n\nThis documentation will show you how to hide unwanted fields from the CartFlows Checkout page.\n\n\n\nSteps to Hide Checkout Fields\n\n\n\nStep 1: Edit Your Funnel\n\n\n\n1. From your WordPress dashboard, go to CartFlows > Funnels.2. Locate and edit the funnel you want to modify.\n\n\n\n\n\n\n\n3. Click on the Checkout Settings (cog icon) to access its settings.\n\n\n\n\n\n\n\nStep 2: Enable the Custom Field Editor\n\n\n\n\nGo to the Checkout Form tab.\n\n\n\nIf the Enable Custom Field Editor option is disabled, switch it on.\n\n\n\n\n\n\n\n\nStep 3: Hide Checkout Fields\n\n\n\n\nOnce the custom field editor is enabled, you’ll see a list of all fields.\n\n\n\nUse the toggle switch next to each field you want to hide.\n\n\n\nAfter making your changes, click the Save Settings button to apply them.\n\n\n\n\n\n\n\n\nYou’ve now successfully hidden the fields you don’t want to show on the checkout page.\";s:3:\"url\";s:55:\"https://cartflows.com/docs/how-to-hide-checkout-fields/\";s:4:\"slug\";s:27:\"how-to-hide-checkout-fields\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-06T14:46:10+05:30\";s:8:\"category\";a:1:{i:0;s:7:\"general\";}}i:248;O:8:\"stdClass\":8:{s:2:\"id\";i:300;s:5:\"title\";s:47:\"Supported Payment Gateway for One Click Upsells\";s:7:\"content\";s:1600:\"CartFlows Pro allows you to offer one‑click upsells and downsells to increase the average order value of your sales funnels. For this functionality to work properly, the payment gateway used during checkout must support the required tokenization or reference transaction features.\n\n\n\nBelow is the list of payment gateways that are officially supported for CartFlows one‑click upsell and downsell offers.\n\n\n\nSupported Payment Gateways\n\n\n\nCartFlows Pro supports one‑click upsells with the following gateways:\n\n\n\n\nAuthorize.net\n\n\n\nBACS (Direct Bank Transfer)\n\n\n\nCash on Delivery (COD)\n\n\n\nMollie – Credit Card and iDEAL\n\n\n\nWooCommerce PayPal Payments\n\n\n\nStripe – Credit Card\n\n\n\nSquare\n\n\n\n\nThese gateways have built‑in compatibility with CartFlows to process additional offers without requiring the customer to re‑enter payment details.\n\n\n\nGateway Compatibility Notice\n\n\n\nOne‑click upsells require dedicated compatibility with each payment gateway. Because of this, support must be built individually for every gateway.\n\n\n\nThe CartFlows team continues to add compatibility for more gateways over time as they become available.\n\n\n\nIf you attempt to use a payment gateway that is not supported, CartFlows will display a notice on the Upsell or Downsell step in the Flow editor.\n\n\n\nThis notice indicates that the currently selected gateway does not support one‑click upsells.\n\n\n\nFrequently Asked Questions\n\n\n\n\n\n\n\n\n\nTo avoid this, you can either use the supported payment gateways or you can add custom support of your payment gateway in the CartFlows with the help of a freelance developer.\";s:3:\"url\";s:45:\"https://cartflows.com/docs/one-click-upsells/\";s:4:\"slug\";s:17:\"one-click-upsells\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-03-12T23:51:40+05:30\";s:8:\"category\";a:1:{i:0;s:17:\"one-click-upsells\";}}i:249;O:8:\"stdClass\":8:{s:2:\"id\";i:295;s:5:\"title\";s:28:\"How To Install CartFlows Pro\";s:7:\"content\";s:1435:\"When you want to install a CartFlows Premium plan (Plus, or Pro), you need to download the plugin, install it, and activate the license key.\n\n\n\nNote: The CartFlows Free plugin is required. If you haven’t installed it yet, see this document.\n\n\n\nInstalling CartFlows Pro\n\n\n\nStep 1: Go to your Account and click on Your Products\n\n\n\nIn your Account page, go to Your Products to view all your products.\n\n\n\n\n\n\n\nStep 2: Download CartFlows Pro\n\n\n\nClick Download to start the .zip download.\n\n\n\n\n\n\n\nStep 3: Login to your WordPress website\n\n\n\nWhen you log in, you will be in your Dashboard.\n\n\n\nStep 4: In the Plugins menu, click Add New Plugin\n\n\n\nNavigate to Plugins &gt; Add New Plugin from your WordPress dashboard.\n\n\n\n\n\n\n\nStep 5: Click Upload Plugin at the top of the screen\n\n\n\nThe screen will expand with the option to upload plugins.\n\n\n\n\n\n\n\nStep 6: Upload the plugin and click Install Now\n\n\n\nIn the Add Plugins screen, you can click on Choose File and upload the .zip file. Click on Install Now to install the plugin; this may take some time.\n\n\n\n\n\n\n\nStep 7: Click Activate Plugin\n\n\n\nAfter installing the plugin, click on Activate Plugin to complete the installation.\n\n\n\n\n\n\n\nCongratulations! You’ve successfully installed the CartFlows Pro plugin on your website.\n\n\n\nWhat’s next?\n\n\n\nMake sure to activate your license to receive plugin updates and access premium features. Click here to learn how to activate your CartFlows Pro license.\";s:3:\"url\";s:52:\"https://cartflows.com/docs/how-to-install-cartflows/\";s:4:\"slug\";s:24:\"how-to-install-cartflows\";s:9:\"parent_id\";N;s:13:\"last_modified\";s:25:\"2026-05-26T12:58:18+05:30\";s:8:\"category\";a:1:{i:0;s:20:\"installation-updates\";}}}}','auto-off'),(971,'_transient_timeout_power_coupons_state_events_checked','1790192180','off'),(972,'_transient_power_coupons_state_events_checked','1','off'),(974,'power-coupons_usage_events_pending','a:6:{i:0;a:4:{s:10:\"event_name\";s:16:\"plugin_activated\";s:11:\"event_value\";s:5:\"1.0.7\";s:10:\"properties\";a:1:{s:6:\"source\";s:11:\"astra-sites\";}s:4:\"date\";s:19:\"2026-09-22 21:36:20\";}i:1;a:4:{s:10:\"event_name\";s:20:\"cart_display_enabled\";s:11:\"event_value\";s:0:\"\";s:10:\"properties\";a:0:{}s:4:\"date\";s:19:\"2026-09-22 21:36:20\";}i:2;a:4:{s:10:\"event_name\";s:24:\"checkout_display_enabled\";s:11:\"event_value\";s:0:\"\";s:10:\"properties\";a:0:{}s:4:\"date\";s:19:\"2026-09-22 21:36:20\";}i:3;a:4:{s:10:\"event_name\";s:20:\"guest_access_enabled\";s:11:\"event_value\";s:0:\"\";s:10:\"properties\";a:0:{}s:4:\"date\";s:19:\"2026-09-22 21:36:20\";}i:4;a:4:{s:10:\"event_name\";s:20:\"drawer_mode_selected\";s:11:\"event_value\";s:0:\"\";s:10:\"properties\";a:0:{}s:4:\"date\";s:19:\"2026-09-22 21:36:20\";}i:5;a:4:{s:10:\"event_name\";s:19:\"expiry_info_enabled\";s:11:\"event_value\";s:0:\"\";s:10:\"properties\";a:0:{}s:4:\"date\";s:19:\"2026-09-22 21:36:20\";}}','auto'),(975,'power_coupons_tracked_version','1.0.7','auto'),(985,'_transient_timeout_surerank_state_events_checked','1790192185','off'),(986,'_transient_surerank_state_events_checked','1','off'),(987,'surerank_usage_events_pushed','a:0:{}','auto'),(988,'sureran